window.QUESTIONS = [{"id":1,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, hoa hồng đại lý bảo hiểm được trả cho đối tượng nào dưới đây:","options":[{"key":"A","text":"Bên mua bảo hiểm."},{"key":"B","text":"Người thụ hưởng."},{"key":"C","text":"Đại lý bảo hiểm."},{"key":"D","text":"A, B, C đúng."}],"answer":"C","explanation":"Theo đáp án của đề cương, đáp án đúng là **C**: **Đại lý bảo hiểm.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Đại lý bảo hiểm.**."},{"id":2,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phát biểu nào dưới đây sai khi nói về hoạt động mà đại lý bảo hiểm có thể được doanh nghiệp bảo hiểm ủy quyền thực hiện:","options":[{"key":"A","text":"Giới thiệu, chào bán sản phẩm bảo hiểm."},{"key":"B","text":"Thu xếp việc giao kết hợp đồng bảo hiểm."},{"key":"C","text":"Thu phí bảo hiểm."},{"key":"D","text":"Thay mặt doanh nghiệp bảo hiểm ký kết hợp đồng bảo hiểm với bên mua bảo hiểm"}],"answer":"D","explanation":"Đây là câu hỏi tìm **phương án ngoại lệ/sai**. Theo đáp án của đề cương, phương án **D** là nội dung không phù hợp: **Thay mặt doanh nghiệp bảo hiểm ký kết hợp đồng bảo hiểm với bên mua bảo hiểm**. Khi làm bài, cần chú ý từ khóa phủ định như **“sai”, “không”, “ngoại trừ”**.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":5,"category":"Kiến thức chung","question":"Phát biểu nào dưới đây không đúng khi nói về vai trò kinh tế của bảo hiểm:","options":[{"key":"A","text":"Góp phần ổn định tài chính của tổ chức, cá nhân tham gia bảo hiểm."},{"key":"B","text":"Đóng vai trò trung gian trong việc huy động vốn cho nền kinh tế quốc dân."},{"key":"C","text":"Góp phần ổn định ngân sách quốc gia."},{"key":"D","text":"Cung cấp tiền vốn cho người gặp rủi ro thay cho vay ngân hàng."}],"answer":"D","explanation":"Đây là câu hỏi tìm **phương án ngoại lệ/sai**. Theo đáp án của đề cương, phương án **D** là nội dung không phù hợp: **Cung cấp tiền vốn cho người gặp rủi ro thay cho vay ngân hàng.**. Khi làm bài, cần chú ý từ khóa phủ định như **“sai”, “không”, “ngoại trừ”**.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":7,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phát biểu nào dưới đây đúng:","options":[{"key":"A","text":"Phí bảo hiểm là khoản tiền mà bên mua bảo hiểm phải đóng cho doanh nghiệp bảo hiểm theo quy định của pháp luật hoặc do các bên thỏa thuận trong hợp đồng bảo hiểm"},{"key":"B","text":"Người được bảo hiểm là tổ chức, cá nhân giao kết hợp đồng bảo hiểm với doanh nghiệp bảo hiểm và đóng phí bảo hiểm"},{"key":"C","text":"A,B đúng"}],"answer":"A","explanation":"Theo đáp án của đề cương, phương án **A** là nội dung đúng: **Phí bảo hiểm là khoản tiền mà bên mua bảo hiểm phải đóng cho doanh nghiệp bảo hiểm theo quy định của pháp luật hoặc do các bên thỏa thuận trong hợp đồng bảo hiểm**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Phí bảo hiểm là khoản tiền mà bên mua bảo hiểm phải đóng cho doanh nghiệp bảo hiểm theo quy…**."},{"id":15,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, chọn phương án đúng về trường hợp hợp đồng bảo hiểm vô hiệu:","options":[{"key":"A","text":"Doanh nghiệp bảo hiểm và bên mua bảo hiểm giao kết hợp đồng bảo hiểm giả tạo."},{"key":"B","text":"Tại thời điểm giao kết hợp đồng bảo hiểm, bên mua bảo hiểm không biết sự kiện bảo hiểm đã xảy ra."},{"key":"C","text":"Đại lý bảo hiểm không nộp phí bảo hiểm đã thu của bên mua bảo hiểm cho doanh nghiệp bảo hiểm."},{"key":"D","text":"A, B, C đúng."}],"answer":"A","explanation":"Theo đáp án của đề cương, phương án **A** là nội dung đúng: **Doanh nghiệp bảo hiểm và bên mua bảo hiểm giao kết hợp đồng bảo hiểm giả tạo.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Doanh nghiệp bảo hiểm và bên mua bảo hiểm giao kết hợp đồng bảo hiểm giả tạo.**."},{"id":20,"category":"Luật Kinh doanh bảo hiểm","question":"Chọn phương án đúng về quyền, nghĩa vụ của doanh nghiệp bảo hiểm:","options":[{"key":"A","text":"Có quyền thay đổi người thụ hưởng bảo hiểm."},{"key":"B","text":"Có trách nhiệm điền thông tin vào giấy yêu cầu bảo hiểm."},{"key":"C","text":"Trực tiếp chi trả hoa hồng bảo hiểm cho người được bảo hiểm."},{"key":"D","text":"Cung cấp cho bên mua bảo hiểm bằng chứng giao kết hợp đồng bảo hiểm theo quy định tại Luật Kinh doanh bảo hiểm."}],"answer":"D","explanation":"Theo đáp án của đề cương, phương án **D** là nội dung đúng: **Cung cấp cho bên mua bảo hiểm bằng chứng giao kết hợp đồng bảo hiểm theo quy định tại Luật Kinh doanh bảo hiểm.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Cung cấp cho bên mua bảo hiểm bằng chứng giao kết hợp đồng bảo hiểm theo quy định tại Luật…**."},{"id":25,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, chọn phương án sai về nghĩa vụ của bên mua bảo hiểm:","options":[{"key":"A","text":"Đóng phí bảo hiểm đầy đủ theo thời hạn và phương thức đã thỏa thuận trong hợp đồng bảo hiểm."},{"key":"B","text":"Kê khai đầy đủ, trung thực mọi thông tin có liên quan đến hợp đồng bảo hiểm theo yêu cầu của doanh nghiệp bảo hiểm."},{"key":"C","text":"Thông báo những trường hợp có thể làm tăng rủi ro hoặc làm phát sinh thêm trách nhiệm của doanh nghiệp bảo hiểm trong quá trình thực hiện hợp đồng bảo hiểm theo yêu cầu của doanh nghiệp bảo hiểm."},{"key":"D","text":"Lựa chọn doanh nghiệp bảo hiểm có đủ năng lực tài chính để chi trả quyền lợi bảo hiểm."}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **Lựa chọn doanh nghiệp bảo hiểm có đủ năng lực tài chính để chi trả quyền lợi bảo hiểm.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":30,"category":"Bảo hiểm xe cơ giới","question":"Theo đơn bảo hiểm tai nạn lái, phụ xe và người ngồi trên xe, trong quá trình lưu thông, lái xe sử dụng rượu, bia có nồng độ cồn vượt quá quy định của pháp luật và gây tai nạn. Trong trường hợp này, doanh nghiệp bảo hiểm sẽ trả tiền bảo hiểm như thế nào:","options":[{"key":"A","text":"Không trả tiền bảo hiểm."},{"key":"B","text":"Xem xét trả tiền bảo hiểm cho cả lái xe và người được bảo hiểm khác trên xe."},{"key":"C","text":"Không trả tiền bảo hiểm cho lái xe nhưng xem xét trả tiền bảo hiểm cho người được bảo hiểm khác trên xe."},{"key":"D","text":"Xem xét trả tiền bảo hiểm cho cả lái xe và  người được bảo hiểm khác trên xe và chế tài một khoản tiền bồi thường đối với lái xe."}],"answer":"C","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **C**: **Không trả tiền bảo hiểm cho lái xe nhưng xem xét trả tiền bảo hiểm cho người được bảo hiểm khác trên xe.**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Không trả tiền bảo hiểm cho lái xe nhưng xem xét trả tiền bảo hiểm cho người được bảo hiểm…**."},{"id":33,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, đại lý bảo hiểm có các nghĩa vụ nào sau đây:","options":[{"key":"A","text":"Hưởng hoa hồng đại lý bảo hiểm, thưởng, hỗ trợ đại lý bảo hiểm"},{"key":"B","text":"Cung cấp thông tin khách hàng cho bên thứ ba mà không cần sự chấp thuận của khách hàng"},{"key":"C","text":"Không được tự ý kê khai thông tin cho bên mua bảo hiểm khi chưa có sự đồng ý của bên mua bảo hiểm"},{"key":"D","text":"A, B, C sai"}],"answer":"C","explanation":"Theo đáp án của đề cương, đáp án đúng là **C**: **Không được tự ý kê khai thông tin cho bên mua bảo hiểm khi chưa có sự đồng ý của bên mua bảo hiểm**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Không được tự ý kê khai thông tin cho bên mua bảo hiểm khi chưa có sự đồng ý của bên mua…**."},{"id":36,"category":"Luật Kinh doanh bảo hiểm","question":"Trường hợp sự kiện bảo hiểm xảy ra trong thời gian gia hạn đóng phí và bên mua bảo hiểm chưa đóng đủ phí bảo hiểm, doanh nghiệp bảo hiểm có trách nhiệm chi trả quyền lợi bảo hiểm. Phát biểu trên là:","options":[{"key":"A","text":"Đúng."},{"key":"B","text":"Sai."}],"answer":"A","explanation":"Khái niệm cần nhớ trong câu này là: **Đúng.**. Đáp án đúng là **A**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Đúng.**."},{"id":41,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phát biểu nào sau đây không thuộc về quyền và nghĩa vụ của đại lý bảo hiểm:","options":[{"key":"A","text":"Đại lý bảo hiểm có quyền được hưởng hoa hồng đại lý bảo hiểm, thưởng, hỗ trợ đại lý bảo hiểm và các quyền lợi khác từ hoạt động đại lý bảo hiểm theo thỏa thuận trong hợp đồng đại lý bảo hiểm"},{"key":"B","text":"Đại lý bảo hiểm có thể chủ động giảm phí bảo hiểm, hoàn phí bảo hiểm để khuyến khích khách hàng mua bảo hiểm"},{"key":"C","text":"Đại lý bảo hiểm có quyền được cung cấp thông tin và điều kiện cần thiết để thực hiện hợp đồng đại lý bảo hiểm"},{"key":"D","text":"Đại lý bảo hiểm phải thực hiện nghĩa vụ trong hợp đồng đại lý bảo hiểm"}],"answer":"B","explanation":"Đây là câu hỏi tìm **phương án ngoại lệ/sai**. Theo đáp án của đề cương, phương án **B** là nội dung không phù hợp: **Đại lý bảo hiểm có thể chủ động giảm phí bảo hiểm, hoàn phí bảo hiểm để khuyến khích khách hàng mua bảo hiểm**. Khi làm bài, cần chú ý từ khóa phủ định như **“sai”, “không”, “ngoại trừ”**.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":52,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, trường hợp hợp đồng bảo hiểm có điều khoản không rõ ràng dẫn đến có cách hiểu khác nhau thì điều khoản đó được giải thích theo hướng có lợi cho đối tượng nào sau đây:","options":[{"key":"A","text":"Doanh nghiệp bảo hiểm."},{"key":"B","text":"Bên mua bảo hiểm."},{"key":"C","text":"Bên thứ ba."},{"key":"D","text":"Tùy từng trường hợp."}],"answer":"B","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **B**: **Bên mua bảo hiểm.**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Bên mua bảo hiểm.**."},{"id":53,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, bằng chứng giao kết hợp đồng bảo hiểm là:","options":[{"key":"A","text":"Giấy yêu cầu bảo hiểm, giấy chứng nhận bảo hiểm, đơn bảo hiểm, điện báo, telex, fax và các hình thức khác do pháp luật quy định."},{"key":"B","text":"Hợp đồng, giấy chứng nhận bảo hiểm, đơn bảo hiểm hoặc hình thức khác theo quy định của pháp luật."}],"answer":"B","explanation":"Khái niệm cần nhớ trong câu này là: **Hợp đồng, giấy chứng nhận bảo hiểm, đơn bảo hiểm hoặc hình thức khác theo quy định của pháp luật.**. Đáp án đúng là **B**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Hợp đồng, giấy chứng nhận bảo hiểm, đơn bảo hiểm hoặc hình thức khác theo quy định của pháp…**."},{"id":70,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, đại lý bảo hiểm không có quyền và nghĩa vụ nào sau đây:","options":[{"key":"A","text":"Hưởng hoa hồng đại lý bảo hiểm, thưởng, hỗ trợ đại lý bảo hiểm theo thỏa thuận trong hợp đồng đại lý bảo hiểm"},{"key":"B","text":"Thực hiện cam kết trong hợp đồng bảo hiểm được ký giữa bên mua bảo hiểm và doanh nghiệp bảo hiểm."},{"key":"C","text":"Tư vấn, giới thiệu, chào bán sản phẩm bảo hiểm; cung cấp các thông tin về sản phẩm bảo hiểm, doanh nghiệp bảo hiểm đầy đủ, chính xác cho bên mua bảo hiểm."},{"key":"D","text":"Thực hiện nghĩa vụ trong hợp đồng đại lý bảo hiểm."}],"answer":"B","explanation":"Đây là câu hỏi tìm **phương án ngoại lệ/sai**. Theo đáp án của đề cương, phương án **B** là nội dung không phù hợp: **Thực hiện cam kết trong hợp đồng bảo hiểm được ký giữa bên mua bảo hiểm và doanh nghiệp bảo hiểm.**. Khi làm bài, cần chú ý từ khóa phủ định như **“sai”, “không”, “ngoại trừ”**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Thực hiện cam kết trong hợp đồng bảo hiểm được ký giữa bên mua bảo hiểm và doanh nghiệp bảo…**."},{"id":72,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, chọn phương án sai về quyền của doanh nghiệp bảo hiểm:","options":[{"key":"A","text":"Bồi thường cho người được bảo hiểm những thiệt hại thuộc trách nhiệm bảo hiểm khi xảy ra sự kiện bảo hiểm."},{"key":"B","text":"Thu phí bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm."},{"key":"C","text":"Yêu cầu bên mua bảo hiểm cung cấp đầy đủ, trung thực thông tin liên quan đến việc giao kết và thực hiện hợp đồng bảo hiểm."},{"key":"D","text":"Từ chối trả tiền bảo hiểm cho người thụ hưởng hoặc từ chối bồi thường cho người được bảo hiểm trong trường hợp không thuộc phạm vi trách nhiệm bảo hiểm hoặc trường hợp loại trừ trách nhiệm bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm."}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Bồi thường cho người được bảo hiểm những thiệt hại thuộc trách nhiệm bảo hiểm khi xảy ra sự kiện bảo hiểm.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":76,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm,  chọn phương án đúng nhất:","options":[{"key":"A","text":"Doanh nghiệp bảo hiểm được quyết định mức chi trả hoa hồng đại lý bảo hiểm"},{"key":"B","text":"Doanh nghiệp bảo hiểm được quyết định mức chi trả hoa hồng đại lý bảo hiểm, thưởng, hỗ trợ đại lý bảo hiểm và quyền lợi khác trong hợp đồng đại lý bảo hiểm không vượt quá mức tối đa theo quy định của Bộ trưởng Bộ Tài chính"},{"key":"C","text":"Doanh nghiệp bảo hiểm được quyết định mức chi trả thưởng, hỗ trợ đại lý bảo hiểm"},{"key":"D","text":"Doanh nghiệp bảo hiểm được quyết định mức chi trả quyền lợi khác trong hợp đồng đại lý bảo hiểm"}],"answer":"B","explanation":"Theo đáp án của đề cương, phương án **B** là nội dung đúng: **Doanh nghiệp bảo hiểm được quyết định mức chi trả hoa hồng đại lý bảo hiểm, thưởng, hỗ trợ đại lý bảo hiểm và quyền lợi khác trong hợp đồng đại lý bảo hiểm không vượt quá mức tối đa theo quy định của Bộ trưởng Bộ Tài chính**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Doanh nghiệp bảo hiểm được quyết định mức chi trả hoa hồng đại lý bảo hiểm, thưởng, hỗ trợ…**."},{"id":80,"category":"Luật Kinh doanh bảo hiểm","question":"Chọn phương án đúng điền vào chỗ _______: \"Theo Luật Kinh doanh bảo hiểm, trường hợp đại lý bảo hiểm vi phạm hợp đồng đại lý bảo hiểm, gây thiệt hại đến quyền, lợi ích hợp pháp của người được bảo hiểm thì _______ phải chịu trách nhiệm thực hiện các nghĩa vụ theo thỏa thuận trong hợp đồng bảo hiểm do đại lý bảo hiểm thu xếp giao kết\".","options":[{"key":"A","text":"Doanh nghiệp bảo hiểm"},{"key":"B","text":"Đại lý bảo hiểm"},{"key":"C","text":"Người mua bảo hiểm"},{"key":"D","text":"Doanh nghiệp bảo hiểm và đại lý bảo hiểm"}],"answer":"A","explanation":"Theo đáp án của đề cương, phương án **A** là nội dung đúng: **Doanh nghiệp bảo hiểm**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Doanh nghiệp bảo hiểm**."},{"id":82,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phát biểu nào sau đây đúng:","options":[{"key":"A","text":"Doanh nghiệp bảo hiểm có thể ủy quyền cho đại lý bảo hiểm thu phí bảo hiểm"},{"key":"B","text":"Cá nhân có quyền đồng thời làm đại lý bảo hiểm cho mọi doanh nghiệp bảo hiểm"},{"key":"C","text":"Đại lý bảo hiểm có thể được doanh nghiệp bảo hiểm ủy quyền ký kết hợp đồng bảo hiểm với bên mua bảo hiểm"},{"key":"D","text":"A, B, C đúng"}],"answer":"A","explanation":"Theo đáp án của đề cương, phương án **A** là nội dung đúng: **Doanh nghiệp bảo hiểm có thể ủy quyền cho đại lý bảo hiểm thu phí bảo hiểm**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Doanh nghiệp bảo hiểm có thể ủy quyền cho đại lý bảo hiểm thu phí bảo hiểm**."},{"id":100,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, chọn phương án đúng nhất về “Nguyên tắc bồi thường”:","options":[{"key":"A","text":"Số tiền bồi thường mà người được bảo hiểm nhận được không vượt quá thiệt hại thực tế trong sự kiện bảo hiểm, trừ trường hợp có thỏa thuận khác trong hợp đồng bảo hiểm."},{"key":"B","text":"Số tiền bồi thường mà người được bảo hiểm nhận được có thể lớn hơn thiệt hại thực tế trong sự kiện bảo hiểm."},{"key":"C","text":"Số tiền bồi thường mà người được bảo hiểm nhận được tùy thuộc vào thỏa thuận giữa doanh nghiệp bảo hiểm và người được bảo hiểm trong hợp đồng bảo hiểm."},{"key":"D","text":"B, C đúng."}],"answer":"A","explanation":"Theo đáp án của đề cương, phương án **A** là nội dung đúng: **Số tiền bồi thường mà người được bảo hiểm nhận được không vượt quá thiệt hại thực tế trong sự kiện bảo hiểm, trừ trường hợp có thỏa thuận khác trong hợp đồng bảo hiểm.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Số tiền bồi thường mà người được bảo hiểm nhận được không vượt quá thiệt hại thực tế trong…**."},{"id":153,"category":"Kiến thức chung","question":"Chọn phương án đúng nhất về giá trị bảo hiểm:","options":[{"key":"A","text":"Giá trị bảo hiểm là giá thị trường của tài sản được bảo hiểm tại thời điểm giao kết hợp đồng bảo hiểm."},{"key":"B","text":"Giá trị bảo hiểm là giá trị còn lại của tài sản được bảo hiểm theo giá trị sổ sách."},{"key":"C","text":"A, B đúng."}],"answer":"A","explanation":"Theo đáp án của đề cương, phương án **A** là nội dung đúng: **Giá trị bảo hiểm là giá thị trường của tài sản được bảo hiểm tại thời điểm giao kết hợp đồng bảo hiểm.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Giá trị bảo hiểm là giá thị trường của tài sản được bảo hiểm tại thời điểm giao kết hợp…**."},{"id":182,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, hợp đồng đại lý bảo hiểm không bắt buộc phải có nội dung nào dưới đây:","options":[{"key":"A","text":"Quyền và nghĩa vụ của doanh nghiệp bảo hiểm"},{"key":"B","text":"Ký quỹ, tài sản thế chấp của đại lý bảo hiểm"},{"key":"C","text":"Hoa hồng đại lý bảo hiểm, thưởng, hỗ trợ đại lý bảo hiểm và các quyền lợi khác (nếu có); Thời hạn hợp đồng; Phương thức giải quyết tranh chấp"},{"key":"D","text":"Phương thức giải quyết tranh chấp"}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án đúng là **B**: **Ký quỹ, tài sản thế chấp của đại lý bảo hiểm**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Ký quỹ, tài sản thế chấp của đại lý bảo hiểm**."},{"id":207,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, cơ quan chịu trách nhiệm trước Chính phủ thực hiện quản lý nhà nước về hoạt động kinh doanh bảo hiểm là:","options":[{"key":"A","text":"Bộ Tài chính."},{"key":"B","text":"Bộ Công Thương."},{"key":"C","text":"Bộ Công an."},{"key":"D","text":"Bộ Lao động - Thương binh và Xã hội."}],"answer":"A","explanation":"Khái niệm cần nhớ trong câu này là: **Bộ Tài chính.**. Đáp án đúng là **A**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Bộ Tài chính.**."},{"id":241,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phương án nào sau đây đúng:","options":[{"key":"A","text":"Đại lý bảo hiểm được hưởng hoa hồng đại lý bảo hiểm theo thỏa thuận trong hợp đồng đại lý bảo hiểm"},{"key":"B","text":"Đại lý bảo hiểm có quyền yêu cầu doanh nghiệp bảo hiểm hoàn trả tiền ký quỹ hoặc tài sản thế chấp theo thỏa thuận trong hợp đồng đại lý bảo hiểm"},{"key":"C","text":"Đại lý bảo hiểm là người đại diện cho bên mua bảo hiểm"},{"key":"D","text":"A, B đúng."}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **A, B đúng.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B đúng.**."},{"id":3,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, chọn phương án đúng điền vào chỗ ______ trong câu sau:\n\"Hợp đồng bảo hiểm trùng là trường hợp có từ hai hợp đồng bảo hiểm trở lên để bảo hiểm cho cùng phạm vi, _______, thời hạn và sự kiện bảo hiểm mà tổng số tiền bảo hiểm vượt quá giá thị trường của tài sản được bảo hiểm tại thời điểm giao kết hợp đồng bảo hiểm\".","options":[{"key":"A","text":"Bên mua bảo hiểm"},{"key":"B","text":"Đối tượng"},{"key":"C","text":"Người được bảo hiểm"},{"key":"D","text":"A, B, C đúng"}],"answer":"B","explanation":"Theo đáp án của đề cương, phương án **B** là nội dung đúng: **Đối tượng**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Đối tượng**."},{"id":4,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phát biểu nào sau đây đúng:","options":[{"key":"A","text":"Luật kinh doanh bảo hiểm không áp dụng đối với bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm tiền gửi và các loại bảo hiểm khác do Nhà nước thực hiện không mang tính kinh doanh."},{"key":"B","text":"Các bên tham gia bảo hiểm không được thỏa thuận áp dụng tập quán quốc tế trong mọi trường hợp."},{"key":"C","text":"A, B đúng"},{"key":"D","text":"A, B sai"}],"answer":"A","explanation":"Theo đáp án của đề cương, phương án **A** là nội dung đúng: **Luật kinh doanh bảo hiểm không áp dụng đối với bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm tiền gửi và các loại bảo hiểm khác do Nhà nước thực hiện không mang tính kinh doanh.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Luật kinh doanh bảo hiểm không áp dụng đối với bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm…**."},{"id":6,"category":"Luật Kinh doanh bảo hiểm","question":"Chọn phương án đúng nhất về chuyển giao hợp đồng bảo hiểm:","options":[{"key":"A","text":"Việc chuyển giao hợp đồng bảo hiểm phải được thỏa thuận tại hợp đồng bảo hiểm."},{"key":"B","text":"Bên nhận chuyển giao hợp đồng bảo hiểm phải có quyền lợi có thể được bảo hiểm, được kế thừa quyền và nghĩa vụ của bên chuyển giao."},{"key":"C","text":"Bên mua bảo hiểm thông báo bằng văn bản cho doanh nghiệp bảo hiểm về việc chuyển giao hợp đồng bảo hiểm và được doanh nghiệp bảo hiểm chấp thuận bằng văn bản, trừ trường hợp việc chuyển giao được thực hiện theo tập quán quốc tế hoặc theo thỏa thuận trong hợp đồng bảo hiểm."},{"key":"D","text":"B, C đúng."}],"answer":"D","explanation":"Theo đáp án của đề cương, phương án **D** là nội dung đúng: **B, C đúng.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **B, C đúng.**."},{"id":8,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, doanh nghiệp bảo hiểm được chi trả hoa hồng bảo hiểm cho đối tượng nào dưới đây:","options":[{"key":"A","text":"Đại lý bảo hiểm"},{"key":"B","text":"Doanh nghiệp môi giới bảo hiểm"},{"key":"C","text":"Bên mua bảo hiểm"},{"key":"D","text":"A, B đúng"}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **A, B đúng**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B đúng**."},{"id":9,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, nội dung nào dưới đây không bắt buộc phải có trong hợp đồng bảo hiểm:","options":[{"key":"A","text":"Bên mua bảo hiểm, người được bảo hiểm, người thụ hưởng (nếu có), doanh nghiệp bảo hiểm hoặc chi nhánh doanh nghiệp bảo hiểm phi nhân thọ nước ngoài."},{"key":"B","text":"Đối tượng bảo hiểm; Số tiền bảo hiểm hoặc giá trị tài sản được bảo hiểm hoặc giới hạn trách nhiệm bảo hiểm."},{"key":"C","text":"Mức phí bảo hiểm, phương thức đóng phí bảo hiểm; Phương thức bồi thường, trả tiền bảo hiểm; Phương thức giải quyết tranh chấp."},{"key":"D","text":"Thu nhập của bên mua bảo hiểm."}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **Thu nhập của bên mua bảo hiểm.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Thu nhập của bên mua bảo hiểm.**."},{"id":10,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, nội dung chủ yếu đào tạo chứng chỉ đại lý bảo hiểm bao gồm:","options":[{"key":"A","text":"Kiến thức chung về bảo hiểm; Pháp luật Việt Nam về hoạt động kinh doanh bảo hiểm"},{"key":"B","text":"Quy tắc đạo đức, ứng xử nghề nghiệp đại lý bảo hiểm; Quyền và nghĩa vụ của doanh nghiệp bảo hiểm, đại lý bảo hiểm trong hoạt động đại lý bảo hiểm"},{"key":"C","text":"Kỹ năng và thực hành hành nghề đại lý bảo hiểm."},{"key":"D","text":"A, B, C đúng"}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **A, B, C đúng**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng**."},{"id":11,"category":"Luật Kinh doanh bảo hiểm","question":"Chọn phương án đúng nhất về loại hợp đồng bảo hiểm quy định tại Luật kinh doanh bảo hiểm:","options":[{"key":"A","text":"Hợp đồng bảo hiểm sức khỏe."},{"key":"B","text":"Hợp đồng bảo hiểm tài sản."},{"key":"C","text":"Hợp đồng bảo hiểm trách nhiệm"},{"key":"D","text":"A, B, C đúng."}],"answer":"D","explanation":"Theo đáp án của đề cương, phương án **D** là nội dung đúng: **A, B, C đúng.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng.**."},{"id":12,"category":"Luật Kinh doanh bảo hiểm","question":"Chọn phương án đúng nhất về loại trừ bảo hiểm:","options":[{"key":"A","text":"Loại trừ bảo hiểm là loại trừ các rủi ro, tổn thất mà doanh nghiệp bảo hiểm không chịu trách nhiệm bồi thường, trả tiền bảo hiểm nếu xảy ra sự kiện bảo hiểm."},{"key":"B","text":"Loại trừ bảo hiểm là loại trừ các rủi ro, tổn thất và chi phí phát sinh mà doanh nghiệp bảo hiểm không chịu trách nhiệm bồi thường, trả tiền bảo hiểm nếu xảy ra sự kiện bảo hiểm."},{"key":"C","text":"Loại trừ bảo hiểm được căn cứ theo các điều kiện, điều khoản loại trừ bảo hiểm quy định trong Quy tắc bảo hiểm và các điều khoản sửa đổi, bổ sung (nếu có) kèm theo hợp đồng bảo hiểm."},{"key":"D","text":"A, C đúng."},{"key":"E","text":"B, C đúng."}],"answer":"D","explanation":"Theo đáp án của đề cương, phương án **D** là nội dung đúng: **A, C đúng.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, C đúng.**."},{"id":13,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phát biểu nào sau đây đúng về việc chuyển giao hợp đồng bảo hiểm:","options":[{"key":"A","text":"Bên mua bảo hiểm không có quyền chuyển giao hợp đồng bảo hiểm."},{"key":"B","text":"Bên mua bảo hiểm có quyền chuyển giao hợp đồng bảo hiểm."},{"key":"C","text":"Bên mua bảo hiểm có thể chuyển giao hợp đồng bảo hiểm cho bất kỳ người nào."}],"answer":"B","explanation":"Theo đáp án của đề cương, phương án **B** là nội dung đúng: **Bên mua bảo hiểm có quyền chuyển giao hợp đồng bảo hiểm.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Bên mua bảo hiểm có quyền chuyển giao hợp đồng bảo hiểm.**."},{"id":14,"category":"Luật Kinh doanh bảo hiểm","question":"Trong quá trình thực hiện hợp đồng bảo hiểm, doanh nghiệp bảo hiểm có quyền hủy bỏ hợp đồng bảo hiểm trong trường hợp nào sau đây:","options":[{"key":"A","text":"Bên mua bảo hiểm cố ý cung cấp không đầy đủ thông tin  nhằm giao kết hợp đồng bảo hiểm để được bồi thường, trả tiền bảo hiểm."},{"key":"B","text":"Bên mua bảo hiểm cung cấp thông tin sai sự thật nhằm giao kết hợp đồng bảo hiểm để được bồi thường, trả tiền bảo hiểm."},{"key":"C","text":"A, B đúng."},{"key":"D","text":"A, B sai."}],"answer":"C","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **C**: **A, B đúng.**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B đúng.**."},{"id":16,"category":"Luật Kinh doanh bảo hiểm","question":"Người có quyền chiếm hữu đối với tài sản thì có \"Quyền lợi có thể được bảo hiểm\" đối với tài sản đó:","options":[{"key":"A","text":"Đúng."},{"key":"B","text":"Sai."}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Đúng.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Đúng.**."},{"id":17,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, trường hợp không có thỏa thuận trong hợp đồng bảo hiểm về thời hạn bồi thường, trả tiền bảo hiểm, doanh nghiệp bảo hiểm phải bồi thường, trả tiền bảo hiểm trong thời hạn:","options":[{"key":"A","text":"15 ngày kể từ ngày nhận được đầy đủ hồ sơ hợp lệ về yêu cầu bồi thường, trả tiền bảo hiểm."},{"key":"B","text":"30 ngày kể từ ngày nhận được đầy đủ hồ sơ hợp lệ về yêu cầu bồi thường, trả tiền bảo hiểm."},{"key":"C","text":"45 ngày kể từ ngày nhận được đầy đủ hồ sơ hợp lệ về yêu cầu bồi thường, trả tiền bảo hiểm."},{"key":"D","text":"60 ngày kể từ ngày nhận được đầy đủ hồ sơ hợp lệ về yêu cầu bồi thường, trả tiền bảo hiểm."}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án **A** là **15 ngày kể từ ngày nhận được đầy đủ hồ sơ hợp lệ về yêu cầu bồi thường, trả tiền bảo hiểm.**. Mốc cần nhớ: **15 ngày**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Chốt mốc **15 ngày** và gắn với đúng điều kiện của câu."},{"id":18,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, đối với bảo hiểm tài sản, trường hợp người được bảo hiểm từ chối chuyển quyền yêu cầu người thứ ba bồi hoàn, doanh nghiệp bảo hiểm có quyền:","options":[{"key":"A","text":"Khấu trừ số tiền bồi thường tuỳ theo mức độ lỗi của người được bảo hiểm."},{"key":"B","text":"Hủy bỏ hợp đồng bảo hiểm."},{"key":"C","text":"Trực tiếp yêu cầu người thứ ba bồi thường"},{"key":"D","text":"A, C đúng."}],"answer":"A","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **A**: **Khấu trừ số tiền bồi thường tuỳ theo mức độ lỗi của người được bảo hiểm.**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Khấu trừ số tiền bồi thường tuỳ theo mức độ lỗi của người được bảo hiểm.**."},{"id":19,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phát biểu nào sau đây sai về quyền và nghĩa vụ của doanh nghiệp bảo hiểm:","options":[{"key":"A","text":"Doanh nghiệp bảo hiểm có quyền từ chối bồi thường, trả tiền bảo hiểm trong trường hợp không thuộc phạm vi trách nhiệm bảo hiểm theo thoả thuận trong hợp đồng bảo hiểm"},{"key":"B","text":"Doanh nghiệp bảo hiểm có quyền từ chối bồi thường, trả tiền bảo hiểm trong trường hợp loại trừ trách nhiệm bảo hiểm theo thoả thuận trong hợp đồng bảo hiểm."},{"key":"C","text":"Doanh nghiệp bảo hiểm không được áp dụng loại trừ trách nhiệm bảo hiểm về việc chậm thông báo trong mọi trường hợp"},{"key":"D","text":"A, B đúng"}],"answer":"C","explanation":"Đây là câu hỏi tìm **phương án ngoại lệ/sai**. Theo đáp án của đề cương, phương án **C** là nội dung không phù hợp: **Doanh nghiệp bảo hiểm không được áp dụng loại trừ trách nhiệm bảo hiểm về việc chậm thông báo trong mọi trường hợp**. Khi làm bài, cần chú ý từ khóa phủ định như **“sai”, “không”, “ngoại trừ”**.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":21,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Theo Quy tắc bảo hiểm “Mọi rủi ro tài sản” của Hiệp hội bảo hiểm Vương quốc Anh (ABI), thiệt hại vật chất đối với tài sản được bảo hiểm do cháy hoặc nổ phát sinh từ việc trục trặc của các dữ liệu điện tử có được bảo hiểm không?","options":[{"key":"A","text":"Không."},{"key":"B","text":"Có, nếu không bị loại trừ bởi các điều kiện khác của Quy tắc này."}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án đúng là **B**: **Có, nếu không bị loại trừ bởi các điều kiện khác của Quy tắc này.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Có, nếu không bị loại trừ bởi các điều kiện khác của Quy tắc này.**."},{"id":22,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, tổ chức, cá nhân được bên mua bảo hiểm hoặc người được bảo hiểm chỉ định để nhận tiền bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm là:","options":[{"key":"A","text":"Người được bảo hiểm."},{"key":"B","text":"Người thụ hưởng."},{"key":"C","text":"Người bảo hiểm."},{"key":"D","text":"Người tham gia bảo hiểm."}],"answer":"B","explanation":"Khái niệm cần nhớ trong câu này là: **Người thụ hưởng.**. Đáp án đúng là **B**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Người thụ hưởng.**."},{"id":23,"category":"Bảo hiểm con người","question":"Ông A tham gia 02 hợp đồng bảo hiểm chi phí y tế tại 02 doanh nghiệp bảo hiểm X và Y, giới hạn chi trả chi phí y tế tại mỗi hợp đồng bảo hiểm là 10 triệu đồng/lần nằm viện. Trong thời hạn bảo hiểm, ông A nằm viện điều trị, chi phí cho đợt nằm viện này là 6 triệu đồng. Số tiền mà ông A sẽ được các doanh nghiệp bảo hiểm chi trả cho đợt nằm viện điều trị này là:","options":[{"key":"A","text":"6 triệu đồng."},{"key":"B","text":"10 triệu đồng."},{"key":"C","text":"12 triệu đồng."}],"answer":"A","explanation":"Khái niệm cần nhớ trong câu này là: **6 triệu đồng.**. Đáp án đúng là **A**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Chốt mốc **6 triệu** và gắn với đúng điều kiện của câu."},{"id":24,"category":"Bảo hiểm con người","question":"Khi tham gia bảo hiểm sức khỏe với quyền lợi bảo hiểm thương tật do tai nạn, trường hợp người được bảo hiểm bị thương tật bộ phận do tai nạn, doanh nghiệp bảo hiểm sẽ chi trả số tiền nào sau đây?","options":[{"key":"A","text":"100% số tiền bảo hiểm."},{"key":"B","text":"Số tiền chi trả tính theo bảng tỷ lệ bồi thường thương tật."},{"key":"C","text":"Số tiền chi phí xét nghiệm do người được bảo hiểm yêu cầu."},{"key":"D","text":"A, B, C đúng."}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án **B** là **Số tiền chi trả tính theo bảng tỷ lệ bồi thường thương tật.**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Số tiền chi trả tính theo bảng tỷ lệ bồi thường thương tật.**."},{"id":26,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, đại lý bảo hiểm không được thực hiện các hành vi nào sau đây:","options":[{"key":"A","text":"Thông tin, quảng cáo sai sự thật về nội dung, phạm vi hoạt động của doanh nghiệp bảo hiểm, điều kiện và điều khoản bảo hiểm làm tổn hại đến quyền, lợi ích hợp pháp của bên mua bảo hiểm."},{"key":"B","text":"Ngăn cản bên mua bảo hiểm cung cấp các thông tin liên quan đến hợp đồng bảo hiểm."},{"key":"C","text":"Tranh giành khách hàng dưới các hình thức ngăn cản, lôi kéo, mua chuộc, đe dọa nhân viên hoặc khách hàng của doanh nghiệp bảo hiểm khác."},{"key":"D","text":"A, B, C đúng."}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **A, B, C đúng.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng.**."},{"id":27,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, đối với các hợp đồng bảo hiểm (trừ bảo hiểm trách nhiệm), trường hợp không có thỏa thuận trong hợp đồng bảo hiểm và người được bảo hiểm hoặc người thụ hưởng không chứng minh được rằng không biết thời điểm xảy ra sự kiện bảo hiểm, thì thời hạn nộp hồ sơ yêu cầu bồi thường, trả tiền bảo hiểm theo hợp đồng bảo hiểm là:","options":[{"key":"A","text":"03 tháng kể từ ngày xảy ra sự kiện bảo hiểm (trừ sự kiện bất khả kháng hoặc trở ngại khách quan)"},{"key":"B","text":"01 năm kể từ ngày xảy ra sự kiện bảo hiểm (trừ sự kiện bất khả kháng hoặc trở ngại khách quan)"},{"key":"C","text":"06 tháng kể từ ngày xảy ra sự kiện bảo hiểm (trừ sự kiện bất khả kháng hoặc trở ngại khách quan)"},{"key":"D","text":"09 tháng kể từ ngày xảy ra sự kiện bảo hiểm (trừ sự kiện bất khả kháng hoặc trở ngại khách quan)"}],"answer":"B","explanation":"Khái niệm cần nhớ trong câu này là: **01 năm kể từ ngày xảy ra sự kiện bảo hiểm (trừ sự kiện bất khả kháng hoặc trở ngại khách quan)**. Đáp án đúng là **B**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Chốt mốc **01 năm** và gắn với đúng điều kiện của câu."},{"id":28,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phát biểu nào sau đây là đúng về bảo hiểm bắt buộc:","options":[{"key":"A","text":"Doanh nghiệp bảo hiểm được phép triển khai bảo hiểm bắt buộc không được từ chối bán khi tổ chức, cá nhân đáp ứng đủ điều kiện mua bảo hiểm bắt buộc theo quy định của pháp luật."},{"key":"B","text":"Tổ chức, cá nhân thuộc đối tượng tham gia bảo hiểm bắt buộc có nghĩa vụ mua bảo hiểm bắt buộc và được lựa chọn tham gia bảo hiểm bắt buộc tại doanh nghiệp bảo hiểm được phép triển khai."},{"key":"C","text":"A, B đúng"},{"key":"D","text":"A, B sai"}],"answer":"C","explanation":"Theo đáp án của đề cương, đáp án đúng là **C**: **A, B đúng**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B đúng**."},{"id":29,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, hợp đồng bảo hiểm vô hiệu trong trường hợp nào sau đây:","options":[{"key":"A","text":"Tại thời điểm giao kết hợp đồng bảo hiểm, bên mua bảo hiểm biết sự kiện bảo hiểm đã xảy ra."},{"key":"B","text":"Tại thời điểm giao kết hợp đồng bảo hiểm không có đối tượng bảo hiểm."},{"key":"C","text":"Tại thời điểm giao kết hợp đồng bảo hiểm, bên mua bảo hiểm không có quyền lợi có thể được bảo hiểm."},{"key":"D","text":"A, B, C đúng."}],"answer":"D","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **D**: **A, B, C đúng.**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng.**."},{"id":31,"category":"Kiến thức chung","question":"Phát biểu nào sau đây là đúng nhất về rủi ro loại trừ:","options":[{"key":"A","text":"Là rủi ro không thể được bảo hiểm."},{"key":"B","text":"Là rủi ro có thể được bảo hiểm nhưng doanh nghiệp bảo hiểm không chấp nhận bảo hiểm."},{"key":"C","text":"A, B đúng."},{"key":"D","text":"A, B sai."}],"answer":"C","explanation":"Theo đáp án của đề cương, đáp án đúng là **C**: **A, B đúng.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B đúng.**."},{"id":32,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Bên thứ ba trong bảo hiểm trách nhiệm nghề nghiệp tư vấn đầu tư xây dựng là:","options":[{"key":"A","text":"Người được bảo hiểm."},{"key":"B","text":"Bên mua bảo hiểm."},{"key":"C","text":"Doanh nghiệp bảo hiểm."},{"key":"D","text":"Nhà dân cạnh công trình xây dựng được bảo hiểm"}],"answer":"D","explanation":"Khái niệm cần nhớ trong câu này là: **Nhà dân cạnh công trình xây dựng được bảo hiểm**. Đáp án đúng là **D**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Nhà dân cạnh công trình xây dựng được bảo hiểm**."},{"id":34,"category":"Bảo hiểm xe cơ giới","question":"Trong khi lưu thông, xe A đâm xe B làm xe B mất kiểm soát và va chạm với người đi đường gây tai nạn. Nguyên nhân gây tai nạn cho người đi đường do xe A là nguyên nhân trực tiếp. Kết luận này là:","options":[{"key":"A","text":"Đúng."},{"key":"B","text":"Sai."}],"answer":"A","explanation":"Khái niệm cần nhớ trong câu này là: **Đúng.**. Đáp án đúng là **A**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Đúng.**."},{"id":35,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, trừ trường hợp có thoả thuận khác trong hợp đồng bảo hiểm, doanh nghiệp bảo hiểm không chịu trách nhiệm bồi thường trong trường hợp tài sản được bảo hiểm bị tổn thất do:","options":[{"key":"A","text":"Hao mòn tự nhiên"},{"key":"B","text":"Bản chất vốn có của tài sản"},{"key":"C","text":"A, B đúng"}],"answer":"C","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **C**: **A, B đúng**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B đúng**."},{"id":37,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phát biểu nào sau đây sai:","options":[{"key":"A","text":"Bên mua bảo hiểm là tổ chức, cá nhân giao kết hợp đồng bảo hiểm với doanh nghiệp bảo hiểm và đóng phí bảo hiểm."},{"key":"B","text":"Bên mua bảo hiểm phải có quyền lợi có thể được bảo hiểm phù hợp với từng loại hợp đồng bảo hiểm theo quy định của Luật Kinh doanh bảo hiểm."},{"key":"C","text":"Bên mua bảo hiểm là cá nhân được người thụ hưởng chỉ định để đóng phí bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm."},{"key":"D","text":"Bên mua bảo hiểm có quyền lựa chọn doanh nghiệp bảo hiểm để giao kết hợp đồng bảo hiểm."}],"answer":"C","explanation":"Đây là câu hỏi tìm **phương án ngoại lệ/sai**. Theo đáp án của đề cương, phương án **C** là nội dung không phù hợp: **Bên mua bảo hiểm là cá nhân được người thụ hưởng chỉ định để đóng phí bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm.**. Khi làm bài, cần chú ý từ khóa phủ định như **“sai”, “không”, “ngoại trừ”**.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":38,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Đối tượng nào sau đây không phải là người được bảo hiểm trong bảo hiểm trách nhiệm nghề nghiệp:","options":[{"key":"A","text":"Doanh nghiệp tái bảo hiểm."},{"key":"B","text":"Doanh nghiệp môi giới bảo hiểm."},{"key":"C","text":"Bác sỹ, y tá, hộ lý."}],"answer":"A","explanation":"Đây là câu hỏi tìm **phương án ngoại lệ/sai**. Theo đáp án của đề cương, phương án **A** là nội dung không phù hợp: **Doanh nghiệp tái bảo hiểm.**. Khi làm bài, cần chú ý từ khóa phủ định như **“sai”, “không”, “ngoại trừ”**.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":39,"category":"Bảo hiểm xe cơ giới","question":"Trường hợp nào sau đây thuộc trách nhiệm bảo hiểm trách nhiệm dân sự của chủ xe cơ giới đối với hàng hóa trên xe:","options":[{"key":"A","text":"Nước mưa chảy qua lỗ thủng bạt che làm hàng hóa bị tổn thất"},{"key":"B","text":"Xe bị nổ lốp gây tai nạn làm hàng hóa trên xe bị tổn thất"},{"key":"C","text":"Hàng hóa bị tổn thất do mốc trong quá trình vận chuyển."},{"key":"D","text":"Hàng bị tổn thất do va đập vào nhau trong quá trình vận chuyển."}],"answer":"B","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **B**: **Xe bị nổ lốp gây tai nạn làm hàng hóa trên xe bị tổn thất**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Xe bị nổ lốp gây tai nạn làm hàng hóa trên xe bị tổn thất**."},{"id":40,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, đối tượng nào sau đây được ủy quyền cho đại lý bảo hiểm trên cơ sở hợp đồng đại lý bảo hiểm để thực hiện các hoạt động đại lý bảo hiểm:","options":[{"key":"A","text":"Doanh nghiệp môi giới bảo hiểm"},{"key":"B","text":"Doanh nghiệp bảo hiểm"},{"key":"C","text":"Bên mua bảo hiểm"},{"key":"D","text":"A, B, C đúng"}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án đúng là **B**: **Doanh nghiệp bảo hiểm**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Doanh nghiệp bảo hiểm**."},{"id":42,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật kinh doanh bảo hiểm, câu trả lời nào sau đây là đúng nhất về hợp đồng bảo hiểm trùng?","options":[{"key":"A","text":"Hợp đồng bảo hiểm trùng là trường hợp bên mua bảo hiểm giao kết hợp đồng bảo hiểm với hai doanh nghiệp bảo hiểm trở lên để bảo hiểm cho cùng một đối tượng bảo hiểm"},{"key":"B","text":"Hợp đồng bảo hiểm trùng là trường hợp bên mua bảo hiểm giao kết nhiều hợp đồng bảo hiểm với một doanh nghiệp bảo hiểm để bảo hiểm cho cùng một đối tượng bảo hiểm"},{"key":"C","text":"Hợp đồng bảo hiểm trùng là trường hợp có từ hai hợp đồng bảo hiểm trở lên để bảo hiểm cho cùng phạm vi, đối tượng, thời hạn và sự kiện bảo hiểm mà tổng số tiền bảo hiểm vượt quá giá thị trường của tài sản được bảo hiểm tại thời điểm giao kết hợp đồng bảo hiểm."},{"key":"D","text":"A, B, C sai"}],"answer":"C","explanation":"Theo đáp án của đề cương, đáp án đúng là **C**: **Hợp đồng bảo hiểm trùng là trường hợp có từ hai hợp đồng bảo hiểm trở lên để bảo hiểm cho cùng phạm vi, đối tượng, thời hạn và sự kiện bảo hiểm mà tổng số tiền bảo hiểm vượt quá giá thị trường của tài sản được bảo hiểm tại thời điểm giao kết hợp đồng bảo hiểm.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Hợp đồng bảo hiểm trùng là trường hợp có từ hai hợp đồng bảo hiểm trở lên để bảo hiểm cho…**."},{"id":43,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, vốn điều lệ của doanh nghiệp bảo hiểm là:","options":[{"key":"A","text":"Tổng số tiền do thành viên đã góp hoặc cam kết góp khi thành lập công ty trách nhiệm hữu hạn và được ghi vào điều lệ của doanh nghiệp bảo hiểm."},{"key":"B","text":"Tổng giá trị mệnh giá cổ phần đã bán hoặc được đăng ký mua khi thành lập công ty cổ phần và được ghi vào điều lệ của doanh nghiệp bảo hiểm."},{"key":"C","text":"A, B đúng"}],"answer":"C","explanation":"Khái niệm cần nhớ trong câu này là: **A, B đúng**. Đáp án đúng là **C**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B đúng**."},{"id":44,"category":"Luật Kinh doanh bảo hiểm","question":"Luật Kinh doanh bảo hiểm quy định về các loại hợp đồng bảo hiểm nào sau đây:","options":[{"key":"A","text":"Hợp đồng bảo hiểm nhân thọ."},{"key":"B","text":"Hợp đồng bảo hiểm sức khỏe."},{"key":"C","text":"Hợp đồng bảo hiểm trách nhiệm."},{"key":"D","text":"A, B, C đúng"}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **A, B, C đúng**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng**."},{"id":45,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phát biểu nào dưới đây đúng:","options":[{"key":"A","text":"Người được bảo hiểm là tổ chức, cá nhân có tài sản, trách nhiệm dân sự, sức khỏe, tính mạng, nghĩa vụ hoặc lợi ích kinh tế được bảo hiểm theo hợp đồng bảo hiểm."},{"key":"B","text":"Phí bảo hiểm là khoản tiền mà đại lý bảo hiểm phải đóng cho doanh nghiệp bảo hiểm theo quy định của pháp luật hoặc do các bên thỏa thuận trong hợp đồng bảo hiểm."},{"key":"C","text":"A, B đúng"}],"answer":"A","explanation":"Theo đáp án của đề cương, phương án **A** là nội dung đúng: **Người được bảo hiểm là tổ chức, cá nhân có tài sản, trách nhiệm dân sự, sức khỏe, tính mạng, nghĩa vụ hoặc lợi ích kinh tế được bảo hiểm theo hợp đồng bảo hiểm.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Người được bảo hiểm là tổ chức, cá nhân có tài sản, trách nhiệm dân sự, sức khỏe, tính…**."},{"id":46,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, doanh nghiệp bảo hiểm có nghĩa vụ:","options":[{"key":"A","text":"Thực hiện các trách nhiệm phát sinh theo hợp đồng đại lý bảo hiểm đã giao kết"},{"key":"B","text":"Chịu sự kiểm tra, giám sát của cơ quan nhà nước có thẩm quyền đối với hoạt động đại lý bảo hiểm"},{"key":"C","text":"Báo cáo về việc đào tạo và sử dụng đại lý bảo hiểm theo quy định của Bộ trưởng Bộ Tài chính"},{"key":"D","text":"A, B, C đúng"}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **A, B, C đúng**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng**."},{"id":47,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phát biểu nào sau đây đúng nhất về điều kiện của doanh nghiệp bảo hiểm được nhận chuyển giao danh mục hợp đồng bảo hiểm:","options":[{"key":"A","text":"Đang kinh doanh nghiệp vụ bảo hiểm nhận chuyển giao"},{"key":"B","text":"Bảo đảm tỷ lệ an toàn vốn, khả năng thanh toán theo quy định của pháp luật."},{"key":"C","text":"Bảo đảm điều kiện triển khai nghiệp vụ bảo hiểm sau khi nhận chuyển giao."},{"key":"D","text":"A, B, C đúng."}],"answer":"D","explanation":"Theo đáp án của đề cương, phương án **D** là nội dung đúng: **A, B, C đúng.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng.**."},{"id":48,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, cá nhân đã được cấp chứng chỉ đại lý bảo hiểm nhưng không hoạt động đại lý bảo hiểm trong thời hạn 03 năm liên tục, nếu muốn tiếp tục hoạt động đại lý bảo hiểm thì:","options":[{"key":"A","text":"Không phải thực hiện thi lấy chứng chỉ đại lý bảo hiểm mới"},{"key":"B","text":"Phải thực hiện thi lấy chứng chỉ đại lý bảo hiểm mới"},{"key":"C","text":"Không phải thực hiện thi lấy chứng chỉ đại lý bảo hiểm mới, tuy nhiên phải được doanh nghiệp bảo hiểm đào tạo lại kiến thức về bảo hiểm"},{"key":"D","text":"Không phải thực hiện thi lấy chứng chỉ đại lý bảo hiểm mới, tuy nhiên chỉ được bán một số sản phẩm bảo hiểm nhất định theo quy định của doanh nghiệp bảo hiểm"}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án **B** là **Phải thực hiện thi lấy chứng chỉ đại lý bảo hiểm mới**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Phải thực hiện thi lấy chứng chỉ đại lý bảo hiểm mới**."},{"id":49,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, nghiệp vụ bảo hiểm nào sau đây không phải nghiệp vụ bảo hiểm bắt buộc:","options":[{"key":"A","text":"Bảo hiểm cháy, nổ"},{"key":"B","text":"Bảo hiểm Hỏa hoạn và các rủi ro đặc biệt"},{"key":"C","text":"Bảo hiểm Trách nhiệm dân sự của chủ xe cơ giới"},{"key":"D","text":"Bảo hiểm Trách nhiệm nghề nghiệp môi giới bảo hiểm"}],"answer":"B","explanation":"Đây là câu hỏi tìm **phương án ngoại lệ/sai**. Theo đáp án của đề cương, phương án **B** là nội dung không phù hợp: **Bảo hiểm Hỏa hoạn và các rủi ro đặc biệt**. Khi làm bài, cần chú ý từ khóa phủ định như **“sai”, “không”, “ngoại trừ”**.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":50,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật kinh doanh bảo hiểm, đối tượng bảo hiểm là:","options":[{"key":"A","text":"Tài sản theo quy định của Bộ luật dân sự."},{"key":"B","text":"Sức khỏe, tuổi thọ, tính mạng con người."},{"key":"C","text":"Trách nhiệm dân sự của người được bảo hiểm đối với người thứ ba."},{"key":"D","text":"A, B, C đúng."}],"answer":"D","explanation":"Khái niệm cần nhớ trong câu này là: **A, B, C đúng.**. Đáp án đúng là **D**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng.**."},{"id":51,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phí bảo hiểm là:","options":[{"key":"A","text":"Khoản tiền mà doanh nghiệp bảo hiểm sẽ trả lại cho người được bảo hiểm khi rủi ro không xảy ra."},{"key":"B","text":"Khoản tiền mà doanh nghiệp bảo hiểm sẽ trả lại cho người được bảo hiểm khi rủi ro xảy ra nhưng tổn thất thấp hơn phí bảo hiểm đã đóng."},{"key":"C","text":"Khoản tiền mà bên mua bảo hiểm phải đóng cho doanh nghiệp bảo hiểm theo quy định của pháp luật hoặc do các bên thỏa thuận trong hợp đồng bảo hiểm."},{"key":"D","text":"A, C đúng."},{"key":"E","text":"B, C đúng."}],"answer":"C","explanation":"Khái niệm cần nhớ trong câu này là: **Khoản tiền mà bên mua bảo hiểm phải đóng cho doanh nghiệp bảo hiểm theo quy định của pháp luật hoặc do các bên thỏa thuận trong hợp đồng bảo hiểm.**. Đáp án đúng là **C**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Khoản tiền mà bên mua bảo hiểm phải đóng cho doanh nghiệp bảo hiểm theo quy định của pháp…**."},{"id":54,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, bên mua bảo hiểm không có nghĩa vụ:","options":[{"key":"A","text":"Đóng phí bảo hiểm đầy đủ, đúng hạn theo thỏa thuận trong hợp đồng bảo hiểm"},{"key":"B","text":"Kê khai đầy đủ, trung thực mọi thông tin có liên quan đến hợp đồng bảo hiểm theo yêu cầu của doanh nghiệp bảo hiểm."},{"key":"C","text":"Thông báo cho doanh nghiệp bảo hiểm những trường hợp có thể làm tăng rủi ro hoặc giảm rủi ro hoặc làm phát sinh thêm trách nhiệm của doanh nghiệp bảo hiểm trong quá trình thực hiện hợp đồng bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm."},{"key":"D","text":"Thanh toán các khoản chi phí liên quan đến việc đánh giá rủi ro được bảo hiểm."}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **Thanh toán các khoản chi phí liên quan đến việc đánh giá rủi ro được bảo hiểm.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Thanh toán các khoản chi phí liên quan đến việc đánh giá rủi ro được bảo hiểm.**."},{"id":55,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, bên mua bảo hiểm có quyền và nghĩa vụ:","options":[{"key":"A","text":"Thông báo cho doanh nghiệp bảo hiểm những trường hợp có thể làm tăng rủi ro trong quá trình thực hiện hợp đồng bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm"},{"key":"B","text":"Yêu cầu doanh nghiệp bảo hiểm cấp hóa đơn thu phí bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm và quy định của pháp luật có liên quan."},{"key":"C","text":"Thanh toán các khoản chi phí liên quan đến việc đánh giá rủi ro được bảo hiểm."},{"key":"D","text":"A, B đúng."}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **A, B đúng.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B đúng.**."},{"id":56,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phương án nào không phải là quyền và nghĩa vụ của doanh nghiệp bảo hiểm:","options":[{"key":"A","text":"Thông báo những trường hợp làm tăng rủi ro của doanh nghiệp bảo hiểm"},{"key":"B","text":"Yêu cầu bên mua bảo hiểm cung cấp đầy đủ, trung thực thông tin liên quan đến việc giao kết và thực hiện hợp đồng bảo hiểm"},{"key":"C","text":"Cung cấp cho bên mua bảo hiểm bản yêu cầu bảo hiểm, bảng câu hỏi liên quan đến rủi ro được bảo hiểm, đối tượng bảo hiểm, quy tắc, điều kiện, điều khoản bảo hiểm"},{"key":"D","text":"Giải thích bằng văn bản lý do từ chối bồi thường, trả tiền bảo hiểm"}],"answer":"A","explanation":"Đây là câu hỏi tìm **phương án ngoại lệ/sai**. Theo đáp án của đề cương, phương án **A** là nội dung không phù hợp: **Thông báo những trường hợp làm tăng rủi ro của doanh nghiệp bảo hiểm**. Khi làm bài, cần chú ý từ khóa phủ định như **“sai”, “không”, “ngoại trừ”**.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":57,"category":"Kiến thức chung","question":"Nguyên tắc thế quyền không được áp dụng đối với loại hợp đồng bảo hiểm nào dưới đây:","options":[{"key":"A","text":"Bảo hiểm hàng hải."},{"key":"B","text":"Bảo hiểm mọi rủi ro tài sản."},{"key":"C","text":"Bảo hiểm trách nhiệm dân sự."},{"key":"D","text":"Bảo hiểm nhân thọ."}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **Bảo hiểm nhân thọ.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Bảo hiểm nhân thọ.**."},{"id":58,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Theo Quy tắc bảo hiểm ‘Hỏa hoạn và các rủi ro đặc biệt” của Hiệp hội bảo hiểm Vương quốc Anh (ABI), có thể bảo hiểm máy móc, thiết bị hay nhà xưởng trên cơ sở giá trị thay thế mới không?","options":[{"key":"A","text":"Có."},{"key":"B","text":"Không."},{"key":"C","text":"Có, với điều kiện bên mua bảo hiểm phải tham gia  thêm Điều khoản sửa đổi bổ sung về bảo hiểm theo “Giá trị thay thế mới”."}],"answer":"C","explanation":"Theo đáp án của đề cương, đáp án đúng là **C**: **Có, với điều kiện bên mua bảo hiểm phải tham gia  thêm Điều khoản sửa đổi bổ sung về bảo hiểm theo “Giá trị thay thế mới”.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Có, với điều kiện bên mua bảo hiểm phải tham gia  thêm Điều khoản sửa đổi bổ sung về bảo…**."},{"id":59,"category":"Luật Kinh doanh bảo hiểm","question":"Đáp án nào dưới đây sai:","options":[{"key":"A","text":"Bên mua bảo hiểm là tổ chức, cá nhân giao kết hợp đồng bảo hiểm với doanh nghiệp bảo hiểm và đóng phí bảo hiểm."},{"key":"B","text":"Bên mua bảo hiểm có thể đồng thời là người được bảo hiểm hoặc người thụ hưởng."},{"key":"C","text":"Bên mua bảo hiểm và người được bảo hiểm không thể là người thụ hưởng."},{"key":"D","text":"Người được bảo hiểm là cá nhân có tuổi thọ, tính mạng được bảo hiểm theo hợp đồng bảo hiểm."}],"answer":"C","explanation":"Theo đáp án của đề cương, đáp án đúng là **C**: **Bên mua bảo hiểm và người được bảo hiểm không thể là người thụ hưởng.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":60,"category":"Bảo hiểm con người","question":"Chọn phương án đúng nhất: bảo hiểm sức khỏe có thể bảo hiểm cho các rủi ro nào sau đây?","options":[{"key":"A","text":"Tai nạn."},{"key":"B","text":"Ốm đau, bệnh tật."},{"key":"C","text":"Thai sản."},{"key":"D","text":"A, B đúng."},{"key":"E","text":"A, B, C đúng."}],"answer":"E","explanation":"Theo đáp án của đề cương, phương án **E** là nội dung đúng: **A, B, C đúng.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng.**."},{"id":61,"category":"Bảo hiểm con người","question":"Chi phí nào sau đây được coi là chi phí y tế hợp lý, hợp lệ có thể được các doanh nghiệp bảo hiểm chi trả trong bảo hiểm sức khỏe?","options":[{"key":"A","text":"Chi phí mua các thực phẩm chức năng hỗ trợ điều trị theo chỉ định của bác sỹ."},{"key":"B","text":"Chi phí phẫu thuật thẩm mĩ."},{"key":"C","text":"Chi phí phẫu thuật nội trú do ốm đau, bệnh tật."}],"answer":"C","explanation":"Theo đáp án của đề cương, đáp án đúng là **C**: **Chi phí phẫu thuật nội trú do ốm đau, bệnh tật.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Chi phí phẫu thuật nội trú do ốm đau, bệnh tật.**."},{"id":62,"category":"Kiến thức chung","question":"Nguyên tắc khoán được áp dụng cho:","options":[{"key":"A","text":"Bảo hiểm nhân thọ."},{"key":"B","text":"Bảo hiểm tài sản."},{"key":"C","text":"Bảo hiểm trách nhiệm."},{"key":"D","text":"A, B, C đúng."}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Bảo hiểm nhân thọ.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Bảo hiểm nhân thọ.**."},{"id":63,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phát biểu nào sau đây sai khi nói về nguyên tắc hoạt động của đại lý bảo hiểm:","options":[{"key":"A","text":"Cá nhân hoạt động đại lý bảo hiểm, nhân viên trong tổ chức hoạt động đại lý bảo hiểm chỉ được thực hiện hoạt động đại lý bảo hiểm đối với những sản phẩm bảo hiểm đã được đào tạo."},{"key":"B","text":"Tổ chức không được đồng thời làm đại lý bảo hiểm cho doanh nghiệp bảo hiểm khác nếu không được chấp thuận bằng văn bản của doanh nghiệp bảo hiểm mà tổ chức đó đang làm đại lý."},{"key":"C","text":"Cá nhân đã được cấp chứng chỉ đại lý bảo hiểm nhưng không hoạt động đại lý bảo hiểm trong thời hạn 03 năm liên tục phải thực hiện thi lấy chứng chỉ đại lý bảo hiểm mới trước khi hoạt động đại lý."},{"key":"D","text":"Đại lý bảo hiểm có thể sửa đổi, bổ sung quy tắc, điều khoản bảo hiểm cho phù hợp với tình hình thực tế của khách hàng."}],"answer":"D","explanation":"Đây là câu hỏi tìm **phương án ngoại lệ/sai**. Theo đáp án của đề cương, phương án **D** là nội dung không phù hợp: **Đại lý bảo hiểm có thể sửa đổi, bổ sung quy tắc, điều khoản bảo hiểm cho phù hợp với tình hình thực tế của khách hàng.**. Khi làm bài, cần chú ý từ khóa phủ định như **“sai”, “không”, “ngoại trừ”**.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":64,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, bảo hiểm cháy, nổ bắt buộc do cơ quan nào ban hành quy định về điều kiện, mức phí bảo hiểm, số tiền bảo hiểm tối thiểu?","options":[{"key":"A","text":"Chính phủ"},{"key":"B","text":"Bộ Công thương"},{"key":"C","text":"Hiệp hội Bảo hiểm Việt Nam"},{"key":"D","text":"Bộ Tài chính"}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án **A** là **Chính phủ**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Chính phủ**."},{"id":65,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, bảo hiểm bắt buộc không bao gồm:","options":[{"key":"A","text":"Bảo hiểm bắt buộc trách nhiệm dân sự của chủ xe cơ giới"},{"key":"B","text":"Bảo hiểm cháy, nổ bắt buộc"},{"key":"C","text":"Bảo hiểm khám chữa bệnh bắt buộc"}],"answer":"C","explanation":"Theo đáp án của đề cương, đáp án đúng là **C**: **Bảo hiểm khám chữa bệnh bắt buộc**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Bảo hiểm khám chữa bệnh bắt buộc**."},{"id":66,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, chọn phương án sai về nghĩa vụ của doanh nghiệp bảo hiểm:","options":[{"key":"A","text":"Từ chối trả tiền bảo hiểm cho người thụ hưởng hoặc từ chối bồi thường cho người được bảo hiểm trong trường hợp không thuộc phạm vi trách nhiệm bảo hiểm hoặc trường hợp loại trừ trách nhiệm bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm."},{"key":"B","text":"Cấp cho bên mua bảo hiểm giấy chứng nhận bảo hiểm, đơn bảo hiểm ngay sau khi giao kết hợp đồng bảo hiểm."},{"key":"C","text":"Giải thích cho bên mua bảo hiểm về các điều kiện, điều khoản bảo hiểm; quyền, nghĩa vụ của bên mua bảo hiểm."},{"key":"D","text":"Trả tiền bảo hiểm kịp thời cho người thụ hưởng hoặc bồi thường cho người được bảo hiểm khi xảy ra sự kiện bảo hiểm."}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Từ chối trả tiền bảo hiểm cho người thụ hưởng hoặc từ chối bồi thường cho người được bảo hiểm trong trường hợp không thuộc phạm vi trách nhiệm bảo hiểm hoặc trường hợp loại trừ trách nhiệm bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":67,"category":"Bảo hiểm xe cơ giới","question":"Chọn phương án đúng về số tiền bồi thường trong đơn bảo hiểm trách nhiệm dân sự của chủ xe cơ giới đối với hàng hóa trên xe:","options":[{"key":"A","text":"Số tiền bồi thường có thể vượt quá mức trách nhiệm bảo hiểm/vụ tổn thất."},{"key":"B","text":"Số tiền bồi thường không được vượt quá mức trách nhiệm bảo hiểm/vụ tổn thất."},{"key":"C","text":"Số tiền bồi thường không được vượt quá mức trách nhiệm bảo hiểm/Mỗi và mọi vụ tổn thất."},{"key":"D","text":"A, B, C sai."}],"answer":"B","explanation":"Theo đáp án của đề cương, phương án **B** là nội dung đúng: **Số tiền bồi thường không được vượt quá mức trách nhiệm bảo hiểm/vụ tổn thất.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Số tiền bồi thường không được vượt quá mức trách nhiệm bảo hiểm/vụ tổn thất.**."},{"id":68,"category":"Kiến thức chung","question":"Rủi ro được coi là rủi ro có thể được bảo hiểm khi đáp ứng các điều kiện sau:","options":[{"key":"A","text":"Tổn thất phải ngẫu nhiên, bất ngờ."},{"key":"B","text":"Phải đo được, định lượng được về tài chính."},{"key":"C","text":"Phải có số đông."},{"key":"D","text":"Không trái với chuẩn mực đạo đức xã hội."},{"key":"E","text":"A, B, C, D đúng."}],"answer":"E","explanation":"Theo đáp án của đề cương, đáp án đúng là **E**: **A, B, C, D đúng.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C, D đúng.**."},{"id":69,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Chọn phương án đúng về số tiền cần phải bảo hiểm máy móc thiết bị của chủ thầu (CPM) của nhà tái bảo hiểm Munich Re:","options":[{"key":"A","text":"Là giá trị thị trường."},{"key":"B","text":"Là giá trị sổ sách."},{"key":"C","text":"Là giá trị thay thế mới."},{"key":"D","text":"A, B, C đúng"}],"answer":"C","explanation":"Theo đáp án của đề cương, phương án **C** là nội dung đúng: **Là giá trị thay thế mới.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Là giá trị thay thế mới.**."},{"id":71,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, sản phẩm bảo hiểm nào sau đây là bảo hiểm bắt buộc:","options":[{"key":"A","text":"Bảo hiểm trách nhiệm dân sự của người vận chuyển hàng không đối với hành khách."},{"key":"B","text":"Bảo hiểm trách nhiệm nghề nghiệp của doanh nghiệp môi giới bảo hiểm."},{"key":"C","text":"Bảo hiểm cháy, nổ bắt buộc"},{"key":"D","text":"A, B, C đúng."}],"answer":"C","explanation":"Theo đáp án của đề cương, đáp án đúng là **C**: **Bảo hiểm cháy, nổ bắt buộc**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Bảo hiểm cháy, nổ bắt buộc**."},{"id":73,"category":"Kiến thức chung","question":"Chọn phương án đúng nhất về bảo hiểm trùng:","options":[{"key":"A","text":"Đối tượng bảo hiểm được bảo vệ bằng ít nhất hai hợp đồng bảo hiểm."},{"key":"B","text":"Rủi ro gây ra tổn thất thuộc rủi ro được bảo hiểm của một trong số các hợp đồng bảo hiểm cho đối tượng bảo hiểm đó."},{"key":"C","text":"Các hợp đồng bảo hiểm phải có cùng phạm vi, đối tượng, thời hạn và sự kiện bảo hiểm."},{"key":"D","text":"A, B đúng."},{"key":"E","text":"A, C đúng."}],"answer":"E","explanation":"Theo đáp án của đề cương, phương án **E** là nội dung đúng: **A, C đúng.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, C đúng.**."},{"id":74,"category":"Luật Kinh doanh bảo hiểm","question":"Theo pháp luật về hoạt động kinh doanh bảo hiểm, phát biểu nào sau đây đúng nhất về giới hạn trách nhiệm bảo hiểm trong bảo hiểm trách nhiệm:","options":[{"key":"A","text":"Trong phạm vi giới hạn trách nhiệm bảo hiểm, doanh nghiệp bảo hiểm phải trả cho người được bảo hiểm những khoản tiền mà theo quy định của pháp luật người được bảo hiểm có trách nhiệm bồi thường cho người thứ ba."},{"key":"B","text":"Doanh nghiệp bảo hiểm phải trả các cho người được bảo hiểm các chi phí liên quan đến việc giải quyết tranh chấp về trách nhiệm đối với người thứ ba."},{"key":"C","text":"Tổng số tiền bồi thường của doanh nghiệp bảo hiểm không vượt quá  giới hạn trách nhiệm bảo hiểm, trừ trường hợp có thỏa thuận khác trong hợp đồng bảo hiểm."},{"key":"D","text":"A, B, C đúng."},{"key":"E","text":"A, C đúng."}],"answer":"D","explanation":"Theo đáp án của đề cương, phương án **D** là nội dung đúng: **A, B, C đúng.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng.**."},{"id":75,"category":"Bảo hiểm xe cơ giới","question":"Phạm vi bảo hiểm của bảo hiểm trách nhiệm dân sự xe cơ giới là: Thiệt hại ngoài hợp đồng về thân thể, tính mạng và tài sản đối với bên thứ ba do xe cơ giới gây ra. Trách nhiệm bồi thường thiệt hại ngoài hợp đồng được hiểu là:","options":[{"key":"A","text":"Bên có nghĩa vụ dân sự đã cam kết trong hợp đồng mà không thực hiện hoặc thực hiện không đúng nghĩa vụ sẽ phải bồi thường cho bên kia."},{"key":"B","text":"Hành vi gây hại không liên quan đến việc thực hiện nghĩa vụ dân sự của bất kỳ hợp đồng nào."}],"answer":"B","explanation":"Khái niệm cần nhớ trong câu này là: **Hành vi gây hại không liên quan đến việc thực hiện nghĩa vụ dân sự của bất kỳ hợp đồng nào.**. Đáp án đúng là **B**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Hành vi gây hại không liên quan đến việc thực hiện nghĩa vụ dân sự của bất kỳ hợp đồng nào.**."},{"id":77,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, đại lý bảo hiểm không được doanh nghiệp bảo hiểm uỷ quyền tiến hành hoạt động nào dưới đây:","options":[{"key":"A","text":"Giới thiệu, chào bán sản phẩm bảo hiểm."},{"key":"B","text":"Thu thập hồ sơ để phục vụ việc giải quyết bồi thường, trả tiền bảo hiểm."},{"key":"C","text":"Đánh giá rủi ro bảo hiểm."},{"key":"D","text":"Thu phí bảo hiểm."}],"answer":"C","explanation":"Theo đáp án của đề cương, đáp án đúng là **C**: **Đánh giá rủi ro bảo hiểm.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Đánh giá rủi ro bảo hiểm.**."},{"id":78,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phát biểu nào dưới đây sai:","options":[{"key":"A","text":"Hoạt động đại lý bảo hiểm là một hoặc một số hoạt động theo ủy quyền của doanh nghiệp bảo hiểm, bao gồm: tư vấn sản phẩm bảo hiểm; giới thiệu sản phẩm bảo hiểm; chào bán sản phẩm bảo hiểm; thu xếp việc giao kết hợp đồng bảo hiểm; thu phí bảo hiểm; thu thập hồ sơ để phục vụ việc giải quyết bồi thường, trả tiền bảo hiểm."},{"key":"B","text":"Sự kiện bảo hiểm là sự kiện khách quan do các bên thỏa thuận hoặc pháp luật quy định mà khi sự kiện đó xảy ra thì doanh nghiệp bảo hiểm phải bồi thường, trả tiền bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm."},{"key":"C","text":"Kinh doanh bảo hiểm là hoạt động của doanh nghiệp bảo hiểm nhằm mục đích sinh lợi, theo đó doanh nghiệp bảo hiểm nhận một khoản phí bảo hiểm của doanh nghiệp bảo hiểm khác để cam kết bồi thường cho các trách nhiệm đã nhận bảo hiểm."}],"answer":"C","explanation":"Đây là câu hỏi tìm **phương án ngoại lệ/sai**. Theo đáp án của đề cương, phương án **C** là nội dung không phù hợp: **Kinh doanh bảo hiểm là hoạt động của doanh nghiệp bảo hiểm nhằm mục đích sinh lợi, theo đó doanh nghiệp bảo hiểm nhận một khoản phí bảo hiểm của doanh nghiệp bảo hiểm khác để cam kết bồi thường cho các trách nhiệm đã nhận bảo hiểm.**. Khi làm bài, cần chú ý từ khóa phủ định như **“sai”, “không”, “ngoại trừ”**.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":79,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, tổ chức, cá nhân được bên mua bảo hiểm hoặc người được bảo hiểm chỉ định để nhận tiền bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm là:","options":[{"key":"A","text":"Người được bảo hiểm"},{"key":"B","text":"Người thụ hưởng"},{"key":"C","text":"Người bảo hiểm"},{"key":"D","text":"Người tham gia bảo hiểm"}],"answer":"B","explanation":"Khái niệm cần nhớ trong câu này là: **Người thụ hưởng**. Đáp án đúng là **B**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Người thụ hưởng**."},{"id":81,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, các loại hợp đồng bảo hiểm bao gồm:","options":[{"key":"A","text":"Hợp đồng bảo hiểm nhân thọ"},{"key":"B","text":"Hợp đồng bảo hiểm sức khỏe"},{"key":"C","text":"Hợp đồng bảo hiểm tài sản; Hợp đồng bảo hiểm thiệt hại; Hợp đồng bảo hiểm trách nhiệm."},{"key":"D","text":"A, B, C đúng"}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **A, B, C đúng**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng**."},{"id":83,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, việc chuyển nhượng hợp đồng bảo hiểm chỉ có hiệu lực khi:","options":[{"key":"A","text":"Bên mua bảo hiểm thông báo bằng văn bản cho doanh nghiệp bảo hiểm về việc chuyển nhượng và doanh nghiệp bảo hiểm có văn bản chấp thuận việc chuyển nhượng đó."},{"key":"B","text":"Bên mua bảo hiểm thông báo bằng văn bản cho doanh nghiệp bảo hiểm về việc chuyển nhượng và doanh nghiệp bảo hiểm có văn bản chấp thuận việc chuyển nhượng đó trừ trường hợp việc chuyển nhượng được thực hiện theo tập quán quốc tế."},{"key":"C","text":"Việc chuyển nhượng hợp đồng được tự động thực hiện theo thỏa thuận tại hợp đồng bảo hiểm."},{"key":"D","text":"A, B đúng"},{"key":"E","text":"A, C đúng"}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án đúng là **B**: **Bên mua bảo hiểm thông báo bằng văn bản cho doanh nghiệp bảo hiểm về việc chuyển nhượng và doanh nghiệp bảo hiểm có văn bản chấp thuận việc chuyển nhượng đó trừ trường hợp việc chuyển nhượng được thực hiện theo tập quán quốc tế.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Bên mua bảo hiểm thông báo bằng văn bản cho doanh nghiệp bảo hiểm về việc chuyển nhượng và…**."},{"id":84,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phát biểu nào dưới đây sai:","options":[{"key":"A","text":"Hợp đồng bảo hiểm là sự thoả thuận giữa bên mua bảo hiểm và doanh nghiệp bảo hiểm, theo đó bên mua bảo hiểm phải đóng phí bảo hiểm, doanh nghiệp bảo hiểm phải bồi thường, trả tiền bảo hiểm theo thỏa thuận trong hợp đồng."},{"key":"B","text":"Các loại hợp đồng bảo hiểm bao gồm: Hợp đồng bảo hiểm nhân thọ; Hợp đồng bảo hiểm sức khỏe; Hợp đồng bảo hiểm tài sản; Hợp đồng bảo hiểm thiệt hại; Hợp đồng bảo hiểm trách nhiệm."},{"key":"C","text":"Trường hợp hợp đồng bảo hiểm có điều khoản không rõ ràng dẫn đến có cách hiểu khác nhau thì điều khoản đó được giải thích theo hướng có lợi cho doanh nghiệp bảo hiểm."},{"key":"D","text":"Doanh nghiệp bảo hiểm và bên mua bảo hiểm được thỏa thuận giao kết một hoặc kết hợp nhiều loại hợp đồng bảo hiểm"}],"answer":"C","explanation":"Đây là câu hỏi tìm **phương án ngoại lệ/sai**. Theo đáp án của đề cương, phương án **C** là nội dung không phù hợp: **Trường hợp hợp đồng bảo hiểm có điều khoản không rõ ràng dẫn đến có cách hiểu khác nhau thì điều khoản đó được giải thích theo hướng có lợi cho doanh nghiệp bảo hiểm.**. Khi làm bài, cần chú ý từ khóa phủ định như **“sai”, “không”, “ngoại trừ”**.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":85,"category":"Luật Kinh doanh bảo hiểm","question":"Khi giao kết hợp đồng bảo hiểm, doanh nghiệp bảo hiểm có quyền và nghĩa vụ:","options":[{"key":"A","text":"Có quyền yêu cầu bên mua bảo hiểm cung cấp đầy đủ, trung thực mọi thông tin liên quan đến việc giao kết hợp đồng bảo hiểm."},{"key":"B","text":"Có quyền thu phí bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm."},{"key":"C","text":"Có nghĩa vụ giải thích rõ ràng, đầy đủ cho bên mua bảo hiểm về quyền lợi bảo hiểm, điều khoản loại trừ trách nhiệm bảo hiểm, quyền và nghĩa vụ của bên mua bảo hiểm."},{"key":"D","text":"A, B, C đúng."}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **A, B, C đúng.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng.**."},{"id":86,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, khi có sự thay đổi những yếu tố làm cơ sở để tính phí bảo hiểm dẫn đến tăng các rủi ro được bảo hiểm, căn cứ thỏa thuận tại hợp đồng bảo hiểm, doanh nghiệp bảo hiểm:","options":[{"key":"A","text":"Có quyền tính lại phí bảo hiểm cho thời gian còn lại của hợp đồng bảo hiểm"},{"key":"B","text":"Không có quyền tính lại phí bảo hiểm cho thời gian còn lại của hợp đồng bảo hiểm"},{"key":"C","text":"Có quyền đơn phương chấm dứt thực hiện hợp đồng bảo hiểm và không cần thông báo ngay bằng văn bản cho bên mua bảo hiểm."}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Có quyền tính lại phí bảo hiểm cho thời gian còn lại của hợp đồng bảo hiểm**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Có quyền tính lại phí bảo hiểm cho thời gian còn lại của hợp đồng bảo hiểm**."},{"id":87,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, đối với tổn thất do hao mòn tự nhiên hoặc do bản chất vốn có của tài sản, doanh nghiệp bảo hiểm sẽ:","options":[{"key":"A","text":"Không chịu trách nhiệm bồi thường  (trừ trường hợp có thỏa thuận khác trong hợp đồng bảo hiểm)"},{"key":"B","text":"Chịu trách nhiệm bồi thường 70% tổn thất"},{"key":"C","text":"Chịu trách nhiệm bồi thường 50% tổn thất"},{"key":"D","text":"Chịu trách nhiệm bồi thường 30% tổn thất"}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Không chịu trách nhiệm bồi thường  (trừ trường hợp có thỏa thuận khác trong hợp đồng bảo hiểm)**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Không chịu trách nhiệm bồi thường  (trừ trường hợp có thỏa thuận khác trong hợp đồng bảo hiểm)**."},{"id":88,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phát biểu nào sau đây sai về quyền và nghĩa vụ của doanh nghiệp bảo hiểm:","options":[{"key":"A","text":"Yêu cầu bên mua bảo hiểm áp dụng các biện pháp đề phòng, hạn chế tổn thất theo quy định của pháp luật."},{"key":"B","text":"Yêu cầu người thứ ba bồi hoàn số tiền mà doanh nghiệp bảo hiểm đã bồi thường cho người được bảo hiểm đối với thiệt hại về tài sản; lợi ích kinh tế hoặc nghĩa vụ thực hiện hợp đồng hoặc nghĩa vụ theo pháp luật; trách nhiệm dân sự do người thứ ba gây ra"},{"key":"C","text":"Chuyển giao hợp đồng bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm hoặc theo quy định của pháp luật."},{"key":"D","text":"Lưu trữ hồ sơ theo quy định của pháp luật"}],"answer":"C","explanation":"Đây là câu hỏi tìm **phương án ngoại lệ/sai**. Theo đáp án của đề cương, phương án **C** là nội dung không phù hợp: **Chuyển giao hợp đồng bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm hoặc theo quy định của pháp luật.**. Khi làm bài, cần chú ý từ khóa phủ định như **“sai”, “không”, “ngoại trừ”**.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":89,"category":"Luật Kinh doanh bảo hiểm","question":"Chọn phương án đúng nhất về số tiền bồi thường hoặc số tiền chi trả quyền lợi bảo hiểm:","options":[{"key":"A","text":"Đối với bảo hiểm tài sản: Là số tiền bồi thường/mỗi và mọi vụ tổn thất trong thời hạn bảo hiểm và có thể vượt quá số tiền bảo hiểm."},{"key":"B","text":"Đối với bảo hiểm vật chất xe cơ giới: Là số tiền bồi thường/vụ tổn thất nhưng không vượt quá số tiền bảo hiểm, tổng số tiền bồi thường của tất cả các vụ tổn thất trong thời hạn bảo hiểm có thể vượt quá số tiền bảo hiểm."},{"key":"C","text":"Đối với bảo hiểm tai nạn con người: Là số tiền phải trả căn cứ vào thương tật ước tính của người được bảo hiểm và thỏa thuận trong hợp đồng bảo hiểm."},{"key":"D","text":"A, B đúng."}],"answer":"B","explanation":"Theo đáp án của đề cương, phương án **B** là nội dung đúng: **Đối với bảo hiểm vật chất xe cơ giới: Là số tiền bồi thường/vụ tổn thất nhưng không vượt quá số tiền bảo hiểm, tổng số tiền bồi thường của tất cả các vụ tổn thất trong thời hạn bảo hiểm có thể vượt quá số tiền bảo hiểm.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Đối với bảo hiểm vật chất xe cơ giới: Là số tiền bồi thường/vụ tổn thất nhưng không vượt…**."},{"id":90,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Theo đơn bảo hiểm “Hoả hoạn và các rủi ro đặc biệt” của Hiệp hội bảo hiểm Vương quốc Anh (ABI), áp dụng từ rủi ro A đến I, tài sản bị thiệt hại do nguyên nhân nào sau đây không bị loại trừ bảo hiểm:","options":[{"key":"A","text":"Thiệt hại gây ra do ô nhiễm, nhiễm bẩn."},{"key":"B","text":"Thiệt hại gây ra do ô nhiễm phát sinh từ rủi ro được bảo hiểm."},{"key":"C","text":"Thiệt hại do máy móc, thiết bị chạy quá tải."},{"key":"D","text":"Thiệt hại gây ra do bạo loạn."}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án đúng là **B**: **Thiệt hại gây ra do ô nhiễm phát sinh từ rủi ro được bảo hiểm.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Thiệt hại gây ra do ô nhiễm phát sinh từ rủi ro được bảo hiểm.**."},{"id":91,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, trường hợp không có thỏa thuận về thời hạn bồi thường, trả tiền bảo hiểm, doanh nghiệp bảo hiểm phải bồi thường, trả tiền bảo hiểm trong thời hạn bao nhiêu ngày kể từ ngày nhận được đầy đủ hồ sơ hợp lệ về yêu cầu bồi thường, trả tiền bảo hiểm:","options":[{"key":"A","text":"15 ngày."},{"key":"B","text":"30 ngày"},{"key":"C","text":"45 ngày"},{"key":"D","text":"60 ngày"}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án **A** là **15 ngày.**. Mốc cần nhớ: **15 ngày**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Chốt mốc **15 ngày** và gắn với đúng điều kiện của câu."},{"id":92,"category":"Bảo hiểm con người","question":"Khi tham gia sản phẩm bảo hiểm sức khỏe với quyền lợi bảo hiểm tai nạn, trường hợp người được bảo hiểm bị tai nạn sẽ không được chi trả khoản chi phí nào sau đây:","options":[{"key":"A","text":"Chi phí nằm viện do tai nạn."},{"key":"B","text":"Chi phí di chuyển bằng xe cứu thương."},{"key":"C","text":"Chi phí cho các xét nghiệm, kiểm tra chẩn đoán."},{"key":"D","text":"Chi phí phát sinh do tai nạn xảy ra trước thời điểm mua bảo hiểm."},{"key":"E","text":"A, B, C đúng."}],"answer":"D","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **D**: **Chi phí phát sinh do tai nạn xảy ra trước thời điểm mua bảo hiểm.**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Chi phí phát sinh do tai nạn xảy ra trước thời điểm mua bảo hiểm.**."},{"id":93,"category":"Bảo hiểm con người","question":"Khi tham gia hợp đồng bảo hiểm sức khỏe với quyền lợi bảo hiểm tai nạn, người được bảo hiểm có thể được nhận quyền lợi bảo hiểm nào sau đây?","options":[{"key":"A","text":"Thương tật bộ phận vĩnh viễn do tai nạn."},{"key":"B","text":"Trợ cấp mất, giảm thu nhập do tai nạn."},{"key":"C","text":"Thai sản."},{"key":"D","text":"A, B đúng."},{"key":"E","text":"A, B, C đúng."}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **A, B đúng.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B đúng.**."},{"id":94,"category":"Kiến thức chung","question":"Bảo hiểm là phương pháp phòng tránh rủi ro nào sau đây:","options":[{"key":"A","text":"Giữ lại rủi ro."},{"key":"B","text":"Né tránh rủi ro."},{"key":"C","text":"Kiểm soát rủi ro."},{"key":"D","text":"Chuyển giao rủi ro."}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **Chuyển giao rủi ro.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Chuyển giao rủi ro.**."},{"id":95,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phát biểu nào sau đây đúng:","options":[{"key":"A","text":"Đại lý bảo hiểm có nghĩa vụ thực hiện nghĩa vụ trong hợp đồng đại lý bảo hiểm"},{"key":"B","text":"Đại lý bảo hiểm được tự ý kê khai thông tin thay cho bên mua bảo hiểm"},{"key":"C","text":"Đại lý bảo hiểm không có nghĩa vụ ký quỹ hoặc thế chấp tài sản cho doanh nghiệp bảo hiểm nếu có thỏa thuận trong hợp đồng đại lý bảo hiểm."},{"key":"D","text":"A, B, C đúng"}],"answer":"A","explanation":"Theo đáp án của đề cương, phương án **A** là nội dung đúng: **Đại lý bảo hiểm có nghĩa vụ thực hiện nghĩa vụ trong hợp đồng đại lý bảo hiểm**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Đại lý bảo hiểm có nghĩa vụ thực hiện nghĩa vụ trong hợp đồng đại lý bảo hiểm**."},{"id":96,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, chọn phương án đúng nhất về bảo hiểm cháy, nổ bắt buộc:","options":[{"key":"A","text":"Là sản phẩm bảo hiểm do Chính phủ quy định chi tiết về điều kiện bảo hiểm, mức phí bảo hiểm"},{"key":"B","text":"Là sản phẩm bảo hiểm do Chính phủ quy định chi tiết về điều kiện, số tiền bảo hiểm tối thiểu"},{"key":"C","text":"Là sản phẩm bảo hiểm do Chính phủ quy định chi tiết về mức phí bảo hiểm, số tiền bảo hiểm tối thiểu"},{"key":"D","text":"Là sản phẩm bảo hiểm do Chính phủ quy định chi tiết về điều kiện bảo hiểm, mức phí bảo hiểm, số tiền bảo hiểm tối thiểu"}],"answer":"D","explanation":"Theo đáp án của đề cương, phương án **D** là nội dung đúng: **Là sản phẩm bảo hiểm do Chính phủ quy định chi tiết về điều kiện bảo hiểm, mức phí bảo hiểm, số tiền bảo hiểm tối thiểu**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Là sản phẩm bảo hiểm do Chính phủ quy định chi tiết về điều kiện bảo hiểm, mức phí bảo…**."},{"id":97,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, bảo hiểm bắt buộc không bao gồm:","options":[{"key":"A","text":"Bảo hiểm bắt buộc thất nghiệp"},{"key":"B","text":"Bảo hiểm bắt buộc thiệt hại vật chất xe ô tô."},{"key":"C","text":"Bảo hiểm cháy, nổ bắt buộc"},{"key":"D","text":"A, B, C đúng"}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án đúng là **B**: **Bảo hiểm bắt buộc thiệt hại vật chất xe ô tô.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Bảo hiểm bắt buộc thiệt hại vật chất xe ô tô.**."},{"id":98,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Người có quyền đối với tài sản thuê, mượn và phải chịu rủi ro về tài sản đó thì có “Quyền lợi có thể được bảo hiểm” đối với tài sản đó trong thời gian thuê, mượn:","options":[{"key":"A","text":"Đúng."},{"key":"B","text":"Sai."}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án **A** là **Đúng.**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Đúng.**."},{"id":99,"category":"Bảo hiểm xe cơ giới","question":"Trong thời hạn bảo hiểm của hợp đồng bảo hiểm thiệt hại vật chất xe cơ giới, trường hợp xe bị nổ lốp gây ra tai nạn dẫn đến tổn thất toàn bộ xe, doanh nghiệp bảo hiểm chi trả bồi thường như  thế nào:","options":[{"key":"A","text":"Bồi thường toàn bộ thiệt hại."},{"key":"B","text":"Bồi thường toàn bộ thiệt hại nhưng trừ chiếc lốp bị nổ."},{"key":"C","text":"Bồi thường toàn bộ thiệt hại nhưng trừ toàn bộ lốp của xe bị tai nạn."},{"key":"D","text":"A, B, C sai."}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án **B** là **Bồi thường toàn bộ thiệt hại nhưng trừ chiếc lốp bị nổ.**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Bồi thường toàn bộ thiệt hại nhưng trừ chiếc lốp bị nổ.**."},{"id":101,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Chọn phương án đúng: Trường hợp  nào sau đây thuộc phạm vi bảo hiểm của Đơn bảo hiểm mọi rủi ro xây dựng CAR của nhà tái bảo hiểm Munich Re?","options":[{"key":"A","text":"Hạng mục công trình bị thiệt hại do lỗi thiết kế"},{"key":"B","text":"Tổn thất đối với  hồ sơ, bản vẽ, sổ sách, hóa đơn."},{"key":"C","text":"Hạng mục công trình bị thiệt hại do bão"},{"key":"D","text":"A, C đúng"},{"key":"E","text":"A, B, C đúng"}],"answer":"C","explanation":"Theo đáp án của đề cương, phương án **C** là nội dung đúng: **Hạng mục công trình bị thiệt hại do bão**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Hạng mục công trình bị thiệt hại do bão**."},{"id":102,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, đại lý bảo hiểm có các quyền nào sau đây:","options":[{"key":"A","text":"Lựa chọn và giao kết hợp đồng đại lý bảo hiểm đối với doanh nghiệp bảo hiểm, chi nhánh doanh nghiệp bảo hiểm phi nhân thọ nước ngoài, tổ chức tương hỗ cung cấp bảo hiểm vi mô theo quy định của pháp luật."},{"key":"B","text":"Yêu cầu doanh nghiệp bảo hiểm hoàn trả tiền ký quỹ hoặc tài sản thế chấp theo thỏa thuận trong hợp đồng đại lý bảo hiểm."},{"key":"C","text":"Sửa đổi, bổ sung điều khoản trong hợp đồng bảo hiểm theo ý kiến của bên mua bảo hiểm"},{"key":"D","text":"A, B đúng"}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **A, B đúng**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B đúng**."},{"id":103,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phát biểu nào sau đây là đúng nhất về đối tượng được phép kinh doanh bảo hiểm sức khỏe có thời hạn trên 01 năm:","options":[{"key":"A","text":"Doanh nghiệp bảo hiểm nhân thọ."},{"key":"B","text":"Doanh nghiệp bảo hiểm phi nhân thọ."},{"key":"C","text":"A, B đúng."},{"key":"D","text":"A, B sai."}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án **A** là **Doanh nghiệp bảo hiểm nhân thọ.**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Doanh nghiệp bảo hiểm nhân thọ.**."},{"id":104,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phát biểu nào sau đây đúng nhất về nguyên tắc trung thực tuyệt đối:","options":[{"key":"A","text":"Chỉ áp dụng cho doanh nghiệp bảo hiểm."},{"key":"B","text":"Chỉ áp dụng cho bên mua bảo hiểm."},{"key":"C","text":"Là nghĩa vụ chung của cả doanh nghiệp bảo hiểm và bên mua bảo hiểm."}],"answer":"C","explanation":"Theo đáp án của đề cương, phương án **C** là nội dung đúng: **Là nghĩa vụ chung của cả doanh nghiệp bảo hiểm và bên mua bảo hiểm.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Là nghĩa vụ chung của cả doanh nghiệp bảo hiểm và bên mua bảo hiểm.**."},{"id":105,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phương án nào sau đây đúng về hợp đồng bảo hiểm tài sản dưới giá trị:","options":[{"key":"A","text":"Hợp đồng bảo hiểm tài sản dưới giá trị là hợp đồng trong đó số tiền bồi thường thấp hơn giá thị trường của tài sản được bảo hiểm tại thời điểm giao kết hợp đồng."},{"key":"B","text":"Hợp đồng bảo hiểm tài sản dưới giá trị là hợp đồng trong đó số tiền bảo hiểm thấp hơn giá thị trường của tài sản được bảo hiểm tại thời điểm giao kết hợp đồng."},{"key":"C","text":"Hợp đồng bảo hiểm tài sản dưới giá trị là hợp đồng trong đó số tiền bảo hiểm thấp hơn giá trị sổ sách của tài sản được bảo hiểm tại thời điểm giao kết hợp đồng."},{"key":"D","text":"B, C đúng"}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án đúng là **B**: **Hợp đồng bảo hiểm tài sản dưới giá trị là hợp đồng trong đó số tiền bảo hiểm thấp hơn giá thị trường của tài sản được bảo hiểm tại thời điểm giao kết hợp đồng.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Hợp đồng bảo hiểm tài sản dưới giá trị là hợp đồng trong đó số tiền bảo hiểm thấp hơn giá…**."},{"id":106,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, chọn phương án sai về quyền của bên mua bảo hiểm:","options":[{"key":"A","text":"Lựa chọn doanh nghiệp bảo hiểm hoạt động tại Việt Nam để mua bảo hiểm."},{"key":"B","text":"Yêu cầu doanh nghiệp bảo hiểm giải thích các điều kiện, điều khoản bảo hiểm; cấp giấy chứng nhận bảo hiểm hoặc đơn bảo hiểm."},{"key":"C","text":"Chuyển giao hợp đồng bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm hoặc theo quy định của pháp luật."},{"key":"D","text":"Thông báo những trường hợp có thể làm tăng rủi ro hoặc làm phát sinh thêm trách nhiệm của doanh nghiệp bảo hiểm trong quá trình thực hiện hợp đồng bảo hiểm theo yêu cầu của doanh nghiệp bảo hiểm."}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **Thông báo những trường hợp có thể làm tăng rủi ro hoặc làm phát sinh thêm trách nhiệm của doanh nghiệp bảo hiểm trong quá trình thực hiện hợp đồng bảo hiểm theo yêu cầu của doanh nghiệp bảo hiểm.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":107,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phát biểu nào dưới đây sai:","options":[{"key":"A","text":"Bên mua bảo hiểm là tổ chức, cá nhân giao kết hợp đồng bảo hiểm với doanh nghiệp bảo hiểm và đóng phí bảo hiểm."},{"key":"B","text":"Người thụ hưởng là tổ chức, cá nhân được bên mua bảo hiểm hoặc người được bảo hiểm chỉ định để nhận tiền bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm."},{"key":"C","text":"Bên mua bảo hiểm và người được bảo hiểm không thể là người thụ hưởng."},{"key":"D","text":"Người được bảo hiểm là tổ chức, cá nhân có tài sản, trách nhiệm dân sự, sức khỏe, tính mạng, nghĩa vụ hoặc lợi ích kinh tế được bảo hiểm theo hợp đồng bảo hiểm."}],"answer":"C","explanation":"Đây là câu hỏi tìm **phương án ngoại lệ/sai**. Theo đáp án của đề cương, phương án **C** là nội dung không phù hợp: **Bên mua bảo hiểm và người được bảo hiểm không thể là người thụ hưởng.**. Khi làm bài, cần chú ý từ khóa phủ định như **“sai”, “không”, “ngoại trừ”**.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":108,"category":"Bảo hiểm xe cơ giới","question":"Chọn phương án đúng về bảo hiểm trách nhiệm bắt buộc:","options":[{"key":"A","text":"Bảo hiểm trách nhiệm công cộng."},{"key":"B","text":"Bảo hiểm trách nhiệm sản phẩm."},{"key":"C","text":"Bảo hiểm trách nhiệm dân sự chủ tàu."},{"key":"D","text":"Bảo hiểm bắt buộc trách nhiệm dân sự của chủ xe cơ giới"}],"answer":"D","explanation":"Theo đáp án của đề cương, phương án **D** là nội dung đúng: **Bảo hiểm bắt buộc trách nhiệm dân sự của chủ xe cơ giới**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Bảo hiểm bắt buộc trách nhiệm dân sự của chủ xe cơ giới**."},{"id":109,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Tổng số tiền bồi thường hàng hóa khi tham gia bảo hiểm trách nhiệm dân sự của chủ xe cơ giới đối với hàng hóa trên xe và chi phí (chi phí ngăn ngừa tổn thất, chi phí bảo quản, xếp dỡ, lưu kho…) có thể vượt quá mức trách nhiệm bảo hiểm/vụ tổn thất (thuộc phạm vi bảo hiểm). Phát biểu trên là:","options":[{"key":"A","text":"Đúng"},{"key":"B","text":"Sai"}],"answer":"B","explanation":"Khái niệm cần nhớ trong câu này là: **Sai**. Đáp án đúng là **B**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Sai**."},{"id":110,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, đại lý bảo hiểm không được lựa chọn và giao kết hợp đồng đại lý bảo hiểm với đối tượng nào sau đây:","options":[{"key":"A","text":"Doanh nghiệp bảo hiểm"},{"key":"B","text":"Chi nhánh doanh nghiệp bảo hiểm phi nhân thọ nước ngoài"},{"key":"C","text":"Tổ chức tương hỗ cung cấp bảo hiểm vi mô theo quy định của pháp luật"},{"key":"D","text":"Văn phòng đại diện của doanh nghiệp bảo hiểm nước ngoài tại Việt Nam"}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **Văn phòng đại diện của doanh nghiệp bảo hiểm nước ngoài tại Việt Nam**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Văn phòng đại diện của doanh nghiệp bảo hiểm nước ngoài tại Việt Nam**."},{"id":111,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, tổ chức, cá nhân tại Việt Nam có nhu cầu tham gia bảo hiểm (trừ trường hợp sử dụng dịch vụ bảo hiểm qua biên giới theo điều ước Quốc tế mà nước CHXHCN Việt Nam là thành viên) thì phương án nào sau đây đúng nhất:","options":[{"key":"A","text":"Được tham gia bảo hiểm tại doanh nghiệp bảo hiểm được cấp giấy phép thành lập và hoạt động tại Việt Nam."},{"key":"B","text":"Được tham gia bảo hiểm tại chi nhánh doanh nghiệp bảo hiểm phi nhân thọ nước ngoài được cấp giấy phép thành lập và hoạt động tại Việt Nam."},{"key":"C","text":"Được tham gia bảo hiểm tại tổ chức tương hỗ cung cấp bảo hiểm vi mô được cấp giấy phép thành lập và hoạt động tại Việt Nam"},{"key":"D","text":"A, B, C đúng."}],"answer":"D","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **D**: **A, B, C đúng.**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng.**."},{"id":112,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phát biểu nào dưới đây sai:","options":[{"key":"A","text":"Kinh doanh bảo hiểm là hoạt động của doanh nghiệp bảo hiểm chấp nhận rủi ro của người được bảo hiểm, trên cơ sở bên mua bảo hiểm đóng phí bảo hiểm để doanh nghiệp bảo hiểm bồi thường, trả tiền bảo hiểm khi xảy ra sự kiện bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm."},{"key":"B","text":"Sự kiện bảo hiểm là sự kiện khách quan do các bên thỏa thuận hoặc pháp luật quy định mà khi sự kiện đó xảy ra thì doanh nghiệp bảo hiểm phải bồi thường, trả tiền bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm."},{"key":"C","text":"Hoạt động đại lý bảo hiểm là việc cung cấp thông tin, tư vấn cho bên mua bảo hiểm về sản phẩm bảo hiểm, điều kiện bảo hiểm, mức phí bảo hiểm, doanh nghiệp bảo hiểm, và các công việc liên quan đến việc đàm phán, thu xếp và thực hiện hợp đồng bảo hiểm theo yêu cầu của bên mua bảo hiểm."}],"answer":"C","explanation":"Đây là câu hỏi tìm **phương án ngoại lệ/sai**. Theo đáp án của đề cương, phương án **C** là nội dung không phù hợp: **Hoạt động đại lý bảo hiểm là việc cung cấp thông tin, tư vấn cho bên mua bảo hiểm về sản phẩm bảo hiểm, điều kiện bảo hiểm, mức phí bảo hiểm, doanh nghiệp bảo hiểm, và các công việc liên quan đến việc đàm phán, thu xếp và thực hiện hợp đồng bảo hiểm theo yêu cầu của bên mua bảo hiểm.**. Khi làm bài, cần chú ý từ khóa phủ định như **“sai”, “không”, “ngoại trừ”**.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":113,"category":"Bảo hiểm con người","question":"Trong hợp đồng bảo hiểm nhân thọ, hợp đồng bảo hiểm sức khỏe, bên mua bảo hiểm có quyền lợi có thể được bảo hiểm đối với những người nào sau đây:","options":[{"key":"A","text":"Người có quyền lợi về tài chính hoặc quan hệ lao động với bên mua bảo hiểm."},{"key":"B","text":"Người có quan hệ nuôi dưỡng, cấp dưỡng với bên mua bảo hiểm."},{"key":"C","text":"Người được bảo hiểm đồng ý bằng văn bản cho bên mua bảo hiểm mua bảo hiểm sức khỏe cho mình."},{"key":"D","text":"A, B, C đúng."}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **A, B, C đúng.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng.**."},{"id":114,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, khoản tiền mà bên mua bảo hiểm phải đóng cho doanh nghiệp bảo hiểm theo quy định của pháp luật hoặc do các bên thỏa thuận trong hợp đồng bảo hiểm là:","options":[{"key":"A","text":"Số tiền bảo hiểm"},{"key":"B","text":"Phí bảo hiểm"},{"key":"C","text":"Giá trị bảo hiểm"},{"key":"D","text":"Số tiền bồi thường"}],"answer":"B","explanation":"Khái niệm cần nhớ trong câu này là: **Phí bảo hiểm**. Đáp án đúng là **B**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Phí bảo hiểm**."},{"id":115,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, doanh nghiệp bảo hiểm có các quyền nào trong hoạt động đại lý bảo hiểm:","options":[{"key":"A","text":"Quyết định mức chi trả hoa hồng đại lý bảo hiểm trong hợp đồng đại lý bảo hiểm không vượt quá mức tối đa theo quy định của Bộ trưởng Bộ Tài chính"},{"key":"B","text":"Nhận và quản lý tiền ký quỹ hoặc tài sản thế chấp của đại lý bảo hiểm nếu có thỏa thuận trong hợp đồng đại lý bảo hiểm"},{"key":"C","text":"Yêu cầu đại lý bảo hiểm thanh toán phí bảo hiểm thu được theo thỏa thuận trong hợp đồng bảo hiểm."},{"key":"D","text":"A, B, C đúng"}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **A, B, C đúng**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng**."},{"id":116,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phát biểu nào sau đây đúng về điều khoản loại trừ trách nhiệm bảo hiểm:","options":[{"key":"A","text":"Điều khoản loại trừ trách nhiệm bảo hiểm quy định các trường hợp doanh nghiệp bảo hiểm, chi nhánh doanh nghiệp bảo hiểm phi nhân thọ nước ngoài không phải bồi thường, trả tiền bảo hiểm."},{"key":"B","text":"Điều khoản loại trừ trách nhiệm bảo hiểm quy định trường hợp doanh nghiệp bảo hiểm không phải trả tiền cho người thứ 3 khi người được bảo hiểm gây thiệt hại cho người thứ 3."},{"key":"C","text":"Điều khoản loại trừ trách nhiệm bảo hiểm được quy định theo thông lệ quốc tế, không cần có trong hợp đồng bảo hiểm."},{"key":"D","text":"A, B đúng."}],"answer":"A","explanation":"Theo đáp án của đề cương, phương án **A** là nội dung đúng: **Điều khoản loại trừ trách nhiệm bảo hiểm quy định các trường hợp doanh nghiệp bảo hiểm, chi nhánh doanh nghiệp bảo hiểm phi nhân thọ nước ngoài không phải bồi thường, trả tiền bảo hiểm.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Điều khoản loại trừ trách nhiệm bảo hiểm quy định các trường hợp doanh nghiệp bảo hiểm, chi…**."},{"id":117,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, cơ quan, tổ chức nào sau đây có trách nhiệm giám sát hoạt động đại lý bảo hiểm:","options":[{"key":"A","text":"Bộ Kế hoạch và Đầu tư"},{"key":"B","text":"Bộ Công Thương"},{"key":"C","text":"Bộ Tài chính"},{"key":"D","text":"Hiệp hội Bảo hiểm Việt Nam."}],"answer":"C","explanation":"Theo đáp án của đề cương, đáp án đúng là **C**: **Bộ Tài chính**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Bộ Tài chính**."},{"id":118,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, chọn phương án đúng nhất về hợp đồng bảo hiểm:","options":[{"key":"A","text":"Hợp đồng bảo hiểm hàng hải được áp dụng theo quy định của Bộ luật hàng hải; đối với những vấn đề mà Bộ luật hàng hải không quy định thì áp dụng theo quy định của Luật Kinh doanh bảo hiểm."},{"key":"B","text":"Hợp đồng bảo hiểm hàng hải được áp dụng theo quy định của Luật kinh doanh bảo hiểm; đối với những vấn đề mà Luật kinh doanh bảo hiểm không quy định thì áp dụng theo quy định của Bộ luật hàng hải."},{"key":"C","text":"Những vấn đề liên quan đến hợp đồng bảo hiểm không quy định trong Luật Kinh doanh bảo hiểm thì áp dụng theo quy định của Bộ luật dân sự và các quy định khác của pháp luật liên quan."},{"key":"D","text":"A, C đúng"},{"key":"E","text":"B, C đúng."}],"answer":"D","explanation":"Theo đáp án của đề cương, phương án **D** là nội dung đúng: **A, C đúng**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, C đúng**."},{"id":119,"category":"Kiến thức chung","question":"Mức khấu trừ là khoản tiền mà người được bảo hiểm phải tự chịu và được khấu trừ từ số tiền mà doanh nghiệp bảo hiểm phải trả cho người được bảo hiểm. Mức khấu trừ thường áp dụng cho (chọn phương án đúng nhất):","options":[{"key":"A","text":"Bảo hiểm tài sản."},{"key":"B","text":"Bảo hiểm nhân thọ."},{"key":"C","text":"Bảo hiểm chi phí y tế."},{"key":"D","text":"A, C đúng."}],"answer":"D","explanation":"Theo đáp án của đề cương, phương án **D** là nội dung đúng: **A, C đúng.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, C đúng.**."},{"id":120,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, chọn phương án đúng nhất về “Nguyên tắc thế quyền”:","options":[{"key":"A","text":"Người được bảo hiểm có trách nhiệm chuyển giao cho doanh nghiệp bảo hiểm quyền yêu cầu người thứ ba có hành vi gây thiệt hại chịu trách nhiệm bồi hoàn trong phạm vi số tiền bồi thường bảo hiểm."},{"key":"B","text":"Nguyên tắc thế quyền không áp dụng đối với hợp đồng bảo hiểm nhân thọ và hợp đồng bảo hiểm sức khỏe."},{"key":"C","text":"A, B đúng."},{"key":"D","text":"A, B sai."}],"answer":"C","explanation":"Theo đáp án của đề cương, phương án **C** là nội dung đúng: **A, B đúng.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B đúng.**."},{"id":121,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, doanh nghiệp bảo hiểm không được áp dụng điều khoản loại trừ trách nhiệm bảo hiểm về việc chậm thông báo trong trường hợp nào sau đây:","options":[{"key":"A","text":"Bên mua bảo hiểm chậm thông báo sự kiện bảo hiểm trong mọi trường hợp."},{"key":"B","text":"Bên mua bảo hiểm chậm thông báo sự kiện bảo hiểm do có sự kiện bất khả kháng"},{"key":"C","text":"Bên mua bảo hiểm chậm thông báo sự kiện bảo hiểm do có sự kiện trở ngại khách quan."},{"key":"D","text":"B, C đúng"}],"answer":"D","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **D**: **B, C đúng**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **B, C đúng**."},{"id":122,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, chọn phương án đúng nhất:","options":[{"key":"A","text":"Doanh nghiệp bảo hiểm phi nhân thọ không được phép kinh doanh bảo hiểm nhân thọ và ngược lại."},{"key":"B","text":"Doanh nghiệp bảo hiểm nhân thọ được phép kinh doanh các sản phẩm thuộc loại hình bảo hiểm sức khỏe, trừ các sản phẩm có thời hạn từ 01 năm trở xuống và các sản phẩm bảo hiểm cho rủi ro tử vong có thời hạn từ 01 năm trở xuống."},{"key":"C","text":"A, B đúng."}],"answer":"A","explanation":"Theo đáp án của đề cương, phương án **A** là nội dung đúng: **Doanh nghiệp bảo hiểm phi nhân thọ không được phép kinh doanh bảo hiểm nhân thọ và ngược lại.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Doanh nghiệp bảo hiểm phi nhân thọ không được phép kinh doanh bảo hiểm nhân thọ và ngược lại.**."},{"id":123,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, bên mua bảo hiểm có quyền:","options":[{"key":"A","text":"Chuyển giao hợp đồng bảo hiểm theo quy định của pháp luật."},{"key":"B","text":"Cung cấp cho bên mua bảo hiểm bằng chứng giao kết hợp đồng bảo hiểm"},{"key":"C","text":"Từ chối cung cấp thông tin có liên quan đến việc giao kết và thực hiện hợp đồng bảo hiểm theo yêu cầu của doanh nghiệp bảo hiểm."},{"key":"D","text":"A, B đúng."}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Chuyển giao hợp đồng bảo hiểm theo quy định của pháp luật.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Chuyển giao hợp đồng bảo hiểm theo quy định của pháp luật.**."},{"id":124,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, đối với hợp đồng bảo hiểm tài sản, trong trường hợp đơn phương chấm dứt thực hiện hợp đồng bảo hiểm khi bên mua bảo hiểm không đóng đủ phí bảo hiểm sau thời gian gia hạn đóng phí bảo hiểm theo thoả thuận trong hợp đồng bảo hiểm thì:","options":[{"key":"A","text":"Doanh nghiệp bảo hiểm có trách nhiệm bồi thường cho người được bảo hiểm khi sự kiện bảo hiểm xảy ra trước thời điểm đơn phương chấm dứt thực hiện hợp đồng bảo hiểm và có quyền khấu trừ phí bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm."},{"key":"B","text":"Bên mua bảo hiểm vẫn phải đóng đủ phí bảo hiểm đến thời điểm đơn phương chấm dứt thực hiện hợp đồng bảo hiểm"},{"key":"C","text":"A, B đúng"},{"key":"D","text":"A, B sai"}],"answer":"C","explanation":"Theo đáp án của đề cương, đáp án **C** là **A, B đúng**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B đúng**."},{"id":125,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, doanh nghiệp bảo hiểm có quyền:","options":[{"key":"A","text":"Thu phí bảo hiểm theo thoả thuận trong hợp đồng bảo hiểm"},{"key":"B","text":"Yêu cầu bên mua bảo hiểm cung cấp đầy đủ, trung thực mọi thông tin có liên quan đến việc giao kết và thực hiện hợp đồng bảo hiểm"},{"key":"C","text":"Bảo mật thông tin do bên mua bảo hiểm, người được bảo hiểm cung cấp"},{"key":"D","text":"A, B đúng."}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **A, B đúng.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B đúng.**."},{"id":126,"category":"Kiến thức chung","question":"Chọn phương án đúng về cách thức quy định về loại trừ bảo hiểm:","options":[{"key":"A","text":"Loại trừ bảo hiểm được tự động thực hiện theo tập quán quốc tế."},{"key":"B","text":"Loại trừ bảo hiểm được áp dụng theo quy tắc, điều khoản bảo hiểm do Hiệp hội bảo hiểm Việt Nam ban hành."},{"key":"C","text":"Loại trừ bảo hiểm được căn cứ theo các điều kiện, điều khoản quy định trong Quy tắc bảo hiểm và các điều khoản sửa đổi, bổ sung (nếu có) kèm theo hợp đồng bảo hiểm."},{"key":"D","text":"A, B, C đúng."}],"answer":"C","explanation":"Theo đáp án của đề cương, phương án **C** là nội dung đúng: **Loại trừ bảo hiểm được căn cứ theo các điều kiện, điều khoản quy định trong Quy tắc bảo hiểm và các điều khoản sửa đổi, bổ sung (nếu có) kèm theo hợp đồng bảo hiểm.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Loại trừ bảo hiểm được căn cứ theo các điều kiện, điều khoản quy định trong Quy tắc bảo…**."},{"id":127,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Tài sản nào sau đây được bảo hiểm theo đơn bảo hiểm “Mọi rủi ro tài sản” của Hiệp hội bảo hiểm Vương quốc Anh (ABI):","options":[{"key":"A","text":"Hệ thống thoát nước của bể bơi."},{"key":"B","text":"Giếng."},{"key":"C","text":"Cây cảnh."},{"key":"D","text":"Nhà xưởng, máy móc, thiết bị."}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **Nhà xưởng, máy móc, thiết bị.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Nhà xưởng, máy móc, thiết bị.**."},{"id":128,"category":"Luật Kinh doanh bảo hiểm","question":"Khoản tiền mà bên mua bảo hiểm đóng cho doanh nghiệp bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm là:","options":[{"key":"A","text":"Số tiền bảo hiểm."},{"key":"B","text":"Phí bảo hiểm."},{"key":"C","text":"Giá trị bảo hiểm."},{"key":"D","text":"Số tiền bồi thường."}],"answer":"B","explanation":"Khái niệm cần nhớ trong câu này là: **Phí bảo hiểm.**. Đáp án đúng là **B**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Phí bảo hiểm.**."},{"id":129,"category":"Bảo hiểm con người","question":"Chọn phương án đúng nhất về các điểm loại trừ thông thường trong một sản phẩm chăm sóc sức khỏe:","options":[{"key":"A","text":"Hỗ trợ sinh sản."},{"key":"B","text":"Rối loạn tâm lý, trầm cảm."},{"key":"C","text":"Tiêm phòng, tiêm chủng."},{"key":"D","text":"A, B, C đúng."}],"answer":"D","explanation":"Theo đáp án của đề cương, phương án **D** là nội dung đúng: **A, B, C đúng.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng.**."},{"id":130,"category":"Bảo hiểm con người","question":"Người được bảo hiểm tham gia hợp đồng bảo hiểm sức khỏe với quyền lợi bảo hiểm tai nạn, do tự vệ nên đã tham gia đánh nhau dẫn đến thương tật bộ phận. Trong trường hợp này, doanh nghiệp bảo hiểm có chi trả bảo hiểm cho người được bảo hiểm không?","options":[{"key":"A","text":"Có."},{"key":"B","text":"Không."}],"answer":"A","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **A**: **Có.**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Có.**."},{"id":131,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, doanh nghiệp bảo hiểm có quyền đơn phương chấm dứt thực hiện hợp đồng bảo hiểm trong trường hợp nào sau đây:","options":[{"key":"A","text":"Bên mua bảo hiểm không có quyền lợi có thể được bảo hiểm."},{"key":"B","text":"Bên mua bảo hiểm không còn quyền lợi có thể được bảo hiểm."},{"key":"C","text":"Bên mua bảo hiểm không đóng phí bảo hiểm hoặc không đóng đủ phí bảo hiểm theo thời hạn thỏa thuận hoặc sau thời gian gia hạn đóng phí."},{"key":"D","text":"B, C đúng."}],"answer":"C","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **C**: **Bên mua bảo hiểm không đóng phí bảo hiểm hoặc không đóng đủ phí bảo hiểm theo thời hạn thỏa thuận hoặc sau thời gian gia hạn đóng phí.**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Bên mua bảo hiểm không đóng phí bảo hiểm hoặc không đóng đủ phí bảo hiểm theo thời hạn thỏa…**."},{"id":132,"category":"Bảo hiểm xe cơ giới","question":"Theo đơn Bảo hiểm trách nhiệm dân sự của chủ xe cơ giới đối với hàng hóa trên xe: Do lái xe bảo quản không cẩn thận hàng hóa sau tổn thất dẫn đến hàng bị mất cắp. Trường hợp này, doanh nghiệp bảo hiểm có bồi thường cho người được bảo hiểm không?","options":[{"key":"A","text":"Có."},{"key":"B","text":"Không."}],"answer":"B","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **B**: **Không.**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Không.**."},{"id":133,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, trường hợp hợp đồng bảo hiểm có điều khoản không rõ ràng dẫn đến có cách hiểu khác nhau thì điều khoản đó được giải thích theo hướng có lợi cho:","options":[{"key":"A","text":"Bên mua bảo hiểm."},{"key":"B","text":"Doanh nghiệp bảo hiểm."},{"key":"C","text":"A, B đúng."},{"key":"D","text":"A, B sai"}],"answer":"A","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **A**: **Bên mua bảo hiểm.**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Bên mua bảo hiểm.**."},{"id":134,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Trong đơn bảo hiểm mọi rủi ro xây dựng/lắp đặt (CAR/EAR) của nhà tái bảo hiểm Munich Re, không có điều khoản sửa đổi, bổ sung, tổn thất gây ra đối với bên thứ ba trong thời gian bảo hành có thuộc trách nhiệm bảo hiểm không:","options":[{"key":"A","text":"Có."},{"key":"B","text":"Không."}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án **B** là **Không.**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Không.**."},{"id":135,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, bảo hiểm bắt buộc là sản phẩm bảo hiểm nhằm mục đích:","options":[{"key":"A","text":"Bảo vệ lợi ích của người tham gia bảo hiểm."},{"key":"B","text":"Bảo vệ lợi ích công cộng, môi trường và an toàn xã hội."},{"key":"C","text":"Bảo vệ lợi ích của doanh nghiệp bảo hiểm."},{"key":"D","text":"A, B, C đúng."}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án đúng là **B**: **Bảo vệ lợi ích công cộng, môi trường và an toàn xã hội.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Bảo vệ lợi ích công cộng, môi trường và an toàn xã hội.**."},{"id":136,"category":"Kiến thức chung","question":"Chọn phương án đúng nhất về việc xác định số tiền mà doanh nghiệp bảo hiểm phải  chi trả theo “Nguyên tắc khoán” khi xảy ra sự kiện bảo hiểm:","options":[{"key":"A","text":"Số tiền đã được thỏa thuận tại hợp đồng bảo hiểm."},{"key":"B","text":"Số tiền thiệt hại thực tế."},{"key":"C","text":"Số tiền chênh lệch giữa số tiền bảo hiểm thỏa thuận tại hợp đồng bảo hiểm và thiệt hại thực tế."},{"key":"D","text":"A, B, C đúng."}],"answer":"A","explanation":"Theo đáp án của đề cương, phương án **A** là nội dung đúng: **Số tiền đã được thỏa thuận tại hợp đồng bảo hiểm.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Số tiền đã được thỏa thuận tại hợp đồng bảo hiểm.**."},{"id":137,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, đối với hợp đồng bảo hiểm trách nhiệm, trách nhiệm của doanh nghiệp bảo hiểm phát sinh khi:","options":[{"key":"A","text":"Người thứ ba yêu cầu người được bảo hiểm bồi thường do có hành vi gây thiệt hại cho người thứ ba trong thời hạn bảo hiểm."},{"key":"B","text":"Người thứ ba yêu cầu người được bảo hiểm bồi thường do có hành vi gây thiệt hại cho người thứ ba"},{"key":"C","text":"Doanh nghiệp bảo hiểm yêu cầu người được bảo hiểm bồi thường do có hành vi gây thiệt hại cho người thứ ba trong thời hạn bảo hiểm."},{"key":"D","text":"A,B,C đúng"}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Người thứ ba yêu cầu người được bảo hiểm bồi thường do có hành vi gây thiệt hại cho người thứ ba trong thời hạn bảo hiểm.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Người thứ ba yêu cầu người được bảo hiểm bồi thường do có hành vi gây thiệt hại cho người…**."},{"id":138,"category":"Kiến thức chung","question":"Chọn phương án sai:","options":[{"key":"A","text":"Bên mua bảo hiểm có thể đồng thời là người được bảo hiểm hoặc người thụ hưởng."},{"key":"B","text":"Người được bảo hiểm có thể đồng thời là người thụ hưởng."},{"key":"C","text":"Người thụ hưởng được bên mua bảo hiểm chỉ định để nhận tiền bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm."},{"key":"D","text":"Đại lý bảo hiểm và môi giới bảo hiểm đại diện cho doanh nghiệp bảo hiểm và được hưởng hoa hồng bảo hiểm do doanh nghiệp bảo hiểm chi trả."}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **Đại lý bảo hiểm và môi giới bảo hiểm đại diện cho doanh nghiệp bảo hiểm và được hưởng hoa hồng bảo hiểm do doanh nghiệp bảo hiểm chi trả.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":139,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Chọn phương án sai về hợp đồng bảo hiểm trách nhiệm nghề nghiệp:","options":[{"key":"A","text":"Thời hạn hồi tố là 01 năm trước ngày hợp đồng bảo hiểm có hiệu lực."},{"key":"B","text":"Chỉ hồi tố khi không có tổn thất hoặc tổn thất tiềm tàng không được biết đến tại thời điểm giao kết hợp đồng bảo hiểm"},{"key":"C","text":"Nếu tổn thất xảy ra trước thời điểm bắt đầu hiệu lực hồi tố thì khiếu nại liên quan vẫn thuộc trách nhiệm bảo hiểm."}],"answer":"C","explanation":"Theo đáp án của đề cương, đáp án đúng là **C**: **Nếu tổn thất xảy ra trước thời điểm bắt đầu hiệu lực hồi tố thì khiếu nại liên quan vẫn thuộc trách nhiệm bảo hiểm.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":140,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Phát biểu sau là đúng hay sai: \"Trong quá trình vận chuyển súc vật sống nếu bị ốm, chết do dịch bệnh thì doanh nghiệp bảo hiểm có trách nhiệm bồi thường thiệt hại cho chủ hàng\":","options":[{"key":"A","text":"Đúng"},{"key":"B","text":"Sai"}],"answer":"B","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **B**: **Sai**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":141,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phát biểu nào dưới đây đúng:","options":[{"key":"A","text":"Bên mua bảo hiểm là tổ chức, cá nhân giao kết hợp đồng bảo hiểm với doanh nghiệp bảo hiểm và đóng phí bảo hiểm."},{"key":"B","text":"Người thụ hưởng là tổ chức, cá nhân được doanh nghiệp bảo hiểm chỉ định để nhận tiền bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm"},{"key":"C","text":"Bên mua bảo hiểm và người được bảo hiểm không thể là người thụ hưởng."},{"key":"D","text":"A, B, C đúng."}],"answer":"A","explanation":"Theo đáp án của đề cương, phương án **A** là nội dung đúng: **Bên mua bảo hiểm là tổ chức, cá nhân giao kết hợp đồng bảo hiểm với doanh nghiệp bảo hiểm và đóng phí bảo hiểm.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Bên mua bảo hiểm là tổ chức, cá nhân giao kết hợp đồng bảo hiểm với doanh nghiệp bảo hiểm…**."},{"id":142,"category":"Bảo hiểm xe cơ giới","question":"Trong thời hạn bảo hiểm của hợp đồng bảo hiểm thiệt hại vật chất xe ô tô, trường hợp xe bị tai nạn dẫn đến thiệt hại và lốp xe bị nổ, xe bị tổn thất toàn bộ, doanh nghiệp bảo hiểm chi trả bồi thường như  thế nào:","options":[{"key":"A","text":"Bồi thường toàn bộ thiệt hại bao gồm cả chiếc lốp bị nổ."},{"key":"B","text":"Bồi thường toàn bộ thiệt hại trừ chiếc lốp bị nổ."}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án **A** là **Bồi thường toàn bộ thiệt hại bao gồm cả chiếc lốp bị nổ.**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Bồi thường toàn bộ thiệt hại bao gồm cả chiếc lốp bị nổ.**."},{"id":143,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, chọn phương án đúng nhất về sự kiện bảo hiểm:","options":[{"key":"A","text":"Là sự kiện chủ quan do các bên thỏa thuận mà khi sự kiện đó xảy ra thì doanh nghiệp bảo hiểm phải bồi thường, trả tiền bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm."},{"key":"B","text":"Là sự kiện khách quan do các bên thỏa thuận mà khi sự kiện đó xảy ra thì doanh nghiệp bảo hiểm phải bồi thường, trả tiền bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm."},{"key":"C","text":"Là sự kiện do pháp luật quy định mà khi sự kiện đó xảy ra thì doanh nghiệp bảo hiểm phải bồi thường, trả tiền bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm."},{"key":"D","text":"B, C đúng."}],"answer":"D","explanation":"Theo đáp án của đề cương, phương án **D** là nội dung đúng: **B, C đúng.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **B, C đúng.**."},{"id":144,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Theo sản phẩm bảo hiểm trách nhiệm nghề nghiệp kỹ sư tư vấn thiết kế xây dựng, người được bảo hiểm có thể vừa là người tư vấn thiết kế vừa là người xây/lắp không:","options":[{"key":"A","text":"Có."},{"key":"B","text":"Không."}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án đúng là **B**: **Không.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Không.**."},{"id":145,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, đối với bảo hiểm tài sản, trừ trường hợp có thoả thuận khác, số tiền bồi thường mà doanh nghiệp bảo hiểm phải trả cho người được bảo hiểm được xác định trên cơ sở:","options":[{"key":"A","text":"Giá thị trường của tài sản được bảo hiểm tại thời điểm, nơi xảy ra tổn thất và mức độ thiệt hại thực tế"},{"key":"B","text":"Giá thị trường của tài sản được bảo hiểm tại thời điểm giao kết hợp đồng bảo hiểm"},{"key":"C","text":"Thỏa thuận giữa bên mua bảo hiểm và người thứ ba gây thiệt hại"},{"key":"D","text":"Nguyên giá của tài sản"}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án **A** là **Giá thị trường của tài sản được bảo hiểm tại thời điểm, nơi xảy ra tổn thất và mức độ thiệt hại thực tế**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Giá thị trường của tài sản được bảo hiểm tại thời điểm, nơi xảy ra tổn thất và mức độ thiệt…**."},{"id":146,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Chọn phương án sai về phạm vi bảo hiểm của quy tắc bảo hiểm đổ vỡ máy móc  “Sự cố hư hỏng máy móc” của nhà tái bảo hiểm Munich Re:","options":[{"key":"A","text":"Thiệt hại do khuyết tật về đúc/nguyên vật liệu."},{"key":"B","text":"Thiệt hại do lỗi thiết kế."},{"key":"C","text":"Thiệt hại do đoản mạch, quá điện áp."},{"key":"D","text":"Thiệt hại do hỏa hoạn, sét đánh trực tiếp vào máy móc."}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **Thiệt hại do hỏa hoạn, sét đánh trực tiếp vào máy móc.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":147,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Cách xác định lợi nhuận gộp theo Đơn bảo hiểm “Gián đoạn kinh doanh” của Hiệp hội bảo hiểm Vương quốc Anh (ABI) nào sau đây không đúng:","options":[{"key":"A","text":"Lợi nhuận gộp là lợi nhuận ròng trước thuế cộng chi phí cố định."},{"key":"B","text":"Lợi nhuận gộp là lợi nhuận kinh doanh thuần sau thuế và chi phí cố định."},{"key":"C","text":"Lợi nhuận gộp được xác định bằng doanh thu trừ đi chi phí biến đổi và các chi phí cố định mà người được bảo hiểm tự bảo hiểm."},{"key":"D","text":"Lợi nhuận gộp = (Doanh thu + Giá trị hàng tồn kho cuối kỳ + Giá trị sản phẩm dở dang cuối kỳ) – (Giá trị hàng tồn kho đầu kỳ + Giá trị sản phẩm dở dang đầu kỳ + Các khoản chi phí hoạt động không được bảo hiểm)."}],"answer":"B","explanation":"Đây là câu hỏi tìm **phương án ngoại lệ/sai**. Theo đáp án của đề cương, phương án **B** là nội dung không phù hợp: **Lợi nhuận gộp là lợi nhuận kinh doanh thuần sau thuế và chi phí cố định.**. Khi làm bài, cần chú ý từ khóa phủ định như **“sai”, “không”, “ngoại trừ”**.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":148,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, kinh doanh bảo hiểm bao gồm hoạt động nào sau đây:","options":[{"key":"A","text":"Hoạt động của doanh nghiệp bảo hiểm chấp nhận rủi ro của người được bảo hiểm, trên cơ sở bên mua bảo hiểm đóng phí bảo hiểm để bồi thường, trả tiền bảo hiểm khi xảy ra sự kiện bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm."},{"key":"B","text":"Hoạt động của doanh nghiệp bảo hiểm nhằm mục đích sinh lợi, theo đó doanh nghiệp bảo hiểm nhận một khoản phí bảo hiểm của doanh nghiệp bảo hiểm khác để cam kết bồi thường cho các trách nhiệm đã nhận bảo hiểm."},{"key":"C","text":"A, B đúng"}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Hoạt động của doanh nghiệp bảo hiểm chấp nhận rủi ro của người được bảo hiểm, trên cơ sở bên mua bảo hiểm đóng phí bảo hiểm để bồi thường, trả tiền bảo hiểm khi xảy ra sự kiện bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Hoạt động của doanh nghiệp bảo hiểm chấp nhận rủi ro của người được bảo hiểm, trên cơ sở…**."},{"id":149,"category":"Luật Kinh doanh bảo hiểm","question":"Chọn phương án đúng nhất: Theo Luật Kinh doanh bảo hiểm, số tiền bảo hiểm của hợp đồng bảo hiểm tài sản là:","options":[{"key":"A","text":"Số tiền mà doanh nghiệp bảo hiểm phải trả cho người được bảo hiểm khi kết thúc hợp đồng bảo hiểm."},{"key":"B","text":"Số tiền mà doanh nghiệp bảo hiểm phải trả cho người được bảo hiểm trong một sự kiện bảo hiểm hoặc trong cả thời hạn bảo hiểm theo thỏa thuận tại hợp đồng bảo hiểm."},{"key":"C","text":"Số tiền mà bên mua bảo hiểm và doanh nghiệp bảo hiểm thỏa thuận trong hợp đồng bảo hiểm để bảo hiểm cho tài sản và thiệt hại trên cơ sở yêu cầu của bên mua bảo hiểm."},{"key":"D","text":"A, B, C đúng"}],"answer":"C","explanation":"Theo đáp án của đề cương, phương án **C** là nội dung đúng: **Số tiền mà bên mua bảo hiểm và doanh nghiệp bảo hiểm thỏa thuận trong hợp đồng bảo hiểm để bảo hiểm cho tài sản và thiệt hại trên cơ sở yêu cầu của bên mua bảo hiểm.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Số tiền mà bên mua bảo hiểm và doanh nghiệp bảo hiểm thỏa thuận trong hợp đồng bảo hiểm để…**."},{"id":150,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, chọn phương án đúng nhất về hành vi bị nghiêm cấm trong hoạt động kinh doanh bảo hiểm:","options":[{"key":"A","text":"Cấu kết giữa các doanh nghiệp bảo hiểm hoặc giữa doanh nghiệp bảo hiểm với bên mua bảo hiểm nhằm phân chia thị trường bảo hiểm, khép kín dịch vụ bảo hiểm."},{"key":"B","text":"Can thiệp trái pháp luật vào việc lựa chọn doanh nghiệp bảo hiểm."},{"key":"C","text":"Lợi dụng chức vụ, quyền hạn chỉ định, yêu cầu, ép buộc, ngăn cản tổ chức, cá nhân tham gia bảo hiểm."},{"key":"D","text":"Đe dọa, cưỡng ép giao kết hợp đồng bảo hiểm."}],"answer":"D","explanation":"Theo đáp án của đề cương, phương án **D** là nội dung đúng: **Đe dọa, cưỡng ép giao kết hợp đồng bảo hiểm.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Đe dọa, cưỡng ép giao kết hợp đồng bảo hiểm.**."},{"id":151,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phát biểu nào sau đây sai:","options":[{"key":"A","text":"Người được bảo hiểm là tổ chức, cá nhân có tài sản, trách nhiệm dân sự, sức khỏe, tính mạng, nghĩa vụ hoặc lợi ích kinh tế được bảo hiểm theo hợp đồng bảo hiểm."},{"key":"B","text":"Người thụ hưởng là tổ chức, cá nhân được bên mua bảo hiểm hoặc người được bảo hiểm chỉ định để nhận tiền bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm."},{"key":"C","text":"Người thụ hưởng là tổ chức, cá nhân được doanh nghiệp bảo hiểm chỉ định để nhận tiền bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm."},{"key":"D","text":"Bên mua bảo hiểm là tổ chức, cá nhân giao kết hợp đồng bảo hiểm với doanh nghiệp bảo hiểm và đóng phí bảo hiểm."}],"answer":"C","explanation":"Đây là câu hỏi tìm **phương án ngoại lệ/sai**. Theo đáp án của đề cương, phương án **C** là nội dung không phù hợp: **Người thụ hưởng là tổ chức, cá nhân được doanh nghiệp bảo hiểm chỉ định để nhận tiền bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm.**. Khi làm bài, cần chú ý từ khóa phủ định như **“sai”, “không”, “ngoại trừ”**.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":152,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, việc chuyển giao danh mục hợp đồng bảo hiểm phải kèm theo việc chuyển giao các đối tượng nào dưới đây của toàn bộ danh mục hợp đồng bảo hiểm được chuyển giao:","options":[{"key":"A","text":"Tài sản tương ứng với dự phòng nghiệp vụ."},{"key":"B","text":"Quỹ dự trữ bắt buộc"},{"key":"C","text":"A, B đúng."}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Tài sản tương ứng với dự phòng nghiệp vụ.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Tài sản tương ứng với dự phòng nghiệp vụ.**."},{"id":154,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, đại lý bảo hiểm có nghĩa vụ nào sau đây:","options":[{"key":"A","text":"Cung cấp các thông tin về sản phẩm bảo hiểm và giải thích rõ ràng, đầy đủ về quyền lợi bảo hiểm, điều khoản loại trừ trách nhiệm bảo hiểm"},{"key":"B","text":"Giữ bí mật thông tin khách hàng, sử dụng thông tin khách hàng đúng mục đích và không được cung cấp cho bên thứ ba mà không có sự chấp thuận của khách hàng, trừ trường hợp cung cấp theo quy định của pháp luật"},{"key":"C","text":"A, B đúng"},{"key":"D","text":"A, B sai"}],"answer":"C","explanation":"Theo đáp án của đề cương, đáp án đúng là **C**: **A, B đúng**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B đúng**."},{"id":155,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, bảo hiểm bắt buộc bao gồm:","options":[{"key":"A","text":"Bảo hiểm bắt buộc tai nạn người ngồi trên xe cơ giới"},{"key":"B","text":"Bảo hiểm bắt buộc trách nhiệm dân sự của chủ xe cơ giới."},{"key":"C","text":"Bảo hiểm bắt buộc thiệt hại vật chất xe cơ giới."},{"key":"D","text":"A, B, C đúng"}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án đúng là **B**: **Bảo hiểm bắt buộc trách nhiệm dân sự của chủ xe cơ giới.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Bảo hiểm bắt buộc trách nhiệm dân sự của chủ xe cơ giới.**."},{"id":156,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, bên mua bảo hiểm có quyền hủy bỏ hợp đồng và được hoàn lại phí bảo hiểm đã đóng trong trường hợp nào sau đây:","options":[{"key":"A","text":"Doanh nghiệp bảo hiểm cố ý không thực hiện nghĩa vụ cung cấp thông tin nhằm giao kết hợp đồng bảo hiểm."},{"key":"B","text":"Doanh nghiệp bảo hiểm cung cấp thông tin sai sự thật nhằm giao kết hợp đồng bảo hiểm."},{"key":"C","text":"A, B  đúng."},{"key":"D","text":"A, B  sai."}],"answer":"C","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **C**: **A, B  đúng.**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B  đúng.**."},{"id":157,"category":"Luật Kinh doanh bảo hiểm","question":"Bên mua bảo hiểm có thể thỏa thuận thanh toán phí bảo hiểm cho doanh nghiệp bảo hiểm theo quy định và phương thức sau:","options":[{"key":"A","text":"Thanh toán một lần."},{"key":"B","text":"Thanh toán làm nhiều kỳ."},{"key":"C","text":"Thời hạn thanh toán phí bảo hiểm không được vượt quá thời hạn bảo hiểm."},{"key":"D","text":"A, B, C đúng."}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **A, B, C đúng.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng.**."},{"id":158,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, trong trường hợp đại lý bảo hiểm vi phạm hợp đồng đại lý bảo hiểm, gây thiệt hại đến quyền, lợi ích hợp pháp của người được bảo hiểm thì:","options":[{"key":"A","text":"Doanh nghiệp bảo hiểm vẫn phải chịu trách nhiệm thực hiện các nghĩa vụ theo thỏa thuận trong hợp đồng bảo hiểm do đại lý bảo hiểm thu xếp giao kết"},{"key":"B","text":"Hợp đồng đại lý bảo hiểm tự động chấm dứt"},{"key":"C","text":"Đại lý bảo hiểm phải bồi hoàn cho doanh nghiệp bảo hiểm các khoản tiền mà doanh nghiệp bảo hiểm đã bồi thường cho người được bảo hiểm, bên mua bảo hiểm"},{"key":"D","text":"A, C đúng"}],"answer":"D","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **D**: **A, C đúng**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, C đúng**."},{"id":159,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phát biểu nào dưới đây đúng:","options":[{"key":"A","text":"Các loại hợp đồng bảo hiểm bao gồm: hợp đồng bảo hiểm ngắn hạn, hợp đồng bảo hiểm dài hạn."},{"key":"B","text":"Hợp đồng bảo hiểm là sự thỏa thuận giữa bên mua bảo hiểm và đại lý bảo hiểm."},{"key":"C","text":"Trường hợp hợp đồng bảo hiểm có điều khoản không rõ ràng dẫn đến có cách hiểu khác nhau thì điều khoản đó được giải thích theo hướng có lợi cho bên mua bảo hiểm."},{"key":"D","text":"A, C đúng."}],"answer":"C","explanation":"Theo đáp án của đề cương, phương án **C** là nội dung đúng: **Trường hợp hợp đồng bảo hiểm có điều khoản không rõ ràng dẫn đến có cách hiểu khác nhau thì điều khoản đó được giải thích theo hướng có lợi cho bên mua bảo hiểm.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Trường hợp hợp đồng bảo hiểm có điều khoản không rõ ràng dẫn đến có cách hiểu khác nhau thì…**."},{"id":160,"category":"Bảo hiểm con người","question":"Khi tham gia bảo hiểm sức khỏe với quyền lợi bảo hiểm thương tật toàn bộ vĩnh viễn do tai nạn, trường hợp người được bảo hiểm bị mất hai bàn tay do tai nạn, doanh nghiệp bảo hiểm sẽ chi trả số tiền nào sau đây:","options":[{"key":"A","text":"200% số tiền bảo hiểm."},{"key":"B","text":"100% số tiền bảo hiểm."},{"key":"C","text":"50% số tiền bảo hiểm."},{"key":"D","text":"20% số tiền bảo hiểm."}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án **B** là **100% số tiền bảo hiểm.**. Mốc cần nhớ: **100**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Chốt mốc **100** và gắn với đúng điều kiện của câu."},{"id":161,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, sản phẩm bảo hiểm nào sau đây không phải là bảo hiểm bắt buộc:","options":[{"key":"A","text":"Bảo hiểm cháy, nổ bắt buộc."},{"key":"B","text":"Bảo hiểm bắt buộc trách nhiệm nghề nghiệp."},{"key":"C","text":"Bảo hiểm bắt buộc trách nhiệm dân sự của chủ xe cơ giới."},{"key":"D","text":"Bảo hiểm bắt buộc trong hoạt động đầu tư xây dựng."}],"answer":"B","explanation":"Đây là câu hỏi tìm **phương án ngoại lệ/sai**. Theo đáp án của đề cương, phương án **B** là nội dung không phù hợp: **Bảo hiểm bắt buộc trách nhiệm nghề nghiệp.**. Khi làm bài, cần chú ý từ khóa phủ định như **“sai”, “không”, “ngoại trừ”**.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":162,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, đối với bảo hiểm tài sản, doanh nghiệp bảo hiểm có quyền:","options":[{"key":"A","text":"Kiểm tra các điều kiện bảo đảm an toàn cho đối tượng bảo hiểm hoặc khuyến nghị, yêu cầu người được bảo hiểm áp dụng các biện pháp đề phòng, hạn chế rủi ro."},{"key":"B","text":"Đơn phương đình chỉ hợp đồng bảo hiểm ngay tại thời điểm phát hiện thấy người được bảo hiểm không thực hiện các biện pháp đảm bảo an toàn cho đối tượng bảo hiểm"},{"key":"C","text":"Tăng phí bảo hiểm ngay thời điểm phát hiện thấy người được bảo hiểm không thực hiện các biện pháp đảm bảo an toàn cho đối tượng bảo hiểm"},{"key":"D","text":"A, B, C đúng"}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Kiểm tra các điều kiện bảo đảm an toàn cho đối tượng bảo hiểm hoặc khuyến nghị, yêu cầu người được bảo hiểm áp dụng các biện pháp đề phòng, hạn chế rủi ro.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Kiểm tra các điều kiện bảo đảm an toàn cho đối tượng bảo hiểm hoặc khuyến nghị, yêu cầu…**."},{"id":163,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, bên mua bảo hiểm có thể mua bảo hiểm sức khỏe cho những người nào sau đây (Chọn phương án đúng nhất):","options":[{"key":"A","text":"Người được bảo hiểm đồng ý bằng văn bản cho bên mua bảo hiểm mua bảo hiểm sức khỏe cho mình"},{"key":"B","text":"Anh ruột, chị ruột, em ruột hoặc người khác có quan hệ nuôi dưỡng, cấp dưỡng với bên mua bảo hiểm"},{"key":"C","text":"Người có quyền lợi về tài chính với bên mua bảo hiểm"},{"key":"D","text":"A, B, C đúng."}],"answer":"D","explanation":"Theo đáp án của đề cương, phương án **D** là nội dung đúng: **A, B, C đúng.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng.**."},{"id":164,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, bên mua bảo hiểm có quyền:","options":[{"key":"A","text":"Yêu cầu doanh nghiệp bảo hiểm cung cấp bản yêu cầu bảo hiểm, bảng câu hỏi liên quan đến rủi ro được bảo hiểm, đối tượng bảo hiểm, quy tắc, điều kiện, điều khoản bảo hiểm và giải thích các điều kiện, điều khoản bảo hiểm."},{"key":"B","text":"Hủy bỏ hợp đồng bảo hiểm trong trường hợp doanh nghiệp bảo hiểm cố ý cung cấp thông tin sai sự thật nhằm giao kết hợp đồng bảo hiểm."},{"key":"C","text":"Yêu cầu doanh nghiệp bảo hiểm bồi thường, trả tiền bảo hiểm khi xảy ra sự kiện bảo hiểm"},{"key":"D","text":"A, B, C đúng."}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **A, B, C đúng.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng.**."},{"id":165,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, đối tượng nào dưới đây KHÔNG được thực hiện hoạt động kinh doanh bảo hiểm tại Việt Nam:","options":[{"key":"A","text":"Văn phòng đại diện của doanh nghiệp bảo hiểm nước ngoài tại Việt Nam"},{"key":"B","text":"Văn phòng đại diện của doanh nghiệp môi giới bảo hiểm nước ngoài tại Việt Nam"},{"key":"C","text":"A, B đúng"}],"answer":"C","explanation":"Theo đáp án của đề cương, đáp án đúng là **C**: **A, B đúng**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B đúng**."},{"id":166,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, đại lý bảo hiểm không có các nghĩa vụ nào sau đây:","options":[{"key":"A","text":"Thực hiện cam kết trong hợp đồng bảo hiểm được ký giữa bên mua bảo hiểm và doanh nghiệp bảo hiểm"},{"key":"B","text":"Ký quỹ hoặc thế chấp tài sản cho doanh nghiệp bảo hiểm nếu có thỏa thuận trong hợp đồng đại lý bảo hiểm"},{"key":"C","text":"Chịu sự kiểm tra, giám sát của doanh nghiệp bảo hiểm"},{"key":"D","text":"Tham dự các khóa đào tạo, cập nhật kiến thức do doanh nghiệp bảo hiểm tổ chức"}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Thực hiện cam kết trong hợp đồng bảo hiểm được ký giữa bên mua bảo hiểm và doanh nghiệp bảo hiểm**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Thực hiện cam kết trong hợp đồng bảo hiểm được ký giữa bên mua bảo hiểm và doanh nghiệp bảo…**."},{"id":167,"category":"Bảo hiểm xe cơ giới","question":"Theo đơn bảo hiểm thiệt hại vật chất xe cơ giới, khi xảy ra sự kiện bảo hiểm, doanh nghiệp bảo hiểm bồi thường cho người được bảo hiểm những trường hợp thiệt hại, chi phí nào sau đây:","options":[{"key":"A","text":"Đâm va, lật đổ, chìm, rơi toàn bộ xe."},{"key":"B","text":"Mất toàn bộ xe do trộm, cướp."},{"key":"C","text":"Chi phí cứu hộ và vận chuyển xe bị thiệt hại tới nơi sửa chữa gần nhất."},{"key":"D","text":"A, B, C đúng."},{"key":"E","text":"A, B  đúng."}],"answer":"D","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **D**: **A, B, C đúng.**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng.**."},{"id":168,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, đại lý bảo hiểm có thể được doanh nghiệp bảo hiểm ủy quyền thực hiện hoạt động nào sau đây:","options":[{"key":"A","text":"Sửa đổi, bổ sung quy tắc, điều khoản bảo hiểm cho phù hợp với tình hình thực tế của bên mua bảo hiểm"},{"key":"B","text":"Giảm phí bảo hiểm để khuyến khích bên mua bảo hiểm tham gia bảo hiểm."},{"key":"C","text":"Giới thiệu, chào bán sản phẩm bảo hiểm."},{"key":"D","text":"Giám định tổn thất."}],"answer":"C","explanation":"Theo đáp án của đề cương, đáp án đúng là **C**: **Giới thiệu, chào bán sản phẩm bảo hiểm.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Giới thiệu, chào bán sản phẩm bảo hiểm.**."},{"id":169,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, đối với bảo hiểm tài sản, bên mua bảo hiểm và doanh nghiệp bảo hiểm có thể thỏa thuận hình thức bồi thường nào dưới đây:","options":[{"key":"A","text":"Sửa chữa tài sản bị thiệt hại"},{"key":"B","text":"Thay thế tài sản bị thiệt hại bằng tài sản khác"},{"key":"C","text":"Trả tiền bồi thường"},{"key":"D","text":"A, B, C đúng"}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **A, B, C đúng**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng**."},{"id":170,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Chọn phương án sai về phạm vi bảo hiểm của quy tắc bảo hiểm đổ vỡ máy móc  “Sự cố hư hỏng máy móc (Machinery Breakdown)”:","options":[{"key":"A","text":"Thiệt hại do nổ vật lý."},{"key":"B","text":"Thiệt hại do nổ hóa học."},{"key":"C","text":"Thiệt hại do tác động của lực ly tâm."},{"key":"D","text":"Thiệt hại do hỏng hóc, trục trặc về cơ điện."}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án đúng là **B**: **Thiệt hại do nổ hóa học.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":171,"category":"Kiến thức chung","question":"Nguyên tắc thế quyền được hiểu thế nào là đúng nhất:","options":[{"key":"A","text":"Người được bảo hiểm có trách nhiệm chuyển giao cho doanh nghiệp bảo hiểm quyền yêu cầu người thứ ba có hành vi gây thiệt hại chịu trách nhiệm bồi hoàn trong phạm vi số tiền bồi thường bảo hiểm."},{"key":"B","text":"Doanh nghiệp bảo hiểm có quyền truy đòi người thứ ba gây thiệt hại trong phạm vi số tiền đã bồi thường cho người được bảo hiểm."},{"key":"C","text":"A, B đúng."},{"key":"D","text":"A, B sai."}],"answer":"C","explanation":"Theo đáp án của đề cương, đáp án đúng là **C**: **A, B đúng.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B đúng.**."},{"id":172,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, hoạt động đại lý bảo hiểm là:","options":[{"key":"A","text":"Một hoặc một số hoạt động theo ủy quyền của doanh nghiệp bảo hiểm, bao gồm: tư vấn sản phẩm bảo hiểm; giới thiệu sản phẩm bảo hiểm; chào bán sản phẩm bảo hiểm; thu xếp việc giao kết hợp đồng bảo hiểm; thu phí bảo hiểm; thu thập hồ sơ để phục vụ việc giải quyết bồi thường, trả tiền bảo hiểm."},{"key":"B","text":"Một hoặc một số hoạt động theo ủy quyền của bên mua bảo hiểm, bao gồm: tư vấn sản phẩm bảo hiểm; giới thiệu sản phẩm bảo hiểm; chào bán sản phẩm bảo hiểm; thu xếp việc giao kết hợp đồng bảo hiểm; thu phí bảo hiểm; thu thập hồ sơ để phục vụ việc giải quyết bồi thường, trả tiền bảo hiểm."},{"key":"C","text":"A, B đúng"}],"answer":"A","explanation":"Khái niệm cần nhớ trong câu này là: **Một hoặc một số hoạt động theo ủy quyền của doanh nghiệp bảo hiểm, bao gồm: tư vấn sản phẩm bảo hiểm; giới thiệu sản phẩm bảo hiểm; chào bán sản phẩm bảo hiểm; thu xếp việc giao kết hợp đồng bảo hiểm; thu phí bảo hiểm; thu thập hồ sơ để phục vụ việc giải quyết bồi thường, trả tiền bảo hiểm.**. Đáp án đúng là **A**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Một hoặc một số hoạt động theo ủy quyền của doanh nghiệp bảo hiểm, bao gồm: tư vấn sản phẩm…**."},{"id":173,"category":"Kiến thức chung","question":"Tiêu chí nào sau đây không phải là tiêu chí đánh giá rủi ro:","options":[{"key":"A","text":"Mức độ rủi ro."},{"key":"B","text":"Nguy cơ rủi ro."},{"key":"C","text":"Tần suất xuất hiện rủi ro."}],"answer":"C","explanation":"Đây là câu hỏi tìm **phương án ngoại lệ/sai**. Theo đáp án của đề cương, phương án **C** là nội dung không phù hợp: **Tần suất xuất hiện rủi ro.**. Khi làm bài, cần chú ý từ khóa phủ định như **“sai”, “không”, “ngoại trừ”**.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":174,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Trong bảo hiểm tài sản, trường hợp áp dụng mức miễn thường không khấu trừ, nếu giá trị tổn thất lớn hơn mức miễn thường thì:","options":[{"key":"A","text":"Số tiền bồi thường bằng giá trị tổn thất."},{"key":"B","text":"Số tiền bồi thường bằng giá trị tổn thất trừ đi mức miễn thường."}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án **A** là **Số tiền bồi thường bằng giá trị tổn thất.**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Số tiền bồi thường bằng giá trị tổn thất.**."},{"id":175,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phát biểu nào sau đây đúng:","options":[{"key":"A","text":"Đại lý bảo hiểm có thể sửa đổi, bổ sung quy tắc, điều khoản bảo hiểm cho phù hợp với tình hình thực tế của khách hàng."},{"key":"B","text":"Đại lý bảo hiểm có quyền lựa chọn và giao kết hợp đồng đại lý bảo hiểm đối với doanh nghiệp bảo hiểm, chi nhánh doanh nghiệp bảo hiểm phi nhân thọ nước ngoài, tổ chức tương hỗ cung cấp bảo hiểm vi mô theo quy định của pháp luật."},{"key":"C","text":"Hoa hồng đại lý bảo hiểm được chi trả cho bên mua bảo hiểm và đại lý bảo hiểm"},{"key":"D","text":"Hoa hồng đại lý bảo hiểm được chi trả cho bên mua bảo hiểm và doanh nghiệp môi giới bảo hiểm"}],"answer":"B","explanation":"Theo đáp án của đề cương, phương án **B** là nội dung đúng: **Đại lý bảo hiểm có quyền lựa chọn và giao kết hợp đồng đại lý bảo hiểm đối với doanh nghiệp bảo hiểm, chi nhánh doanh nghiệp bảo hiểm phi nhân thọ nước ngoài, tổ chức tương hỗ cung cấp bảo hiểm vi mô theo quy định của pháp luật.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Đại lý bảo hiểm có quyền lựa chọn và giao kết hợp đồng đại lý bảo hiểm đối với doanh nghiệp…**."},{"id":176,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, hoạt động đại lý bảo hiểm bao gồm hoạt động nào sau đây:","options":[{"key":"A","text":"Tư vấn sản phẩm bảo hiểm; giới thiệu sản phẩm bảo hiểm; chào bán sản phẩm bảo hiểm; thu xếp việc giao kết hợp đồng bảo hiểm; thu phí bảo hiểm; thu thập hồ sơ để phục vụ việc giải quyết bồi thường, trả tiền bảo hiểm."},{"key":"B","text":"Giới thiệu, chào bán bảo hiểm, giám định bảo hiểm, trả tiền bảo hiểm."},{"key":"C","text":"Giới thiệu, chào bán bảo hiểm, giải quyết bồi thường bảo hiểm."},{"key":"D","text":"A, B, C đúng."}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Tư vấn sản phẩm bảo hiểm; giới thiệu sản phẩm bảo hiểm; chào bán sản phẩm bảo hiểm; thu xếp việc giao kết hợp đồng bảo hiểm; thu phí bảo hiểm; thu thập hồ sơ để phục vụ việc giải quyết bồi thường, trả tiền bảo hiểm.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Tư vấn sản phẩm bảo hiểm; giới thiệu sản phẩm bảo hiểm; chào bán sản phẩm bảo hiểm; thu xếp…**."},{"id":177,"category":"Bảo hiểm con người","question":"Khi tham gia bảo hiểm sức khỏe với quyền lợi bảo hiểm tai nạn, người được bảo hiểm không may bị tai nạn khi tham gia vào các cuộc thi đấu có tính chất chuyên nghiệp như đua ngựa, đua xe (Hợp đồng bảo hiểm không có điều khoản sửa đổi bổ sung về bảo hiểm rủi ro tai nạn khi tham gia vào các cuộc thi đấu có tính chất chuyên nghiệp). Phương án giải quyết quyền lợi bảo hiểm nào sau đây đúng:","options":[{"key":"A","text":"Số tiền bảo hiểm theo tỷ lệ thương tật do tai nạn."},{"key":"B","text":"Chi phí y tế điều trị tai nạn."},{"key":"C","text":"Không thuộc phạm vi trách nhiệm bảo hiểm."},{"key":"D","text":"A, B đúng."}],"answer":"C","explanation":"Theo đáp án của đề cương, đáp án đúng là **C**: **Không thuộc phạm vi trách nhiệm bảo hiểm.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Không thuộc phạm vi trách nhiệm bảo hiểm.**."},{"id":178,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, trường hợp bên mua bảo hiểm có lý do chính đáng trong việc chậm thông báo cho doanh nghiệp bảo hiểm về việc xảy ra sự kiện bảo hiểm, có áp dụng điều khoản loại trừ trách nhiệm bảo hiểm không:","options":[{"key":"A","text":"Có."},{"key":"B","text":"Không"}],"answer":"B","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **B**: **Không**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Không**."},{"id":179,"category":"Luật Kinh doanh bảo hiểm","question":"Theo pháp luật về hoạt động kinh doanh bảo hiểm, đối tượng nào có nghĩa vụ thanh toán hoa hồng theo thỏa thuận trong hợp đồng đại lý bảo hiểm:","options":[{"key":"A","text":"Doanh nghiệp bảo hiểm"},{"key":"B","text":"Bên mua bảo hiểm"},{"key":"C","text":"A, B đúng"}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Doanh nghiệp bảo hiểm**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Doanh nghiệp bảo hiểm**."},{"id":180,"category":"Bảo hiểm con người","question":"Khi tham gia hợp đồng bảo hiểm sức khỏe với quyền lợi bảo hiểm tai nạn, người được bảo hiểm không được nhận quyền lợi bảo hiểm nào sau đây?","options":[{"key":"A","text":"Trợ cấp lương, thu nhập do ốm đau, bệnh tật."},{"key":"B","text":"Chi phí y tế điều trị tai nạn."},{"key":"C","text":"Thương tật tạm thời do tai nạn."},{"key":"D","text":"B, C đúng."}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Trợ cấp lương, thu nhập do ốm đau, bệnh tật.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Trợ cấp lương, thu nhập do ốm đau, bệnh tật.**."},{"id":181,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phát biểu: \"Hợp đồng bảo hiểm vô hiệu do bên mua bảo hiểm không có quyền lợi có thể được bảo hiểm tại thời điểm giao kết hợp đồng\" là:","options":[{"key":"A","text":"Đúng."},{"key":"B","text":"Sai."}],"answer":"A","explanation":"Đây là câu hỏi tìm **phương án ngoại lệ/sai**. Theo đáp án của đề cương, phương án **A** là nội dung không phù hợp: **Đúng.**. Khi làm bài, cần chú ý từ khóa phủ định như **“sai”, “không”, “ngoại trừ”**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Đúng.**."},{"id":183,"category":"Luật Kinh doanh bảo hiểm","question":"Chọn phương án đúng nhất: Theo Luật Kinh doanh bảo hiểm,  đối với điều khoản loại trừ trách nhiệm bảo hiểm, doanh nghiệp bảo hiểm phải:","options":[{"key":"A","text":"Quy định rõ trong hợp đồng bảo hiểm."},{"key":"B","text":"Giải thích rõ ràng, đầy đủ cho bên mua bảo hiểm về điều khoản loại trừ bảo hiểm khi giao kết hợp đồng bảo hiểm."},{"key":"C","text":"Có bằng chứng xác nhận việc bên mua bảo hiểm đã được doanh nghiệp bảo hiểm giải thích đầy đủ và hiểu rõ về điều khoản loại trừ bảo hiểm khi giao kết hợp đồng bảo hiểm."},{"key":"D","text":"A, B, C đúng"}],"answer":"D","explanation":"Theo đáp án của đề cương, phương án **D** là nội dung đúng: **A, B, C đúng**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng**."},{"id":184,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, các tổ chức kinh doanh bảo hiểm không bao gồm đối tượng nào sau đây:","options":[{"key":"A","text":"Hợp tác xã bảo hiểm"},{"key":"B","text":"Tổ chức cung cấp bảo hiểm vi mô"},{"key":"C","text":"Doanh nghiệp bảo hiểm"},{"key":"D","text":"Chi nhánh doanh nghiệp bảo hiểm phi nhân thọ nước ngoài"}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Hợp tác xã bảo hiểm**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Hợp tác xã bảo hiểm**."},{"id":185,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, tổ chức, cá nhân giao kết hợp đồng bảo hiểm với doanh nghiệp bảo hiểm và đóng phí bảo hiểm được gọi là:","options":[{"key":"A","text":"Người được bảo hiểm."},{"key":"B","text":"Bên mua bảo hiểm."},{"key":"C","text":"Đại lý bảo hiểm."},{"key":"D","text":"Người thụ hưởng."}],"answer":"B","explanation":"Khái niệm cần nhớ trong câu này là: **Bên mua bảo hiểm.**. Đáp án đúng là **B**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Bên mua bảo hiểm.**."},{"id":186,"category":"Bảo hiểm xe cơ giới","question":"Theo đơn Bảo hiểm trách nhiệm dân sự của chủ xe cơ giới đối với hàng hóa trên xe: Trong quá trình vận chuyển, do xếp hàng không đúng quy cách nên hàng va đập vào nhau và bị tổn thất. Trường hợp này có thuộc phạm vi bảo hiểm không:","options":[{"key":"A","text":"Có."},{"key":"B","text":"Không."}],"answer":"B","explanation":"Đây là câu hỏi tìm **phương án ngoại lệ/sai**. Theo đáp án của đề cương, phương án **B** là nội dung không phù hợp: **Không.**. Khi làm bài, cần chú ý từ khóa phủ định như **“sai”, “không”, “ngoại trừ”**.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":187,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, đại lý bảo hiểm có quyền:","options":[{"key":"A","text":"Ngăn cản bên mua bảo hiểm cung cấp các thông tin liên quan đến hợp đồng bảo hiểm"},{"key":"B","text":"Tư vấn cho bên mua bảo hiểm, người được bảo hiểm không kê khai các thông tin liên quan đến hợp đồng bảo hiểm"},{"key":"C","text":"Tiết lộ thông tin liên quan đến bên mua bảo hiểm cho bên thứ ba"},{"key":"D","text":"Hưởng hoa hồng đại lý bảo hiểm"}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **Hưởng hoa hồng đại lý bảo hiểm**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Hưởng hoa hồng đại lý bảo hiểm**."},{"id":188,"category":"Bảo hiểm xe cơ giới","question":"Bồi thường bảo hiểm trách nhiệm dân sự của chủ xe đối với hàng hóa trên xe/vụ tổn thất được hiểu là:","options":[{"key":"A","text":"Trong mọi trường hợp, tổng số tiền bồi thường không được vượt quá mức trách nhiệm bảo hiểm/vụ tổn thất"},{"key":"B","text":"Không giới hạn số lượng các vụ tổn thất trong suốt thời hạn bảo hiểm."},{"key":"C","text":"Trường hợp trong thời hạn bảo hiểm xảy ra nhiều vụ tổn thất, tổng số tiền bồi thường hàng hóa bị tổn thất trong suốt thời hạn bảo hiểm không vượt quá tổng mức trách nhiệm bảo hiểm."},{"key":"D","text":"A, B đúng."}],"answer":"D","explanation":"Khái niệm cần nhớ trong câu này là: **A, B đúng.**. Đáp án đúng là **D**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B đúng.**."},{"id":189,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Chi phí/các khoản tiền nào sau đây không được doanh nghiệp bảo hiểm chi trả theo hợp đồng bảo hiểm trách nhiệm nghề nghiệp cho kỹ sư, tư vấn, thiết kế:","options":[{"key":"A","text":"Chi phí dọn dẹp hiện trường của tổn thất phát sinh do lỗi thiết kế của người được bảo hiểm."},{"key":"B","text":"Án phí hoặc chi phí trọng tài để giải quyết tranh chấp về trách nhiệm đối với người thứ ba của người được bảo hiểm."},{"key":"C","text":"Tiền phạt vi phạm hành chính của tòa án đối với người được bảo hiểm."},{"key":"D","text":"B, C đúng."}],"answer":"C","explanation":"Theo đáp án của đề cương, đáp án đúng là **C**: **Tiền phạt vi phạm hành chính của tòa án đối với người được bảo hiểm.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Tiền phạt vi phạm hành chính của tòa án đối với người được bảo hiểm.**."},{"id":190,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Thông thường, giới hạn mức trách nhiệm bảo hiểm đối với bên thứ ba về người và tài sản theo Đơn bảo hiểm mọi rủi ro xây dựng/lắp đặt (CAR/EAR) của nhà tái bảo hiểm Munich Re được các nhà nhận tái bảo hiểm trên thế giới chấp nhận là:","options":[{"key":"A","text":"Không có giới hạn"},{"key":"B","text":"Không vượt quá 50% số tiền bảo hiểm của Phần I- Tổn thất vật chất"},{"key":"C","text":"Không vượt quá 75% số tiền bảo hiểm của Phần I- Tổn thất vật chất"},{"key":"D","text":"Không vượt quá 90% số tiền bảo hiểm của Phần I- Tổn thất vật chất"}],"answer":"B","explanation":"Khái niệm cần nhớ trong câu này là: **Không vượt quá 50% số tiền bảo hiểm của Phần I- Tổn thất vật chất**. Đáp án đúng là **B**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Chốt mốc **50** và gắn với đúng điều kiện của câu."},{"id":191,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"\"Trong bảo hiểm tài sản, đơn vị rủi ro (ngôi nhà, bộ phận nhà hoặc kho) được coi là cách biệt về mặt cấu trúc nếu ngôi nhà, bộ phận nhà hoặc kho được ngăn cách bằng tường ngăn cháy\". Phát biểu trên là:","options":[{"key":"A","text":"Đúng."},{"key":"B","text":"Sai."}],"answer":"A","explanation":"Khái niệm cần nhớ trong câu này là: **Đúng.**. Đáp án đúng là **A**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Đúng.**."},{"id":192,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, doanh nghiệp bảo hiểm có nghĩa vụ:","options":[{"key":"A","text":"Bồi thường, trả tiền bảo hiểm khi xảy ra sự kiện bảo hiểm."},{"key":"B","text":"Giải thích bằng văn bản lý do từ chối bồi thường, trả tiền bảo hiểm."},{"key":"C","text":"A, B đúng."}],"answer":"C","explanation":"Theo đáp án của đề cương, đáp án đúng là **C**: **A, B đúng.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B đúng.**."},{"id":193,"category":"Luật Kinh doanh bảo hiểm","question":"Khi giao kết hợp đồng bảo hiểm, doanh nghiệp bảo hiểm có quyền và nghĩa vụ:","options":[{"key":"A","text":"Có quyền yêu cầu bên mua bảo hiểm cung cấp đầy đủ, trung thực mọi thông tin có liên quan đến việc giao kết hợp đồng bảo hiểm."},{"key":"B","text":"Có quyền thu phí bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm."},{"key":"C","text":"Có nghĩa vụ giải thích rõ ràng, đầy đủ cho bên mua bảo hiểm về quyền lợi bảo hiểm, điều khoản loại trừ trách nhiệm bảo hiểm, quyền và nghĩa vụ của bên mua bảo hiểm khi giao kết hợp đồng bảo hiểm."},{"key":"D","text":"A, B, C đúng."}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **A, B, C đúng.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng.**."},{"id":194,"category":"Kiến thức chung","question":"Chọn phương án đúng nhất về “Nguyên tắc nguyên nhân trực tiếp”:","options":[{"key":"A","text":"Tổn thất thuộc trách nhiệm bảo hiểm phải phát sinh trực tiếp bởi một rủi ro được bảo hiểm."},{"key":"B","text":"Nguyên nhân trực tiếp không nhất thiết phải là nguyên nhân ban đầu hay nguyên nhân gần nhất gây ra tổn thất."},{"key":"C","text":"Nguyên nhân trực tiếp là nguyên nhân chi phối và có tác động gây ra tổn thất."},{"key":"D","text":"A, B, C đúng."}],"answer":"D","explanation":"Theo đáp án của đề cương, phương án **D** là nội dung đúng: **A, B, C đúng.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng.**."},{"id":195,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, bảo hiểm sức khỏe là loại hình bảo hiểm cho trường hợp:","options":[{"key":"A","text":"Người được bảo hiểm sống đến một thời hạn nhất định."},{"key":"B","text":"Người được bảo hiểm chết trong một thời hạn nhất định."},{"key":"C","text":"Người được bảo hiểm bị thương tật, tai nạn, ốm đau, bệnh tật hoặc chết vào bất kỳ thời điểm nào trong suốt cuộc đời của người đó."},{"key":"D","text":"Người được bảo hiểm bị thương tật, tai nạn, ốm đau, bệnh tật hoặc chăm sóc sức khỏe."}],"answer":"D","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **D**: **Người được bảo hiểm bị thương tật, tai nạn, ốm đau, bệnh tật hoặc chăm sóc sức khỏe.**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Người được bảo hiểm bị thương tật, tai nạn, ốm đau, bệnh tật hoặc chăm sóc sức khỏe.**."},{"id":196,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, đối tượng nào sau đây chỉ định người thụ hưởng để nhận tiền bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm:","options":[{"key":"A","text":"Bên mua bảo hiểm"},{"key":"B","text":"Người được bảo hiểm"},{"key":"C","text":"A, B đúng"},{"key":"D","text":"A, B sai"}],"answer":"C","explanation":"Theo đáp án của đề cương, đáp án đúng là **C**: **A, B đúng**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B đúng**."},{"id":197,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, đại lý bảo hiểm có các nghĩa vụ nào sau đây:","options":[{"key":"A","text":"Tư vấn, giới thiệu, chào bán sản phẩm bảo hiểm; cung cấp các thông tin về sản phẩm bảo hiểm, doanh nghiệp bảo hiểm đầy đủ, chính xác cho bên mua bảo hiểm."},{"key":"B","text":"Thực hiện nghĩa vụ trong hợp đồng đại lý bảo hiểm."},{"key":"C","text":"Chịu sự kiểm tra, giám sát của doanh nghiệp bảo hiểm"},{"key":"D","text":"A, B, C đúng."}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **A, B, C đúng.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng.**."},{"id":198,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, đại lý bảo hiểm không được tranh giành khách hàng dưới các hình thức ngăn cản, lôi kéo, mua chuộc, đe dọa nhân viên hoặc khách hàng của:","options":[{"key":"A","text":"Doanh nghiệp bảo hiểm, chi nhánh doanh nghiệp bảo hiểm phi nhân thọ nước ngoài khác."},{"key":"B","text":"Tổ chức tương hỗ cung cấp bảo hiểm vi mô khác."},{"key":"C","text":"Đại lý bảo hiểm, doanh nghiệp môi giới bảo hiểm khác"},{"key":"D","text":"A, B, C đúng."}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **A, B, C đúng.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng.**."},{"id":199,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, trường hợp các bên giao kết hợp đồng bảo hiểm trùng, khi xảy ra sự kiện bảo hiểm thì:","options":[{"key":"A","text":"Số tiền bồi thường của mỗi hợp đồng bảo hiểm được tính tương ứng theo tỷ lệ giữa số tiền bảo hiểm đã thoả thuận trên tổng số tiền bảo hiểm của tất cả các hợp đồng mà bên mua bảo hiểm đã giao kết. Tổng số tiền bồi thường của các hợp đồng bảo hiểm không vượt quá giá trị thiệt hại thực tế của tài sản."},{"key":"B","text":"Số tiền bồi thường của mỗi hợp đồng bảo hiểm được tính tương ứng theo tỷ lệ giữa số tiền bảo hiểm đã thoả thuận trên tổng số tiền bảo hiểm của tất cả các hợp đồng mà bên mua bảo hiểm đã giao kết. Tổng số tiền bồi thường của các hợp đồng bảo hiểm có thể lớn hơn giá trị thiệt hại thực tế của tài sản."},{"key":"C","text":"Số tiền bồi thường của mỗi hợp đồng bảo hiểm được doanh nghiệp bảo hiểm chi trả theo tỷ lệ bằng nhau trên tổng số tiền bảo hiểm của tất cả các hợp đồng mà bên mua bảo hiểm đã giao kết. Tổng số tiền bồi thường của các hợp đồng bảo hiểm không vượt quá giá trị thiệt hại thực tế của tài sản."},{"key":"D","text":"Số tiền bồi thường của mỗi hợp đồng bảo hiểm được chi trả theo thiệt hại thực tế đã thoả thuận trên tổng số tiền bảo hiểm của tất cả các hợp đồng mà bên mua bảo hiểm đã giao kết."}],"answer":"A","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **A**: **Số tiền bồi thường của mỗi hợp đồng bảo hiểm được tính tương ứng theo tỷ lệ giữa số tiền bảo hiểm đã thoả thuận trên tổng số tiền bảo hiểm của tất cả các hợp đồng mà bên mua bảo hiểm đã giao kết. Tổng số tiền bồi thường của các hợp đồng bảo hiểm không vượt quá giá trị thiệt hại thực tế của tài sản.**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Số tiền bồi thường của mỗi hợp đồng bảo hiểm được tính tương ứng theo tỷ lệ giữa số tiền…**."},{"id":200,"category":"Kiến thức chung","question":"Rủi ro có thể được bảo hiểm và được doanh nghiệp bảo hiểm chấp nhận bảo hiểm là rủi ro được bảo hiểm:","options":[{"key":"A","text":"Đúng."},{"key":"B","text":"Sai."}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Đúng.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Đúng.**."},{"id":201,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, doanh nghiệp bảo hiểm có nghĩa vụ:","options":[{"key":"A","text":"Yêu cầu đại lý bảo hiểm thanh toán phí bảo hiểm thu được theo thỏa thuận trong hợp đồng bảo hiểm"},{"key":"B","text":"Yêu cầu đại lý bảo hiểm phải có tài sản thế chấp"},{"key":"C","text":"Chịu trách nhiệm thực hiện các nghĩa vụ theo thỏa thuận trong hợp đồng bảo hiểm do đại lý bảo hiểm thu xếp giao kết"},{"key":"D","text":"A, C đúng"}],"answer":"C","explanation":"Theo đáp án của đề cương, đáp án đúng là **C**: **Chịu trách nhiệm thực hiện các nghĩa vụ theo thỏa thuận trong hợp đồng bảo hiểm do đại lý bảo hiểm thu xếp giao kết**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Chịu trách nhiệm thực hiện các nghĩa vụ theo thỏa thuận trong hợp đồng bảo hiểm do đại lý…**."},{"id":202,"category":"Luật Kinh doanh bảo hiểm","question":"Phát biểu sau là đúng hay sai:\"Theo Luật Kinh doanh bảo hiểm, trường hợp hợp đồng bảo hiểm có điều khoản không rõ ràng dẫn đến có cách hiểu khác nhau thì điều khoản đó được giải thích theo hướng có lợi cho doanh nghiệp bảo hiểm\".","options":[{"key":"A","text":"Đúng"},{"key":"B","text":"Sai"}],"answer":"B","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **B**: **Sai**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":203,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, trong hợp đồng bảo hiểm sức khỏe, trường hợp người được bảo hiểm bị thương tật hoặc đau ốm do hành vi trực tiếp hoặc gián tiếp của người thứ ba gây ra thì:","options":[{"key":"A","text":"Doanh nghiệp bảo hiểm vẫn có nghĩa vụ bồi thường, trả tiền bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm và được quyền yêu cầu người thứ ba bồi hoàn khoản tiền mà doanh nghiệp bảo hiểm đã trả cho người thụ hưởng"},{"key":"B","text":"Doanh nghiệp bảo hiểm có quyền từ chối bồi thường và yêu cầu người thứ ba bồi thường trực tiếp cho người được bảo hiểm."},{"key":"C","text":"Doanh nghiệp bảo hiểm vẫn có nghĩa vụ bồi thường, trả tiền bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm mà không có quyền yêu cầu người thứ ba bồi hoàn khoản tiền mà doanh nghiệp bảo hiểm đã trả cho người thụ hưởng."}],"answer":"C","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **C**: **Doanh nghiệp bảo hiểm vẫn có nghĩa vụ bồi thường, trả tiền bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm mà không có quyền yêu cầu người thứ ba bồi hoàn khoản tiền mà doanh nghiệp bảo hiểm đã trả cho người thụ hưởng.**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Doanh nghiệp bảo hiểm vẫn có nghĩa vụ bồi thường, trả tiền bảo hiểm theo thỏa thuận trong…**."},{"id":204,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, đối tượng bảo hiểm của hợp đồng bảo hiểm trách nhiệm là:","options":[{"key":"A","text":"Trách nhiệm dân sự của người được bảo hiểm đối với doanh nghiệp bảo hiểm theo quy định của pháp luật."},{"key":"B","text":"Trách nhiệm dân sự của người được bảo hiểm đối với bên mua bảo hiểm theo quy định của pháp luật."},{"key":"C","text":"Trách nhiệm dân sự của người được bảo hiểm đối với người thứ ba theo quy định của pháp luật."},{"key":"D","text":"A, B, C đúng"}],"answer":"C","explanation":"Khái niệm cần nhớ trong câu này là: **Trách nhiệm dân sự của người được bảo hiểm đối với người thứ ba theo quy định của pháp luật.**. Đáp án đúng là **C**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Trách nhiệm dân sự của người được bảo hiểm đối với người thứ ba theo quy định của pháp luật.**."},{"id":205,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, trường hợp đơn phương chấm dứt thực hiện hợp đồng bảo hiểm do bên mua bảo hiểm không đóng phí bảo hiểm hoặc không đóng đủ phí bảo hiểm theo thời hạn thỏa thuận hoặc sau thời gian gia hạn đóng phí, bên mua bảo hiểm vẫn phải đóng đủ phí bảo hiểm đến thời điểm đơn phương chấm dứt thực hiện hợp đồng bảo hiểm. Quy định này được áp dụng đối với:","options":[{"key":"A","text":"Hợp đồng bảo hiểm trách nhiệm."},{"key":"B","text":"Hợp đồng bảo hiểm tài sản."},{"key":"C","text":"Hợp đồng bảo hiểm nhân thọ (trừ hợp đồng bảo hiểm nhóm)."},{"key":"D","text":"A,B đúng"}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án **D** là **A,B đúng**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A,B đúng**."},{"id":206,"category":"Luật Kinh doanh bảo hiểm","question":"Bên mua bảo hiểm có thể là:","options":[{"key":"A","text":"Người được bảo hiểm."},{"key":"B","text":"Người thụ hưởng."},{"key":"C","text":"A, B đúng."},{"key":"D","text":"A, B sai."}],"answer":"C","explanation":"Khái niệm cần nhớ trong câu này là: **A, B đúng.**. Đáp án đúng là **C**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B đúng.**."},{"id":208,"category":"Luật Kinh doanh bảo hiểm","question":"Khi giao kết hợp đồng bảo hiểm, bên mua bảo hiểm có quyền và nghĩa vụ:","options":[{"key":"A","text":"Có quyền yêu cầu doanh nghiệp bảo hiểm giải thích các điều kiện, điều khoản bảo hiểm."},{"key":"B","text":"Có nghĩa vụ kê khai đầy đủ, trung thực mọi thông tin có liên quan đến hợp đồng bảo hiểm theo yêu cầu của doanh nghiệp bảo hiểm."},{"key":"C","text":"Có nghĩa vụ đóng phí bảo hiểm đầy đủ, đúng hạn theo thỏa thuận trong hợp đồng bảo hiểm."},{"key":"D","text":"A, B, C đúng"}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **A, B, C đúng**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng**."},{"id":209,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phát biểu nào sau đây sai:","options":[{"key":"A","text":"Đại lý bảo hiểm có nghĩa vụ tư vấn, giới thiệu, chào bán sản phẩm bảo hiểm; cung cấp các thông tin về sản phẩm bảo hiểm, doanh nghiệp bảo hiểm đầy đủ, chính xác cho bên mua bảo hiểm"},{"key":"B","text":"Đại lý bảo hiểm có quyền khuyến mại khách hàng dưới hình thức như giảm phí bảo hiểm, hoàn phí bảo hiểm"},{"key":"C","text":"Đại lý bảo hiểm có nghĩa vụ tham dự các khóa đào tạo, cập nhật kiến thức do doanh nghiệp bảo hiểm tổ chức"},{"key":"D","text":"Đại lý bảo hiểm được doanh nghiệp bảo hiểm ủy quyền thu thập hồ sơ để phục vụ việc giải quyết bồi thường, trả tiền bảo hiểm"}],"answer":"B","explanation":"Đây là câu hỏi tìm **phương án ngoại lệ/sai**. Theo đáp án của đề cương, phương án **B** là nội dung không phù hợp: **Đại lý bảo hiểm có quyền khuyến mại khách hàng dưới hình thức như giảm phí bảo hiểm, hoàn phí bảo hiểm**. Khi làm bài, cần chú ý từ khóa phủ định như **“sai”, “không”, “ngoại trừ”**.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":210,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phát biểu nào sau đây đúng:","options":[{"key":"A","text":"Hoa hồng đại lý bảo hiểm được thỏa thuận tại hợp đồng đại lý bảo hiểm. Mức hoa hồng đại lý bảo hiểm tối đa theo quy định của Bộ trưởng Bộ Tài chính"},{"key":"B","text":"Hoa hồng đại lý bảo hiểm do doanh nghiệp bảo hiểm chi trả có thể thấp hơn mức tối đa do Bộ trưởng Bộ Tài chính quy định."},{"key":"C","text":"Ngoài mức hoa hồng đại lý bảo hiểm theo quy định của pháp luật, doanh nghiệp bảo hiểm có thể trả thêm hoa hồng đại lý bảo hiểm theo thỏa thuận giữa doanh nghiệp bảo hiểm và đại lý bảo hiểm."},{"key":"D","text":"A, B đúng."}],"answer":"D","explanation":"Theo đáp án của đề cương, phương án **D** là nội dung đúng: **A, B đúng.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B đúng.**."},{"id":211,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Chọn phương án đúng nhất: Thuật ngữ “Sản Phẩm” trong bảo hiểm trách nhiệm sản phẩm được hiểu là:","options":[{"key":"A","text":"Hàng hóa (bao gồm thùng/hộp chứa hàng, bao bì, hướng dẫn sử dụng) đã được bán, cung cấp hoặc sửa chữa, thay thế, bảo hành bởi người được bảo hiểm."},{"key":"B","text":"Hàng hóa đã rời khỏi sự kiểm soát của người được bảo hiểm."},{"key":"C","text":"Hàng hóa trong phạm vi nhà xưởng của người được bảo hiểm."},{"key":"D","text":"A, B đúng."},{"key":"E","text":"A, C đúng."}],"answer":"D","explanation":"Theo đáp án của đề cương, phương án **D** là nội dung đúng: **A, B đúng.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B đúng.**."},{"id":212,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phát biểu nào sau đây SAI về bảo hiểm tài sản trên giá trị:","options":[{"key":"A","text":"Hợp đồng bảo hiểm tài sản trên giá trị là hợp đồng trong đó số tiền bảo hiểm cao hơn giá thị trường của tài sản được bảo hiểm tại thời điểm giao kết hợp đồng."},{"key":"B","text":"Trong trường hợp giao kết hợp đồng bảo hiểm tài sản trên giá trị do lỗi cố ý của bên mua bảo hiểm, nếu chưa xảy ra sự kiện bảo hiểm, doanh nghiệp bảo hiểm phải hoàn lại cho bên mua bảo hiểm số phí bảo hiểm đã đóng tương ứng với số tiền bảo hiểm vượt quá giá thị trường của tài sản được bảo hiểm tại thời điểm giao kết hợp đồng sau khi trừ các chi phí hợp lý (nếu có) theo thỏa thuận trong hợp đồng bảo hiểm"},{"key":"C","text":"Doanh nghiệp bảo hiểm, chi nhánh doanh nghiệp bảo hiểm phi nhân thọ nước ngoài và bên mua bảo hiểm không được cố ý giao kết hợp đồng bảo hiểm tài sản trên giá trị."},{"key":"D","text":"A, C đúng"}],"answer":"B","explanation":"Đây là câu hỏi tìm **phương án ngoại lệ/sai**. Theo đáp án của đề cương, phương án **B** là nội dung không phù hợp: **Trong trường hợp giao kết hợp đồng bảo hiểm tài sản trên giá trị do lỗi cố ý của bên mua bảo hiểm, nếu chưa xảy ra sự kiện bảo hiểm, doanh nghiệp bảo hiểm phải hoàn lại cho bên mua bảo hiểm số phí bảo hiểm đã đóng tương ứng với số tiền bảo hiểm vượt quá giá thị trường của tài sản được bảo hiểm tại thời điểm giao kết hợp đồng sau khi trừ các chi phí hợp lý (nếu có) theo thỏa thuận trong hợp đồng bảo hiểm**. Khi làm bài, cần chú ý từ khóa phủ định như **“sai”, “không”, “ngoại trừ”**.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":213,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Theo Quy tắc bảo hiểm ‘Mọi rủi ro tài sản” của Hiệp hội bảo hiểm Vương quốc Anh (ABI), chi phí khắc phục thiệt hại gây ra do hệ thống cung cấp nước, điện, khí đốt hoặc nhiên liệu bị gián đoạn hoặc hệ thống thoát thải nối với khu vực được bảo hiểm bị hư hỏng có thuộc trách nhiệm bảo hiểm không:","options":[{"key":"A","text":"Có."},{"key":"B","text":"Không."},{"key":"C","text":"Không, trừ khi thiệt hại xảy ra tiếp theo do một nguyên nhân khác không bị loại trừ trong Quy tắc bảo hiểm này gây ra."}],"answer":"C","explanation":"Theo đáp án của đề cương, đáp án đúng là **C**: **Không, trừ khi thiệt hại xảy ra tiếp theo do một nguyên nhân khác không bị loại trừ trong Quy tắc bảo hiểm này gây ra.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Không, trừ khi thiệt hại xảy ra tiếp theo do một nguyên nhân khác không bị loại trừ trong…**."},{"id":214,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, bên nhận phí bảo hiểm để bồi thường, trả tiền bảo hiểm khi xảy ra sự kiện bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm là:","options":[{"key":"A","text":"Doanh nghiệp môi giới bảo hiểm"},{"key":"B","text":"Đại lý bảo hiểm."},{"key":"C","text":"Doanh nghiệp bảo hiểm."},{"key":"D","text":"A, B, C đúng"}],"answer":"C","explanation":"Khái niệm cần nhớ trong câu này là: **Doanh nghiệp bảo hiểm.**. Đáp án đúng là **C**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Doanh nghiệp bảo hiểm.**."},{"id":215,"category":"Luật Kinh doanh bảo hiểm","question":"Chọn phương án đúng về trường hợp đơn phương chấm dứt hợp đồng bảo hiểm của doanh nghiệp bảo hiểm:","options":[{"key":"A","text":"Bên mua bảo hiểm không có quyền lợi có thể được bảo hiểm."},{"key":"B","text":"Bên mua bảo hiểm không còn quyền lợi có thể được bảo hiểm."},{"key":"C","text":"Bên mua bảo hiểm không đóng phí bảo hiểm hoặc không đóng đủ phí bảo hiểm theo thời hạn thỏa thuận hoặc sau thời gian gia hạn đóng phí."},{"key":"D","text":"A, B, C đúng"}],"answer":"C","explanation":"Theo đáp án của đề cương, phương án **C** là nội dung đúng: **Bên mua bảo hiểm không đóng phí bảo hiểm hoặc không đóng đủ phí bảo hiểm theo thời hạn thỏa thuận hoặc sau thời gian gia hạn đóng phí.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Bên mua bảo hiểm không đóng phí bảo hiểm hoặc không đóng đủ phí bảo hiểm theo thời hạn thỏa…**."},{"id":216,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phát biểu nào dưới đây đúng nhất:","options":[{"key":"A","text":"Người được bảo hiểm là tổ chức, cá nhân giao kết hợp đồng bảo hiểm với doanh nghiệp bảo hiểm và đóng phí bảo hiểm"},{"key":"B","text":"Người thụ hưởng là tổ chức, cá nhân được bên mua bảo hiểm hoặc người được bảo hiểm chỉ định để nhận tiền bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm"},{"key":"C","text":"A, B đúng"}],"answer":"B","explanation":"Theo đáp án của đề cương, phương án **B** là nội dung đúng: **Người thụ hưởng là tổ chức, cá nhân được bên mua bảo hiểm hoặc người được bảo hiểm chỉ định để nhận tiền bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Người thụ hưởng là tổ chức, cá nhân được bên mua bảo hiểm hoặc người được bảo hiểm chỉ định…**."},{"id":217,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, trừ trường hợp có thỏa thuận trong hợp đồng bảo hiểm, thời hạn bồi thường, trả tiền bảo hiểm là:","options":[{"key":"A","text":"21 ngày kể từ ngày nhận được đầy đủ hồ sơ hợp lệ về yêu cầu bồi thường."},{"key":"B","text":"15 ngày kể từ ngày nhận được đầy đủ hồ sơ hợp lệ về yêu cầu bồi thường."},{"key":"C","text":"30 ngày kể từ ngày nhận được đầy đủ hồ sơ hợp lệ về yêu cầu bồi thường."},{"key":"D","text":"1 năm kể từ ngày nhận được đầy đủ hồ sơ hợp lệ về yêu cầu bồi thường."}],"answer":"B","explanation":"Khái niệm cần nhớ trong câu này là: **15 ngày kể từ ngày nhận được đầy đủ hồ sơ hợp lệ về yêu cầu bồi thường.**. Đáp án đúng là **B**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Chốt mốc **15 ngày** và gắn với đúng điều kiện của câu."},{"id":218,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, đại lý bảo hiểm có thể lựa chọn và ký kết hợp đồng đại lý bảo hiểm với:","options":[{"key":"A","text":"Tổ chức tương hỗ cung cấp bảo hiểm vi mô theo quy định của pháp luật"},{"key":"B","text":"Văn phòng đại diện doanh nghiệp bảo hiểm nước ngoài tại Việt Nam"},{"key":"C","text":"Doanh nghiệp môi giới bảo hiểm"},{"key":"D","text":"Chi nhánh doanh nghiệp bảo hiểm nhân thọ nước ngoài"}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Tổ chức tương hỗ cung cấp bảo hiểm vi mô theo quy định của pháp luật**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Tổ chức tương hỗ cung cấp bảo hiểm vi mô theo quy định của pháp luật**."},{"id":219,"category":"Luật Kinh doanh bảo hiểm","question":"Theo pháp luật về hoạt động kinh doanh bảo hiểm, doanh nghiệp bảo hiểm có phải chịu sự kiểm tra giám sát của cơ quan nhà nước có thẩm quyền đối với hoạt động do đại lý bảo hiểm của doanh nghiệp bảo hiểm thực hiện không?","options":[{"key":"A","text":"Có"},{"key":"B","text":"Không"}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Có**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Có**."},{"id":220,"category":"Bảo hiểm con người","question":"Ông A tham gia bảo hiểm chi phí y tế, thời hạn 01 năm kể từ ngày 01/01/2023. Hợp đồng bảo hiểm có thỏa thuận về áp dụng thời gian chờ là 30 ngày đối với trường hợp điều trị bệnh thông thường. Ngày 15/01/2023, ông A bị đau dạ dày phải nhập viện phẫu thuật. Đợt điều trị kéo dài 07 ngày. Trường hợp này doanh nghiệp bảo hiểm chi trả quyền lợi bảo hiểm nào sau đây?","options":[{"key":"A","text":"Quyền lợi trợ cấp nằm viện."},{"key":"B","text":"Quyền lợi chi phí y tế thực tế."},{"key":"C","text":"Quyền lợi phẫu thuật."},{"key":"D","text":"Không chi trả."}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án **D** là **Không chi trả.**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Không chi trả.**."},{"id":221,"category":"Kiến thức chung","question":"Quy luật số đông được hiểu là (chọn phương án đúng nhất):","options":[{"key":"A","text":"Số lượng đủ lớn các đối tượng được bảo hiểm nhằm bù đắp cho số ít đối tượng đó bị tổn thất trong thời hạn bảo hiểm."},{"key":"B","text":"Các đối tượng bảo hiểm phải đồng nhất."},{"key":"C","text":"Các đối tượng bảo hiểm phải độc lập với nhau."},{"key":"D","text":"A, C đúng."},{"key":"E","text":"A, B, C đúng"}],"answer":"E","explanation":"Theo đáp án của đề cương, phương án **E** là nội dung đúng: **A, B, C đúng**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng**."},{"id":222,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, trường hợp doanh nghiệp bảo hiểm cố ý không thực hiện nghĩa vụ cung cấp thông tin hoặc cung cấp thông tin sai sự thật nhằm giao kết hợp đồng bảo hiểm thì:","options":[{"key":"A","text":"Bên mua bảo hiểm có quyền hủy bỏ hợp đồng bảo hiểm; Doanh nghiệp bảo hiểm không phải bồi thường thiệt hại phát sinh cho bên mua bảo hiểm do cung cấp thông tin sai sự thật."},{"key":"B","text":"Bên mua bảo hiểm có quyền hủy bỏ hợp đồng bảo hiểm; Doanh nghiệp bảo hiểm phải bồi thường thiệt hại phát sinh cho bên mua bảo hiểm do cung cấp thông tin sai sự thật"},{"key":"C","text":"Bên mua bảo hiểm không có quyền hủy bỏ hợp đồng bảo hiểm; Doanh nghiệp bảo hiểm phải bồi thường thiệt hại phát sinh cho bên mua bảo hiểm do cung cấp thông tin sai sự thật"},{"key":"D","text":"Bên mua bảo hiểm không có quyền hủy bỏ hợp đồng bảo hiểm; Doanh nghiệp bảo hiểm không phải bồi thường thiệt hại phát sinh cho bên mua bảo hiểm do cung cấp thông tin sai sự thật"}],"answer":"B","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **B**: **Bên mua bảo hiểm có quyền hủy bỏ hợp đồng bảo hiểm; Doanh nghiệp bảo hiểm phải bồi thường thiệt hại phát sinh cho bên mua bảo hiểm do cung cấp thông tin sai sự thật**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":223,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, cá nhân đã được cấp chứng chỉ đại lý bảo hiểm nhưng không hoạt động đại lý bảo hiểm trong thời hạn bao lâu phải thực hiện việc thi chứng chỉ đại lý bảo hiểm mới trước khi hoạt động đại lý?","options":[{"key":"A","text":"6 tháng"},{"key":"B","text":"1 năm"},{"key":"C","text":"2 năm"},{"key":"D","text":"3 năm"}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án **D** là **3 năm**. Mốc cần nhớ: **3 năm**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Chốt mốc **3 năm** và gắn với đúng điều kiện của câu."},{"id":224,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, thời hạn nộp hồ sơ yêu cầu bồi thường, trả tiền bảo hiểm theo hợp đồng bảo hiểm là:","options":[{"key":"A","text":"03 tháng kể từ ngày xảy ra sự kiện bảo hiểm"},{"key":"B","text":"06 tháng kể từ ngày xảy ra sự kiện bảo hiểm"},{"key":"C","text":"09 tháng kể từ ngày xảy ra sự kiện bảo hiểm"},{"key":"D","text":"01 năm kể từ ngày xảy ra sự kiện bảo hiểm"}],"answer":"D","explanation":"Khái niệm cần nhớ trong câu này là: **01 năm kể từ ngày xảy ra sự kiện bảo hiểm**. Đáp án đúng là **D**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Chốt mốc **01 năm** và gắn với đúng điều kiện của câu."},{"id":225,"category":"Luật Kinh doanh bảo hiểm","question":"Doanh nghiệp bảo hiểm có quyền từ chối bồi thường, trả tiền bảo hiểm trong trường hợp:","options":[{"key":"A","text":"Sự kiện bảo hiểm xảy ra không thuộc phạm vi trách nhiệm bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm."},{"key":"B","text":"Sự kiện bảo hiểm xảy ra thuộc các trường hợp loại trừ trách nhiệm bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm."},{"key":"C","text":"Sự kiện bảo hiểm xảy ra trong thời gian gia hạn đóng phí bảo hiểm."},{"key":"D","text":"A, B đúng."}],"answer":"D","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **D**: **A, B đúng.**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B đúng.**."},{"id":226,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phát biểu nào dưới đây sai:","options":[{"key":"A","text":"Bên mua bảo hiểm có quyền chuyển giao hợp đồng bảo hiểm theo thoả thuận trong hợp đồng bảo hiểm hoặc theo quy định của pháp luật."},{"key":"B","text":"Bên mua bảo hiểm không có quyền chuyển giao hợp đồng bảo hiểm"},{"key":"C","text":"Bên mua bảo hiểm không có quyền lợi có thể được bảo hiểm tại thời điểm giao kết hợp đồng bảo hiểm thì hợp đồng bảo hiểm sẽ vô hiệu."},{"key":"D","text":"Khi hợp đồng bảo hiểm vô hiệu thì hợp đồng không có hiệu lực từ thời điểm giao kết."}],"answer":"B","explanation":"Đây là câu hỏi tìm **phương án ngoại lệ/sai**. Theo đáp án của đề cương, phương án **B** là nội dung không phù hợp: **Bên mua bảo hiểm không có quyền chuyển giao hợp đồng bảo hiểm**. Khi làm bài, cần chú ý từ khóa phủ định như **“sai”, “không”, “ngoại trừ”**.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":227,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, văn phòng đại diện của doanh nghiệp bảo hiểm, doanh nghiệp môi giới bảo hiểm nước ngoài tại Việt Nam không được thực hiện hoạt động nào sau đây:","options":[{"key":"A","text":"Xúc tiến xây dựng các dự án đầu tư của doanh nghiệp bảo hiểm nước ngoài, doanh nghiệp tái bảo hiểm nước ngoài tại Việt Nam."},{"key":"B","text":"Thúc đẩy và theo dõi việc thực hiện các dự án do doanh nghiệp bảo hiểm, doanh nghiệp môi giới bảo hiểm nước ngoài tài trợ tại Việt Nam."},{"key":"C","text":"Kinh doanh bảo hiểm tại Việt Nam"},{"key":"D","text":"Nghiên cứu thị trường tại Việt Nam"}],"answer":"C","explanation":"Theo đáp án của đề cương, đáp án đúng là **C**: **Kinh doanh bảo hiểm tại Việt Nam**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Kinh doanh bảo hiểm tại Việt Nam**."},{"id":228,"category":"Luật Kinh doanh bảo hiểm","question":"Khi bảo hiểm tài sản trên giá trị, nếu xảy ra sự kiện bảo hiểm thì doanh nghiệp bảo hiểm tính toán bồi thường theo:","options":[{"key":"A","text":"Giá trị sổ sách."},{"key":"B","text":"Giá trị nguyên giá của tài sản sau khi trừ khấu hao."},{"key":"C","text":"Số tiền bảo hiểm của tài sản đó ghi trên giấy chứng nhận bảo hiểm."},{"key":"D","text":"Giá thị trường của tài sản được bảo hiểm tại thời điểm xảy ra thiệt hại."}],"answer":"D","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **D**: **Giá thị trường của tài sản được bảo hiểm tại thời điểm xảy ra thiệt hại.**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Giá thị trường của tài sản được bảo hiểm tại thời điểm xảy ra thiệt hại.**."},{"id":229,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Chọn phương án đúng về thời hạn bảo hiểm kết thúc theo quy tắc \"bảo hiểm mọi rủi ro lắp đặt\" (EAR) của nhà tái bảo hiểm Munich Re được các nhà nhận tái bảo hiểm trên thế giới chấp nhận:","options":[{"key":"A","text":"Khi các thiết bị, máy móc được bàn giao hay ngay khi kết thúc hoạt động chạy thử đầu tiên, tùy thời điểm nào xảy ra trước nhưng thời gian chạy thử không muộn hơn ngày kết thúc ghi trên giấy chứng nhận bảo hiểm."},{"key":"B","text":"Khi các thiết bị máy móc được bàn giao và kết thúc vào ngày ghi trên giấy chứng nhận bảo hiểm"},{"key":"C","text":"Vào thời điểm ghi trong giấy chứng nhận bảo hiểm"},{"key":"D","text":"B, C đúng"}],"answer":"A","explanation":"Theo đáp án của đề cương, phương án **A** là nội dung đúng: **Khi các thiết bị, máy móc được bàn giao hay ngay khi kết thúc hoạt động chạy thử đầu tiên, tùy thời điểm nào xảy ra trước nhưng thời gian chạy thử không muộn hơn ngày kết thúc ghi trên giấy chứng nhận bảo hiểm.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Khi các thiết bị, máy móc được bàn giao hay ngay khi kết thúc hoạt động chạy thử đầu tiên,…**."},{"id":230,"category":"Kiến thức chung","question":"Rủi ro thuần túy là rủi ro có hậu quả:","options":[{"key":"A","text":"Liên quan đến khả năng đầu cơ."},{"key":"B","text":"Liên quan đến khả năng tổn thất."},{"key":"C","text":"Liên quan đến khả năng đầu cơ và khả năng tổn thất."},{"key":"D","text":"Không phương án nào đúng."}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án đúng là **B**: **Liên quan đến khả năng tổn thất.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Liên quan đến khả năng tổn thất.**."},{"id":231,"category":"Luật Kinh doanh bảo hiểm","question":"Phạm vi điều chỉnh của Luật Kinh doanh bảo hiểm là:","options":[{"key":"A","text":"Tổ chức và hoạt động kinh doanh bảo hiểm; quyền và nghĩa vụ của tổ chức, cá nhân tham gia bảo hiểm; quản lý nhà nước về hoạt động kinh doanh bảo hiểm."},{"key":"B","text":"Bảo hiểm xã hội."},{"key":"C","text":"Bảo hiểm y tế."},{"key":"D","text":"Bảo hiểm tiền gửi."}],"answer":"A","explanation":"Khái niệm cần nhớ trong câu này là: **Tổ chức và hoạt động kinh doanh bảo hiểm; quyền và nghĩa vụ của tổ chức, cá nhân tham gia bảo hiểm; quản lý nhà nước về hoạt động kinh doanh bảo hiểm.**. Đáp án đúng là **A**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Tổ chức và hoạt động kinh doanh bảo hiểm; quyền và nghĩa vụ của tổ chức, cá nhân tham gia…**."},{"id":232,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Theo quy tắc bảo hiểm “Gián đoạn kinh doanh” của Hiệp hội bảo hiểm Vương quốc Anh (ABI), chi phí hoạt động không được bảo hiểm trong công thức tính lợi nhuận gộp (theo phương pháp trừ) được hiểu là:","options":[{"key":"A","text":"Chi phí cố định."},{"key":"B","text":"Chi phí biến đổi và những chi phí cố định mà người được bảo hiểm muốn tự bảo hiểm."}],"answer":"B","explanation":"Khái niệm cần nhớ trong câu này là: **Chi phí biến đổi và những chi phí cố định mà người được bảo hiểm muốn tự bảo hiểm.**. Đáp án đúng là **B**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Chi phí biến đổi và những chi phí cố định mà người được bảo hiểm muốn tự bảo hiểm.**."},{"id":233,"category":"Luật Kinh doanh bảo hiểm","question":"Luật kinh doanh bảo hiểm phân loại hợp đồng bảo hiểm theo tiêu chí nào:","options":[{"key":"A","text":"Đối tượng bảo hiểm."},{"key":"B","text":"Số tiền bảo hiểm."},{"key":"C","text":"Giá trị bảo hiểm."},{"key":"D","text":"Thời hạn bảo hiểm."}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Đối tượng bảo hiểm.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Đối tượng bảo hiểm.**."},{"id":234,"category":"Bảo hiểm xe cơ giới","question":"Theo đơn bảo hiểm trách nhiệm dân sự hàng hóa trên xe của chủ xe cơ giới: Trong quá trình vận chuyển, xe bị tai nạn làm hàng hóa trên xe bị tổn thất. Trường hợp này, doanh nghiệp bảo hiểm bồi thường cho người được bảo hiểm những chi phí nào sau đây:","options":[{"key":"A","text":"Chi phí xếp dỡ hàng hóa tổn thất."},{"key":"B","text":"Chi phí lưu kho, bãi hàng hóa tổn thất."},{"key":"C","text":"Chi phí thuê xe khác để tiếp tục chở hàng còn tốt về địa điểm giao hàng."},{"key":"D","text":"A, B đúng."},{"key":"E","text":"A, B, C đúng."}],"answer":"D","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **D**: **A, B đúng.**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B đúng.**."},{"id":235,"category":"Luật Kinh doanh bảo hiểm","question":"Chọn phương án sai về phạm vi bảo hiểm:","options":[{"key":"A","text":"Phạm vi bảo hiểm là phạm vi giới hạn những rủi ro, tổn thất phát sinh mà theo thỏa thuận doanh nghiệp bảo hiểm sẽ chịu trách nhiệm nếu xảy ra sự kiện bảo hiểm."},{"key":"B","text":"Phạm vi bảo hiểm là phạm vi giới hạn những rủi ro, tổn thất và chi phí phát sinh mà theo thỏa thuận doanh nghiệp bảo hiểm sẽ chịu trách nhiệm nếu xảy ra sự kiện bảo hiểm."},{"key":"C","text":"Phạm vi bảo hiểm được căn cứ theo các điều kiện, điều khoản quy định trong Quy tắc bảo hiểm và các điều khoản sửa đổi bổ sung (nếu có) kèm theo hợp đồng bảo hiểm."},{"key":"D","text":"A, C đúng."},{"key":"E","text":"B, C đúng"}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Phạm vi bảo hiểm là phạm vi giới hạn những rủi ro, tổn thất phát sinh mà theo thỏa thuận doanh nghiệp bảo hiểm sẽ chịu trách nhiệm nếu xảy ra sự kiện bảo hiểm.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":236,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phát biểu nào sau đây đúng về các trường hợp chuyển giao danh mục hợp đồng bảo hiểm:","options":[{"key":"A","text":"Thu hẹp nội dung, phạm vi hoạt động"},{"key":"B","text":"Chia, tách, sáp nhập, hợp nhất, giải thể, chấm dứt hoạt động"},{"key":"C","text":"A. B đúng"},{"key":"D","text":"A, B sai"}],"answer":"C","explanation":"Theo đáp án của đề cương, phương án **C** là nội dung đúng: **A. B đúng**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A. B đúng**."},{"id":237,"category":"Bảo hiểm con người","question":"Chọn phương án đúng nhất: Trong bảo hiểm sức khỏe, đối với quyền lợi bảo hiểm chi phí y tế, doanh nghiệp bảo hiểm chịu trách nhiệm chi trả:","options":[{"key":"A","text":"Số tiền không vượt quá chi phí y tế thực tế mà người được bảo hiểm đã trả khi khám, chữa bệnh trong phạm vi số tiền bảo hiểm."},{"key":"B","text":"Số tiền theo thỏa thuận tại hợp đồng bảo hiểm."},{"key":"C","text":"Số tiền có thể vượt quá chi phí y tế thực tế mà người được bảo hiểm đã trả khi khám chữa bệnh nhưng vẫn trong phạm vi số tiền bảo hiểm."}],"answer":"A","explanation":"Theo đáp án của đề cương, phương án **A** là nội dung đúng: **Số tiền không vượt quá chi phí y tế thực tế mà người được bảo hiểm đã trả khi khám, chữa bệnh trong phạm vi số tiền bảo hiểm.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Số tiền không vượt quá chi phí y tế thực tế mà người được bảo hiểm đã trả khi khám, chữa…**."},{"id":238,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phát biểu nào sau đây là sai về nghĩa vụ của đại lý bảo hiểm:","options":[{"key":"A","text":"Giới thiệu, chào bán sản phẩm bảo hiểm"},{"key":"B","text":"Cung cấp thông tin về sản phẩm bảo hiểm một cách đầy đủ, chính xác cho bên mua bảo hiểm"},{"key":"C","text":"Tự kê khai thông tin cho bên mua bảo hiểm mà không cần có sự đồng ý của bên mua bảo hiểm"},{"key":"D","text":"A, B đúng"}],"answer":"C","explanation":"Theo đáp án của đề cương, đáp án đúng là **C**: **Tự kê khai thông tin cho bên mua bảo hiểm mà không cần có sự đồng ý của bên mua bảo hiểm**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":239,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, trừ trường hợp việc chuyển giao hợp đồng bảo hiểm được thực hiện theo tập quán quốc tế hoặc theo thỏa thuận trong hợp đồng bảo hiểm thì việc chuyển giao hợp đồng bảo hiểm chỉ có hiệu lực khi:","options":[{"key":"A","text":"Bên mua bảo hiểm chuyển giao hợp đồng bảo hiểm cho bên nhận chuyển giao và không cần phải thông báo cho doanh nghiệp bảo hiểm"},{"key":"B","text":"Bên mua bảo hiểm chủ động chuyển giao hợp đồng bảo hiểm cho bên nhận chuyển giao sau khi có thông báo bằng văn bản cho doanh nghiệp bảo hiểm về việc chuyển giao mà không cần có sự chấp thuận của doanh nghiệp bảo hiểm"},{"key":"C","text":"Bên mua bảo hiểm thông báo bằng văn bản và được doanh nghiệp bảo hiểm đồng ý bằng văn bản về việc chuyển giao đó"},{"key":"D","text":"A, B, C sai"}],"answer":"C","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **C**: **Bên mua bảo hiểm thông báo bằng văn bản và được doanh nghiệp bảo hiểm đồng ý bằng văn bản về việc chuyển giao đó**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Bên mua bảo hiểm thông báo bằng văn bản và được doanh nghiệp bảo hiểm đồng ý bằng văn bản…**."},{"id":240,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, bảo hiểm bắt buộc là sản phẩm bảo hiểm do Chính phủ quy định về:","options":[{"key":"A","text":"Điều kiện bảo hiểm, số tiền bảo hiểm tối thiểu."},{"key":"B","text":"Điều kiện bảo hiểm, mức phí bảo hiểm, số tiền bảo hiểm tối thiểu."},{"key":"C","text":"Điều kiện bảo hiểm, phí bảo hiểm tối thiểu."},{"key":"D","text":"Phí bảo hiểm, số tiền bảo hiểm tối thiểu."}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án đúng là **B**: **Điều kiện bảo hiểm, mức phí bảo hiểm, số tiền bảo hiểm tối thiểu.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Điều kiện bảo hiểm, mức phí bảo hiểm, số tiền bảo hiểm tối thiểu.**."},{"id":242,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, tổ chức, cá nhân có tài sản, trách nhiệm dân sự, sức khỏe, tính mạng, nghĩa vụ hoặc lợi ích kinh tế được bảo hiểm theo hợp đồng bảo hiểm được gọi là:","options":[{"key":"A","text":"Người được bảo hiểm"},{"key":"B","text":"Bên mua bảo hiểm"},{"key":"C","text":"Đại lý bảo hiểm"},{"key":"D","text":"Người thụ hưởng"}],"answer":"A","explanation":"Khái niệm cần nhớ trong câu này là: **Người được bảo hiểm**. Đáp án đúng là **A**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Người được bảo hiểm**."},{"id":243,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, chọn phương án đúng về các hình thức cung cấp sản phẩm bảo hiểm của doanh nghiệp bảo hiểm:","options":[{"key":"A","text":"Trực tiếp"},{"key":"B","text":"Thông qua đại lý bảo hiểm, môi giới bảo hiểm"},{"key":"C","text":"Thông qua giao dịch điện tử"},{"key":"D","text":"A, B, C đúng"}],"answer":"D","explanation":"Theo đáp án của đề cương, phương án **D** là nội dung đúng: **A, B, C đúng**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng**."},{"id":244,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phát biểu nào sau đây là đúng nhất:","options":[{"key":"A","text":"Đại lý bảo hiểm có quyền yêu cầu doanh nghiệp bảo hiểm hoàn trả tiền ký quỹ hoặc tài sản thế chấp theo thỏa thuận trong hợp đồng đại lý bảo hiểm."},{"key":"B","text":"Đại lý bảo hiểm là tổ chức có thể đồng thời làm đại lý bảo hiểm cho doanh nghiệp bảo hiểm khác mà không cần sự chấp thuận bằng văn bản của doanh nghiệp mà tổ chức đó đang làm đại lý."},{"key":"C","text":"Đại lý bảo hiểm có thể chủ động giảm phí bảo hiểm, hoàn phí bảo hiểm hoặc cung cấp các quyền lợi nằm ngoài hợp đồng bảo hiểm để khuyến khích khách hàng tham gia bảo hiểm."},{"key":"D","text":"A, C đúng."}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Đại lý bảo hiểm có quyền yêu cầu doanh nghiệp bảo hiểm hoàn trả tiền ký quỹ hoặc tài sản thế chấp theo thỏa thuận trong hợp đồng đại lý bảo hiểm.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Đại lý bảo hiểm có quyền yêu cầu doanh nghiệp bảo hiểm hoàn trả tiền ký quỹ hoặc tài sản…**."},{"id":245,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, tổ chức kinh doanh bảo hiểm là:","options":[{"key":"A","text":"Doanh nghiệp bảo hiểm, tổ chức tương hỗ cung cấp bảo hiểm vi mô, chi nhánh doanh nghiệp bảo hiểm phi nhân thọ nước ngoài."},{"key":"B","text":"Doanh nghiệp bảo hiểm, tổ chức tương hỗ cung cấp bảo hiểm vi mô, chi nhánh doanh nghiệp bảo hiểm phi nhân thọ nước ngoài, hợp tác xã bảo hiểm."},{"key":"C","text":"Doanh nghiệp bảo hiểm, chi nhánh doanh nghiệp bảo hiểm phi nhân thọ nước ngoài, hợp tác xã bảo hiểm."}],"answer":"A","explanation":"Khái niệm cần nhớ trong câu này là: **Doanh nghiệp bảo hiểm, tổ chức tương hỗ cung cấp bảo hiểm vi mô, chi nhánh doanh nghiệp bảo hiểm phi nhân thọ nước ngoài.**. Đáp án đúng là **A**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Doanh nghiệp bảo hiểm, tổ chức tương hỗ cung cấp bảo hiểm vi mô, chi nhánh doanh nghiệp bảo…**."},{"id":246,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Theo đơn bảo hiểm “Gián đoạn kinh doanh” của Hiệp hội bảo hiểm Vương quốc Anh (ABI), các chi phí hoạt động gia tăng thêm ngoài chi phí hoạt động gia tăng thuộc hạng mục Lợi nhuận gộp có thể được bảo hiểm trong loại hình bảo hiểm gián đoạn kinh doanh không?","options":[{"key":"A","text":"Có."},{"key":"B","text":"Không."}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án đúng là **B**: **Không.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Không.**."},{"id":247,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Theo đơn bảo hiểm mọi rủi ro xây dựng/lắp đặt (CAR/EAR) của nhà tái bảo hiểm Munich Re, số tiền bảo hiểm đối với Phần tổn thất vật chất (Phần I) được quy định cho mỗi và mọi vụ tổn thất có nghĩa là:","options":[{"key":"A","text":"Số tiền bồi thường cho một vụ tổn thất không vượt quá số tiền bảo hiểm, và không giới hạn các vụ tổn thất trong thời hạn bảo hiểm."},{"key":"B","text":"Giới hạn các vụ tổn thất trong thời hạn bảo hiểm, tổng số tiền bồi thường của một hoặc nhiều vụ tổn thất không vượt quá số tiền bảo hiểm."},{"key":"C","text":"Không giới hạn các vụ tổn thất trong thời hạn bảo hiểm, tổng số tiền bồi thường của một hoặc nhiều vụ tổn thất không vượt quá số tiền bảo hiểm."}],"answer":"C","explanation":"Khái niệm cần nhớ trong câu này là: **Không giới hạn các vụ tổn thất trong thời hạn bảo hiểm, tổng số tiền bồi thường của một hoặc nhiều vụ tổn thất không vượt quá số tiền bảo hiểm.**. Đáp án đúng là **C**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Không giới hạn các vụ tổn thất trong thời hạn bảo hiểm, tổng số tiền bồi thường của một…**."},{"id":248,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, trường hợp các bên giao kết hợp đồng bảo hiểm trùng, khi xảy ra sự kiện bảo hiểm thì:","options":[{"key":"A","text":"Tổng số tiền bồi thường của các hợp đồng bảo hiểm không vượt quá giá trị thiệt hại thực tế của tài sản."},{"key":"B","text":"Tổng số tiền bồi thường của các hợp đồng bảo hiểm không vượt quá giá trị thị trường của tài sản tại thời điểm giao kết hợp đồng bảo hiểm."},{"key":"C","text":"Tổng số tiền bồi thường của các hợp đồng bảo hiểm không vượt quá giá trị sổ sách của tài sản tại thời điểm giao kết hợp đồng bảo hiểm."},{"key":"D","text":"A, B đúng."}],"answer":"A","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **A**: **Tổng số tiền bồi thường của các hợp đồng bảo hiểm không vượt quá giá trị thiệt hại thực tế của tài sản.**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Tổng số tiền bồi thường của các hợp đồng bảo hiểm không vượt quá giá trị thiệt hại thực tế…**."},{"id":249,"category":"Kiến thức chung","question":"Bảo hiểm là phương thức quản lý rủi ro nào sau đây:","options":[{"key":"A","text":"Né tránh rủi ro."},{"key":"B","text":"Chuyển giao rủi ro."},{"key":"C","text":"Chấp nhận rủi ro."},{"key":"D","text":"Kiểm soát rủi ro."}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án đúng là **B**: **Chuyển giao rủi ro.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Chuyển giao rủi ro.**."},{"id":250,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phát biểu nào sau đây là đúng nhất về đồng bảo hiểm:","options":[{"key":"A","text":"Các doanh nghiệp bảo hiểm có thể đồng bảo hiểm trên cơ sở cùng thống nhất giao kết với bên mua bảo hiểm trên một hợp đồng bảo hiểm."},{"key":"B","text":"Các doanh nghiệp bảo hiểm, chi nhánh doanh nghiệp bảo hiểm phi nhân thọ nước ngoài nhận phí bảo hiểm."},{"key":"C","text":"Các doanh nghiệp bảo hiểm bồi thường, trả tiền bảo hiểm theo tỷ lệ đã thỏa thuận trong hợp đồng bảo hiểm."},{"key":"D","text":"A, B, C đúng."}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **A, B, C đúng.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng.**."},{"id":251,"category":"Kiến thức chung","question":"Vai trò xã hội của bảo hiểm là:","options":[{"key":"A","text":"Góp phần đảm bảo an toàn cho nền kinh tế - xã hội."},{"key":"B","text":"Tạo thêm việc làm cho xã hội."},{"key":"C","text":"Tạo nếp sống tiết kiệm và mang đến trạng thái an toàn về mặt tinh thần cho xã hội."},{"key":"D","text":"A, B, C đúng."}],"answer":"D","explanation":"Khái niệm cần nhớ trong câu này là: **A, B, C đúng.**. Đáp án đúng là **D**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng.**."},{"id":252,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, trường hợp người được bảo hiểm hoặc người thụ hưởng chứng minh được rằng không biết thời điểm xảy ra sự kiện bảo hiểm thì thời hạn nộp hồ sơ yêu cầu bồi thường, trả tiền bảo hiểm là:","options":[{"key":"A","text":"01 năm kể từ ngày xảy ra sự kiện bảo hiểm"},{"key":"B","text":"02 năm kể từ ngày xảy ra sự kiện bảo hiểm."},{"key":"C","text":"01 năm tính từ ngày người được bảo hiểm hoặc người thụ hưởng biết việc xảy ra sự kiện bảo hiểm đó."},{"key":"D","text":"02 năm tính từ ngày người được bảo hiểm hoặc người thụ hưởng biết việc xảy ra sự kiện bảo hiểm đó."}],"answer":"C","explanation":"Khái niệm cần nhớ trong câu này là: **01 năm tính từ ngày người được bảo hiểm hoặc người thụ hưởng biết việc xảy ra sự kiện bảo hiểm đó.**. Đáp án đúng là **C**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Chốt mốc **01 năm** và gắn với đúng điều kiện của câu."},{"id":253,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, bảo hiểm bắt buộc không bao gồm:","options":[{"key":"A","text":"Bảo hiểm cháy, nổ bắt buộc."},{"key":"B","text":"Bảo hiểm bắt buộc trách nhiệm dân sự của chủ xe cơ giới."},{"key":"C","text":"Bảo hiểm sức khỏe bắt buộc."},{"key":"D","text":"Bảo hiểm bắt buộc trong hoạt động đầu tư xây dựng."}],"answer":"C","explanation":"Theo đáp án của đề cương, đáp án đúng là **C**: **Bảo hiểm sức khỏe bắt buộc.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Bảo hiểm sức khỏe bắt buộc.**."},{"id":254,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, chọn phương án đúng điền vào chỗ _____ của câu sau: \"Tổng số tiền bồi thường của các hợp đồng bảo hiểm _____ giá trị thiệt hại thực tế của tài sản\".","options":[{"key":"A","text":"Luôn đúng bằng."},{"key":"B","text":"Luôn ít hơn."},{"key":"C","text":"Không vượt quá."},{"key":"D","text":"Có thể vượt quá."}],"answer":"C","explanation":"Theo đáp án của đề cương, phương án **C** là nội dung đúng: **Không vượt quá.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Không vượt quá.**."},{"id":255,"category":"Bảo hiểm con người","question":"Trong sản phẩm bảo hiểm sức khỏe với quyền lợi bảo hiểm tai nạn, tai nạn được hiểu là:","options":[{"key":"A","text":"Tai nạn do một sự kiện bất ngờ, ngoài ý muốn của người được bảo hiểm, từ bên ngoài tác động lên thân thể người được bảo hiểm, là nguyên nhân trực tiếp khiến cho người được bảo hiểm bị chết hoặc thương tật thân thể."},{"key":"B","text":"Tai nạn do một sự kiện bất ngờ, ngoài ý muốn của người được bảo hiểm, từ bên ngoài tác động lên thân thể người được bảo hiểm, là nguyên nhân gián tiếp khiến cho người được bảo hiểm bị chết hoặc thương tật thân thể."},{"key":"C","text":"Tai nạn do một sự kiện bất ngờ, ngoài ý muốn của người được bảo hiểm, từ bên ngoài tác động lên thân thể người được bảo hiểm, là nguyên nhân trực tiếp hoặc gián tiếp khiến cho người được bảo hiểm bị chết hoặc thương tật thân thể."}],"answer":"A","explanation":"Khái niệm cần nhớ trong câu này là: **Tai nạn do một sự kiện bất ngờ, ngoài ý muốn của người được bảo hiểm, từ bên ngoài tác động lên thân thể người được bảo hiểm, là nguyên nhân trực tiếp khiến cho người được bảo hiểm bị chết hoặc thương tật thân thể.**. Đáp án đúng là **A**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Tai nạn do một sự kiện bất ngờ, ngoài ý muốn của người được bảo hiểm, từ bên ngoài tác động…**."},{"id":256,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, trong trường hợp hợp đồng bảo hiểm tài sản dưới giá trị được giao kết thì:","options":[{"key":"A","text":"Doanh nghiệp bảo hiểm chỉ chịu trách nhiệm bồi thường thiệt hại theo tỷ lệ tương ứng với số tiền bảo hiểm và giá trị sổ sách của tài sản được bảo hiểm tại thời điểm giao kết hoặc thỏa thuận trong hợp đồng bảo hiểm."},{"key":"B","text":"Doanh nghiệp bảo hiểm chỉ chịu trách nhiệm bồi thường thiệt hại theo tỷ lệ tương ứng với số tiền bảo hiểm và giá thị trường của tài sản được bảo hiểm tại thời điểm giao kết hoặc thỏa thuận trong hợp đồng bảo hiểm."},{"key":"C","text":"Doanh nghiệp bảo hiểm chỉ chịu trách nhiệm bồi thường thiệt hại theo tỷ lệ tương ứng với giá trị bảo hiểm và giá trị sổ sách của tài sản được bảo hiểm tại thời điểm giao kết hoặc thỏa thuận trong hợp đồng bảo hiểm."},{"key":"D","text":"A, B, C đúng"}],"answer":"B","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **B**: **Doanh nghiệp bảo hiểm chỉ chịu trách nhiệm bồi thường thiệt hại theo tỷ lệ tương ứng với số tiền bảo hiểm và giá thị trường của tài sản được bảo hiểm tại thời điểm giao kết hoặc thỏa thuận trong hợp đồng bảo hiểm.**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Doanh nghiệp bảo hiểm chỉ chịu trách nhiệm bồi thường thiệt hại theo tỷ lệ tương ứng với số…**."},{"id":257,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, việc chuyển giao hợp đồng bảo hiểm (trừ trường hợp việc chuyển giao được thực hiện theo tập quán quốc tế hoặc theo thỏa thuận trong hợp đồng bảo hiểm) chỉ có hiệu lực khi:","options":[{"key":"A","text":"Bên mua bảo hiểm thông báo bằng văn bản."},{"key":"B","text":"Được doanh nghiệp bảo hiểm, chi nhánh doanh nghiệp bảo hiểm phi nhân thọ nước ngoài đồng ý bằng văn bản."},{"key":"C","text":"A, B đúng."},{"key":"D","text":"A, B sai."}],"answer":"C","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **C**: **A, B đúng.**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B đúng.**."},{"id":258,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, doanh nghiệp bảo hiểm không được ký kết hợp đồng đại lý bảo hiểm với những đối tượng sau:","options":[{"key":"A","text":"Tổ chức, cá nhân đang bị truy cứu trách nhiệm hình sự."},{"key":"B","text":"Cá nhân đang chấp hành hình phạt tù."},{"key":"C","text":"Tổ chức đang bị đình chỉ hoạt động có thời hạn, đang bị đình chỉ hoạt động vĩnh viễn hoặc đang bị cấm kinh doanh, cấm hoạt động trong lĩnh vực liên quan đến bảo hiểm."},{"key":"D","text":"A, B, C đúng"}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **A, B, C đúng**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng**."},{"id":259,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, khi xảy ra sự kiện bảo hiểm, doanh nghiệp bảo hiểm phải bồi thường, trả tiền bảo hiểm:","options":[{"key":"A","text":"Theo thời hạn đã thỏa thuận trong hợp đồng bảo hiểm."},{"key":"B","text":"Trong thời hạn 15 ngày kể từ ngày nhận được đầy đủ hồ sơ hợp lệ về yêu cầu bồi thường, trả tiền bảo hiểm (trường hợp không có thỏa thuận về thời hạn)."},{"key":"C","text":"A, B đúng."}],"answer":"C","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **C**: **A, B đúng.**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B đúng.**."},{"id":260,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, đại lý bảo hiểm có quyền:","options":[{"key":"A","text":"Lựa chọn và giao kết hợp đồng đại lý bảo hiểm đối với doanh nghiệp bảo hiểm theo quy định của pháp luật."},{"key":"B","text":"Thay mặt doanh nghiệp bảo hiểm ký kết hợp đồng bảo hiểm với bên mua bảo hiểm."},{"key":"C","text":"Giảm phí bảo hiểm cho các khách hàng thân thiết."},{"key":"D","text":"A, B, C đúng."}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Lựa chọn và giao kết hợp đồng đại lý bảo hiểm đối với doanh nghiệp bảo hiểm theo quy định của pháp luật.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Lựa chọn và giao kết hợp đồng đại lý bảo hiểm đối với doanh nghiệp bảo hiểm theo quy định…**."},{"id":261,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, các loại hình bảo hiểm được chia thành:","options":[{"key":"A","text":"Bảo hiểm con người, bảo hiểm tài sản, bảo hiểm trách nhiệm dân sự."},{"key":"B","text":"Bảo hiểm nhân thọ, bảo hiểm phi nhân thọ, bảo hiểm sức khỏe."},{"key":"C","text":"Bảo hiểm ngắn hạn, bảo hiểm dài hạn."},{"key":"D","text":"Bảo hiểm cá nhân, bảo hiểm nhóm."}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Bảo hiểm con người, bảo hiểm tài sản, bảo hiểm trách nhiệm dân sự.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Bảo hiểm con người, bảo hiểm tài sản, bảo hiểm trách nhiệm dân sự.**."},{"id":262,"category":"Bảo hiểm con người","question":"Khi tham gia bảo hiểm sức khỏe với quyền lợi bảo hiểm thương tật toàn bộ vĩnh viễn do tai nạn, trường hợp người được bảo hiểm bị mù hoàn toàn hai mắt do tai nạn, doanh nghiệp bảo hiểm sẽ chi trả số tiền bảo hiểm nào sau đây?","options":[{"key":"A","text":"200% số tiền bảo hiểm."},{"key":"B","text":"100% số tiền bảo hiểm."},{"key":"C","text":"50% số tiền bảo hiểm."},{"key":"D","text":"20% số tiền bảo hiểm."}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án **B** là **100% số tiền bảo hiểm.**. Mốc cần nhớ: **100**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Chốt mốc **100** và gắn với đúng điều kiện của câu."},{"id":263,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, đại lý bảo hiểm là:","options":[{"key":"A","text":"Người được doanh nghiệp bảo hiểm ủy quyền thực hiện tất cả các công việc liên quan đến nghiệp vụ bảo hiểm."},{"key":"B","text":"Tổ chức, cá nhân được doanh nghiệp bảo hiểm ủy quyền trên cơ sở hợp đồng đại lý bảo hiểm để thực hiện hoạt động đại lý bảo hiểm."},{"key":"C","text":"Tổ chức, cá nhân được bên mua bảo hiểm ủy quyển trên cơ sở hợp đồng đại lý bảo hiểm để thực hiện hoạt động đại lý bảo hiểm."},{"key":"D","text":"A, B, C đúng."}],"answer":"B","explanation":"Khái niệm cần nhớ trong câu này là: **Tổ chức, cá nhân được doanh nghiệp bảo hiểm ủy quyền trên cơ sở hợp đồng đại lý bảo hiểm để thực hiện hoạt động đại lý bảo hiểm.**. Đáp án đúng là **B**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Tổ chức, cá nhân được doanh nghiệp bảo hiểm ủy quyền trên cơ sở hợp đồng đại lý bảo hiểm để…**."},{"id":264,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Chọn phương án đúng nhất: Cơ sở giải quyết bồi thường đối với Phần II - Trách nhiệm đối với bên thứ ba trong Đơn bảo hiểm mọi rủi ro xây dựng, lắp đặt (CAR.EAR) của nhà tái bảo hiểm Munich Re là:","options":[{"key":"A","text":"Thiệt hại về người và tài sản đối với bên thứ ba là hậu quả của hành vi bất cẩn. sai sót mà người được bảo hiểm phải chịu trách nhiệm theo quy định của pháp luật."},{"key":"B","text":"Phải có thiệt hại về tài sản và.hoặc người."},{"key":"C","text":"Tổng số tiền bồi thường đối với Phần II có thể vượt quá mức trách nhiệm bảo hiểm theo Phần I (Phần tổn thất vật chất)"},{"key":"D","text":"A, B đúng."}],"answer":"D","explanation":"Theo đáp án của đề cương, phương án **D** là nội dung đúng: **A, B đúng.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B đúng.**."},{"id":265,"category":"Kiến thức chung","question":"Hãy chọn phương án sai:","options":[{"key":"A","text":"Mức miễn thường không khấu trừ có nghĩa là nếu giá trị tổn thất lớn hơn mức miễn thường thì bồi thường toàn bộ giá trị tổn thất."},{"key":"B","text":"Mức miễn thường không khấu trừ có nghĩa là nếu giá trị tổn thất nhỏ hơn mức miễn thường thì doanh nghiệp bảo hiểm không phải bồi thường."},{"key":"C","text":"Mức miễn thường có khấu trừ có nghĩa là nếu giá trị tổn thất lớn hơn mức miễn thường thì bồi thường toàn bộ giá trị tổn thất."},{"key":"D","text":"Mức miễn thường có khấu trừ có nghĩa là nếu giá trị tổn thất lớn hơn mức miễn thường thì số tiền bồi thường bằng giá trị tổn thất trừ đi mức miễn thường."}],"answer":"C","explanation":"Theo đáp án của đề cương, đáp án đúng là **C**: **Mức miễn thường có khấu trừ có nghĩa là nếu giá trị tổn thất lớn hơn mức miễn thường thì bồi thường toàn bộ giá trị tổn thất.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":266,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, hợp đồng bảo hiểm tài sản trên giá trị là:","options":[{"key":"A","text":"Hợp đồng trong đó số tiền bảo hiểm cao hơn giá trị của tài sản được bảo hiểm tại thời điểm giao kết hợp đồng."},{"key":"B","text":"Hợp đồng trong đó số tiền bảo hiểm cao hơn giá thị trường của tài sản được bảo hiểm tại thời điểm giao kết hợp đồng."},{"key":"C","text":"Hợp đồng trong đó số tiền bảo hiểm cao hơn giá trị trên sổ sách của tài sản được bảo hiểm tại thời điểm xảy ra tổn thất."},{"key":"D","text":"Hợp đồng trong đó số tiền bảo hiểm cao hơn giá trị ước tính của tài sản được bảo hiểm tại thời điểm xảy ra tổn thất."}],"answer":"B","explanation":"Khái niệm cần nhớ trong câu này là: **Hợp đồng trong đó số tiền bảo hiểm cao hơn giá thị trường của tài sản được bảo hiểm tại thời điểm giao kết hợp đồng.**. Đáp án đúng là **B**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Hợp đồng trong đó số tiền bảo hiểm cao hơn giá thị trường của tài sản được bảo hiểm tại…**."},{"id":267,"category":"Bảo hiểm con người","question":"Khi tham gia bảo hiểm sức khỏe, trường hợp người được bảo hiểm bị ốm đau, bệnh tật thì có thể được nhận quyền lợi bảo hiểm nào sau đây?","options":[{"key":"A","text":"Quyền lợi bảo hiểm cho các chi phi y tế điều trị nội trú do ốm đau, bệnh tật."},{"key":"B","text":"Quyền lợi bảo hiểm cho các chi phí điều trị ngoại trú do ốm đau, bệnh tật."},{"key":"C","text":"Chi phí điều trị không theo chỉ định của bác sỹ."},{"key":"D","text":"A, B đúng."},{"key":"E","text":"A, B, C đúng."}],"answer":"D","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **D**: **A, B đúng.**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B đúng.**."},{"id":268,"category":"Kiến thức chung","question":"Mức miễn thường là phần tổn thất và/hoặc chi phí do sự kiện bảo hiểm gây ra mà người được bảo hiểm phải tự chịu. Mức miễn thường được áp dụng cho (chọn phương án đúng nhất):","options":[{"key":"A","text":"Bảo hiểm tài sản."},{"key":"B","text":"Bảo hiểm nhân thọ."},{"key":"C","text":"Bảo hiểm y tế."},{"key":"D","text":"A, C đúng."}],"answer":"D","explanation":"Theo đáp án của đề cương, phương án **D** là nội dung đúng: **A, C đúng.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, C đúng.**."},{"id":269,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, doanh nghiệp bảo hiểm không được áp dụng điều khoản loại trừ trách nhiệm bảo hiểm về việc chậm thông báo trong trường hợp nào sau đây:","options":[{"key":"A","text":"Bên mua bảo hiểm chậm thông báo sự kiện bảo hiểm trong mọi trường hợp."},{"key":"B","text":"Bên mua bảo hiểm chậm thông báo sự kiện bảo hiểm do có sự kiện bất khả kháng."},{"key":"C","text":"Bên mua bảo hiểm chậm thông báo sự kiện bảo hiểm do có sự kiện trở ngại khách quan."},{"key":"D","text":"B, C đúng."}],"answer":"D","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **D**: **B, C đúng.**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **B, C đúng.**."},{"id":270,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Một trong các nguyên tắc bồi thường áp dụng trong bảo hiểm tài sản là:","options":[{"key":"A","text":"Doanh nghiệp bảo hiểm bồi thường trên cơ sở giá trị thực tế (giá thị trường) của tài sản trước thời điểm xảy ra tổn thất."},{"key":"B","text":"Doanh nghiệp bảo hiểm bồi thường không vượt quá số tiền bảo hiểm trừ trường hợp có thỏa thuận khác trong hợp đồng bảo hiểm."},{"key":"C","text":"Doanh nghiệp bảo hiểm bồi thường theo giá trị thay thế mới tài sản."},{"key":"D","text":"A, C đúng."}],"answer":"B","explanation":"Khái niệm cần nhớ trong câu này là: **Doanh nghiệp bảo hiểm bồi thường không vượt quá số tiền bảo hiểm trừ trường hợp có thỏa thuận khác trong hợp đồng bảo hiểm.**. Đáp án đúng là **B**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Doanh nghiệp bảo hiểm bồi thường không vượt quá số tiền bảo hiểm trừ trường hợp có thỏa…**."},{"id":271,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, đáp án nào đúng khi điền vào chỗ ____ trong câu dưới đây: \"Doanh nghiệp bảo hiểm, chi nhánh doanh nghiệp bảo hiểm phi nhân thọ nước ngoài có quyền kiểm tra các điều kiện bảo đảm an toàn cho ____ \"","options":[{"key":"A","text":"Đối tượng bảo hiểm."},{"key":"B","text":"Người được bảo hiểm."},{"key":"C","text":"Đại lý bảo hiểm."}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Đối tượng bảo hiểm.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Đối tượng bảo hiểm.**."},{"id":272,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phát biểu nào dưới đây đúng nhất:","options":[{"key":"A","text":"Người được bảo hiểm là tổ chức, cá nhân giao kết hợp đồng bảo hiểm với doanh nghiệp bảo hiểm và đóng phí bảo hiểm."},{"key":"B","text":"Người thụ hưởng là tổ chức, cá nhân được bên mua bảo hiểm hoặc người được bảo hiểm chỉ định để nhận tiền bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm."},{"key":"C","text":"A, B đúng."}],"answer":"C","explanation":"Theo đáp án của đề cương, phương án **C** là nội dung đúng: **A, B đúng.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B đúng.**."},{"id":273,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phát biểu nào sau đây đúng:","options":[{"key":"A","text":"Mức hoa hồng đại lý bảo hiểm tối đa theo quy định của Bộ trưởng Bộ Tài chính."},{"key":"B","text":"Hoa hồng đại lý bảo hiểm do doanh nghiệp bảo hiểm chi trả có thể thấp hơn mức tối đa do Bộ trưởng Bộ Tài chính quy định."},{"key":"C","text":"Ngoài mức hoa hồng đại lý bảo hiểm theo quy định của pháp luật, doanh nghiệp bảo hiểm có thể trả thêm hoa hồng đại lý bảo hiểm theo thỏa thuận giữa doanh nghiệp bảo hiểm và đại lý bảo hiểm."},{"key":"D","text":"A, B đúng."}],"answer":"D","explanation":"Theo đáp án của đề cương, phương án **D** là nội dung đúng: **A, B đúng.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B đúng.**."},{"id":274,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, Trong bảo hiểm tài sản, đáp án nào đúng khi điền vào chỗ ____ dưới đây: \"Trường hợp xảy ra tổn thất, ____ không được từ bỏ tài sản được bảo hiểm và phải áp dụng các biện pháp cần thiết mà khả năng cho phép để ngăn chặn hoặc giảm thiểu tổn thất, trừ trường hợp pháp luật có quy định khác hoặc các bên có thỏa thuận khác\".","options":[{"key":"A","text":"Doanh nghiệp bảo hiểm."},{"key":"B","text":"Người thụ hưởng."},{"key":"C","text":"Người được bảo hiểm."},{"key":"D","text":"Người gây ra tổn thất."}],"answer":"C","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **C**: **Người được bảo hiểm.**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Người được bảo hiểm.**."},{"id":275,"category":"Luật Kinh doanh bảo hiểm","question":"Theo pháp luật về hoạt động kinh doanh bảo hiểm, phát biểu nào sau đây đúng nhất về giới hạn trách nhiệm bảo hiểm trong bảo hiểm trách nhiệm:","options":[{"key":"A","text":"Trong phạm vi giới hạn trách nhiệm bảo hiểm, doanh nghiệp bảo hiểm phải trả cho người được bảo hiểm những khoản tiền mà theo quy định của pháp luật người được bảo hiểm có trách nhiệm bồi thường cho người thứ ba."},{"key":"B","text":"Doanh nghiệp bảo hiểm phải trả các cho người được bảo hiểm các chi phí liên quan đến việc giải quyết tranh chấp về trách nhiệm đối với người thứ ba."},{"key":"C","text":"Tổng số tiền bồi thường của doanh nghiệp bảo hiểm không vượt quá giới hạn trách nhiệm bảo hiểm, trừ trường hợp có thỏa thuận khác trong hợp đồng bảo hiểm."},{"key":"D","text":"A, B, C đúng."},{"key":"E","text":"A, C đúng."}],"answer":"D","explanation":"Theo đáp án của đề cương, phương án **D** là nội dung đúng: **A, B, C đúng.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng.**."},{"id":276,"category":"Luật Kinh doanh bảo hiểm","question":"Chọn phương án đúng nhất về phạm vi bảo hiểm:","options":[{"key":"A","text":"Phạm vi bảo hiểm là giới hạn những rủi ro, tổn thất mà doanh nghiệp bảo hiểm sẽ chịu trách nhiệm bồi thường, trả tiền bảo hiểm nếu xảy ra sự kiện bảo hiểm"},{"key":"B","text":"Phạm vi bảo hiểm là giới hạn những rủi ro, tổn thất và chi phí phát sinh mà doanh nghiệp bảo hiểm sẽ chịu trách nhiệm bồi thường, trả tiền bảo hiểm nếu xảy ra sự kiện bảo hiểm"},{"key":"C","text":"Phạm vi bảo hiểm được căn cứ theo các điều kiện, điều khoản bảo hiểm quy định trong quy tắc bảo hiểm và các điều khoản sửa đổi, bổ sung (nếu có) kèm hợp đồng bảo hiểm"},{"key":"D","text":"A, C đúng"},{"key":"E","text":"B, C đúng"}],"answer":"E","explanation":"Theo đáp án của đề cương, phương án **E** là nội dung đúng: **B, C đúng**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **B, C đúng**."},{"id":277,"category":"Bảo hiểm xe cơ giới","question":"Trong bảo hiểm thiệt hại vật chất ô tô, những tài liệu nào sau đây được sử dụng để làm căn cứ xác định giá trị xe nhằm xác định số tiền bảo hiểm:","options":[{"key":"A","text":"Hóa đơn mua xe"},{"key":"B","text":"Hóa đơn thuế trước bạ"},{"key":"C","text":"Bảng giá xe để tính thuế của cơ quan thuế"},{"key":"D","text":"A, B đúng"},{"key":"E","text":"A, B, C đúng"}],"answer":"E","explanation":"Theo đáp án của đề cương, đáp án **E** là **A, B, C đúng**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng**."},{"id":278,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phát biểu nào dưới đây là đúng.","options":[{"key":"A","text":"Doanh nghiệp bảo hiểm là doanh nghiệp được thành lập, tổ chức và hoạt động theo quy định của Luật này và luật khác có liên quan để kinh doanh bảo hiểm, kinh doanh tái bảo hiểm, nhượng tái bảo hiểm. Doanh nghiệp bảo hiểm bao gồm doanh nghiệp bảo hiểm nhân thọ, doanh nghiệp bảo hiểm phi nhân thọ, doanh nghiệp bảo hiểm sức khỏe."},{"key":"B","text":"Hoạt động đại lý bảo hiểm là việc cung cấp thông tin, tư vấn cho bên mua bảo hiểm về sản phẩm bảo hiểm, điều kiện bảo hiểm, mức phí bảo hiểm, doanh nghiệp bảo hiểm, và các công việc liên quan đến việc đàm phán, thu xếp và thực hiện hợp đồng bảo hiểm theo yêu cầu của bên mua bảo hiểm."},{"key":"C","text":"A, B sai."}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Doanh nghiệp bảo hiểm là doanh nghiệp được thành lập, tổ chức và hoạt động theo quy định của Luật này và luật khác có liên quan để kinh doanh bảo hiểm, kinh doanh tái bảo hiểm, nhượng tái bảo hiểm. Doanh nghiệp bảo hiểm bao gồm doanh nghiệp bảo hiểm nhân thọ, doanh nghiệp bảo hiểm phi nhân thọ, doanh nghiệp bảo hiểm sức khỏe.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Doanh nghiệp bảo hiểm là doanh nghiệp được thành lập, tổ chức và hoạt động theo quy định…**."},{"id":279,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, thời hạn nộp hồ sơ yêu cầu bồi thường, trả tiền bảo hiểm kể từ ngày xảy ra sự kiện bảo hiểm theo hợp đồng bảo hiểm là:","options":[{"key":"A","text":"6 tháng (thời gian xảy ra sự kiện bắt khả kháng hoặc trở ngại khách quan không tính vào thời hạn nộp hồ sơ yêu cầu bồi thường, trả tiền bảo hiểm)."},{"key":"B","text":"1 năm (thời gian xảy ra sự kiện bất khả kháng hoặc trở ngại khách quan không tính vào thời hạn nộp hồ sơ yêu cầu bồi thường, trả tiền bảo hiểm)."},{"key":"C","text":"2 năm (thời gian xảy ra sự kiện bất khả kháng hoặc trở ngại khách quan không tính vào thời hạn nộp hồ sơ yêu cầu bồi thường, trả tiền bảo hiểm)."},{"key":"D","text":"3 năm (thời gian xảy ra sự kiện bất khả kháng hoặc trở ngại khách quan không tính vào thời hạn nộp hồ sơ yêu cầu bồi thường, trả tiền bảo hiểm)."}],"answer":"B","explanation":"Khái niệm cần nhớ trong câu này là: **1 năm (thời gian xảy ra sự kiện bất khả kháng hoặc trở ngại khách quan không tính vào thời hạn nộp hồ sơ yêu cầu bồi thường, trả tiền bảo hiểm).**. Đáp án đúng là **B**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Chốt mốc **1 năm** và gắn với đúng điều kiện của câu."},{"id":280,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Hợp đồng bảo hiểm trách nhiệm nghề nghiệp (Professional Indemnity) thường áp dụng thời hạn bảo hiểm trên cơ sở:","options":[{"key":"A","text":"Khiếu nại được lập (Claim made basis)."},{"key":"B","text":"Tổn thất phát sinh (Occurrence basis)."},{"key":"C","text":"Kết hợp cơ sở sự kiện phát sinh (Occurrence basis) và khiếu nại phát sinh (Claim made basis)."},{"key":"D","text":"Phát sinh hành vi lỗi (Act or omission committed) của người được bảo hiểm."}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án **A** là **Khiếu nại được lập (Claim made basis).**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Khiếu nại được lập (Claim made basis).**."},{"id":281,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, doanh nghiệp kinh doanh bảo hiểm nước ngoài không được phép thành lập tại Việt Nam:","options":[{"key":"A","text":"Công ty TNHH bảo hiểm."},{"key":"B","text":"Công ty cổ phần bảo hiểm."},{"key":"C","text":"Chi nhánh doanh nghiệp bảo hiểm nhân thọ nước ngoài."},{"key":"D","text":"Chi nhánh doanh nghiệp bảo hiểm phi nhân thọ nước ngoài."}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án đúng là **B**: **Công ty cổ phần bảo hiểm.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Công ty cổ phần bảo hiểm.**."},{"id":282,"category":"Bảo hiểm con người","question":"Trong thời hạn bảo hiểm của hợp đồng bảo hiểm sức khỏe với quyền lợi bảo hiểm tai nạn, người được bảo hiểm không may bị tai nạn dẫn đến thương tật khi tham gia hoạt động nhảy dù. Trường hợp này, doanh nghiệp bảo hiểm sẽ chi trả cho người được bảo hiểm số tiền nào sau đây?","options":[{"key":"A","text":"Số tiền bảo hiểm theo tỷ lệ thương tật do tai nạn."},{"key":"B","text":"Chi phí y tế điều trị tai nạn."},{"key":"C","text":"Không chi trả."}],"answer":"C","explanation":"Theo đáp án của đề cương, đáp án **C** là **Không chi trả.**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Không chi trả.**."},{"id":283,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật kinh doanh bảo hiểm, phát biểu nào sau đây là đúng nhất về đối tượng bảo hiểm của hợp đồng bảo hiểm tài sản :","options":[{"key":"A","text":"Đối tượng bảo hiểm là tài sản theo quy định của Bộ luật Dân sự"},{"key":"B","text":"Đối tượng bảo hiểm là tài sản bao gồm bất động sản và động sản"},{"key":"C","text":"Đổi tượng bảo hiểm là trách nhiệm dân sự của người được bảo hiểm"}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Đối tượng bảo hiểm là tài sản theo quy định của Bộ luật Dân sự**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Đối tượng bảo hiểm là tài sản theo quy định của Bộ luật Dân sự**."},{"id":284,"category":"Luật Kinh doanh bảo hiểm","question":"Trong quá trình thực hiện hợp đồng bảo hiểm, bên mua bảo hiểm có nghĩa vụ:","options":[{"key":"A","text":"Thông báo cho doanh nghiệp bảo hiểm những trường hợp có thể làm tăng rủi ro hoặc giảm rủi ro hoặc làm phát sinh thêm trách nhiệm của doanh nghiệp bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm."},{"key":"B","text":"Thông báo cho doanh nghiệp bảo hiểm về việc xảy ra sự kiện bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm."},{"key":"C","text":"Áp dụng các biện pháp để phòng, hạn chế tổn thất theo quy định của pháp luật."},{"key":"D","text":"A, B, C đúng."}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **A, B, C đúng.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng.**."},{"id":285,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, đại lý bảo hiểm có các nghĩa vụ nào sau đây:","options":[{"key":"A","text":"Chịu sự kiểm tra, giám sát của doanh nghiệp bảo hiểm"},{"key":"B","text":"Giữ bí mật thông tin khách hàng"},{"key":"C","text":"Có thể đem phí bảo hiểm đi đầu tư và trả một phần lãi cho doanh nghiệp bảo hiểm."},{"key":"D","text":"A, B đúng"}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **A, B đúng**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B đúng**."},{"id":286,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phát biểu nào sau đây đúng nhất về bảo hiểm sức khỏe?","options":[{"key":"A","text":"Bảo hiểm sức khỏe là bảo hiểm bắt buộc được quy định trong Luật Bảo hiểm y tế."},{"key":"B","text":"Bảo hiểm sức khỏe là bảo hiểm bắt buộc được quy định trong Luật Kinh doanh bảo hiểm."},{"key":"C","text":"Bảo hiểm sức khỏe là bảo hiểm không bắt buộc có số tiền bảo hiểm linh hoạt tùy theo nhu cầu của người tham gia bảo hiểm."}],"answer":"C","explanation":"Theo đáp án của đề cương, phương án **C** là nội dung đúng: **Bảo hiểm sức khỏe là bảo hiểm không bắt buộc có số tiền bảo hiểm linh hoạt tùy theo nhu cầu của người tham gia bảo hiểm.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Bảo hiểm sức khỏe là bảo hiểm không bắt buộc có số tiền bảo hiểm linh hoạt tùy theo nhu cầu…**."},{"id":287,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Trách nhiệm dân sự (TNDS) đối với bên thứ ba theo Đơn bảo hiểm mọi rủi ro xây dựng lắp đặt (CAR/EAR) của nhà tái bảo hiểm Munich Re được hiểu là:","options":[{"key":"A","text":"TNDS của chủ đầu tư công trình và nhà thầu thi công đối với bên thứ ba về người và tài sản."},{"key":"B","text":"TNDS của nhà thầu thi công này đối với nhà thầu thi công khác trên công trường."},{"key":"C","text":"TNDS của chủ đầu tư công trình đối với công nhân của các nhà thầu trên công trường."},{"key":"D","text":"TNDS của nhà thầu thi công đối với chủ đầu tư công trình."}],"answer":"A","explanation":"Khái niệm cần nhớ trong câu này là: **TNDS của chủ đầu tư công trình và nhà thầu thi công đối với bên thứ ba về người và tài sản.**. Đáp án đúng là **A**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **TNDS của chủ đầu tư công trình và nhà thầu thi công đối với bên thứ ba về người và tài sản.**."},{"id":288,"category":"Kiến thức chung","question":"Nguyên tắc thể quyền không được áp dụng đối với loại hợp đồng bảo hiểm nào dưới đây:","options":[{"key":"A","text":"Bảo hiểm hàng hải."},{"key":"B","text":"Bảo hiểm mọi rủi ro tài sản."},{"key":"C","text":"Bảo hiểm trách nhiệm dân sự."},{"key":"D","text":"Bảo hiểm nhân thọ."}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **Bảo hiểm nhân thọ.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Bảo hiểm nhân thọ.**."},{"id":289,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phương án nào sau đây đúng.","options":[{"key":"A","text":"Đại lý bảo hiểm được hưởng hoa hồng đại lý bảo hiểm theo thỏa thuận trong hợp đồng đại lý bảo hiểm"},{"key":"B","text":"Đại lý bảo hiểm có quyền yêu cầu doanh nghiệp bảo hiểm hoàn trả tiền ký quỹ hoặc tài sản thế chấp theo thỏa thuận trong hợp đồng đại lý bảo hiểm"},{"key":"C","text":"Đại lý bảo hiểm là người đại diện cho bên mua bảo hiểm"},{"key":"D","text":"A, B đúng"}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **A, B đúng**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B đúng**."},{"id":290,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Máy móc trong quá trình lắp đặt, di chuyển hoặc thay đổi vị trí (bao gồm cả việc tháo dỡ và lắp đặt lại) có được bảo hiểm theo Quy tắc bảo hiểm \"Mọi rủi ro tài sản\" của Hiệp hội bảo hiểm Vương quốc Anh (ABI) không:","options":[{"key":"A","text":"Có."},{"key":"B","text":"Không."},{"key":"C","text":"Không, nếu nguyên nhân của thiệt hại có thể được quy là do những hoạt động lắp đặt, di chuyển hoặc thay đổi vị trí gây ra."}],"answer":"C","explanation":"Theo đáp án của đề cương, đáp án đúng là **C**: **Không, nếu nguyên nhân của thiệt hại có thể được quy là do những hoạt động lắp đặt, di chuyển hoặc thay đổi vị trí gây ra.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Không, nếu nguyên nhân của thiệt hại có thể được quy là do những hoạt động lắp đặt, di…**."},{"id":291,"category":"Luật Kinh doanh bảo hiểm","question":"Chọn phương án đúng nhất về đặc trưng pháp lý của hợp đồng bảo hiểm:","options":[{"key":"A","text":"Hợp đồng bảo hiểm là hợp đồng song vụ, theo đó mỗi bên trong hợp đồng đều có nghĩa vụ đối với nhau."},{"key":"B","text":"Hợp đồng bảo hiểm là hợp đồng theo mẫu do doanh nghiệp bảo hiểm đưa ra."},{"key":"C","text":"Hợp đồng bảo hiểm là sự thoả thuận giữa bên mua bảo hiểm và doanh nghiệp bảo hiểm, theo đó bên mua bảo hiểm phải đóng phí bảo hiểm, doanh nghiệp bảo hiểm phải bồi thường, trả tiền bảo hiểm theo thỏa thuận trong hợp đồng."},{"key":"D","text":"A, C đúng."},{"key":"E","text":"A, B, C đúng."}],"answer":"E","explanation":"Theo đáp án của đề cương, phương án **E** là nội dung đúng: **A, B, C đúng.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng.**."},{"id":292,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Trong bảo hiểm tài sản, trường hợp áp dụng mức miễn thường có khấu trừ, nếu giá trị tổn thất lớn hơn mức khấu trừ thì:","options":[{"key":"A","text":"Sổ tiền bồi thường bằng giá trị tổn thất."},{"key":"B","text":"Số tiền bồi thường bằng giá trị tổn thất trừ đi mức miễn thường."}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án **B** là **Số tiền bồi thường bằng giá trị tổn thất trừ đi mức miễn thường.**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Số tiền bồi thường bằng giá trị tổn thất trừ đi mức miễn thường.**."},{"id":293,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phát biểu nào sau đây đúng nhất:","options":[{"key":"A","text":"Doanh nghiệp bảo hiểm nhân thọ được phép kinh doanh bảo hiểm sức khỏe"},{"key":"B","text":"Doanh nghiệp bảo hiểm phi nhân thọ không được phép kinh doanh bảo hiểm nhân thọ và bảo hiểm sức khỏe trừ các sản phẩm bảo hiểm cho rủi ro tử vong có thời hạn từ 1 năm trở xuống và các sản phẩm bảo"},{"key":"C","text":"A, B đúng."}],"answer":"C","explanation":"Theo đáp án của đề cương, phương án **C** là nội dung đúng: **A, B đúng.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B đúng.**."},{"id":294,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, trường hợp bên mua bảo hiểm có hành vi lừa dối khi giao kết hợp đồng bảo hiểm (trừ trường hợp bên mua bảo hiểm vi phạm nghĩa vụ cung cấp thông tin) thì:","options":[{"key":"A","text":"Hợp đồng bảo hiểm vô hiệu. Doanh nghiệp bảo hiểm và bên mua bảo hiểm hoàn trả cho nhau những gì đã nhận. Bên có lỗi gây thiệt hại phải bồi thường."},{"key":"B","text":"Doanh nghiệp bảo hiểm có quyền đơn phương chấm dứt thực hiện hợp đồng bảo hiểm và thu phí đến thời điểm phát hiện ra hành vi lừa dối của bên mua bảo hiểm."},{"key":"C","text":"Doanh nghiệp bảo hiểm có quyền hủy bỏ hợp đồng bảo hiểm."},{"key":"D","text":"A, B, C đúng."}],"answer":"D","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **D**: **A, B, C đúng.**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng.**."},{"id":295,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, doanh nghiệp bảo hiểm có trách nhiệm cung cấp đầy đủ, chính xác cho bên mua bảo hiểm các thông tin liên quan đến:","options":[{"key":"A","text":"Hợp đồng bảo hiểm."},{"key":"B","text":"Đối tượng bảo hiểm."},{"key":"C","text":"A, B đúng."}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Hợp đồng bảo hiểm.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Hợp đồng bảo hiểm.**."},{"id":296,"category":"Bảo hiểm xe cơ giới","question":"Theo đơn Bảo hiểm trách nhiệm dân sự của chủ xe cơ giới đối với hàng hóa vận chuyển trên xe, doanh nghiệp bảo hiểm có bồi thường cho tổn thất của hàng hóa trên xe bị mốc trong quá trình vận chuyển không:","options":[{"key":"A","text":"Có"},{"key":"B","text":"Không"}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án đúng là **B**: **Không**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Không**."},{"id":297,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Theo đơn bảo hiểm mọi rủi ro xây dựng (CAR) của nhà tái bảo hiểm Munich Re, tổn thất gián tiếp có nguyên nhân do khuyết tật của vật liệu, tay nghề kém có thuộc trách nhiệm bảo hiểm không:","options":[{"key":"A","text":"Có"},{"key":"B","text":"Không"}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Có**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Có**."},{"id":298,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, chọn phương án đúng về sản phẩm bảo hiểm mà doanh nghiệp bảo hiểm phi nhân thọ được phép triển khai:","options":[{"key":"A","text":"Sản phẩm thuộc loại hình bảo hiểm sức khỏe có thời hạn từ 01 năm trở xuống."},{"key":"B","text":"Sản phẩm bảo hiểm cho rủi ro tử vong có thời hạn từ 01 năm trở xuống."},{"key":"C","text":"Mọi sản phẩm bảo hiểm sức khỏe,"},{"key":"D","text":"A, B đúng."}],"answer":"D","explanation":"Theo đáp án của đề cương, phương án **D** là nội dung đúng: **A, B đúng.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B đúng.**."},{"id":299,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phát biểu nào sau đây sai về bảo hiểm bắt buộc:","options":[{"key":"A","text":"Bảo hiểm bắt buộc là sản phẩm bảo hiểm nhằm mục đích bảo vệ lợi ích công cộng, môi trường và an toàn xã hội."},{"key":"B","text":"Chính phủ quy định chi tiết về điều kiện bảo hiểm, mức phí bảo hiểm, số tiền bảo hiểm tối thiểu đối với bảo hiểm bắt buộc"},{"key":"C","text":"Chính phủ quy định chi tiết về điều kiện bảo hiểm, mức phí bảo hiểm, số tiền bảo hiểm tối đa đối với bảo hiểm bắt buộc"}],"answer":"C","explanation":"Đây là câu hỏi tìm **phương án ngoại lệ/sai**. Theo đáp án của đề cương, phương án **C** là nội dung không phù hợp: **Chính phủ quy định chi tiết về điều kiện bảo hiểm, mức phí bảo hiểm, số tiền bảo hiểm tối đa đối với bảo hiểm bắt buộc**. Khi làm bài, cần chú ý từ khóa phủ định như **“sai”, “không”, “ngoại trừ”**.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":300,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, đối với bảo hiểm tài sản, chi phí để xác định mức độ thiệt hại do đối tượng nào sau đây chi trả:","options":[{"key":"A","text":"Doanh nghiệp bảo hiểm"},{"key":"B","text":"Bên mua bảo hiểm"},{"key":"C","text":"A, B đúng"},{"key":"D","text":"A, B sai"}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án **A** là **Doanh nghiệp bảo hiểm**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Doanh nghiệp bảo hiểm**."},{"id":301,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, trong hợp đồng bảo hiểm tài sản, trừ trường hợp có thỏa thuận khác trong hợp đồng bảo hiểm, cơ sở để xác định số tiền bồi thường mà doanh nghiệp bảo hiểm phải trả cho người được bảo hiểm là:","options":[{"key":"A","text":"Giá thị trường của tài sản được bảo hiểm tại thời điểm, nơi xảy ra tổn thất, mức độ thiệt hại thực tế."},{"key":"B","text":"Giá thị trường của tài sản được bảo hiểm tại thời điểm tham gia bảo hiểm và mức độ thiệt hại thực tế."},{"key":"C","text":"Giá trị sổ sách của tài sản được bảo hiểm tại thời điểm tham gia bảo hiểm và mức độ thiệt hại thực tế."},{"key":"D","text":"Giá trị thỏa thuận."}],"answer":"A","explanation":"Khái niệm cần nhớ trong câu này là: **Giá thị trường của tài sản được bảo hiểm tại thời điểm, nơi xảy ra tổn thất, mức độ thiệt hại thực tế.**. Đáp án đúng là **A**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Giá thị trường của tài sản được bảo hiểm tại thời điểm, nơi xảy ra tổn thất, mức độ thiệt…**."},{"id":302,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phát biểu nào sau đây đúng nhất:","options":[{"key":"A","text":"Tổ chức có quyền đồng thời làm đại lý bảo hiểm cho mọi doanh nghiệp bảo hiểm"},{"key":"B","text":"Cá nhân có quyền đồng thời làm đại lý cho mọi doanh nghiệp bảo hiểm"},{"key":"C","text":"Cá nhân không được đồng thời làm đại lý bảo hiểm cho doanh nghiệp bảo hiểm khác hoạt động trong cùng loại hình bảo hiểm với doanh nghiệp bảo hiểm mà cá nhân đó đang làm đại lý"},{"key":"D","text":"A, B đúng"}],"answer":"C","explanation":"Theo đáp án của đề cương, phương án **C** là nội dung đúng: **Cá nhân không được đồng thời làm đại lý bảo hiểm cho doanh nghiệp bảo hiểm khác hoạt động trong cùng loại hình bảo hiểm với doanh nghiệp bảo hiểm mà cá nhân đó đang làm đại lý**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Cá nhân không được đồng thời làm đại lý bảo hiểm cho doanh nghiệp bảo hiểm khác hoạt động…**."},{"id":303,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, đáp án nào dưới đây đúng nhất khi điền vào chỗ trong câu sau: \"Sự kiện bảo hiểm là do các bên thỏa thuận hoặc pháp luật quy định mà khi sự kiện đó xảy ra thì doanh nghiệp bảo hiểm phải bồi thường, trả tiền bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm.","options":[{"key":"A","text":"Sự kiện"},{"key":"B","text":"Sự kiện khách quan"},{"key":"C","text":"Sự kiện chủ quan"},{"key":"D","text":"Sự kiện khách quan hoặc chủ quan"}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án đúng là **B**: **Sự kiện khách quan**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Sự kiện khách quan**."},{"id":304,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, đối tượng của hợp đồng bảo hiểm sức khỏe là:","options":[{"key":"A","text":"Sức khoẻ con người."},{"key":"B","text":"Tuổi thọ, tính mạng, sức khỏe và tai nạn con người."},{"key":"C","text":"Sức khỏe và tai nạn con người."},{"key":"D","text":"Tính mạng và trách nhiệm dân sự của người được bảo hiểm."}],"answer":"A","explanation":"Khái niệm cần nhớ trong câu này là: **Sức khoẻ con người.**. Đáp án đúng là **A**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Sức khoẻ con người.**."},{"id":305,"category":"Bảo hiểm con người","question":"Khi tham gia bảo hiểm sức khỏe, trường hợp người được bảo hiểm bị tai nạn thì có thể được nhận quyền lợi bảo hiểm nào sau đây?","options":[{"key":"A","text":"Tử vong do tai nạn."},{"key":"B","text":"Thương tật vĩnh viễn do tai nạn."},{"key":"C","text":"Chi phí y tế do tai nạn."},{"key":"D","text":"A, B, C đúng."}],"answer":"D","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **D**: **A, B, C đúng.**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng.**."},{"id":306,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, bảo hiểm bắt buộc không bao gồm:","options":[{"key":"A","text":"Bảo hiểm cháy, nổ bắt buộc"},{"key":"B","text":"Bảo hiểm Hỏa hoạn và các rủi ro đặc biệt"},{"key":"C","text":"Bảo hiểm bắt buộc trách nhiệm dân sự của chủ xe cơ giới"},{"key":"D","text":"Bảo hiểm bắt buộc trong hoạt động đầu tư xây dựng"}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án đúng là **B**: **Bảo hiểm Hỏa hoạn và các rủi ro đặc biệt**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Bảo hiểm Hỏa hoạn và các rủi ro đặc biệt**."},{"id":307,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, một trong các đối tượng bảo hiểm của hợp đồng bảo hiểm tài sản là:","options":[{"key":"A","text":"Trách nhiệm dân sự của người được bảo hiểm"},{"key":"B","text":"Quyền tài sản"},{"key":"C","text":"Thiệt hại do gián đoạn kinh doanh"},{"key":"D","text":"B, C đúng"}],"answer":"B","explanation":"Khái niệm cần nhớ trong câu này là: **Quyền tài sản**. Đáp án đúng là **B**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Quyền tài sản**."},{"id":308,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Theo đơn bảo hiểm “Gián đoạn kinh doanh\" của Hiệp hội bảo hiểm Vương quốc Anh (ABI), hạn mức bồi thường đối với chi phí hoạt động gia tăng được bảo hiểm thuộc hạng mục Lợi nhuận gộp để khắc phục bớt sự suy giảm doanh thu do thiệt hại gây ra là:","options":[{"key":"A","text":"Không giới hạn."},{"key":"B","text":"Số tiền được tính bằng cách lấy tỷ lệ Lợi nhuận gộp nhân với số doanh thu khôi phục lại được nhờ các chi phí hoạt động gia tăng đó."}],"answer":"B","explanation":"Khái niệm cần nhớ trong câu này là: **Số tiền được tính bằng cách lấy tỷ lệ Lợi nhuận gộp nhân với số doanh thu khôi phục lại được nhờ các chi phí hoạt động gia tăng đó.**. Đáp án đúng là **B**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Số tiền được tính bằng cách lấy tỷ lệ Lợi nhuận gộp nhân với số doanh thu khôi phục lại…**."},{"id":309,"category":"Luật Kinh doanh bảo hiểm","question":"Trường hợp người được bảo hiểm không thực hiện các biện pháp bảo đảm an toàn cho đối tượng bảo hiểm thì doanh nghiệp bảo hiểm có quyền:","options":[{"key":"A","text":"Đơn phương chấm dứt thực hiện hợp đồng bảo hiểm ngay tại thời điểm phát hiện thấy tăng nguy cơ rủi ro đối với đối tượng bảo hiểm."},{"key":"B","text":"Tăng phí bảo hiểm ngay tại thời điểm phát hiện thấy tăng nguy cơ rủi ro đối với đối tượng bảo hiểm."},{"key":"C","text":"Ấn định một thời hạn để người được bảo hiểm thực hiện các biện pháp đó. Nếu hết thời hạn này mà các biện pháp bảo đảm an toàn vẫn không được thực hiện thì doanh nghiệp bảo hiểm có quyền tăng phí bảo hiểm hoặc đơn phương chấm dứt thực hiện hợp đồng bảo hiểm."},{"key":"D","text":"A, B đúng."}],"answer":"C","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **C**: **Ấn định một thời hạn để người được bảo hiểm thực hiện các biện pháp đó. Nếu hết thời hạn này mà các biện pháp bảo đảm an toàn vẫn không được thực hiện thì doanh nghiệp bảo hiểm có quyền tăng phí bảo hiểm hoặc đơn phương chấm dứt thực hiện hợp đồng bảo hiểm.**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Ấn định một thời hạn để người được bảo hiểm thực hiện các biện pháp đó. Nếu hết thời hạn…**."},{"id":310,"category":"Kiến thức chung","question":"Nguyên tắc thế quyền được hiểu thế nào là đúng nhất:","options":[{"key":"A","text":"Người được bảo hiểm có trách nhiệm chuyển giao cho doanh nghiệp bảo hiểm quyền yêu cầu người thứ ba có hành vi gây thiệt hại chịu trách nhiệm bồi hoàn trong phạm vi số tiền bồi thường bảo hiểm."},{"key":"B","text":"Doanh nghiệp bảo hiểm đòi bồi hoàn bên thứ ba trong phạm vi số tiền đã bồi thường cho người được bảo hiểm."},{"key":"C","text":"Nguyên tắc này không áp dụng đối với hợp đồng bảo hiểm nhân thọ và hợp đồng bảo hiểm sức khỏe."},{"key":"D","text":"A, B đúng."},{"key":"E","text":"A, B, C đúng."}],"answer":"E","explanation":"Theo đáp án của đề cương, đáp án đúng là **E**: **A, B, C đúng.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng.**."},{"id":311,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Máy móc thiết bị chủ thầu được bảo hiểm theo quy tắc bảo hiểm Máy móc thiết bị chủ thầu CPM của nhà tái bảo hiểm Munich Re. Trường hợp nào dưới đây không thuộc phạm vi bảo hiểm?","options":[{"key":"A","text":"Bảo hiểm tổn thất máy móc, thiết bị trong quá trình thực hiện công việc trên tất cả các công trình dự án."},{"key":"B","text":"Bảo hiểm tổn thất máy móc, thiết bị được tập kết trong kho bãi của chủ thầu."},{"key":"C","text":"Bảo hiểm tổn thất máy móc, thiết bị trong quá trình lưu hành trên công lộ."},{"key":"D","text":"B, C đúng."}],"answer":"C","explanation":"Đây là câu hỏi tìm **phương án ngoại lệ/sai**. Theo đáp án của đề cương, phương án **C** là nội dung không phù hợp: **Bảo hiểm tổn thất máy móc, thiết bị trong quá trình lưu hành trên công lộ.**. Khi làm bài, cần chú ý từ khóa phủ định như **“sai”, “không”, “ngoại trừ”**.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":312,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, người có quyền chiếm hữu đối với tài sản thì có “Quyền lợi có thể được bảo hiểm” đối với tài sản đó:","options":[{"key":"A","text":"Đúng."},{"key":"B","text":"Sai."}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Đúng.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Đúng.**."},{"id":313,"category":"Bảo hiểm con người","question":"Người được bảo hiểm tham gia hợp đồng bảo hiểm sức khỏe với quyền lợi bảo hiểm tai nạn. Trong thời hạn bảo hiểm, người được bảo hiểm bị tai nạn khi tham gia các cuộc diễn tập, huấn luyện quân sự. Trường hợp này doanh nghiệp bảo hiểm có chi trả bảo hiểm cho người được bảo hiểm không?","options":[{"key":"A","text":"Có"},{"key":"B","text":"Không."}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án **B** là **Không.**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Không.**."},{"id":314,"category":"Bảo hiểm xe cơ giới","question":"Mức trách nhiệm bảo hiểm trách nhiệm dân sự của chủ xe cơ giới đối với hàng hóa trên xe là:","options":[{"key":"A","text":"Mức trách nhiệm bảo hiểm.vụ tổn thất."},{"key":"B","text":"Mức trách nhiệm bảo hiểm.mỗi và mọi vụ tổn thất."},{"key":"C","text":"Không có phương án nào đúng."}],"answer":"C","explanation":"Khái niệm cần nhớ trong câu này là: **Không có phương án nào đúng.**. Đáp án đúng là **C**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Không có phương án nào đúng.**."},{"id":315,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, doanh nghiệp bảo hiểm không có quyền đơn phương chấm dứt thực hiện hợp đồng bảo hiểm (đồng thời phải thông báo ngay bằng văn bản cho bên mua bảo hiểm) trong trường hợp nào dưới đây:","options":[{"key":"A","text":"Khi có sự thay đổi những yếu tố làm cơ sở để tính phí bảo hiểm dẫn đến tăng các rủi ro được bảo hiểm, doanh nghiệp bảo hiểm tính lại phí bảo hiểm cho thời gian còn lại của hợp đồng bảo hiểm nhưng bên mua bảo hiểm không chấp nhận."},{"key":"B","text":"Bên mua bảo hiểm không thực hiện các biện pháp bảo đảm an toàn cho đối tượng bảo hiểm trong thời hạn mà doanh nghiệp bảo hiểm đã ấn định để bên mua bảo hiểm thực hiện các biện pháp đó"},{"key":"C","text":"Bên mua bảo hiểm không đóng đủ phí bảo hiểm trong thời gian gia hạn đóng phí"},{"key":"D","text":"Bên mua bảo hiểm không đồng ý chuyển giao danh mục hợp đồng bảo hiểm theo quy định tại Luật Kinh doanh bảo hiểm."}],"answer":"A","explanation":"Đây là câu hỏi tìm **phương án ngoại lệ/sai**. Theo đáp án của đề cương, phương án **A** là nội dung không phù hợp: **Khi có sự thay đổi những yếu tố làm cơ sở để tính phí bảo hiểm dẫn đến tăng các rủi ro được bảo hiểm, doanh nghiệp bảo hiểm tính lại phí bảo hiểm cho thời gian còn lại của hợp đồng bảo hiểm nhưng bên mua bảo hiểm không chấp nhận.**. Khi làm bài, cần chú ý từ khóa phủ định như **“sai”, “không”, “ngoại trừ”**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Khi có sự thay đổi những yếu tố làm cơ sở để tính phí bảo hiểm dẫn đến tăng các rủi ro được…**."},{"id":316,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phát biểu nào sau đây đúng nhất về \"Nguyên tắc thế quyền\" trong bảo hiểm tài sản:","options":[{"key":"A","text":"Người được bảo hiểm có trách nhiệm chuyển giao cho doanh nghiệp bảo hiểm quyền yêu cầu người thứ ba có hành vi gây thiệt hại chịu trách nhiệm bồi hoàn trong phạm vi số tiền bồi thường bảo hiểm."},{"key":"B","text":"Người được bảo hiểm có trách nhiệm chuyển giao cho doanh nghiệp bảo hiểm quyền yêu cầu người thứ ba có hành vi gây thiệt hại chịu trách nhiệm bồi hoàn."},{"key":"C","text":"Người được bảo hiểm có trách nhiệm chuyển giao cho doanh nghiệp bảo hiểm quyền yêu cầu người thứ ba bồi hoàn trong phạm vi số tiền bồi thường bảo hiểm."},{"key":"D","text":"Người được bảo hiểm có trách nhiệm chuyển giao cho doanh nghiệp bảo hiểm quyền yêu cầu người thứ ba bồi hoàn."}],"answer":"A","explanation":"Theo đáp án của đề cương, phương án **A** là nội dung đúng: **Người được bảo hiểm có trách nhiệm chuyển giao cho doanh nghiệp bảo hiểm quyền yêu cầu người thứ ba có hành vi gây thiệt hại chịu trách nhiệm bồi hoàn trong phạm vi số tiền bồi thường bảo hiểm.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Người được bảo hiểm có trách nhiệm chuyển giao cho doanh nghiệp bảo hiểm quyền yêu cầu…**."},{"id":317,"category":"Kiến thức chung","question":"Thời điểm nào là thời điểm xác định giá trị bảo hiểm:","options":[{"key":"A","text":"Khi gửi giấy yêu cầu bảo hiểm."},{"key":"B","text":"Khi giao kết hợp đồng bảo hiểm."},{"key":"C","text":"Khi tiến hành khắc phục tổn thất"},{"key":"D","text":"A, B, C đúng"}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án đúng là **B**: **Khi giao kết hợp đồng bảo hiểm.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Khi giao kết hợp đồng bảo hiểm.**."},{"id":318,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Công ty sản xuất thức ăn gia súc tham gia bảo hiểm trách nhiệm sản phẩm. Trong thời hạn bảo hiểm có 4 vụ khiếu nại của khách hàng đối với người được bảo hiểm. Khiếu nại nào sau đây có thể được doanh nghiệp bảo hiểm xem xét bồi thường theo hợp đồng bảo hiểm trách nhiệm sản phẩm:","options":[{"key":"A","text":"Gia súc không chịu ăn thức ăn của công ty sản xuất."},{"key":"B","text":"Gia súc không tăng cân như thông báo của công ty sản xuất."},{"key":"C","text":"Hàm lượng protein trong bao thức ăn thấp hơn rất nhiều so với công thức được ghi trên bao bì, tuy nhiên không gây bệnh tật cho gia súc."},{"key":"D","text":"Gia súc bị chết do trong bao thức ăn có sót lại một số mảnh phôi kim loại bén rơi ra từ máy trộn thức ăn của công ty sản xuất."}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án **D** là **Gia súc bị chết do trong bao thức ăn có sót lại một số mảnh phôi kim loại bén rơi ra từ máy trộn thức ăn của công ty sản xuất.**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Gia súc bị chết do trong bao thức ăn có sót lại một số mảnh phôi kim loại bén rơi ra từ máy…**."},{"id":319,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Thiệt hại tài chính do ngừng công việc, trì hoãn hoặc mất thị trường do tác động của một rủi ro được bảo hiểm có thuộc phạm vi bảo hiểm theo Quy tắc bảo hiểm “Mọi rủi ro tài sản” của Hiệp hội bảo hiểm Vương quốc Anh (ABI) không:","options":[{"key":"A","text":"Có."},{"key":"B","text":"Không."}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án đúng là **B**: **Không.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Không.**."},{"id":320,"category":"Bảo hiểm xe cơ giới","question":"Theo đơn Bảo hiểm trách nhiệm dân sự của chủ xe cơ giới đối với hàng hóa trên xe: Trong quá trình vận chuyển, do chủ xe cơ giới (lái xe) che chắn không cẩn thận nên khi mưa đã làm hàng bị tổn thất. Trường hợp này, doanh nghiệp bảo hiểm có bồi thường cho người được bảo hiểm không?","options":[{"key":"A","text":"Có."},{"key":"B","text":"Không."}],"answer":"B","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **B**: **Không.**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Không.**."},{"id":321,"category":"Kiến thức chung","question":"Chọn phương án đúng nhất về đồng bảo hiểm:","options":[{"key":"A","text":"Nhiều doanh nghiệp bảo hiểm cùng bảo hiểm cho một đối tượng bảo hiểm và thể hiện trên một hợp đồng bảo hiểm."},{"key":"B","text":"Một doanh nghiệp bảo hiểm đứng tên trên hợp đồng bảo hiểm, sau đó doanh nghiệp bảo hiểm này ký hợp đồng bảo hiểm với các doanh nghiệp bảo hiểm khác."},{"key":"C","text":"Các doanh nghiệp bảo hiểm được hưởng phí bảo hiểm và có trách nhiệm bồi thường theo tỷ lệ tham gia đồng bảo hiểm đã thỏa thuận trong hợp đồng bảo hiểm."},{"key":"D","text":"A, C đúng."},{"key":"E","text":"A, B, C đúng."}],"answer":"D","explanation":"Theo đáp án của đề cương, phương án **D** là nội dung đúng: **A, C đúng.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, C đúng.**."},{"id":322,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phát biểu nào dưới đây sai:","options":[{"key":"A","text":"Luật kinh doanh bảo hiểm quy định về tổ chức và hoạt động kinh doanh bảo hiểm; quyền và nghĩa vụ của tổ chức, cá nhân tham gia bảo hiểm; quản lý nhà nước về hoạt động kinh doanh bảo hiểm."},{"key":"B","text":"Nhà nước bảo đảm quyền, lợi ích hợp pháp của các tổ chức, cá nhân tham gia bảo hiểm và các tổ chức hoạt động kinh doanh bảo hiểm."},{"key":"C","text":"Tổ chức, cá nhân tại Việt Nam có nhu cầu tham gia bảo hiểm có thể tham gia bảo hiểm tại bất kỳ doanh nghiệp bảo hiểm nào hoạt động tại Việt Nam hoặc nước ngoài."}],"answer":"C","explanation":"Đây là câu hỏi tìm **phương án ngoại lệ/sai**. Theo đáp án của đề cương, phương án **C** là nội dung không phù hợp: **Tổ chức, cá nhân tại Việt Nam có nhu cầu tham gia bảo hiểm có thể tham gia bảo hiểm tại bất kỳ doanh nghiệp bảo hiểm nào hoạt động tại Việt Nam hoặc nước ngoài.**. Khi làm bài, cần chú ý từ khóa phủ định như **“sai”, “không”, “ngoại trừ”**.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":323,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, nguyên tắc thế quyền không được áp dụng trong loại hợp đồng bảo hiểm nào sau đây:","options":[{"key":"A","text":"Bảo hiểm tài sản."},{"key":"B","text":"Bảo hiểm thiệt hại."},{"key":"C","text":"Bảo hiểm trách nhiệm."},{"key":"D","text":"Bảo hiểm nhân thọ."}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **Bảo hiểm nhân thọ.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Bảo hiểm nhân thọ.**."},{"id":324,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, chọn phương án đúng nhất về nghĩa vụ của doanh nghiệp bảo hiểm trong giao kết và thực hiện hợp đồng bảo hiểm:","options":[{"key":"A","text":"Giải thích rõ ràng, đầy đủ cho bên mua bảo hiểm về quyền lợi bảo hiểm, điều khoản loại trừ trách nhiệm bảo hiểm, quyền và nghĩa vụ của bên mua bảo hiểm khi giao kết hợp đồng bảo hiểm."},{"key":"B","text":"Yêu cầu bên mua bảo hiểm cung cấp đầy đủ thông tin liên quan đến giao kết hợp đồng"},{"key":"C","text":"Phối hợp với bên mua bảo hiểm để giải quyết yêu cầu của người thứ ba đòi bồi thường về những thiệt hại thuộc trách nhiệm bảo hiểm khi xảy ra sự kiện bảo hiểm."},{"key":"D","text":"A, B đúng."},{"key":"E","text":"A, C đúng."}],"answer":"E","explanation":"Theo đáp án của đề cương, phương án **E** là nội dung đúng: **A, C đúng.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, C đúng.**."},{"id":325,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, nội dung nào sau đây không thuộc quyền của đại lý bảo hiểm:","options":[{"key":"A","text":"Thay mặt bên mua bảo hiểm ký hợp đồng bảo hiểm"},{"key":"B","text":"Được cung cấp thông tin và điều kiện cần thiết để thực hiện hợp đồng đại lý bảo hiểm"},{"key":"C","text":"Hưởng hoa hồng đại lý bảo hiểm, thưởng, hỗ trợ đại lý bảo hiểm và các quyền lợi khác từ hoạt động đại lý bảo hiểm theo thỏa thuận trong hợp đồng đại lý bảo hiểm"},{"key":"D","text":"Yêu cầu doanh nghiệp bảo hiểm hoàn trả tiền ký quỹ hoặc tài sản thế chấp theo thỏa thuận trong hợp đồng đại lý bảo hiểm"}],"answer":"A","explanation":"Đây là câu hỏi tìm **phương án ngoại lệ/sai**. Theo đáp án của đề cương, phương án **A** là nội dung không phù hợp: **Thay mặt bên mua bảo hiểm ký hợp đồng bảo hiểm**. Khi làm bài, cần chú ý từ khóa phủ định như **“sai”, “không”, “ngoại trừ”**.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":326,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, số tiền mà bên mua bảo hiểm và doanh nghiệp bảo hiểm thỏa thuận trong hợp đồng bảo hiểm để bảo hiểm cho tài sản và thiệt hại trên cơ sở yêu cầu của bên mua bảo hiểm theo quy định của pháp luật được gọi là:","options":[{"key":"A","text":"Phí bảo hiểm"},{"key":"B","text":"Số tiền bảo hiểm"},{"key":"C","text":"Giá trị bảo hiểm"},{"key":"D","text":"Số tiền bồi thường"}],"answer":"B","explanation":"Khái niệm cần nhớ trong câu này là: **Số tiền bảo hiểm**. Đáp án đúng là **B**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Số tiền bảo hiểm**."},{"id":327,"category":"Bảo hiểm xe cơ giới","question":"Xe ô tô tham gia bảo hiểm thiệt hại vật chất (không tham gia điều khoản thay thế mới). Chọn phương án đúng nhất trong trường hợp xe bị tổn thất bộ phận thì chi phí khắc phục được hiểu là:","options":[{"key":"A","text":"Chi phí sửa chữa, thay thế (đã trừ khấu hao)."},{"key":"B","text":"Chi phí sửa chữa, thay thế và chi phí hợp lý khác như: bảo vệ hiện trường, cứu hộ. di chuyển tài sản…"},{"key":"C","text":"Chi phí sửa chữa, thay thế (đã trừ khấu hao) và chi phí hợp lý khác như: bảo vệ hiện trường, cứu hộ. di chuyển tài sản…"}],"answer":"C","explanation":"Theo đáp án của đề cương, phương án **C** là nội dung đúng: **Chi phí sửa chữa, thay thế (đã trừ khấu hao) và chi phí hợp lý khác như: bảo vệ hiện trường, cứu hộ. di chuyển tài sản…**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Chi phí sửa chữa, thay thế (đã trừ khấu hao) và chi phí hợp lý khác như: bảo vệ hiện…**."},{"id":328,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, đại lý bảo hiểm không được thực hiện hành vi nào sau đây:","options":[{"key":"A","text":"Tranh giành khách hàng dưới các hình thức ngăn cản, lôi kéo, mua chuộc, đe dọa nhân viên hoặc khách hàng của doanh nghiệp bảo hiểm khác."},{"key":"B","text":"Thông tin, quảng cáo sai sự thật về nội dung, phạm vi hoạt động, điều kiện bảo hiểm, làm tổn hại đến quyền, lợi ích hợp pháp của bên mua bảo hiểm."},{"key":"C","text":"Xúi giục khách hàng hủy bỏ hợp đồng bảo hiểm đang có hiệu lực dưới mọi hình thức."},{"key":"D","text":"A, B, C đúng."}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **A, B, C đúng.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng.**."},{"id":329,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Mục đích của việc thỏa thuận giới hạn địa lý. lãnh thổ (Geographical. Territorial Limits) trong hợp đồng bảo hiểm trách nhiệm công cộng là:","options":[{"key":"A","text":"Doanh nghiệp bảo hiểm chỉ xem xét giải quyết bồi thường đối với những hành vi gây thiệt hại của người được bảo hiểm và khiếu nại của người thứ ba phải được lập trong phạm vi lãnh thổ. địa lý đã thỏa thuận trong hợp đồng bảo hiểm."},{"key":"B","text":"Doanh nghiệp bảo hiểm chỉ xem xét giải quyết bồi thường đối với những khiếu nại được lập của người thứ ba trong phạm vi lãnh thổ. địa lý đã thỏa thuận trong hợp đồng bảo hiểm."},{"key":"C","text":"Doanh nghiệp bảo hiểm chỉ xem xét giải quyết bồi thường đối với những hành vi gây thiệt hại của người được bảo hiểm phát sinh trong phạm vi lãnh thổ.địa lý đã thỏa thuận trong hợp đồng bảo hiểm."},{"key":"D","text":"Doanh nghiệp bảo hiểm chỉ xem xét giải quyết bồi thường đối với những khiếu nại được lập của người thứ ba theo luật và tập quán áp dụng trong phạm vi lãnh thổ. địa lý đã thỏa thuận trong hợp đồng bảo hiểm."}],"answer":"C","explanation":"Khái niệm cần nhớ trong câu này là: **Doanh nghiệp bảo hiểm chỉ xem xét giải quyết bồi thường đối với những hành vi gây thiệt hại của người được bảo hiểm phát sinh trong phạm vi lãnh thổ.địa lý đã thỏa thuận trong hợp đồng bảo hiểm.**. Đáp án đúng là **C**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Doanh nghiệp bảo hiểm chỉ xem xét giải quyết bồi thường đối với những hành vi gây thiệt hại…**."},{"id":330,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, đối với bảo hiểm tài sản,  trường hợp doanh nghiệp bảo hiểm và bên mua bảo hiểm không thoả thuận được về hình thức bồi thường thì việc bồi thường sẽ được thực hiện bằng:","options":[{"key":"A","text":"Sửa chữa tài sản bị thiệt hại"},{"key":"B","text":"Thay thế tài sản bị thiệt hại bằng tài sản khác"},{"key":"C","text":"Trả tiền bồi thường"},{"key":"D","text":"A, C đúng"}],"answer":"C","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **C**: **Trả tiền bồi thường**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Trả tiền bồi thường**."},{"id":331,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, đại lý bảo hiểm có quyền:","options":[{"key":"A","text":"Được hưởng hoa hồng đại lý bảo hiểm theo thỏa thuận tại hợp đồng đại lý bảo hiểm"},{"key":"B","text":"Tư vấn cho khách hàng huỷ bỏ hợp đồng bảo hiểm đang có hiệu lực để ký hợp đồng bảo hiểm mới"},{"key":"C","text":"Ngăn cản bên mua bảo hiểm cung cấp các thông tin liên quan đến hợp đồng bảo hiểm"},{"key":"D","text":"Mua chuộc khách hàng của doanh nghiệp bảo hiểm khác"}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Được hưởng hoa hồng đại lý bảo hiểm theo thỏa thuận tại hợp đồng đại lý bảo hiểm**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Được hưởng hoa hồng đại lý bảo hiểm theo thỏa thuận tại hợp đồng đại lý bảo hiểm**."},{"id":332,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, đại lý bảo hiểm được thực hiện các hoạt động nào sau đây theo ủy quyền của doanh nghiệp bảo hiểm:","options":[{"key":"A","text":"Tư vấn sản phẩm bảo hiểm; giới thiệu sản phẩm bảo hiểm; chào bán sản phẩm bảo hiểm; thu xếp việc giao kết hợp đồng bảo hiểm."},{"key":"B","text":"Thay mặt doanh nghiệp bảo hiểm ký kết hợp đồng với bên mua bảo hiểm."},{"key":"C","text":"A, B đúng."}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Tư vấn sản phẩm bảo hiểm; giới thiệu sản phẩm bảo hiểm; chào bán sản phẩm bảo hiểm; thu xếp việc giao kết hợp đồng bảo hiểm.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Tư vấn sản phẩm bảo hiểm; giới thiệu sản phẩm bảo hiểm; chào bán sản phẩm bảo hiểm; thu xếp…**."},{"id":333,"category":"Kiến thức chung","question":"Tiêu chí nào sau đây là tiêu chí đánh giá rủi ro:","options":[{"key":"A","text":"Mức độ rủi ro và kiểm soát rủi ro."},{"key":"B","text":"Mức độ rủi ro và nguy cơ rủi ro."},{"key":"C","text":"Nguy cơ rủi ro và kiểm soát rủi ro."},{"key":"D","text":"A, B, C đúng."}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án đúng là **B**: **Mức độ rủi ro và nguy cơ rủi ro.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Mức độ rủi ro và nguy cơ rủi ro.**."},{"id":334,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Giá trị cần phải bảo hiểm đối với bảo hiểm các công trình dân dụng đã hoàn thành (CECR) theo quy tắc bảo hiểm của nhà tái bảo hiểm Munich Re là:","options":[{"key":"A","text":"Giá trị sổ sách."},{"key":"B","text":"Giá trị thực tế tại thời điểm tổn thất."},{"key":"C","text":"Giá trị thay thế mới."},{"key":"D","text":"A, B, C đúng."}],"answer":"C","explanation":"Khái niệm cần nhớ trong câu này là: **Giá trị thay thế mới.**. Đáp án đúng là **C**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Giá trị thay thế mới.**."},{"id":335,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, các loại hợp đồng bảo hiểm bao gồm:","options":[{"key":"A","text":"Hợp đồng bảo hiểm nhân thọ; Hợp đồng bảo hiểm sức khỏe; Hợp đồng bảo hiểm phi nhân thọ."},{"key":"B","text":"Hợp đồng bảo hiểm nhân thọ; Hợp đồng bảo hiểm sức khỏe; Hợp đồng bảo hiểm tài sản; Hợp đồng bảo hiểm thiệt hại; Hợp đồng bảo hiểm trách nhiệm."},{"key":"C","text":"Hợp đồng bảo hiểm chính; Hợp đồng bảo hiểm bổ trợ."}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án đúng là **B**: **Hợp đồng bảo hiểm nhân thọ; Hợp đồng bảo hiểm sức khỏe; Hợp đồng bảo hiểm tài sản; Hợp đồng bảo hiểm thiệt hại; Hợp đồng bảo hiểm trách nhiệm.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Hợp đồng bảo hiểm nhân thọ; Hợp đồng bảo hiểm sức khỏe; Hợp đồng bảo hiểm tài sản; Hợp đồng…**."},{"id":336,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, trong trường hợp đại lý bảo hiểm vi phạm hợp đồng đại lý bảo hiểm gây thiệt hại đến quyền và lợi ích hợp pháp của người được bảo hiểm thì doanh nghiệp bảo hiểm có phải chịu trách nhiệm thực hiện các nghĩa vụ theo thỏa thuận trong hợp đồng bảo hiểm do đại lý bảo hiểm thu xếp giao kết không?","options":[{"key":"A","text":"Có"},{"key":"B","text":"Không"}],"answer":"A","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **A**: **Có**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Có**."},{"id":337,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, ngoài số tiền bồi thường đối với tổn thất thuộc trách nhiệm bảo hiểm, những chi phí cần thiết, hợp lý theo thỏa thuận tại hợp đồng bảo hiểm để thực hiện các biện pháp hạn chế tổn thất trong bảo hiểm tài sản có thuộc phạm vi bảo hiểm không?","options":[{"key":"A","text":"Có."},{"key":"B","text":"Không."},{"key":"C","text":"Có, với điều kiện các biện pháp để hạn chế tổn thất được thực hiện theo hướng dẫn của doanh nghiệp bảo hiểm."}],"answer":"C","explanation":"Theo đáp án của đề cương, đáp án **C** là **Có, với điều kiện các biện pháp để hạn chế tổn thất được thực hiện theo hướng dẫn của doanh nghiệp bảo hiểm.**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Có, với điều kiện các biện pháp để hạn chế tổn thất được thực hiện theo hướng dẫn của doanh…**."},{"id":338,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phát biểu nào sau đây là đúng nhất về điều kiện đối với cá nhân hoạt động đại lý bảo hiểm:","options":[{"key":"A","text":"Thường trú tại Việt Nam; Có năng lực hành vi dân sự đầy đủ; Có chứng chỉ đại lý bảo hiểm phù hợp theo quy định của pháp luật về hoạt động kinh doanh bảo hiểm"},{"key":"B","text":"Là công dân Việt Nam thường trú tại Việt Nam; Có chứng chỉ đại lý bảo hiểm phù hợp theo quy định của pháp luật về hoạt động kinh doanh bảo hiểm"},{"key":"C","text":"Là công dân Việt Nam thường trú tại Việt Nam; Có năng lực hành vi dân sự đầy đủ; Có chứng chỉ đại lý bảo hiểm phù hợp theo quy định của pháp luật về hoạt động kinh doanh bảo hiểm"},{"key":"D","text":"Là công dân Việt Nam thường trú tại Việt Nam; Có năng lực hành vi dân sự đầy đủ; có bằng đại học hoặc trên đại học; có chứng chỉ đại lý bảo hiểm phù hợp theo quy định của pháp luật về hoạt động kinh doanh bảo hiểm"}],"answer":"C","explanation":"Theo đáp án của đề cương, đáp án đúng là **C**: **Là công dân Việt Nam thường trú tại Việt Nam; Có năng lực hành vi dân sự đầy đủ; Có chứng chỉ đại lý bảo hiểm phù hợp theo quy định của pháp luật về hoạt động kinh doanh bảo hiểm**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Là công dân Việt Nam thường trú tại Việt Nam; Có năng lực hành vi dân sự đầy đủ; Có chứng…**."},{"id":339,"category":"Bảo hiểm xe cơ giới","question":"Theo đơn bảo hiểm thiệt hại vật chất xe cơ giới, doanh nghiệp bảo hiểm không chịu trách nhiệm bảo hiểm đối với những rủi ro xảy ra do:","options":[{"key":"A","text":"Hành động cố ý gây thiệt hại của chủ xe và.hoặc lái xe cơ giới."},{"key":"B","text":"Lái xe không có Giấy phép lái xe hoặc Giấy phép lái xe không phù hợp đối với loại xe cơ giới bắt buộc có Giấy phép lái xe."},{"key":"C","text":"Xe không có Giấy kiểm định an toàn kỹ thuật và bảo vệ môi trường."},{"key":"D","text":"A, B, C đúng."},{"key":"E","text":"A, C đúng."}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **A, B, C đúng.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng.**."},{"id":340,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, đáp án nào dưới đây đúng khi điền vào chỗ ______ của câu sau:\n\"Văn phòng đại diện của doanh nghiệp bảo hiểm, doanh nghiệp môi giới bảo hiểm nước ngoài______\":","options":[{"key":"A","text":"Không được thực hiện hoạt động kinh doanh bảo hiểm tại Việt Nam."},{"key":"B","text":"Được kinh doanh bảo hiểm tại Việt Nam"},{"key":"C","text":"Được kinh doanh tái bảo hiểm tại Việt Nam"},{"key":"D","text":"Được thực hiện hoạt động môi giới bảo hiểm tại Việt Nam"}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Không được thực hiện hoạt động kinh doanh bảo hiểm tại Việt Nam.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Không được thực hiện hoạt động kinh doanh bảo hiểm tại Việt Nam.**."},{"id":341,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, chọn phương án đúng nhất về chuyển giao hợp đồng bảo hiểm:","options":[{"key":"A","text":"Bên mua bảo hiểm có quyền chuyển giao hợp đồng bảo hiểm."},{"key":"B","text":"Đối với hợp đồng bảo hiểm nhân thọ, việc chuyển giao phải được sự đồng ý bằng văn bản của người được bảo hiểm hoặc người đại diện theo pháp luật của người được bảo hiểm."},{"key":"C","text":"Bên nhận chuyển giao hợp đồng bảo hiểm phải có quyền lợi có thể được bảo hiểm, được kế thừa quyền và nghĩa vụ của bên chuyển giao."},{"key":"D","text":"A, B, C đúng"}],"answer":"D","explanation":"Theo đáp án của đề cương, phương án **D** là nội dung đúng: **A, B, C đúng**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng**."},{"id":342,"category":"Luật Kinh doanh bảo hiểm","question":"Chọn phương án đúng nhất theo Luật Kinh doanh bảo hiểm:","options":[{"key":"A","text":"Chính phủ quy định chi tiết về điều kiện bảo hiểm, mức phí bảo hiểm, số tiền bảo hiểm tối thiểu đối với bảo hiểm bắt buộc."},{"key":"B","text":"Các sản phẩm thuộc nghiệp vụ bảo hiểm nhân thọ, bảo hiểm sức khỏe phải được Bộ Tài chính chấp thuận phương pháp, cơ sở tính phí bảo hiểm trước khi triển khai."},{"key":"C","text":"Ngoài loại hình bảo hiểm bắt buộc, đối với các sản phẩm thuộc nghiệp vụ bảo hiểm phi nhân thọ, doanh nghiệp bảo hiểm chủ động xây dựng quy tắc, điều khoản, phương pháp, cơ sở tính phí bảo hiểm."},{"key":"D","text":"A, B đúng."},{"key":"E","text":"A, B, C đúng."}],"answer":"D","explanation":"Theo đáp án của đề cương, phương án **D** là nội dung đúng: **A, B đúng.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B đúng.**."},{"id":343,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, trong bảo hiểm trách nhiệm, theo yêu cầu của người được bảo hiểm, doanh nghiệp bảo hiểm có thể bồi thường trực tiếp cho:","options":[{"key":"A","text":"Người được bảo hiểm"},{"key":"B","text":"Người thứ ba bị thiệt hại"},{"key":"C","text":"A, B đúng"},{"key":"D","text":"A, B sai"}],"answer":"C","explanation":"Theo đáp án của đề cương, đáp án đúng là **C**: **A, B đúng**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B đúng**."},{"id":344,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, khi có sự thay đổi những yếu tố làm cơ sở để tính phí bảo hiểm dẫn đến giảm các rủi ro được bảo hiểm, căn cứ thỏa thuận tại hợp đồng bảo hiểm, bên mua bảo hiểm:","options":[{"key":"A","text":"Có quyền yêu cầu doanh nghiệp bảo hiểm giảm phí bảo hiểm cho thời gian còn lại của hợp đồng bảo hiểm"},{"key":"B","text":"Có quyền yêu cầu doanh nghiệp bảo hiểm giảm số tiền bảo hiểm cho thời gian còn lại của hợp đồng bảo hiểm"},{"key":"C","text":"Không có quyền yêu cầu doanh nghiệp bảo hiểm kéo dài thời hạn bảo hiểm."},{"key":"D","text":"Có quyền yêu cầu doanh nghiệp bảo hiểm rút ngắn thời hạn bảo hiểm"}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Có quyền yêu cầu doanh nghiệp bảo hiểm giảm phí bảo hiểm cho thời gian còn lại của hợp đồng bảo hiểm**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Có quyền yêu cầu doanh nghiệp bảo hiểm giảm phí bảo hiểm cho thời gian còn lại của hợp đồng…**."},{"id":345,"category":"Kiến thức chung","question":"Chọn phương án đúng nhất về mức trách nhiệm bảo hiểm:","options":[{"key":"A","text":"Mức trách nhiệm bảo hiểm là trách nhiệm của người được bảo hiểm đối với người thứ ba."},{"key":"B","text":"Mức trách nhiệm bảo hiểm là một khoản tiền giới hạn trách nhiệm cho mỗi sự cố hoặc cho cả thời hạn bảo hiểm."},{"key":"C","text":"Mức trách nhiệm bảo hiểm là mức trách nhiệm của doanh nghiêp bảo hiểm đối với người thứ ba về người và tài sản trong mỗi sự cố hoặc cho cả thời hạn bảo hiểm."},{"key":"D","text":"Mức trách nhiệm bảo hiểm là số tiền tối đa mà doanh nghiệp bảo hiểm phải trả cho người được bảo hiểm trong một sự kiện bảo hiểm hoặc trong cả thời hạn bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm."}],"answer":"D","explanation":"Theo đáp án của đề cương, phương án **D** là nội dung đúng: **Mức trách nhiệm bảo hiểm là số tiền tối đa mà doanh nghiệp bảo hiểm phải trả cho người được bảo hiểm trong một sự kiện bảo hiểm hoặc trong cả thời hạn bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Mức trách nhiệm bảo hiểm là số tiền tối đa mà doanh nghiệp bảo hiểm phải trả cho người được…**."},{"id":346,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, đối với hợp đồng bảo hiểm trách nhiệm, trách nhiệm của doanh nghiệp bảo hiểm chỉ phát sinh khi:","options":[{"key":"A","text":"Người thứ ba yêu cầu người được bảo hiểm bồi thường do có hành vi gây thiệt hại cho người thứ ba trong thời hạn bảo hiểm."},{"key":"B","text":"Người thứ ba yêu cầu người được bảo hiểm bồi thường do có hành vi gây thiệt hại cho người thứ ba"},{"key":"C","text":"Doanh nghiệp bảo hiểm yêu cầu người được bảo hiểm bồi thường do có hành vi gây thiệt hại cho người thứ ba trong thời hạn bảo hiểm."},{"key":"D","text":"A, B, C đúng"}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Người thứ ba yêu cầu người được bảo hiểm bồi thường do có hành vi gây thiệt hại cho người thứ ba trong thời hạn bảo hiểm.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Người thứ ba yêu cầu người được bảo hiểm bồi thường do có hành vi gây thiệt hại cho người…**."},{"id":347,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Chọn phương án đúng: Cây cầu A tham gia Đơn bảo hiểm mọi rủi ro xây dựng CAR của nhà tái bảo hiểm Munich Re (Đơn không kèm điều kiện sửa đổi bổ sung). Do lỗi thiết kế, trụ cầu bị đổ, dẫn đến gầm cây cầu A cũng bị tổn thất. Hạng mục nào không thuộc phạm vi bảo hiểm của Đơn CAR:","options":[{"key":"A","text":"Trụ cầu"},{"key":"B","text":"Gầm cầu"},{"key":"C","text":"A, B đúng"}],"answer":"C","explanation":"Đây là câu hỏi tìm **phương án ngoại lệ/sai**. Theo đáp án của đề cương, phương án **C** là nội dung không phù hợp: **A, B đúng**. Khi làm bài, cần chú ý từ khóa phủ định như **“sai”, “không”, “ngoại trừ”**.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":348,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, hợp đồng bảo hiểm là sự thỏa thuận giữa:","options":[{"key":"A","text":"Bên mua bảo hiểm và doanh nghiệp bảo hiểm"},{"key":"B","text":"Bên mua bảo hiểm và đại lý bảo hiểm"},{"key":"C","text":"Người được bảo hiểm và doanh nghiệp bảo hiểm"},{"key":"D","text":"Người được bảo hiểm và đại lý bảo hiểm"}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Bên mua bảo hiểm và doanh nghiệp bảo hiểm**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Bên mua bảo hiểm và doanh nghiệp bảo hiểm**."},{"id":349,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, doanh nghiệp bảo hiểm có quyền:","options":[{"key":"A","text":"Kiểm tra, giám sát việc thực hiện hợp đồng đại lý bảo hiểm"},{"key":"B","text":"Chấp thuận mà không cần văn bản khi đại lý bảo hiểm của doanh nghiệp mình đồng thời làm đại lý cho nhiều doanh nghiệp bảo hiểm khác"},{"key":"C","text":"Yêu cầu đại lý bảo hiểm phải có Hợp đồng bảo hiểm trước khi được trở thành đại lý chính thức của doanh nghiệp bảo hiểm"},{"key":"D","text":"A, B đúng"}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **A, B đúng**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B đúng**."},{"id":350,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, chọn phương án sai về trường hợp hợp đồng bảo hiểm vô hiệu:","options":[{"key":"A","text":"Bên mua bảo hiểm không có quyền lợi có thể được bảo hiểm tại thời điểm giao kết hợp đồng bảo hiểm."},{"key":"B","text":"Không có đối tượng bảo hiểm tại thời điểm giao kết hợp đồng bảo hiểm."},{"key":"C","text":"Tại thời điểm giao kết hợp đồng bảo hiểm, bên mua bảo hiểm biết sự kiện bảo hiểm đã xảy ra."},{"key":"D","text":"Đại lý bảo hiểm không nộp phí bảo hiểm đã thu của bên mua bảo hiểm cho doanh nghiệp bảo hiểm."}],"answer":"D","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **D**: **Đại lý bảo hiểm không nộp phí bảo hiểm đã thu của bên mua bảo hiểm cho doanh nghiệp bảo hiểm.**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":351,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Theo quy tắc bảo hiểm của Hiệp hội bảo hiểm Vương quốc Anh (ABI), phương án nào sau đây là đúng nhất về \"Điều khoản về hệ thống thiết bị 4B\":","options":[{"key":"A","text":"Thiệt hại do cháy đối với các máy móc thiết bị điện phát sinh từ các sự cố vượt quá dòng điện, vượt quá điện quá áp, đoản mạch, hồ quang điện, tự đốt nóng hoặc rò điện do bất kỳ nguyên nhân gì (kể cả do sét đánh) sẽ thuộc phạm vi bảo hiểm."},{"key":"B","text":"Tổn thất nhưng không gây cháy đối với thiết bị hoặc hệ thống điện phát sinh do hoặc gây ra bởi hoạt động quá tải, đoản mạch, phóng hồ quang điện hay rò điện do bất kỳ nguyên nhân nào được bảo hiểm."},{"key":"C","text":"Thiệt hại do cháy đối với các máy móc thiết bị điện phát sinh từ các sự cố vượt quá dòng điện, vượt quá điện quá áp, đoản mạch, hồ quang điện, tự đốt nóng hoặc rò điện do bất kỳ nguyên nhân gì nhưng không phải do sét đánh sẽ thuộc phạm vi bảo hiểm."}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Thiệt hại do cháy đối với các máy móc thiết bị điện phát sinh từ các sự cố vượt quá dòng điện, vượt quá điện quá áp, đoản mạch, hồ quang điện, tự đốt nóng hoặc rò điện do bất kỳ nguyên nhân gì (kể cả do sét đánh) sẽ thuộc phạm vi bảo hiểm.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Thiệt hại do cháy đối với các máy móc thiết bị điện phát sinh từ các sự cố vượt quá dòng…**."},{"id":352,"category":"Bảo hiểm xe cơ giới","question":"Trong đơn Bảo hiểm trách nhiệm dân sự của chủ xe cơ giới đối với hàng hóa vận chuyển trên xe, doanh nghiệp bảo hiểm sẽ bảo hiểm trách nhiệm dân sự của chủ xe cơ giới đối  với:","options":[{"key":"A","text":"Hành lý, hàng hóa trên xe du lịch."},{"key":"B","text":"Hành lý, hàng hóa trên xe khách."},{"key":"C","text":"Hàng hóa trong quá trình vận chuyển trên xe cơ giới (được phép kinh doanh vận tải hàng hóa) theo hợp đồng vận chuyển giữa chủ xe và chủ hàng."},{"key":"D","text":"A, B, C đúng."}],"answer":"C","explanation":"Theo đáp án của đề cương, đáp án đúng là **C**: **Hàng hóa trong quá trình vận chuyển trên xe cơ giới (được phép kinh doanh vận tải hàng hóa) theo hợp đồng vận chuyển giữa chủ xe và chủ hàng.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Hàng hóa trong quá trình vận chuyển trên xe cơ giới (được phép kinh doanh vận tải hàng hóa)…**."},{"id":353,"category":"Kiến thức chung","question":"Khi bảo hiểm tài sản dưới giá trị, nếu xảy ra sự kiện bảo hiểm thì số tiền bồi thường tối đa doanh nghiệp bảo hiểm có thể chi trả là:","options":[{"key":"A","text":"Giá trị sổ sách."},{"key":"B","text":"Giá trị nguyên giá của tài sản sau khi trừ khấu hao."},{"key":"C","text":"Số tiền bảo hiểm của tài sản đó ghi trên Giấy chứng nhận bảo hiểm.Đơn bảo hiểm."},{"key":"D","text":"Giá thị trường của tài sản được bảo hiểm tại thời điểm xảy ra sự kiện bảo hiểm."}],"answer":"C","explanation":"Khái niệm cần nhớ trong câu này là: **Số tiền bảo hiểm của tài sản đó ghi trên Giấy chứng nhận bảo hiểm.Đơn bảo hiểm.**. Đáp án đúng là **C**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Số tiền bảo hiểm của tài sản đó ghi trên Giấy chứng nhận bảo hiểm.Đơn bảo hiểm.**."},{"id":354,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, trong bảo hiểm trách nhiệm, doanh nghiệp bảo hiểm không phải trả cho người được bảo hiểm khoản tiền nào sau đây:","options":[{"key":"A","text":"Khoản tiền mà theo quy định của pháp luật người được bảo hiểm có trách nhiệm bồi thường cho người thứ ba"},{"key":"B","text":"Chi phí liên quan đến việc giải quyết tranh chấp về trách nhiệm đối với người thứ ba"},{"key":"C","text":"Lãi phải trả cho người thứ ba do người được bảo hiểm chậm trả tiền bồi thường theo chỉ dẫn của doanh nghiệp bảo hiểm"},{"key":"D","text":"Khoản thiệt hại do bên thứ ba gây ra cho bên mua bảo hiểm"}],"answer":"D","explanation":"Đây là câu hỏi tìm **phương án ngoại lệ/sai**. Theo đáp án của đề cương, phương án **D** là nội dung không phù hợp: **Khoản thiệt hại do bên thứ ba gây ra cho bên mua bảo hiểm**. Khi làm bài, cần chú ý từ khóa phủ định như **“sai”, “không”, “ngoại trừ”**.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":355,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, chọn phương án sai về người thụ hưởng:","options":[{"key":"A","text":"Người thụ hưởng là tổ chức, cá nhân được bên mua bảo hiểm chỉ định để nhận tiền bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm."},{"key":"B","text":"Người thụ hưởng là tổ chức, cá nhân được người được bảo hiểm chỉ định để nhận tiền bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm."},{"key":"C","text":"Người thụ hưởng là tổ chức, cá nhân được doanh nghiệp bảo hiểm chỉ định để nhận tiền bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm."},{"key":"D","text":"A, B đúng."}],"answer":"C","explanation":"Theo đáp án của đề cương, đáp án đúng là **C**: **Người thụ hưởng là tổ chức, cá nhân được doanh nghiệp bảo hiểm chỉ định để nhận tiền bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":356,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Chọn phương án sai về đối tượng bảo hiểm của hợp đồng bảo hiểm thiệt hại:","options":[{"key":"A","text":"Bất kỳ lợi ích kinh tế mà người được bảo hiểm phải gánh chịu khi xảy ra tổn thất."},{"key":"B","text":"Nghĩa vụ thực hiện hợp đồng mà người được bảo hiểm phải gánh chịu khi xảy ra tổn thất."},{"key":"C","text":"Nghĩa vụ theo pháp luật mà người được bảo hiểm phải gánh chịu khi xảy ra tổn thất."},{"key":"D","text":"Trách nhiệm dân sự mà người được bảo hiểm phải gánh chịu khi xảy ra tổn thất."}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **Trách nhiệm dân sự mà người được bảo hiểm phải gánh chịu khi xảy ra tổn thất.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":357,"category":"Luật Kinh doanh bảo hiểm","question":"Trong quá trình thực hiện hợp đồng bảo hiểm, bên mua bảo hiểm có nghĩa vụ:","options":[{"key":"A","text":"Thông báo cho doanh nghiệp bảo hiểm những trường hợp có thể làm tăng rủi ro hoặc giảm rủi ro hoặc làm phát sinh thêm trách nhiệm của doanh nghiệp bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm."},{"key":"B","text":"Thông báo cho doanh nghiệp bảo hiểm về việc xảy ra sự kiện bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm."},{"key":"C","text":"Áp dụng các biện pháp đề phòng, hạn chế tổn thất theo quy định của pháp luật."},{"key":"D","text":"A, B, C đúng."}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **A, B, C đúng.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng.**."},{"id":358,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Theo hợp đồng bảo hiểm trách nhiệm được cấp trên cơ sở khiếu nại được lập, doanh nghiệp bảo hiểm sẽ bồi thường cho những sự kiện bảo hiểm xảy ra vào thời điểm nào sau đây:","options":[{"key":"A","text":"Sự kiện bảo hiểm xảy ra trước ngày bắt đầu hiệu lực của hợp đồng bảo hiểm (nhưng trong thời gian hiệu lực của hồi tố) và khiếu nại của bên thứ ba được lập trong thời hạn của hợp đồng bảo hiểm"},{"key":"B","text":"Sự kiện bảo hiểm xảy ra trước ngày bắt đầu hiệu lực của hợp đồng bảo hiểm, được phát hiện trong thời hạn của hợp đồng bảo hiểm."},{"key":"C","text":"Sự kiện bảo hiểm xảy ra trong thời hạn hợp đồng bảo hiểm và khiếu nại của bên thứ ba có thể được lập sau khi hết thời hạn hợp đồng bảo hiểm."},{"key":"D","text":"Sự kiện bảo hiểm xảy ra trước ngày bắt đầu hiệu lực của hợp đồng bảo hiểm, được phát hiện trong thời hạn bảo hiểm và khiếu nại của bên thứ ba được lập sau thời hạn của hợp đồng bảo hiểm."}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Sự kiện bảo hiểm xảy ra trước ngày bắt đầu hiệu lực của hợp đồng bảo hiểm (nhưng trong thời gian hiệu lực của hồi tố) và khiếu nại của bên thứ ba được lập trong thời hạn của hợp đồng bảo hiểm**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Sự kiện bảo hiểm xảy ra trước ngày bắt đầu hiệu lực của hợp đồng bảo hiểm (nhưng trong thời…**."},{"id":359,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Điều kiện để được bồi thường trách nhiệm dân sự theo Đơn bảo hiểm mọi rủi ro xây dựng/lắp đặt (CAR/EAR) của nhà tái bảo hiểm Munich Re là:","options":[{"key":"A","text":"Có hành vi bất cẩn, sai sót; phải phát sinh trách nhiệm theo quy định pháp luật."},{"key":"B","text":"Phải có thiệt hại về người và.hoặc tài sản."},{"key":"C","text":"Có mối quan hệ nhân quả giữa hành vi bất cẩn, sai sót và thiệt hại đó."},{"key":"D","text":"A, B, C đúng."}],"answer":"D","explanation":"Khái niệm cần nhớ trong câu này là: **A, B, C đúng.**. Đáp án đúng là **D**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng.**."},{"id":360,"category":"Bảo hiểm con người","question":"Khi tham gia bảo hiểm chi phí y tế, người được bảo hiểm có thể được nhận quyền lợi điều trị ngoại trú nào sau đây?","options":[{"key":"A","text":"Tiền thuốc điều trị bệnh theo chỉ định của bác sỹ."},{"key":"B","text":"Chi phí điều trị theo yêu cầu của người được bảo hiểm."},{"key":"C","text":"Tiền mua các thực phẩm chức năng hỗ trợ điều trị."},{"key":"D","text":"A, B đúng."},{"key":"E","text":"A, B, C đúng."}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Tiền thuốc điều trị bệnh theo chỉ định của bác sỹ.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Tiền thuốc điều trị bệnh theo chỉ định của bác sỹ.**."},{"id":361,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phát biểu  nào sau đây là đúng:","options":[{"key":"A","text":"Bên mua bảo hiểm được hưởng hoa hồng bảo hiểm"},{"key":"B","text":"Đại lý bảo hiểm được hưởng hoa hồng đại lý bảo hiểm theo thỏa thuận tại hợp đồng đại lý bảo hiểm"},{"key":"C","text":"Môi giới bảo hiểm được hưởng hoa hồng môi giới bảo hiểm theo quy định của Bộ trưởng Bộ tài chính"},{"key":"D","text":"B, C đúng"}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **B, C đúng**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **B, C đúng**."},{"id":362,"category":"Bảo hiểm xe cơ giới","question":"Theo đơn bảo hiểm thiệt hại vật chất xe cơ giới, doanh nghiệp bảo hiểm không chịu trách nhiệm đối với những rủi ro xảy ra do:","options":[{"key":"A","text":"Đâm va, lật đổ, chìm, rơi toàn bộ xe."},{"key":"B","text":"Hỏa hoạn, cháy, nổ."},{"key":"C","text":"Thiệt hại săm lốp, chụp lốp, nhãn, đề can, bạt, chắn bùn, biểu tượng trừ trường hợp các bộ phận trên tổn thất do tai nạn."},{"key":"D","text":"A, B, C sai."}],"answer":"C","explanation":"Theo đáp án của đề cương, đáp án đúng là **C**: **Thiệt hại săm lốp, chụp lốp, nhãn, đề can, bạt, chắn bùn, biểu tượng trừ trường hợp các bộ phận trên tổn thất do tai nạn.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Thiệt hại săm lốp, chụp lốp, nhãn, đề can, bạt, chắn bùn, biểu tượng trừ trường hợp các bộ…**."},{"id":363,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, trường hợp bên mua bảo hiểm vì trở ngại khách quan dẫn đến chậm thông báo cho doanh nghiệp bảo hiểm về việc xảy ra sự kiện bảo hiểm, doanh nghiệp bảo hiểm có được áp dụng điều khoản loại trừ trách nhiệm bảo hiểm về việc chậm thông báo không:","options":[{"key":"A","text":"Có"},{"key":"B","text":"Không"}],"answer":"B","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **B**: **Không**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Không**."},{"id":364,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, đối với hợp đồng bảo hiểm trách nhiệm, trong phạm vi giới hạn trách nhiệm bảo hiểm, doanh nghiệp bảo hiểm có trách nhiệm chi trả cho người được bảo hiểm các khoản tiền nào sau đây:","options":[{"key":"A","text":"Khoản tiền mà theo quy định của pháp luật người được bảo hiểm có trách nhiệm bồi thường cho người thứ ba."},{"key":"B","text":"Các chi phí liên quan đến việc giải quyết tranh chấp về trách nhiệm đối với người thứ ba và lãi phải trả cho người thứ ba do người được bảo hiểm chậm trả tiền bồi thường theo chỉ dẫn của doanh nghiệp bảo hiểm."},{"key":"C","text":"A, B đúng"},{"key":"D","text":"A, B sai"}],"answer":"C","explanation":"Theo đáp án của đề cương, đáp án đúng là **C**: **A, B đúng**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B đúng**."},{"id":365,"category":"Bảo hiểm con người","question":"Khi tham gia bảo hiểm sức khỏe với quyền lợi bảo hiểm tai nạn, người được bảo hiểm không may bị tai nạn khi tham gia vào các cuộc thi đấu có tính chất chuyên nghiệp như đua ngựa, đua xe (Hợp đồng bảo hiểm không có điều khoản sửa đổi bổ sung về bảo hiểm rủi ro tai nạn khi tham gia vào các cuộc thi đấu có tính chất chuyên nghiệp). Phương án giải quyết quyền lợi bảo hiểm nào sau đây đúng:","options":[{"key":"A","text":"Số tiền bảo hiểm theo tỷ lệ thương tật do tai nạn."},{"key":"B","text":"Chi phí y tế điều trị tai nạn."},{"key":"C","text":"Không thuộc phạm vi trách nhiệm bảo hiểm."},{"key":"D","text":"A, B đúng"}],"answer":"C","explanation":"Theo đáp án của đề cương, đáp án đúng là **C**: **Không thuộc phạm vi trách nhiệm bảo hiểm.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Không thuộc phạm vi trách nhiệm bảo hiểm.**."},{"id":366,"category":"Bảo hiểm con người","question":"Người được bảo hiểm tham gia hợp đồng bảo hiểm sức khỏe với quyền lợi tử vong do tai nạn. Chọn phương án đúng nhất về cách thức doanh nghiệp bảo hiểm giải quyết trong trường hợp người được bảo hiểm tử vong do tai nạn:","options":[{"key":"A","text":"Chi trả 100% số tiền bảo hiểm."},{"key":"B","text":"Chi trả theo nguyên tắc bồi thường."},{"key":"C","text":"Doanh nghiệp bảo hiểm không có quyền yêu cầu người thứ ba bồi hoàn khoản tiền đã trả cho người thụ hưởng trong trường hợp người được bảo hiểm tử vong do lỗi của người thứ ba."},{"key":"D","text":"A, C đúng"},{"key":"E","text":"B, C đúng."}],"answer":"D","explanation":"Theo đáp án của đề cương, phương án **D** là nội dung đúng: **A, C đúng**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, C đúng**."},{"id":367,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, chọn phương án đúng về hoạt động đại lý bảo hiểm:","options":[{"key":"A","text":"Thay mặt khách hàng ký Giấy yêu cầu bảo hiểm"},{"key":"B","text":"Thay mặt khách hàng ký Giấy nhận tiền bồi thường hoặc trả tiền bảo hiểm"},{"key":"C","text":"Thu thập hồ sơ để phục vụ việc giải quyết bồi thường, trả tiền bảo hiểm"},{"key":"D","text":"A, B, C sai"}],"answer":"C","explanation":"Theo đáp án của đề cương, phương án **C** là nội dung đúng: **Thu thập hồ sơ để phục vụ việc giải quyết bồi thường, trả tiền bảo hiểm**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Thu thập hồ sơ để phục vụ việc giải quyết bồi thường, trả tiền bảo hiểm**."},{"id":368,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Dự án X được thi công bởi 2 Nhà thầu A và B; dự án được bảo hiểm theo quy tắc bảo hiểm mọi rủi ro xây dựng CAR của nhà tái bảo hiểm Munich Re (kèm Điều khoản SĐBS 002 – Trách nhiệm chéo) gồm:\nPhần I – Tổn thất vật chất: Giá trị công trình; xe cẩu nhà thầu A\nPhần II – Trách nhiệm đối với bên thứ ba\nTrong quá trình thi công, xe cẩu của nhà thầu A bất ngờ bị đổ và đồng thời, gây tổn thất cho máy xúc nhà thầu B, nhà dân cạnh công trường và khách tham quan công trình. Những tổn thất nào sau đây không thuộc trách nhiệm bảo hiểm:","options":[{"key":"A","text":"Tổn thất hư hỏng xe cẩu của nhà thầu A"},{"key":"B","text":"Tổn thất hư hỏng máy xúc của nhà thầu B"},{"key":"C","text":"Thiệt hại của nhà dân cạnh công trường"},{"key":"D","text":"Thiệt hại khách tham quan công trình"}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án đúng là **B**: **Tổn thất hư hỏng máy xúc của nhà thầu B**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Tổn thất hư hỏng máy xúc của nhà thầu B**."},{"id":369,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Trong bảo hiểm tài sản, thông thường, giới hạn phụ của các điều khoản sửa đổi bổ sung không vượt quá 10% số tiền bảo hiểm:","options":[{"key":"A","text":"Đúng."},{"key":"B","text":"Sai."}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Đúng.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Đúng.**."},{"id":370,"category":"Kiến thức chung","question":"Chọn phương án đúng nhất về “Nguyên tắc đóng góp bồi thường”:","options":[{"key":"A","text":"Khi đối tượng bảo hiểm bị tổn thất thuộc phạm vi bảo hiểm, các doanh nghiệp bảo hiểm có nghĩa vụ đóng góp bồi thường căn cứ theo tỷ lệ phần trách nhiệm bảo hiểm đã nhận bảo hiểm."},{"key":"B","text":"Tổng số tiền bồi thường không vượt quá thiệt hại thực tế của người được bảo hiểm trong sự kiện bảo hiểm."},{"key":"C","text":"Nguyên tắc này không áp dụng cho bảo hiểm nhân thọ."},{"key":"D","text":"A, B, C đúng."}],"answer":"D","explanation":"Theo đáp án của đề cương, phương án **D** là nội dung đúng: **A, B, C đúng.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng.**."},{"id":371,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Hợp đồng bảo hiểm trách nhiệm nghề nghiệp không loại trừ tổn thất của người thứ ba do người được bảo hiểm gây ra khi:","options":[{"key":"A","text":"Người được bảo hiểm không đáp ứng về mặt thời gian công việc chuyên môn."},{"key":"B","text":"Người được bảo hiểm vi phạm bản quyền thương hiệu khi thực hiện công việc chuyên môn."},{"key":"C","text":"Người được bảo hiểm tư vấn.cung cấp dịch vụ chuyên môn cho bên thứ ba."},{"key":"D","text":"Bất khả kháng."}],"answer":"C","explanation":"Theo đáp án của đề cương, đáp án đúng là **C**: **Người được bảo hiểm tư vấn.cung cấp dịch vụ chuyên môn cho bên thứ ba.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Người được bảo hiểm tư vấn.cung cấp dịch vụ chuyên môn cho bên thứ ba.**."},{"id":372,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Người có quyền sử dụng đối với tài sản thuê, mượn và phải chịu rủi ro về tài sản đó thì có \"Quyền lợi có thể được bảo hiểm\" đối với tài sản đó trong thời gian thuê, mượn:","options":[{"key":"A","text":"Đúng."},{"key":"B","text":"Sai."}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án **A** là **Đúng.**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Đúng.**."},{"id":373,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, chọn phương án đúng nhất về sự kiện bảo hiểm:","options":[{"key":"A","text":"Là sự kiện chủ quan do các bên thỏa thuận mà khi sự kiện đó xảy ra thì doanh nghiệp bảo hiểm phải trả tiền bảo hiểm cho người thụ hưởng hoặc bồi thường cho người được bảo hiểm."},{"key":"B","text":"Là sự kiện khách quan do các bên thỏa thuận hoặc pháp luật quy định mà khi sự kiện đó xảy ra thì doanh nghiệp bảo hiểm phải bồi thường, trả tiền bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm."},{"key":"C","text":"Là sự kiện khách quan do pháp luật quy định mà khi sự kiện đó xảy ra thì doanh nghiệp bảo hiểm phải trả tiền bảo hiểm cho người thụ hưởng hoặc bồi thường cho người được bảo hiểm."},{"key":"D","text":"Là sự kiện chủ quan do pháp luật quy định mà khi sự kiện đó xảy ra thì doanh nghiệp bảo hiểm phải trả tiền bảo hiểm cho người thụ hưởng hoặc bồi thường cho người được bảo hiểm."}],"answer":"B","explanation":"Theo đáp án của đề cương, phương án **B** là nội dung đúng: **Là sự kiện khách quan do các bên thỏa thuận hoặc pháp luật quy định mà khi sự kiện đó xảy ra thì doanh nghiệp bảo hiểm phải bồi thường, trả tiền bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Là sự kiện khách quan do các bên thỏa thuận hoặc pháp luật quy định mà khi sự kiện đó xảy…**."},{"id":374,"category":"Bảo hiểm xe cơ giới","question":"Theo đơn Bảo hiểm trách nhiệm dân sự của chủ xe cơ giới đối với hàng hóa trên xe: Trường hợp xe cơ giới bị tai nạn dẫn đến hàng hóa vận chuyển trên xe bị tổn thất, doanh nghiệp bảo hiểm có bồi thường cho người được bảo hiểm chi phí xếp dỡ, bảo quản hàng hóa bị tổn thất không:","options":[{"key":"A","text":"Có."},{"key":"B","text":"Không."}],"answer":"A","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **A**: **Có.**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Có.**."},{"id":375,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Chi phí dọn dẹp hiện trường là một trong các hạng mục có thể được bảo hiểm theo Đơn bảo hiểm mọi rủi ro xây dựng/lắp đặt (CAR/EAR) của nhà tái bảo hiểm Munich Re. Chi phí này được hiểu là:","options":[{"key":"A","text":"Chi phí dọn dẹp ban đầu để lấy mặt bằng xây dựng.lắp đặt."},{"key":"B","text":"Chi phí dọn dẹp công trình sau khi thi công xong để đưa vào sử dụng."},{"key":"C","text":"Chi phí phát sinh do di chuyển, dọn dẹp các chất phế thải xây dựng, đất đá do sự cố thuộc trách nhiệm bảo hiểm gây ra...nhằm làm sạch để tiếp tục thi công"},{"key":"D","text":"A, B, C đúng."}],"answer":"C","explanation":"Khái niệm cần nhớ trong câu này là: **Chi phí phát sinh do di chuyển, dọn dẹp các chất phế thải xây dựng, đất đá do sự cố thuộc trách nhiệm bảo hiểm gây ra...nhằm làm sạch để tiếp tục thi công**. Đáp án đúng là **C**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Chi phí phát sinh do di chuyển, dọn dẹp các chất phế thải xây dựng, đất đá do…**."},{"id":376,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, bằng chứng giao kết hợp đồng bảo hiểm là:","options":[{"key":"A","text":"Giấy yêu cầu bảo hiểm, giấy chứng nhận bảo hiểm, đơn bảo hiểm, điện báo, telex, fax."},{"key":"B","text":"Hợp đồng, giấy chứng nhận bảo hiểm, đơn bảo hiểm hoặc hình thức khác theo quy định của pháp luật."}],"answer":"B","explanation":"Khái niệm cần nhớ trong câu này là: **Hợp đồng, giấy chứng nhận bảo hiểm, đơn bảo hiểm hoặc hình thức khác theo quy định của pháp luật.**. Đáp án đúng là **B**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Hợp đồng, giấy chứng nhận bảo hiểm, đơn bảo hiểm hoặc hình thức khác theo quy định của pháp…**."},{"id":377,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Theo quy tắc bảo hiểm của Hiệp hội bảo hiểm Vương quốc Anh (ABI), chọn phương án đúng nhất về \"Điều khoản về điều chỉnh thời gian (Điều khoản 72 giờ)\":","options":[{"key":"A","text":"Bất kỳ tổn thất nào đối với tài sản được bảo hiểm phát sinh trong vòng 72 giờ liên tục gây ra bởi giông bão, lũ lụt, động đất, sạt lở, sụp đổ, chấn động hoặc suy yếu bộ phận chống đỡ sẽ được coi như là một sự cố khi xem xét để áp dụng mức miễn thường có khấu trừ cho một sự cố."},{"key":"B","text":"Bất kỳ tổn thất nào đối với tài sản được bảo hiểm phát sinh trong vòng 72 giờ kể từ khi xảy ra tổn thất đầu tiên gây ra bởi giông bão, lũ lụt, động đất, sạt lở, sụp đổ, chấn động hoặc suy yếu bộ phận chống đỡ sẽ được coi như là một sự cố khi xem xét để áp dụng mức miễn thường có khấu trừ cho một sự cố."}],"answer":"A","explanation":"Theo đáp án của đề cương, phương án **A** là nội dung đúng: **Bất kỳ tổn thất nào đối với tài sản được bảo hiểm phát sinh trong vòng 72 giờ liên tục gây ra bởi giông bão, lũ lụt, động đất, sạt lở, sụp đổ, chấn động hoặc suy yếu bộ phận chống đỡ sẽ được coi như là một sự cố khi xem xét để áp dụng mức miễn thường có khấu trừ cho một sự cố.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Chốt mốc **72 giờ** và gắn với đúng điều kiện của câu."},{"id":378,"category":"Bảo hiểm con người","question":"Đối với bảo hiểm sức khỏe với quyền lợi bảo hiểm tai nạn, doanh nghiệp bảo hiểm không chi trả bảo hiểm cho trường hợp nào sau đây?","options":[{"key":"A","text":"Người được bảo hiểm cố ý gây tai nạn."},{"key":"B","text":"Người được bảo hiểm bị ảnh hưởng trực tiếp do sử dụng rượu bia, ma túy và các chất kích thích tương tự."},{"key":"C","text":"Người được bảo hiểm điều khiển phương tiện tham gia giao thông vượt quá tốc độ quy định."},{"key":"D","text":"Người được bảo hiểm tham gia chống các hành động phạm pháp."},{"key":"E","text":"A, B, C đúng."}],"answer":"E","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **E**: **A, B, C đúng.**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng.**."},{"id":379,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, chọn phương án đúng điền vào chỗ ________ của câu sau: \n\"Tổng số tiền bồi thường của các hợp đồng bảo hiểm __________ giá trị thiệt hại thực tế của tài sản\".","options":[{"key":"A","text":"Luôn đúng bằng"},{"key":"B","text":"Luôn ít hơn"},{"key":"C","text":"Không vượt quá"},{"key":"D","text":"Có thể vượt quá"}],"answer":"C","explanation":"Theo đáp án của đề cương, phương án **C** là nội dung đúng: **Không vượt quá**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Không vượt quá**."},{"id":380,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, đối với bảo hiểm trách nhiệm, trách nhiệm của doanh nghiệp bảo hiểm phát sinh khi:","options":[{"key":"A","text":"Ngay khi người được bảo hiểm gây ra thiệt hại cho người thứ ba."},{"key":"B","text":"Người thứ ba yêu cầu người được bảo hiểm bồi thường do có hành vi gây thiệt hại cho người thứ ba trong thời hạn bảo hiểm."},{"key":"C","text":"A, B đúng"},{"key":"D","text":"A, B sai"}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án đúng là **B**: **Người thứ ba yêu cầu người được bảo hiểm bồi thường do có hành vi gây thiệt hại cho người thứ ba trong thời hạn bảo hiểm.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Người thứ ba yêu cầu người được bảo hiểm bồi thường do có hành vi gây thiệt hại cho người…**."},{"id":381,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, việc giao kết hợp đồng bảo hiểm với doanh nghiệp bảo hiểm và đóng phí bảo hiểm được thực hiện bởi:","options":[{"key":"A","text":"Bên mua bảo hiểm."},{"key":"B","text":"Môi giới bảo hiểm."},{"key":"C","text":"Đại lý bảo hiểm."},{"key":"D","text":"B, C đúng."}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Bên mua bảo hiểm.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Bên mua bảo hiểm.**."},{"id":382,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Theo đơn bảo hiểm mọi rủi ro xây dựng (CAR) của nhà tái bảo hiểm Munich Re, tổn thất gián tiếp các hạng mục khác xảy ra do một tai nạn là hậu quả khuyết tật của vật liệu và tay nghề có thuộc điểm loại trừ bảo hiểm không:","options":[{"key":"A","text":"Có."},{"key":"B","text":"Không."}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án đúng là **B**: **Không.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Không.**."},{"id":383,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phát biểu nào sau đây là đúng nhất về giám định tổn thất bảo hiểm:","options":[{"key":"A","text":"Là hoạt động tính toán phân bổ trách nhiệm bồi thường tổn thất làm cơ sở giải quyết bồi thường bảo hiểm."},{"key":"B","text":"Là hoạt động xác định hiện trạng, nguyên nhân, mức độ tổn thất và tính toán phân bổ trách nhiệm bồi thường tổn thất làm cơ sở giải quyết bồi thường bảo hiểm."},{"key":"C","text":"Là hoạt động xác định hiện trạng, nguyên nhân, mức độ tổn thất làm cơ sở giải quyết bồi thường bảo hiểm."},{"key":"D","text":"A, B, C sai."}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án đúng là **B**: **Là hoạt động xác định hiện trạng, nguyên nhân, mức độ tổn thất và tính toán phân bổ trách nhiệm bồi thường tổn thất làm cơ sở giải quyết bồi thường bảo hiểm.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Là hoạt động xác định hiện trạng, nguyên nhân, mức độ tổn thất và tính toán phân bổ trách…**."},{"id":384,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Chọn phương án đúng nhất theo đơn bảo hiểm “Gián đoạn kinh doanh” của Hiệp hội bảo hiểm Vương quốc Anh (ABI):","options":[{"key":"A","text":"Thời hạn bồi thường được bắt đầu từ khi thiệt hại vật chất xảy ra trong thời hạn bảo hiểm gây ra việc gián đoạn kinh doanh và có thể kéo dài vượt quá thời hạn bảo hiểm."},{"key":"B","text":"Thời hạn bồi thường được bắt đầu từ khi thiệt hại vật chất xảy ra trong thời hạn bảo hiểm gây ra việc gián đoạn kinh doanh và có thể kéo dài vượt quá thời hạn bảo hiểm tùy thuộc vào thời gian hồi phục hoạt động kinh doanh, nhưng không vượt quá thời hạn bồi thường tối đa được thỏa thuận và được ghi trong hợp đồng bảo hiểm."},{"key":"C","text":"Thời hạn bồi thường được bắt đầu từ khi thiệt hại vật chất xảy ra gây ra việc gián đoạn kinh doanh và có thể kéo dài vượt quá thời hạn bảo hiểm nhưng không vượt quá thời hạn bồi thường tối đa."}],"answer":"B","explanation":"Theo đáp án của đề cương, phương án **B** là nội dung đúng: **Thời hạn bồi thường được bắt đầu từ khi thiệt hại vật chất xảy ra trong thời hạn bảo hiểm gây ra việc gián đoạn kinh doanh và có thể kéo dài vượt quá thời hạn bảo hiểm tùy thuộc vào thời gian hồi phục hoạt động kinh doanh, nhưng không vượt quá thời hạn bồi thường tối đa được thỏa thuận và được ghi trong hợp đồng bảo hiểm.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Thời hạn bồi thường được bắt đầu từ khi thiệt hại vật chất xảy ra trong thời hạn bảo hiểm…**."},{"id":385,"category":"Bảo hiểm con người","question":"Khi tham gia bảo hiểm chi phí y tế cơ bản, người được bảo hiểm có thể được nhận quyền lợi điều trị nội trú nào sau đây?","options":[{"key":"A","text":"Chi phí giường bệnh."},{"key":"B","text":"Chi phí xét nghiệm, thuốc điều  trị trong thời gian điều trị nội trú."},{"key":"C","text":"Chi phí nha khoa."},{"key":"D","text":"A, B, C đúng."},{"key":"E","text":"A, B đúng."}],"answer":"E","explanation":"Theo đáp án của đề cương, đáp án đúng là **E**: **A, B đúng.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B đúng.**."},{"id":386,"category":"Kiến thức chung","question":"Rủi ro thuần túy là rủi ro có hậu quả:","options":[{"key":"A","text":"Liên quan đến khả năng đầu cơ."},{"key":"B","text":"Liên quan đến khả năng tổn thất."},{"key":"C","text":"Liên quan đến khả năng đầu cơ và khả năng tổn thất."},{"key":"D","text":"Không phương án nào đúng."}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án đúng là **B**: **Liên quan đến khả năng tổn thất.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Liên quan đến khả năng tổn thất.**."},{"id":387,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, hoạt động của doanh nghiệp bảo hiểm nhận một khoản phí tái bảo hiểm của doanh nghiệp bảo hiểm khác để cam kết bồi thường cho các trách nhiệm đã nhận bảo hiểm là:","options":[{"key":"A","text":"Kinh doanh bảo hiểm"},{"key":"B","text":"Kinh doanh tái bảo hiểm"},{"key":"C","text":"Nhượng tái bảo hiểm"}],"answer":"B","explanation":"Khái niệm cần nhớ trong câu này là: **Kinh doanh tái bảo hiểm**. Đáp án đúng là **B**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Kinh doanh tái bảo hiểm**."},{"id":388,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, loại hợp đồng bảo hiểm nào sau đây thuộc loại hình bảo hiểm phi nhân thọ:","options":[{"key":"A","text":"Hợp đồng bảo hiểm sức khỏe"},{"key":"B","text":"Hợp đồng bảo hiểm trách nhiệm"},{"key":"C","text":"Hợp đồng bảo hiểm trọn đời"},{"key":"D","text":"Hợp đồng bảo hiểm liên kết đầu tư"}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án đúng là **B**: **Hợp đồng bảo hiểm trách nhiệm**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Hợp đồng bảo hiểm trách nhiệm**."},{"id":389,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Đơn bảo hiểm mọi rủi ro xây dựng CAR theo quy tắc bảo hiểm của nhà tái bảo hiểm Munich Re. Trong quá trình thi công, do khuyết tật của vật liệu gây tổn thất trực tiếp cho hạng mục A và tổn thất gián tiếp cho hạng mục B (Hạng mục A&B được bảo hiểm theo Phần I – Tổn thất vật chất). Hạng mục nào được xem xét giải quyết bồi thường (Hợp đồng bảo hiểm không kèm theo Điều khoản sửa đổi bổ sung):","options":[{"key":"A","text":"Hạng mục A."},{"key":"B","text":"Hạng mục B."},{"key":"C","text":"Hạng mục A,B."}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án đúng là **B**: **Hạng mục B.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Hạng mục B.**."},{"id":390,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, việc chuyển giao hợp đồng bảo hiểm chỉ có hiệu lực khi:","options":[{"key":"A","text":"Bên mua bảo hiểm thông báo bằng văn bản cho doanh nghiệp bảo hiểm về việc chuyển giao."},{"key":"B","text":"Bên mua bảo hiểm thông báo bằng văn bản và được doanh nghiệp bảo hiểm đồng ý bằng văn bản, trừ trường hợp việc chuyển giao được thực hiện theo tập quán quốc tế hoặc theo thỏa thuận trong hợp đồng bảo hiểm."},{"key":"C","text":"Việc chuyển nhượng hợp đồng được tự động thực hiện theo thỏa thuận tại hợp đồng bảo hiểm."},{"key":"D","text":"A, B đúng"},{"key":"E","text":"A, C đúng"}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án đúng là **B**: **Bên mua bảo hiểm thông báo bằng văn bản và được doanh nghiệp bảo hiểm đồng ý bằng văn bản, trừ trường hợp việc chuyển giao được thực hiện theo tập quán quốc tế hoặc theo thỏa thuận trong hợp đồng bảo hiểm.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Bên mua bảo hiểm thông báo bằng văn bản và được doanh nghiệp bảo hiểm đồng ý bằng văn bản,…**."},{"id":391,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, bảo hiểm bắt buộc không bao gồm:","options":[{"key":"A","text":"Bảo hiểm cháy, nổ bắt buộc"},{"key":"B","text":"Bảo hiểm Hỏa hoạn và các rủi ro đặc biệt"},{"key":"C","text":"Bảo hiểm bắt buộc trách nhiệm dân sự của chủ xe cơ giới"},{"key":"D","text":"Bảo hiểm bắt buộc trong hoạt động đầu tư xây dựng"}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án đúng là **B**: **Bảo hiểm Hỏa hoạn và các rủi ro đặc biệt**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Bảo hiểm Hỏa hoạn và các rủi ro đặc biệt**."},{"id":392,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phương án nào không phải là điều kiện hoạt động của tổ chức hoạt động đại lý bảo hiểm:","options":[{"key":"A","text":"Được thành lập và hoạt động hợp pháp tại Việt Nam"},{"key":"B","text":"Có nhân viên trực tiếp thực hiện hoạt động đại lý bảo hiểm đáp ứng các điều kiện quy định của pháp luật"},{"key":"C","text":"Ký quỹ và thế chấp tài sản của đại lý bảo hiểm"},{"key":"D","text":"Nhân sự của tổ chức hoạt động đại lý bảo hiểm đáp ứng quy định pháp luật"}],"answer":"C","explanation":"Đây là câu hỏi tìm **phương án ngoại lệ/sai**. Theo đáp án của đề cương, phương án **C** là nội dung không phù hợp: **Ký quỹ và thế chấp tài sản của đại lý bảo hiểm**. Khi làm bài, cần chú ý từ khóa phủ định như **“sai”, “không”, “ngoại trừ”**.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":393,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, doanh nghiệp bảo hiểm có nghĩa vụ nào sau đây trong hoạt động đại lý bảo hiểm:","options":[{"key":"A","text":"Kiểm tra, giám sát việc thực hiện hợp đồng đại lý bảo hiểm, đánh giá chất lượng tư vấn, giới thiệu sản phẩm bảo hiểm của đại lý bảo hiểm và nhân viên trong tổ chức hoạt động đại lý bảo hiểm"},{"key":"B","text":"Trường hợp đại lý bảo hiểm vi phạm hợp đồng đại lý bảo hiểm gây thiệt hại đến quyền, lợi ích hợp pháp của bên mua bảo hiểm thì doanh nghiệp bảo hiểm vẫn phải chịu trách nhiệm thực hiện các nghĩa vụ theo thỏa thuận trong hợp đồng bảo hiểm do đại lý bảo hiểm thu xếp giao kết"},{"key":"C","text":"A, B đúng"}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án đúng là **B**: **Trường hợp đại lý bảo hiểm vi phạm hợp đồng đại lý bảo hiểm gây thiệt hại đến quyền, lợi ích hợp pháp của bên mua bảo hiểm thì doanh nghiệp bảo hiểm vẫn phải chịu trách nhiệm thực hiện các nghĩa vụ theo thỏa thuận trong hợp đồng bảo hiểm do đại lý bảo hiểm thu xếp giao kết**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Trường hợp đại lý bảo hiểm vi phạm hợp đồng đại lý bảo hiểm gây thiệt hại đến quyền, lợi…**."},{"id":394,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Chọn phương án đúng nhất về trách nhiệm bồi thường thiệt hại theo hợp đồng:","options":[{"key":"A","text":"Được xác định trên cơ sở các nghĩa vụ dân sự hình thành theo thỏa thuận giữa các bên trong một hợp đồng."},{"key":"B","text":"Là trách nhiệm phát sinh trên cơ sở các nghĩa vụ dân sự do Bộ luật dân sự quy định cho các chủ thể."},{"key":"C","text":"Bên có nghĩa vụ dân sự không thực hiện hoặc thực hiện không đúng nghĩa vụ dân sự đã cam kết trong hợp đồng thì phải bồi thường cho bên kia."},{"key":"D","text":"A, C đúng."},{"key":"E","text":"B, C đúng."}],"answer":"D","explanation":"Theo đáp án của đề cương, phương án **D** là nội dung đúng: **A, C đúng.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, C đúng.**."},{"id":395,"category":"Kiến thức chung","question":"Chọn phương án đúng nhất về phạm vi bảo hiểm:","options":[{"key":"A","text":"Phạm vi bảo hiểm là giới hạn những rủi ro, tổn thất mà doanh nghiệp bảo hiểm sẽ chịu trách nhiệm bồi thường, trả tiền bảo hiểm nếu xảy ra sự kiện bảo hiểm."},{"key":"B","text":"Phạm vi bảo hiểm là giới hạn những rủi ro, tổn thất và chi phí phát sinh mà doanh nghiệp bảo hiểm sẽ chịu trách nhiệm bồi thường, trả tiền bảo hiểm nếu xảy ra sự kiện bảo hiểm."},{"key":"C","text":"Phạm vi bảo hiểm được căn cứ theo các điều kiện, điều khoản bảo hiểm quy định trong Quy tắc bảo hiểm và các điều khoản sửa đổi, bổ sung (nếu có) kèm theo hợp đồng bảo hiểm."},{"key":"D","text":"A, C đúng."},{"key":"E","text":"B, C đúng."}],"answer":"E","explanation":"Theo đáp án của đề cương, phương án **E** là nội dung đúng: **B, C đúng.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **B, C đúng.**."},{"id":396,"category":"Bảo hiểm xe cơ giới","question":"Theo đơn bảo hiểm thiệt hại vật chất xe cơ giới, chủ xe tham gia bảo hiểm dưới giá trị. Trường hợp xe bị tổn thất toàn bộ, khoản tiền thu được từ việc thanh lý xác xe có được phân bổ cho doanh nghiệp bảo hiểm và người được bảo hiểm theo tỷ lệ tham gia bảo hiểm dưới giá trị không?","options":[{"key":"A","text":"Có"},{"key":"B","text":"Không."}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án **A** là **Có**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Có**."},{"id":397,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Chọn phương án đúng nhất về điều khoản trượt giá 10% (tăng số tiền bảo hiểm) theo quy tắc bảo hiểm của Hiệp hội bảo hiểm Vương quốc Anh (ABI):","options":[{"key":"A","text":"Số tiền bảo hiểm về tài sản trong suốt thời hạn bảo hiểm sẽ tăng đến 10% theo tỉ lệ tương ứng được tính bằng số ngày từ khi bắt đầu thời hạn bảo hiểm cho đến ngày áp dụng chia cho cả thời hạn bảo hiểm."},{"key":"B","text":"Số tiền bảo hiểm về tài sản trong suốt thời hạn bảo hiểm sẽ tăng đến 10% tương ứng với số ngày tăng giá trị bảo hiểm."}],"answer":"A","explanation":"Theo đáp án của đề cương, phương án **A** là nội dung đúng: **Số tiền bảo hiểm về tài sản trong suốt thời hạn bảo hiểm sẽ tăng đến 10% theo tỉ lệ tương ứng được tính bằng số ngày từ khi bắt đầu thời hạn bảo hiểm cho đến ngày áp dụng chia cho cả thời hạn bảo hiểm.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Chốt mốc **10** và gắn với đúng điều kiện của câu."},{"id":398,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Theo đơn bảo hiểm mọi rủi ro xây dựng/lắp đặt (CAR/EAR) của nhà tái bảo hiểm Munich Re, tổn thất vật liệu, trang thiết bị lắp đặt trong khi vận chuyển trên khu vực công trường hay khi lắp đặt, tháo dỡ có được bảo hiểm không?","options":[{"key":"A","text":"Có"},{"key":"B","text":"Không."}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Có**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Có**."},{"id":399,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, chọn phương án đúng nhất về bảo hiểm trùng:","options":[{"key":"A","text":"Đối tượng được bảo hiểm được bảo vệ bằng ít nhất hai hợp đồng bảo hiểm."},{"key":"B","text":"Các hợp đồng bảo hiểm phải có cùng phạm vi, thời hạn và sự kiện bảo hiểm."},{"key":"C","text":"Tổng số tiền bảo hiểm vượt quá giá thị trường của tài sản được bảo hiểm tại thời điểm giao kết hợp đồng bảo hiểm."},{"key":"D","text":"A, B đúng."},{"key":"E","text":"A, B, C đúng."}],"answer":"E","explanation":"Theo đáp án của đề cương, phương án **E** là nội dung đúng: **A, B, C đúng.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng.**."},{"id":400,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, đại lý bảo hiểm không có các nghĩa vụ nào sau đây:","options":[{"key":"A","text":"Thực hiện nghĩa vụ trong hợp đồng đại lý bảo hiểm."},{"key":"B","text":"Quyết định chi trả quyền lợi bảo hiểm theo hợp đồng bảo hiểm"},{"key":"C","text":"Ký quỹ hoặc thế chấp tài sản cho doanh nghiệp bảo hiểm nếu có thỏa thuận trong hợp đồng đại lý bảo hiểm"},{"key":"D","text":"Tư vấn, giới thiệu, chào bán sản phẩm bảo hiểm; cung cấp các thông tin về sản phẩm bảo hiểm, doanh nghiệp bảo hiểm đầy đủ, chính xác cho bên mua bảo hiểm"}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án đúng là **B**: **Quyết định chi trả quyền lợi bảo hiểm theo hợp đồng bảo hiểm**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Quyết định chi trả quyền lợi bảo hiểm theo hợp đồng bảo hiểm**."},{"id":401,"category":"Bảo hiểm con người","question":"Người được bảo hiểm tham gia hợp đồng bảo hiểm sức khỏe với quyền lợi tử vong do tai nạn. Chọn phương án đúng nhất về cách thức doanh nghiệp bảo hiểm giải quyết trong trường hợp người được bảo hiểm tử vong do tai nạn:","options":[{"key":"A","text":"Chi trả 100% số tiền bảo hiểm."},{"key":"B","text":"Chi trả theo nguyên tắc bồi thường."},{"key":"C","text":"Doanh nghiệp bảo hiểm không có quyền yêu cầu người thứ ba bồi hoàn khoản tiền đã trả cho người thụ hưởng trong trường hợp người được bảo hiểm tử vong do lỗi của người thứ ba."},{"key":"D","text":"A, C đúng"},{"key":"E","text":"B, C đúng."}],"answer":"D","explanation":"Theo đáp án của đề cương, phương án **D** là nội dung đúng: **A, C đúng**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, C đúng**."},{"id":402,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, khi xảy ra sự kiện bảo hiểm, doanh nghiệp bảo hiểm phải bồi thường, trả tiền bảo hiểm:","options":[{"key":"A","text":"Theo thời hạn đã thỏa thuận trong hợp đồng bảo hiểm."},{"key":"B","text":"Trong thời hạn 15 ngày kể từ ngày nhận được đầy đủ hồ sơ hợp lệ về yêu cầu bồi thường, trả tiền bảo hiểm (trường hợp không có thỏa thuận về thời hạn)."},{"key":"C","text":"A, B đúng."}],"answer":"C","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **C**: **A, B đúng.**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B đúng.**."},{"id":403,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Đối với bảo hiểm trách nhiệm nghề nghiệp kiến trúc sư, kỹ sư tư vấn, khi tổn thất phát sinh do lỗi thiết kế, lỗi thi công được phát hiện sau thời điểm kết thúc thời hạn bảo hiểm thì tổn thất đó có thuộc trách nhiệm bảo hiểm không:","options":[{"key":"A","text":"Có"},{"key":"B","text":"Không."}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án **B** là **Không.**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Không.**."},{"id":404,"category":"Bảo hiểm xe cơ giới","question":"Theo đơn bảo hiểm trách nhiệm dân sự của chủ xe cơ giới đối với hàng hóa trên xe (không kèm điều khoản sửa đổi bổ sung), trường hợp hàng hóa bị tổn thất trong quá trình xếp dỡ hàng, doanh nghiệp bảo hiểm có bồi thường cho người được bảo hiểm không:","options":[{"key":"A","text":"Có"},{"key":"B","text":"Không."}],"answer":"B","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **B**: **Không.**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Không.**."},{"id":405,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Trong bảo hiểm tài sản, trường hợp áp dụng mức miễn thường không khấu trừ, nếu giá trị tổn thất nhỏ hơn mức miễn thường thì:","options":[{"key":"A","text":"Số tiền bồi thường bằng giá trị tổn thất."},{"key":"B","text":"Số tiền bồi thường bằng giá trị tổn thất trừ đi mức miễn thường."},{"key":"C","text":"Doanh nghiệp bảo hiểm không phải bồi thường."}],"answer":"C","explanation":"Theo đáp án của đề cương, đáp án **C** là **Doanh nghiệp bảo hiểm không phải bồi thường.**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Doanh nghiệp bảo hiểm không phải bồi thường.**."},{"id":406,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, người thụ hưởng là:","options":[{"key":"A","text":"Tổ chức, cá nhân được bên mua bảo hiểm hoặc người được bảo hiểm chỉ định để nhận tiền bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm."},{"key":"B","text":"Tổ chức, cá nhân có tài sản, trách nhiệm dân sự, sức khỏe, tính mạng, nghĩa vụ hoặc lợi ích kinh tế được bảo hiểm theo hợp đồng bảo hiểm."},{"key":"C","text":"A, B đúng"},{"key":"D","text":"A, B sai"}],"answer":"A","explanation":"Khái niệm cần nhớ trong câu này là: **Tổ chức, cá nhân được bên mua bảo hiểm hoặc người được bảo hiểm chỉ định để nhận tiền bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm.**. Đáp án đúng là **A**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Tổ chức, cá nhân được bên mua bảo hiểm hoặc người được bảo hiểm chỉ định để nhận tiền bảo…**."},{"id":407,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phát biểu nào sau đây là sai:","options":[{"key":"A","text":"Đại lý bảo hiểm phải thực hiện nghĩa vụ trong hợp đồng đại lý bảo hiểm."},{"key":"B","text":"Đại lý bảo hiểm không được tranh giành khách hàng dưới các hình thức ngăn cản, lôi kéo, mua chuộc, đe dọa nhân viên hoặc khách hàng của doanh nghiệp bảo hiểm khác."},{"key":"C","text":"Đại lý bảo hiểm có thể sử dụng hoa hồng bảo hiểm để giảm phí cho khách hàng"},{"key":"D","text":"Đại lý bảo hiểm không được xúi giục khách hàng hủy bỏ hợp đồng bảo hiểm đang có hiệu lực dưới mọi hình thức."}],"answer":"C","explanation":"Theo đáp án của đề cương, đáp án đúng là **C**: **Đại lý bảo hiểm có thể sử dụng hoa hồng bảo hiểm để giảm phí cho khách hàng**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":408,"category":"Bảo hiểm con người","question":"Trong bảo hiểm sức khỏe, doanh nghiệp bảo hiểm có chi trả chi phí điều trị trước và sau khi nhập viện do ốm đau, bệnh tật theo chỉ định của bác sỹ không?","options":[{"key":"A","text":"Có"},{"key":"B","text":"Không."}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Có**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Có**."},{"id":409,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, đáp án nào đúng khi điền vào chỗ ____________ trong câu dưới đây:\n\"Doanh nghiệp bảo hiểm, chi nhánh doanh nghiệp bảo hiểm phi nhân thọ nước ngoài có quyền kiểm tra các điều kiện bảo đảm an toàn cho ___________\"","options":[{"key":"A","text":"Đối tượng bảo hiểm."},{"key":"B","text":"Người được bảo hiểm."},{"key":"C","text":"Đại lý bảo hiểm."}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Đối tượng bảo hiểm.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Đối tượng bảo hiểm.**."},{"id":410,"category":"Kiến thức chung","question":"Chọn phương án đúng nhất về phương pháp quản lý rủi ro:","options":[{"key":"A","text":"Né tránh rủi ro."},{"key":"B","text":"Chấp nhận rủi ro."},{"key":"C","text":"Kiểm soát rủi ro."},{"key":"D","text":"Chuyển giao rủi ro."},{"key":"E","text":"A, B, C, D đúng."}],"answer":"E","explanation":"Theo đáp án của đề cương, phương án **E** là nội dung đúng: **A, B, C, D đúng.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C, D đúng.**."},{"id":411,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phát biểu nào dưới đây sai:","options":[{"key":"A","text":"Doanh nghiệp bảo hiểm là doanh nghiệp được thành lập, tổ chức và hoạt động theo quy định của Luật này và luật khác có liên quan để kinh doanh bảo hiểm, kinh doanh tái bảo hiểm, nhượng tái bảo hiểm. Doanh nghiệp bảo hiểm bao gồm doanh nghiệp bảo hiểm nhân thọ, doanh nghiệp bảo hiểm phi nhân thọ, doanh nghiệp bảo hiểm sức khỏe."},{"key":"B","text":"Sự kiện bảo hiểm là sự kiện khách quan do các bên thỏa thuận hoặc pháp luật quy định mà khi sự kiện đó xảy ra thì doanh nghiệp bảo hiểm, chi nhánh doanh nghiệp bảo hiểm phi nhân thọ nước ngoài, tổ chức tương hỗ cung cấp bảo hiểm vi mô phải bồi thường, trả tiền bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm."},{"key":"C","text":"Kinh doanh tái bảo hiểm là hoạt động của doanh nghiệp bảo hiểm nhằm mục đích sinh lợi, theo đó doanh nghiệp bảo hiểm chấp nhận rủi ro của người được bảo hiểm, trên cơ sở bên mua bảo hiểm đóng phí bảo hiểm để doanh nghiệp bảo hiểm trả tiền bảo hiểm cho người thụ hưởng hoặc bồi thường cho người được bảo hiểm khi xảy ra sự kiện bảo hiểm."}],"answer":"C","explanation":"Đây là câu hỏi tìm **phương án ngoại lệ/sai**. Theo đáp án của đề cương, phương án **C** là nội dung không phù hợp: **Kinh doanh tái bảo hiểm là hoạt động của doanh nghiệp bảo hiểm nhằm mục đích sinh lợi, theo đó doanh nghiệp bảo hiểm chấp nhận rủi ro của người được bảo hiểm, trên cơ sở bên mua bảo hiểm đóng phí bảo hiểm để doanh nghiệp bảo hiểm trả tiền bảo hiểm cho người thụ hưởng hoặc bồi thường cho người được bảo hiểm khi xảy ra sự kiện bảo hiểm.**. Khi làm bài, cần chú ý từ khóa phủ định như **“sai”, “không”, “ngoại trừ”**.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":412,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Phát biểu sau là đúng hay sai: \"Đơn bảo hiểm mọi rủi ro lắp đặt (EAR) của nhà tái bảo hiểm Munich Re, tổn thất gián tiếp có nguyên nhân do khuyết tật đúc, tay nghề kém nhưng không phải lỗi trong khi lắp đặt thuộc trách nhiệm bảo hiểm\"","options":[{"key":"A","text":"Đúng."},{"key":"B","text":"Sai."}],"answer":"B","explanation":"Đây là câu hỏi tìm **phương án ngoại lệ/sai**. Theo đáp án của đề cương, phương án **B** là nội dung không phù hợp: **Sai.**. Khi làm bài, cần chú ý từ khóa phủ định như **“sai”, “không”, “ngoại trừ”**.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":413,"category":"Kiến thức chung","question":"Hãy chọn phương án sai:","options":[{"key":"A","text":"Mức miễn thường không khấu trừ có nghĩa là nếu giá trị tổn thất lớn hơn mức miễn thường thì bồi thường toàn bộ giá trị tổn thất."},{"key":"B","text":"Mức miễn thường không khấu trừ có nghĩa là nếu giá trị tổn thất nhỏ hơn mức miễn thường thì doanh nghiệp bảo hiểm không phải bồi thường."},{"key":"C","text":"Mức miễn thường có khấu trừ có nghĩa là nếu giá trị tổn thất lớn hơn mức miễn thường thì bồi thường toàn bộ giá trị tổn thất."},{"key":"D","text":"Mức miễn thường có khấu trừ có nghĩa là nếu giá trị tổn thất lớn hơn mức miễn thường thì số tiền bồi thường bằng giá trị tổn thất trừ đi mức miễn thường."}],"answer":"C","explanation":"Theo đáp án của đề cương, đáp án đúng là **C**: **Mức miễn thường có khấu trừ có nghĩa là nếu giá trị tổn thất lớn hơn mức miễn thường thì bồi thường toàn bộ giá trị tổn thất.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":414,"category":"Kiến thức chung","question":"Chọn phương án đúng nhất về trách nhiệm bồi thường thiệt hại ngoài hợp đồng:","options":[{"key":"A","text":"Được xác định trên cơ sở các nghĩa vụ dân sự hình thành theo thỏa thuận giữa các bên trong một hợp đồng."},{"key":"B","text":"Là trách nhiệm phát sinh trên cơ sở các nghĩa vụ dân sự do Bộ luật dân sự quy định cho các chủ thể."},{"key":"C","text":"Hành vi gây hại không liên quan đến việc thực hiện nghĩa vụ dân sự của bất kỳ hợp đồng nào. Việc xác định trách nhiệm bồi thường dựa trên cơ sở quy định chung của Bộ luật dân sự."},{"key":"D","text":"A, C đúng."},{"key":"E","text":"B, C đúng."}],"answer":"E","explanation":"Theo đáp án của đề cương, phương án **E** là nội dung đúng: **B, C đúng.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **B, C đúng.**."},{"id":415,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Theo quy tắc bảo hiểm “Gián đoạn kinh doanh” của Hiệp hội bảo hiểm Vương quốc Anh (ABI), chọn phương án đúng nhất về đối tượng bảo hiểm:","options":[{"key":"A","text":"Mất thị trường."},{"key":"B","text":"Sụt giảm doanh thu do hậu quả của thiệt hại được bảo hiểm."},{"key":"C","text":"Chi phí hoạt động gia tăng nhằm hạn chế mức độ suy giảm doanh thu do hậu quả của thiệt hại được bảo hiểm gây ra."},{"key":"D","text":"A, C đúng."},{"key":"E","text":"B, C đúng."}],"answer":"E","explanation":"Theo đáp án của đề cương, phương án **E** là nội dung đúng: **B, C đúng.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **B, C đúng.**."},{"id":416,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phát biểu nào sau đây là đúng nhất về đối tượng của hợp đồng bảo hiểm trách nhiệm dân sự:","options":[{"key":"A","text":"Trách nhiệm dân sự của doanh nghiệp bảo hiểm đối với tài sản của người thứ ba"},{"key":"B","text":"Trách nhiệm dân sự của người được bảo hiểm đối với người thứ ba theo quy định của pháp luật."},{"key":"C","text":"Trách nhiệm dân sự của doanh nghiệp bảo hiểm đối với thiệt hại của người được bảo hiểm theo quy định của pháp luật."},{"key":"D","text":"Trách nhiệm dân sự của người được bảo hiểm đối với thiệt hại vật chất, tinh thần của người thứ ba"}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án đúng là **B**: **Trách nhiệm dân sự của người được bảo hiểm đối với người thứ ba theo quy định của pháp luật.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Trách nhiệm dân sự của người được bảo hiểm đối với người thứ ba theo quy định của pháp luật.**."},{"id":417,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Phương án nào sau đây không thuộc phạm vi bảo hiểm khi Máy móc thiết bị chủ thầu (CPM) bảo hiểm theo năm:","options":[{"key":"A","text":"Bảo hiểm tổn thất máy móc, thiết bị trong quá trình thực hiện công việc trên tất cả các công trình dự án."},{"key":"B","text":"Bảo hiểm tổn thất máy móc, thiết bị được tập kết trong kho bãi của chủ thầu."},{"key":"C","text":"Bảo hiểm tổn thất máy móc, thiết bị trong quá trình lưu hành trên công lộ."},{"key":"D","text":"B,C đúng."}],"answer":"C","explanation":"Đây là câu hỏi tìm **phương án ngoại lệ/sai**. Theo đáp án của đề cương, phương án **C** là nội dung không phù hợp: **Bảo hiểm tổn thất máy móc, thiết bị trong quá trình lưu hành trên công lộ.**. Khi làm bài, cần chú ý từ khóa phủ định như **“sai”, “không”, “ngoại trừ”**.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":418,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, chọn phương án đúng nhất về giới hạn trách nhiệm bảo hiểm trong hợp đồng bảo hiểm trách nhiệm dân sự:","options":[{"key":"A","text":"Giới hạn trách nhiệm bảo hiểm là giới hạn những rủi ro được bảo hiểm và rủi ro không được bảo hiểm."},{"key":"B","text":"Giới hạn trách nhiệm bảo hiểm là số tiền mà doanh nghiệp bảo hiểm phải trả cho bên thứ ba."},{"key":"C","text":"Giới hạn trách nhiệm bảo hiểm là giá trị tổn thất mà dưới mức đó doanh nghiệp bảo hiểm không phải trả cho người được bảo hiểm."},{"key":"D","text":"Giới hạn trách nhiệm bảo hiểm là số tiền mà doanh nghiệp bảo hiểm phải trả cho người được bảo hiểm theo thoả thuận trong hợp đồng bảo hiểm."}],"answer":"D","explanation":"Theo đáp án của đề cương, phương án **D** là nội dung đúng: **Giới hạn trách nhiệm bảo hiểm là số tiền mà doanh nghiệp bảo hiểm phải trả cho người được bảo hiểm theo thoả thuận trong hợp đồng bảo hiểm.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Giới hạn trách nhiệm bảo hiểm là số tiền mà doanh nghiệp bảo hiểm phải trả cho người được…**."},{"id":419,"category":"Bảo hiểm xe cơ giới","question":"Trong thời hạn bảo hiểm của hợp đồng bảo hiểm thiệt hại vật chất xe ô tô, trường hợp xe để trong garage bị cháy toàn bộ do chập ắc quy, doanh nghiệp bảo hiểm chi trả bồi thường như  thế nào:","options":[{"key":"A","text":"Bồi thường toàn bộ xe."},{"key":"B","text":"Bồi thường toàn bộ xe trừ ắc quy."}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án **B** là **Bồi thường toàn bộ xe trừ ắc quy.**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Bồi thường toàn bộ xe trừ ắc quy.**."},{"id":420,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Đơn bảo hiểm mọi rủi ro xây dựng/lắp đặt (CAR/EAR) của nhà tái bảo hiểm Munich Re: Trong thời hạn xây dựng.lắp đặt, công trình bị tổn thất bất ngờ và gây tổn thất cho bên thứ ba. Tổn thất đối với tài sản của bên thứ ba thuộc trách nhiệm bảo hiểm được hiểu thế nào là đúng:","options":[{"key":"A","text":"Là tổn thất vật chất đối với tài sản (nhà cửa, máy móc thiết bị, đồ đạc, hàng hóa) của bên thứ ba."},{"key":"B","text":"Là tổn thất mất thu nhập gây ra cho bên thứ ba"},{"key":"C","text":"A, B đúng"}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án **A** là **Là tổn thất vật chất đối với tài sản (nhà cửa, máy móc thiết bị, đồ đạc, hàng hóa) của bên thứ ba.**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Là tổn thất vật chất đối với tài sản (nhà cửa, máy móc thiết bị, đồ đạc, hàng hóa) của bên…**."},{"id":421,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Theo đơn bảo hiểm “Hỏa hoạn và các rủi ro đặc biệt” của Hiệp hội bảo hiểm Vương quốc Anh (ABI), rủi ro nào sau đây không thuộc phạm vi bảo hiểm của Nhóm rủi ro H - “Giông, bão, lụt”:","options":[{"key":"A","text":"Nước mưa hắt vào nhà qua cửa sổ không đóng."},{"key":"B","text":"Các công trình đang xây dựng cải tạo, có các ô mở đã được hoàn tất để bảo vệ, chống lại giông bão."},{"key":"C","text":"Nước biển tràn vào nhà do bão."},{"key":"D","text":"Nước mưa tràn vào nhà thông qua các chỗ hở trên phần kết cấu của tòa nhà mà những chỗ hở này được tạo ra bởi tác động trực tiếp của giông, bão."}],"answer":"A","explanation":"Đây là câu hỏi tìm **phương án ngoại lệ/sai**. Theo đáp án của đề cương, phương án **A** là nội dung không phù hợp: **Nước mưa hắt vào nhà qua cửa sổ không đóng.**. Khi làm bài, cần chú ý từ khóa phủ định như **“sai”, “không”, “ngoại trừ”**.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":422,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, đối tượng nào sau đây không phải mua bảo hiểm trách nhiệm nghề nghiệp:","options":[{"key":"A","text":"Doanh nghiệp Tái bảo hiểm."},{"key":"B","text":"Đại lý bảo hiểm"},{"key":"C","text":"Doanh nghiệp Môi giới bảo hiểm."},{"key":"D","text":"Tổ chức cung cấp dịch vụ phụ trợ bảo hiểm"},{"key":"E","text":"A, B đúng"}],"answer":"E","explanation":"Đây là câu hỏi tìm **phương án ngoại lệ/sai**. Theo đáp án của đề cương, phương án **E** là nội dung không phù hợp: **A, B đúng**. Khi làm bài, cần chú ý từ khóa phủ định như **“sai”, “không”, “ngoại trừ”**.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":423,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, trong bảo hiểm trách nhiệm dân sự:","options":[{"key":"A","text":"Người thứ ba không có quyền trực tiếp yêu cầu doanh nghiệp bảo hiểm, chi nhánh doanh nghiệp bảo hiểm phi nhân thọ nước ngoài bồi thường, trừ trường hợp pháp luật có quy định khác"},{"key":"B","text":"Người thứ ba được trực tiếp yêu cầu doanh nghiệp bảo hiểm bồi thường."},{"key":"C","text":"Doanh nghiệp bảo hiểm có quyền thay mặt người được bảo hiểm để thương lượng với người thứ ba về mức độ bồi thường thiệt hại, trừ trường hợp có thỏa thuận khác trong hợp đồng bảo hiểm."},{"key":"D","text":"A, C đúng."}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **A, C đúng.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, C đúng.**."},{"id":424,"category":"Kiến thức chung","question":"Nguyên tắc nào không phải là nguyên tắc cơ bản của bảo hiểm:","options":[{"key":"A","text":"Quyền lợi có thể được bảo hiểm"},{"key":"B","text":"Nguyên tắc thế quyền"},{"key":"C","text":"Nguyên tắc phân tán rủi ro"},{"key":"D","text":"Nguyên tắc trung thực tuyệt đối"}],"answer":"C","explanation":"Đây là câu hỏi tìm **phương án ngoại lệ/sai**. Theo đáp án của đề cương, phương án **C** là nội dung không phù hợp: **Nguyên tắc phân tán rủi ro**. Khi làm bài, cần chú ý từ khóa phủ định như **“sai”, “không”, “ngoại trừ”**.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":425,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Dự án X được thi công bởi 2 nhà thầu A và B; dự án được bảo hiểm theo Đơn bảo hiểm mọi rủi ro xây dựng CAR của nhà tái bảo hiểm Munich Re (Không có điều khoản Sửa đổi bổ sung) gồm: Phần I – Tổn thất vật chất: Giá trị công trình, máy móc thiết bị chủ thầu CPM. Phần II – Trách nhiệm đối với bên thứ ba. Trong quá trình thi công, xe cẩu của nhà thầu A bất ngờ bị đổ, hỏng và gây tổn thất cho máy xúc nhà thầu B và khách thăm quan công trình. Những tổn thất nào sau đây thuộc trách nhiệm bảo hiểm theo Đơn bảo hiểm mọi rủi ro xây dựng CAR:","options":[{"key":"A","text":"Cần cẩu của nhà thầu A"},{"key":"B","text":"Máy xúc của nhà thầu B"},{"key":"C","text":"Khách thăm quan công trình"},{"key":"D","text":"A, B, C đúng"}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **A, B, C đúng**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng**."},{"id":426,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, đáp án nào đúng khi điền vào chỗ _________ trong câu dưới đây: “Doanh nghiệp bảo hiểm, chi nhánh doanh nghiệp bảo hiểm phi nhân thọ nước ngoài có quyền kiểm tra các điều kiện đảm bảo an toàn cho _______”","options":[{"key":"A","text":"Đối tượng bảo hiểm."},{"key":"B","text":"Người được bảo hiểm"},{"key":"C","text":"Đại lý bảo hiểm"}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Đối tượng bảo hiểm.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Đối tượng bảo hiểm.**."},{"id":427,"category":"Bảo hiểm xe cơ giới","question":"Trường hợp lái xe A tham gia bảo hiểm tai nạn lái, phụ xe và người ngồi trên xe ở hai doanh nghiệp bảo hiểm (DNBH) X và DNBH Y. Trong thời hạn bảo hiểm, lái xe A bị tai nạn dẫn đến tử vong. Trường hợp này, các DNBH sẽ chi trả như thế nào:","options":[{"key":"A","text":"DNBH X và DNBH Y chi trả theo tỷ lệ giữa số tiền bảo hiểm của từng hợp đồng bảo hiểm trên tổng số tiền bảo hiểm của hai hợp đồng bảo hiểm."},{"key":"B","text":"Cả DNBH X và DNBH Y đều chi trả 100% số tiền bảo hiểm đã thỏa thuận tại hợp đồng bảo hiểm."},{"key":"C","text":"DNBH nào có hợp đồng bảo hiểm với số tiền bảo hiểm lớn hơn thực hiện chi trả."},{"key":"D","text":"Chi trả theo hợp đồng bảo hiểm giao kết trước."}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án **B** là **Cả DNBH X và DNBH Y đều chi trả 100% số tiền bảo hiểm đã thỏa thuận tại hợp đồng bảo hiểm.**. Mốc cần nhớ: **100**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Chốt mốc **100** và gắn với đúng điều kiện của câu."},{"id":428,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Theo đơn bảo hiểm “Gián đoạn kinh doanh” của Hiệp hội bảo hiểm Vương quốc Anh (ABI), hạn mức bồi thường đối với chi phí hoạt động gia tăng thêm ngoài chi phí hoạt động gia tăng thuộc hạng mục Lợi nhuận gộp là:","options":[{"key":"A","text":"Không giới hạn"},{"key":"B","text":"Số tiền được tính bằng cách lấy tỷ lệ lợi nhuận gộp nhân với số doanh thu khôi phục lại nhờ các chi phí đó"},{"key":"C","text":"Hạn mức riêng được quy định trong hợp đồng bảo hiểm ngoài số tiền bảo hiểm về lợi nhuận gộp."}],"answer":"C","explanation":"Khái niệm cần nhớ trong câu này là: **Hạn mức riêng được quy định trong hợp đồng bảo hiểm ngoài số tiền bảo hiểm về lợi nhuận gộp.**. Đáp án đúng là **C**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Hạn mức riêng được quy định trong hợp đồng bảo hiểm ngoài số tiền bảo hiểm về lợi nhuận gộp.**."},{"id":429,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, trong bảo hiểm sức khỏe, trường hợp người được bảo hiểm chết, thương tật hoặc đau ốm do hành vi trực tiếp hoặc gián tiếp của người thứ ba gây ra, doanh nghiệp bảo hiểm có nghĩa vụ bồi thường, trả tiền bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm và:","options":[{"key":"A","text":"Không có quyền yêu cầu người thứ ba bồi hoàn khoản tiền mà doanh nghiệp bảo hiểm đã trả cho người thụ hưởng"},{"key":"B","text":"Có quyền yêu cầu người thứ ba bồi hoàn khoản tiền mà doanh nghiệp bảo hiểm đã trả cho người thụ hưởng"},{"key":"C","text":"Không được yêu cầu bồi hoàn trong trường hợp người thứ ba không đồng ý"},{"key":"D","text":"Không được yêu cầu bồi hoàn khi người được bảo hiểm còn sống"}],"answer":"A","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **A**: **Không có quyền yêu cầu người thứ ba bồi hoàn khoản tiền mà doanh nghiệp bảo hiểm đã trả cho người thụ hưởng**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Không có quyền yêu cầu người thứ ba bồi hoàn khoản tiền mà doanh nghiệp bảo hiểm đã trả cho…**."},{"id":430,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật kinh doanh bảo hiểm, những loại hợp đồng nào sau đây thuộc loại hình bảo hiểm phi nhân thọ?","options":[{"key":"A","text":"Hợp đồng bảo hiểm chi phí y tế; hợp đồng bảo hiểm tài sản; hợp đồng bảo hiểm trách nhiệm"},{"key":"B","text":"Hợp đồng bảo hiểm tài sản; hợp đồng bảo hiểm thiệt hại; hợp đồng bảo hiểm trách nhiệm"},{"key":"C","text":"Hợp đồng bảo hiểm sức khỏe dưới 01 năm; hợp đồng bảo hiểm tài sản; hợp đồng bảo hiểm trách nhiệm"},{"key":"D","text":"Hợp đồng bảo hiểm sức khỏe dưới 01 năm; hợp đồng bảo hiểm tài sản và thiệt hại; hợp đồng bảo hiểm trách nhiệm"}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án đúng là **B**: **Hợp đồng bảo hiểm tài sản; hợp đồng bảo hiểm thiệt hại; hợp đồng bảo hiểm trách nhiệm**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Hợp đồng bảo hiểm tài sản; hợp đồng bảo hiểm thiệt hại; hợp đồng bảo hiểm trách nhiệm**."},{"id":431,"category":"Kiến thức chung","question":"Ông A mua cổ phiếu của Công ty xây dựng X trên thị trường chứng khoán. Rủi ro biến động giá cổ phiếu này là:","options":[{"key":"A","text":"Rủi ro có thể được bảo hiểm"},{"key":"B","text":"Rủi ro thuần túy"},{"key":"C","text":"Rủi ro chung"},{"key":"D","text":"Rủi ro đầu cơ"}],"answer":"D","explanation":"Khái niệm cần nhớ trong câu này là: **Rủi ro đầu cơ**. Đáp án đúng là **D**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Rủi ro đầu cơ**."},{"id":432,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Các chi phí nào sau đây không phải là đối tượng được bảo hiểm trong Quy tắc bảo hiểm Gián đoạn kinh doanh của Hiệp hội bảo hiểm Vương quốc Anh (ABI):","options":[{"key":"A","text":"Nguyên vật liệu dùng cho sản xuất"},{"key":"B","text":"Chi phí đóng gói, vận chuyển hàng hóa"},{"key":"C","text":"Tiền lương để duy trì bộ máy làm việc"},{"key":"D","text":"A, B đúng"},{"key":"E","text":"A, C đúng"}],"answer":"D","explanation":"Đây là câu hỏi tìm **phương án ngoại lệ/sai**. Theo đáp án của đề cương, phương án **D** là nội dung không phù hợp: **A, B đúng**. Khi làm bài, cần chú ý từ khóa phủ định như **“sai”, “không”, “ngoại trừ”**.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":433,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Bảo hiểm trách nhiệm trên cơ sở khiếu nại được lập là loại hình bảo hiểm theo đó khiếu nại của người thứ ba đối với người được bảo hiểm có thể được lập sau thời gian hiệu lực của hợp đồng bảo hiểm, doanh nghiệp bảo hiểm phải xem xét bồi thường mặc dù sự kiện bảo hiểm xảy ra trong hoặc trước thời hạn bảo hiểm (trong thời gian hồi tố).","options":[{"key":"A","text":"Đúng"},{"key":"B","text":"Sai"}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án **B** là **Sai**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Sai**."},{"id":434,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Theo quy tắc bảo hiểm “Gián đoạn kinh doanh” của Hiệp hội bảo hiểm Vương quốc Anh (ABI), “Doanh thu tiêu chuẩn” là:","options":[{"key":"A","text":"Doanh thu của năm trước liền kề với năm bảo hiểm"},{"key":"B","text":"Doanh thu của 12 tháng ngay trước ngày xảy ra thiệt hại"},{"key":"C","text":"Doanh thu của giai đoạn tương ứng với thời hạn bồi thường trong 12 tháng ngay trước thời điểm xảy ra thiệt hại"},{"key":"D","text":"Doanh thu của giai đoạn tương ứng với thời hạn bồi thường trong 12 tháng ngay trước thời điểm xảy ra thiệt hại và được điều chỉnh để phản ánh những xu hướng, thay đổi trong hoạt động kinh doanh trước hoặc sau khi xảy ra thiệt hại, hoặc ảnh hưởng tới hoạt động kinh doanh nếu không xảy ra thiệt hại."}],"answer":"B","explanation":"Khái niệm cần nhớ trong câu này là: **Doanh thu của 12 tháng ngay trước ngày xảy ra thiệt hại**. Đáp án đúng là **B**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Chốt mốc **12 tháng** và gắn với đúng điều kiện của câu."},{"id":435,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật kinh doanh bảo hiểm, trong bảo hiểm sức khỏe, điều kiện về nhóm tham gia hợp đồng bảo hiểm nhóm phải là nhóm như thế nào?","options":[{"key":"A","text":"Là nhóm đã được hình thành không phải vì mục đích tham gia bảo hiểm"},{"key":"B","text":"Là nhóm đã được hình thành vì mục đích tham gia bảo hiểm"},{"key":"C","text":"Là nhóm đã được hình thành không phải vì lợi ích chung của các thành viên"},{"key":"D","text":"Là nhóm đã được hình thành mà các thành viên phải là người trong gia đình"}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Là nhóm đã được hình thành không phải vì mục đích tham gia bảo hiểm**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Là nhóm đã được hình thành không phải vì mục đích tham gia bảo hiểm**."},{"id":436,"category":"Kiến thức chung","question":"Bảo hiểm là biện pháp chuyển giao rủi ro và được thực hiện thông qua:","options":[{"key":"A","text":"Giấy yêu cầu bảo hiểm"},{"key":"B","text":"Hợp đồng bảo hiểm"},{"key":"C","text":"Bản chào phí của doanh nghiệp bảo hiểm"},{"key":"D","text":"Báo cáo đánh giá rủi ro của doanh nghiệp bảo hiểm"}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án đúng là **B**: **Hợp đồng bảo hiểm**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Hợp đồng bảo hiểm**."},{"id":437,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Giá trị thực tế của các công trình kiến trúc và máy móc, thiết bị để tham gia bảo hiểm là:","options":[{"key":"A","text":"Giá trị theo sổ sách kế toán"},{"key":"B","text":"Giá trị nếu được thay thế mới hay mua mới ban đầu trừ đi phần giảm giá trị do hao mòn, xuống cấp theo thời gian và mức độ sử dụng, khai thác"},{"key":"C","text":"Giá trị nếu được thay thế mới hay mua mới ở hiện tại trừ đi phần giảm giá trị do hao mòn, xuống cấp theo thời gian và mức độ sử dụng, khai thác"},{"key":"D","text":"A, C đúng"}],"answer":"C","explanation":"Khái niệm cần nhớ trong câu này là: **Giá trị nếu được thay thế mới hay mua mới ở hiện tại trừ đi phần giảm giá trị do hao mòn, xuống cấp theo thời gian và mức độ sử dụng, khai thác**. Đáp án đúng là **C**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Giá trị nếu được thay thế mới hay mua mới ở hiện tại trừ đi phần giảm giá trị do hao mòn,…**."},{"id":438,"category":"Bảo hiểm con người","question":"Theo pháp luật Việt Nam về kinh doanh bảo hiểm, trong bảo hiểm bắt buộc trách nhiệm dân sự của chủ xe cơ giới, trường hợp chưa xác định được vụ tai nạn thuộc phạm vi bồi thường thiệt hại, doanh nghiệp bảo hiểm phải tạm ứng bồi thường đối với thiệt hại về sức khỏe, tính mạng là bao nhiêu % giới hạn trách nhiệm bảo hiểm theo quy định cho một người trong một vụ tai nạn đối với trường hợp ước tính tỷ lệ tổn thương từ 31% đến dưới 81%:","options":[{"key":"A","text":"10%"},{"key":"B","text":"30%"},{"key":"C","text":"50%"},{"key":"D","text":"70%"}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án **A** là **10%**. Mốc cần nhớ: **10**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Chốt mốc **10** và gắn với đúng điều kiện của câu."},{"id":439,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật kinh doanh bảo hiểm, thời hạn nộp hồ sơ yêu cầu bồi thường, trả tiền bảo hiểm theo hợp đồng bảo hiểm là:","options":[{"key":"A","text":"01 năm kể từ ngày xảy ra sự kiện bảo hiểm. Thời gian xảy ra sự kiện bất khả kháng hoặc trở ngại khách quan không tính vào thời hạn nộp hồ sơ yêu cầu bồi thường, trả tiền bảo hiểm"},{"key":"B","text":"01 năm kể từ ngày người được bảo hiểm thông báo cho doanh nghiệp bảo hiểm về việc xảy ra sự kiện bảo hiểm. Thời gian xảy ra sự kiện bất khả kháng hoặc trở ngại khách quan không tính vào thời hạn nộp hồ sơ yêu cầu bồi thường, trả tiền bảo hiểm."},{"key":"C","text":"A, B đúng"}],"answer":"A","explanation":"Khái niệm cần nhớ trong câu này là: **01 năm kể từ ngày xảy ra sự kiện bảo hiểm. Thời gian xảy ra sự kiện bất khả kháng hoặc trở ngại khách quan không tính vào thời hạn nộp hồ sơ yêu cầu bồi thường, trả tiền bảo hiểm**. Đáp án đúng là **A**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Chốt mốc **01 năm** và gắn với đúng điều kiện của câu."},{"id":440,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, trong hợp đồng bảo hiểm tài sản, trừ trường hợp có thỏa thuận khác trong hợp đồng bảo hiểm, cơ sở để xác định số tiền bồi thường mà doanh nghiệp bảo hiểm phải trả cho người được bảo hiểm là:","options":[{"key":"A","text":"Giá thị trường của tài sản được bảo hiểm tại thời điểm, nơi xảy ra tổn thất, mức độ thiệt hại thực tế"},{"key":"B","text":"Giá thị trường của tài sản được bảo hiểm tại thời điểm tham gia bảo hiểm và mức độ thiệt hại thực tế"},{"key":"C","text":"Giá trị sổ sách của tài sản được bảo hiểm tại thời điểm tham gia bảo hiểm và mức độ thiệt hại thực tế"},{"key":"D","text":"Giá trị thỏa thuận"}],"answer":"A","explanation":"Khái niệm cần nhớ trong câu này là: **Giá thị trường của tài sản được bảo hiểm tại thời điểm, nơi xảy ra tổn thất, mức độ thiệt hại thực tế**. Đáp án đúng là **A**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Giá thị trường của tài sản được bảo hiểm tại thời điểm, nơi xảy ra tổn thất, mức độ thiệt…**."},{"id":441,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, sản phẩm bảo hiểm nào sao đây không phải là bảo hiểm bắt buộc? (chọn Phương án đúng nhất)","options":[{"key":"A","text":"Bảo hiểm bắt buộc trách nhiệm công cộng"},{"key":"B","text":"ph"},{"key":"C","text":"Bảo hiểm bắt buộc trách nhiệm nghề nghiệp môi giới tái bảo hiểm"},{"key":"D","text":"A, B, C đúng"}],"answer":"D","explanation":"Đây là câu hỏi tìm **phương án ngoại lệ/sai**. Theo đáp án của đề cương, phương án **D** là nội dung không phù hợp: **A, B, C đúng**. Khi làm bài, cần chú ý từ khóa phủ định như **“sai”, “không”, “ngoại trừ”**.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":442,"category":"Bảo hiểm xe cơ giới","question":"Chọn Phương án đúng nhất: Theo pháp luật Việt Nam về kinh doanh bảo hiểm, trong bảo hiểm bắt buộc trách nhiệm dân sự của chủ xe cơ giới, doanh nghiệp bảo hiểm có quyền giảm trừ tối đa 5% số tiền bồi thường thiệt hại đối với tài sản trong trường hợp:","options":[{"key":"A","text":"Bên mua bảo hiểm, người được bảo hiểm không thông báo tai nạn cho doanh nghiệp bảo hiểm trong thời hạn quy định"},{"key":"B","text":"Sau khi xảy ra sự kiện bảo hiểm, doanh nghiệp bảo hiểm phát hiện trong quá trình thực hiện hợp đồng bảo hiểm, bên mua bảo hiểm, người được bảo hiểm không thực hiện nghĩa vụ thông báo khi có sự thay đổi những yếu tố làm cơ sở để tính phí bảo hiểm, dẫn đến tăng các rủi ro được bảo hiểm."},{"key":"C","text":"Sau khi xảy ra sự kiện bảo hiểm, doanh nghiệp bảo hiểm phát hiện trong quá trình thực hiện hợp đồng bảo hiểm, bên mua bảo hiểm, người được bảo hiểm không thực hiện nghĩa vụ thông báo khi có sự thay đổi những yếu tố làm cơ sở để tính phí bảo hiểm, dẫn đến tăng hoặc giảm các rủi ro được bảo hiểm."},{"key":"D","text":"A, B đúng"},{"key":"E","text":"A, C đúng"}],"answer":"D","explanation":"Theo đáp án của đề cương, phương án **D** là nội dung đúng: **A, B đúng**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B đúng**."},{"id":443,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, doanh nghiệp bảo hiểm được quyền chi trả hoa hồng đại lý bảo hiểm cho đại lý bảo hiểm theo quy định của:","options":[{"key":"A","text":"Doanh nghiệp bảo hiểm"},{"key":"B","text":"Cục Quản lý, giám sát bảo hiểm"},{"key":"C","text":"Bộ trưởng Bộ Tài chính"},{"key":"D","text":"Chính phủ"}],"answer":"C","explanation":"Theo đáp án của đề cương, đáp án đúng là **C**: **Bộ trưởng Bộ Tài chính**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Bộ trưởng Bộ Tài chính**."},{"id":444,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, đối với hợp đồng bảo hiểm sức khỏe, bên mua bảo hiểm không có quyền lợi có thể được bảo hiểm đối với trường hợp nào dưới đây?","options":[{"key":"A","text":"Người có quyền lợi về tài chính hoặc quan hệ lao động với bên mua bảo hiểm"},{"key":"B","text":"Anh ruột, chị ruột, em ruột hoặc người khác có quan hệ nuôi dưỡng, cấp dưỡng với bên mua bảo hiểm"},{"key":"C","text":"Người được bảo hiểm đồng ý bằng văn bản cho bên mua bảo hiểm mua bảo hiểm sức khỏe cho mình"},{"key":"D","text":"Ông/bà của bên mua bảo hiểm"}],"answer":"D","explanation":"Đây là câu hỏi tìm **phương án ngoại lệ/sai**. Theo đáp án của đề cương, phương án **D** là nội dung không phù hợp: **Ông/bà của bên mua bảo hiểm**. Khi làm bài, cần chú ý từ khóa phủ định như **“sai”, “không”, “ngoại trừ”**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Ông/bà của bên mua bảo hiểm**."},{"id":445,"category":"Bảo hiểm con người","question":"Theo pháp luật Việt Nam về kinh doanh bảo hiểm, trong bảo hiểm sức khỏe, trường hợp doanh nghiệp bảo hiểm bổ sung thêm các dấu hiệu, triệu chứng đặc thù của bệnh có sẵn trong các điều kiện, điều khoản bảo hiểm thì chỉ được xem xét đến các dấu hiệu, triệu chứng khởi phát trong vòng bao nhiêu tháng trước ngày hiệu lực hoặc ngày khôi phục hiệu lực (gần nhất) của hợp đồng bảo hiểm?","options":[{"key":"A","text":"12 tháng"},{"key":"B","text":"24 tháng"},{"key":"C","text":"36 tháng"},{"key":"D","text":"60 tháng"}],"answer":"C","explanation":"Theo đáp án của đề cương, đáp án **C** là **36 tháng**. Mốc cần nhớ: **36 tháng**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Chốt mốc **36 tháng** và gắn với đúng điều kiện của câu."},{"id":446,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Phương án nào sau đây không thuộc điểm loại trừ của bảo hiểm trách nhiệm nghề nghiệp:","options":[{"key":"A","text":"Các khoản tiền phạt"},{"key":"B","text":"Khiếu nại được đưa ra lần đầu tiên và được thông báo cho doanh nghiệp bảo hiểm trong thời hạn bảo hiểm"},{"key":"C","text":"Các khiếu nại thuộc các công việc khác ngoài lĩnh vực chuyên môn"},{"key":"D","text":"Các khiếu nại mà Người được bảo hiểm đã biết tại thời điểm giao kết hợp đồng bảo hiểm"}],"answer":"B","explanation":"Đây là câu hỏi tìm **phương án ngoại lệ/sai**. Theo đáp án của đề cương, phương án **B** là nội dung không phù hợp: **Khiếu nại được đưa ra lần đầu tiên và được thông báo cho doanh nghiệp bảo hiểm trong thời hạn bảo hiểm**. Khi làm bài, cần chú ý từ khóa phủ định như **“sai”, “không”, “ngoại trừ”**.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":447,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Đối tượng bảo hiểm các công trình dân dụng đã hoàn thành (CECR) là các công trình dân dụng đã kết thúc giai đoạn xây dựng/lắp đặt và được đưa vào sử dụng. Phát biểu này đúng hay sai:","options":[{"key":"A","text":"Đúng"},{"key":"B","text":"Sai"}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Đúng**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":448,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, chọn Phương án sai về nghĩa vụ của bên mua bảo hiểm trong hợp đồng bảo hiểm sức khỏe.","options":[{"key":"A","text":"Kê khai đầy đủ, trung thực mọi thông tin có liên quan đến hợp đồng bảo hiểm theo yêu cầu của doanh nghiệp bảo hiểm"},{"key":"B","text":"Đóng phí bảo hiểm đầy đủ, đúng hạn theo thỏa thuận trong hợp đồng bảo hiểm"},{"key":"C","text":"Thông báo cho doanh nghiệp bảo hiểm về việc xảy ra sự kiện bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm; phối hợp với doanh nghiệp bảo hiểm trong giám định tổn thất"},{"key":"D","text":"Yêu cầu doanh nghiệp bảo hiểm cấp hóa đơn thu phí bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm và quy định của pháp luật có liên quan"}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **Yêu cầu doanh nghiệp bảo hiểm cấp hóa đơn thu phí bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm và quy định của pháp luật có liên quan**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":449,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật kinh doanh bảo hiểm, trong hoạt động đại lý bảo hiểm, doanh nghiệp bảo hiểm có quyền:","options":[{"key":"A","text":"Tuyển dụng đại lý bảo hiểm và giao kết hợp đồng đại lý bảo hiểm, quyết định mức chi trả hoa hồng đại lý bảo hiểm trong hợp đồng đại lý bảo hiểm không vượt quá mức tối đa theo quy định của Bộ trưởng Bộ Tài chính"},{"key":"B","text":"Không phải chịu trách nhiệm về hợp đồng bảo hiểm do đại lý thu xếp, giao kết trong trường hợp đại lý bảo hiểm vi phạm hợp đồng đại lý bảo hiểm, gây thiệt hại đến quyền, lợi ích hợp pháp của người được bảo hiểm."},{"key":"C","text":"Nhận và quản lý tiền ký quỹ hoặc tài sản thế chấp của đại lý bảo hiểm trong mọi trường hợp"},{"key":"D","text":"Tuyển dụng đại lý bảo hiểm và giao kết hợp đồng đại lý bảo hiểm, chủ động quyết định mức chi trả hoa hồng đại lý bảo hiểm trong hợp đồng đại lý bảo hiểm"}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Tuyển dụng đại lý bảo hiểm và giao kết hợp đồng đại lý bảo hiểm, quyết định mức chi trả hoa hồng đại lý bảo hiểm trong hợp đồng đại lý bảo hiểm không vượt quá mức tối đa theo quy định của Bộ trưởng Bộ Tài chính**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Tuyển dụng đại lý bảo hiểm và giao kết hợp đồng đại lý bảo hiểm, quyết định mức chi trả hoa…**."},{"id":450,"category":"Bảo hiểm xe cơ giới","question":"Theo đơn Bảo hiểm trách nhiệm dân sự của chủ xe cơ giới đối với hàng hóa trên xe: Trường hợp xe cơ giới chở hàng hóa và bị mất cắp toàn bộ (cả xe và hàng), doanh nghiệp bảo hiểm có bồi thường cho người được bảo hiểm không?","options":[{"key":"A","text":"Có"},{"key":"B","text":"Không"}],"answer":"A","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **A**: **Có**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Có**."},{"id":451,"category":"Luật Kinh doanh bảo hiểm","question":"Theo pháp luật Việt Nam về kinh doanh bảo hiểm, tỷ lệ hoa hồng đại lý bảo hiểm tối đa với hợp đồng bảo hiểm hàng hóa vận chuyển là:","options":[{"key":"A","text":"5%"},{"key":"B","text":"10%"},{"key":"C","text":"15%"},{"key":"D","text":"20%"}],"answer":"B","explanation":"Khái niệm cần nhớ trong câu này là: **10%**. Đáp án đúng là **B**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Chốt mốc **10** và gắn với đúng điều kiện của câu."},{"id":452,"category":"Luật Kinh doanh bảo hiểm","question":"Theo pháp luật Việt Nam về kinh doanh bảo hiểm, tỷ lệ hoa hồng đại lý bảo hiểm tối đa với hợp đồng bảo hiểm tài sản là:","options":[{"key":"A","text":"5%"},{"key":"B","text":"10%"},{"key":"C","text":"15%"},{"key":"D","text":"20%"}],"answer":"A","explanation":"Khái niệm cần nhớ trong câu này là: **5%**. Đáp án đúng là **A**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Chốt mốc **5** và gắn với đúng điều kiện của câu."},{"id":453,"category":"Luật Kinh doanh bảo hiểm","question":"Trong Luật Kinh doanh bảo hiểm, trường hợp phát sinh khiếu nại theo hợp đồng bảo hiểm trách nhiệm dân sự thì:","options":[{"key":"A","text":"Doanh nghiệp bảo hiểm không có quyền thay mặt người được bảo hiểm thương lượng với người thứ ba về mức độ bồi thường thiệt hại"},{"key":"B","text":"Doanh nghiệp bảo hiểm có quyền thay mặt người được bảo hiểm để thương lượng với người thứ ba về mức độ bồi thường thiệt hại, trừ trường hợp có thỏa thuận khác trong hợp đồng bảo hiểm."}],"answer":"B","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **B**: **Doanh nghiệp bảo hiểm có quyền thay mặt người được bảo hiểm để thương lượng với người thứ ba về mức độ bồi thường thiệt hại, trừ trường hợp có thỏa thuận khác trong hợp đồng bảo hiểm.**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Doanh nghiệp bảo hiểm có quyền thay mặt người được bảo hiểm để thương lượng với người thứ…**."},{"id":454,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Theo Quy tắc bảo hiểm “Hỏa hoạn và các rủi ro đặc biệt” của Hiệp hội bảo hiểm Vương quốc Anh (ABI), có thể bảo hiểm máy móc, thiết bị hay nhà xưởng trên cơ sở giá trị thay thế mới không?","options":[{"key":"A","text":"Có"},{"key":"B","text":"Không"},{"key":"C","text":"Có, với điều kiện bên mua bảo hiểm phải tham gia thêm Điều khoản sửa đổi bổ sung về bảo hiểm theo “Giá trị thay thế mới”"}],"answer":"C","explanation":"Theo đáp án của đề cương, đáp án đúng là **C**: **Có, với điều kiện bên mua bảo hiểm phải tham gia thêm Điều khoản sửa đổi bổ sung về bảo hiểm theo “Giá trị thay thế mới”**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Có, với điều kiện bên mua bảo hiểm phải tham gia thêm Điều khoản sửa đổi bổ sung về bảo…**."},{"id":455,"category":"Kiến thức chung","question":"Chọn Phương án đúng nhất. Phạm vi bảo hiểm là:","options":[{"key":"A","text":"Phạm vi giới hạn những rủi ro, tổn thất và chi phí phát sinh mà theo đó người bảo hiểm sẽ chịu trách nhiệm nếu xảy ra sự kiện bảo hiểm."},{"key":"B","text":"Phạm vi giới hạn những rủi ro, tổn thất và chi phí phát sinh mà theo đó người được bảo hiểm và người bảo hiểm cùng chịu trách nhiệm nếu xảy ra sự kiện bảo hiểm"},{"key":"C","text":"Phạm vi giới hạn những rủi ro, tổn thất và chi phí phát sinh theo yêu cầu của người được bảo hiểm nếu xảy ra sự kiện bảo hiểm"},{"key":"D","text":"Tổn thất bảo hiểm"}],"answer":"A","explanation":"Theo đáp án của đề cương, phương án **A** là nội dung đúng: **Phạm vi giới hạn những rủi ro, tổn thất và chi phí phát sinh mà theo đó người bảo hiểm sẽ chịu trách nhiệm nếu xảy ra sự kiện bảo hiểm.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Phạm vi giới hạn những rủi ro, tổn thất và chi phí phát sinh mà theo đó người bảo hiểm sẽ…**."},{"id":456,"category":"Bảo hiểm con người","question":"Trong bảo hiểm sức khỏe, không áp dụng thời gian chờ đối vói mọi trường hợp điều trị do ốm đau, bệnh tật?","options":[{"key":"A","text":"Đúng"},{"key":"B","text":"Sai"}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án **B** là **Sai**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Sai**."},{"id":457,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phương án nào dưới đây là đúng nhất về phương thức giải quyết tranh chấp về hợp đồng bảo hiểm?","options":[{"key":"A","text":"Tranh chấp về hợp đồng bảo hiểm được giải quyết thông qua thương lượng giữa các bên. Trường hợp không thương lượng được thì tranh chấp được giải quyết thông qua hòa giải hoặc Trọng tài hoặc Tòa án theo thỏa thuận trong hợp đồng bảo hiểm và quy định của pháp luật"},{"key":"B","text":"Tranh chấp về hợp đồng bảo hiểm được giải quyết thông qua thương lượng giữa các bên. Trường hợp không thương lượng được thì tranh chấp được giải quyết thông qua hòa giải hoặc Trọng tài theo thỏa thuận trong hợp đồng bảo hiểm và quy định của pháp luật"},{"key":"C","text":"Tranh chấp về hợp đồng bảo hiểm được giải quyết thông qua thương lượng giữa các bên. Trường hợp không thương lượng được thì tranh chấp được giải quyết thông qua hòa giải hoặc Tòa án theo thỏa thuận trong hợp đồng bảo hiểm và quy định của pháp luật"},{"key":"D","text":"Tranh chấp về hợp đồng bảo hiểm được giải quyết thông qua thương lượng giữa các bên. Trường hợp không thương lượng được thì tranh chấp được giải quyết thông qua Trọng tài hoặc Tòa án theo thỏa thuận trong hợp đồng bảo hiểm và quy định của pháp luật"}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Tranh chấp về hợp đồng bảo hiểm được giải quyết thông qua thương lượng giữa các bên. Trường hợp không thương lượng được thì tranh chấp được giải quyết thông qua hòa giải hoặc Trọng tài hoặc Tòa án theo thỏa thuận trong hợp đồng bảo hiểm và quy định của pháp luật**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Tranh chấp về hợp đồng bảo hiểm được giải quyết thông qua thương lượng giữa các bên. Trường…**."},{"id":458,"category":"Luật Kinh doanh bảo hiểm","question":"Chọn Phương án đúng nhất: Theo Luật Kinh doanh bảo hiểm, doanh nghiệp bảo hiểm có quyền đơn phương chấm dứt thực hiện hợp đồng bảo hiểm trong trường hợp nào?","options":[{"key":"A","text":"Bên mua bảo hiểm không đóng phí bảo hiểm hoặc không đóng đủ phí bảo hiểm theo thời hạn thảo thuận hoặc sau thời gian gia hạn đóng phí"},{"key":"B","text":"Người được bảo hiểm không thực hiện các biện pháp bảo đảm an toàn cho đối tượng bảo hiểm theo quy định của pháp luật về kinh doanh bảo hiểm"},{"key":"C","text":"Doanh nghiệp bảo hiểm mất khả năng thanh toán"},{"key":"D","text":"A, B đúng"},{"key":"E","text":"A, B, C đúng"}],"answer":"D","explanation":"Theo đáp án của đề cương, phương án **D** là nội dung đúng: **A, B đúng**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B đúng**."},{"id":459,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Nguyên tắc cơ bản khi giải quyết bồi thường tài sản là khôi phục tài sản được bảo hiểm trở về tình trạng như ngay trước khi xảy ra tổn thất:","options":[{"key":"A","text":"Đúng"},{"key":"B","text":"Sai"}],"answer":"A","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **A**: **Đúng**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Đúng**."},{"id":460,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, đối với bảo hiểm trách nhiệm, chọn đáp án đúng để điền vào chỗ ______: “Doanh nghiệp bảo hiểm, chi nhánh doanh nghiệp bảo hiểm phi nhân thọ nước ngoài __________ thay mặt người được bảo hiểm để thương lượng với người thứ ba về mức độ bồi thường thiệt hại, trừ trường hợp có thỏa thuận khác trong hợp đồng bảo hiểm.”","options":[{"key":"A","text":"Không được"},{"key":"B","text":"Có quyền"},{"key":"C","text":"Bắt buộc phải"},{"key":"D","text":"A, B, C sai"}],"answer":"B","explanation":"Theo đáp án của đề cương, phương án **B** là nội dung đúng: **Có quyền**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Có quyền**."},{"id":461,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, chọn phương án đúng nhất về bảo hiểm chảy, nổ bắt buộc:","options":[{"key":"A","text":"Là sản phẩm bảo hiểm do Chính phủ quy định chi tiết về điều kiện bảo hiểm, mức phí bảo hiểm"},{"key":"B","text":"Là sản phẩm bảo hiểm do Chính phủ quy định chi tiết về điều kiện, số tiền bảo hiểm tối thiểu"},{"key":"C","text":"Là sản phẩm bảo hiểm do chính phủ quy định chi tiết về mức phí bảo hiểm, số tiền bảo hiểm tối thiểu"},{"key":"D","text":"Là sản phẩm bảo hiểm do chính phủ quy định chi tiết về điều kiện bảo hiểm, mức phí bảo hiểm, số tiền bảo hiểm tối thiểu"}],"answer":"D","explanation":"Theo đáp án của đề cương, phương án **D** là nội dung đúng: **Là sản phẩm bảo hiểm do chính phủ quy định chi tiết về điều kiện bảo hiểm, mức phí bảo hiểm, số tiền bảo hiểm tối thiểu**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Là sản phẩm bảo hiểm do chính phủ quy định chi tiết về điều kiện bảo hiểm, mức phí bảo…**."},{"id":462,"category":"Luật Kinh doanh bảo hiểm","question":"Chọn phương án đúng nhất: Theo Luật Kinh doanh bảo hiểm, trong bảo hiểm sức khỏe, hợp đồng bảo hiểm nhóm được hiểu như thế nào?","options":[{"key":"A","text":"Là sự thỏa thuận giữa bên mua bảo hiểm và doanh nghiệp bảo hiểm để bảo hiểm cho những người được bảo hiểm thuộc nhóm tham gia bảo hiểm trong cùng một hợp đồng bảo hiểm"},{"key":"B","text":"Nhóm tham gia hợp đồng bảo hiểm phải là nhóm đã được hình thành không phải vì mục đích tham gia bảo hiểm"},{"key":"C","text":"Nhóm tham gia hợp đồng bảo hiểm phải là nhóm đã được hình thành vì mục đích tham gia bảo hiểm"},{"key":"D","text":"A, B đúng"},{"key":"E","text":"A, C đúng"}],"answer":"D","explanation":"Theo đáp án của đề cương, phương án **D** là nội dung đúng: **A, B đúng**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B đúng**."},{"id":463,"category":"Kiến thức chung","question":"Rủi ro mà hậu quả của nó có thể xác định được thành tiền là:","options":[{"key":"A","text":"Rủi ro thuần túy"},{"key":"B","text":"Rủi ro tài chính"},{"key":"C","text":"Rủi roc hung"},{"key":"D","text":"Rủi ro riêng"}],"answer":"B","explanation":"Khái niệm cần nhớ trong câu này là: **Rủi ro tài chính**. Đáp án đúng là **B**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Rủi ro tài chính**."},{"id":464,"category":"Bảo hiểm con người","question":"Theo pháp luật Việt Nam về kinh doanh bảo hiểm, đối với bảo hiểm sức khỏe, việc chứng nhận người được bảo hiểm bị liệt hoàn toàn và không thể phục hồi chức năng của các bộ phận cơ thể hoặc mù hoàn toàn hoặc bị tổn thương cơ thể từ 81% trở lên được thực hiện không sớm hơn bao nhiêu ngày?","options":[{"key":"A","text":"90 ngày"},{"key":"B","text":"180 ngày"},{"key":"C","text":"270 ngày"},{"key":"D","text":"365 ngày"}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án **B** là **180 ngày**. Mốc cần nhớ: **180 ngày**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Chốt mốc **180 ngày** và gắn với đúng điều kiện của câu."},{"id":465,"category":"Bảo hiểm con người","question":"Trong bảo hiểm sức khỏe, doanh nghiệp bảo hiểm và bên mua bảo hiểm có thể thỏa thuận lựa chọn những quyền lợi bảo hiểm nào sau đây:","options":[{"key":"A","text":"Thương tật do tai nạn"},{"key":"B","text":"Chi phí y tế điều trị do tai nạn"},{"key":"C","text":"Trợ cấp mất, giảm thu nhập"},{"key":"D","text":"A, B, C đúng"}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **A, B, C đúng**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng**."},{"id":466,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Trong bảo hiểm tài sản, thông thường, giới hạn phụ của các điều khoản sửa đổi bổ sung không vượt quá 10% số tiền bảo hiểm:","options":[{"key":"A","text":"Đúng"},{"key":"B","text":"Sai"}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án **A** là **Đúng**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Đúng**."},{"id":467,"category":"Bảo hiểm con người","question":"Trong bảo hiểm sức khỏe, chi phí y tế điều trị tai nạn của người được bảo hiểm được doanh nghiệp bảo hiểm chi trả theo nguyên tắc nào?","options":[{"key":"A","text":"Nguyên tắc khoán"},{"key":"B","text":"Nguyên tắc bồi thường"},{"key":"C","text":"A, B đúng"}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án đúng là **B**: **Nguyên tắc bồi thường**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Nguyên tắc bồi thường**."},{"id":468,"category":"Luật Kinh doanh bảo hiểm","question":"Hợp đồng bảo hiểm vô hiệu khi:","options":[{"key":"A","text":"Tại thời điểm giao kết hợp đồng bảo hiểm, bên mua bảo hiểm không biết sự kiện bảo hiểm đã xảy ra"},{"key":"B","text":"Không có đối tượng bảo hiểm tại thời điểm giao kết hợp đồng bảo hiểm"},{"key":"C","text":"Hợp đồng bảo hiểm được giao kết do bị đe dọa, cưỡng ép"},{"key":"D","text":"B, C đúng"},{"key":"E","text":"A, B, C đúng"}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **B, C đúng**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **B, C đúng**."},{"id":469,"category":"Luật Kinh doanh bảo hiểm","question":"Chọn phương án đúng nhất: Theo Luật Kinh doanh bảo hiểm, đối với hợp đồng bảo hiểm tài sản, hợp đồng bảo hiểm thiệt hại, trường hợp doanh nghiệp bảo hiểm và bên mua bảo hiểm không thống nhất về nguyên nhân và mức độ tổn thất và không thỏa thuận được việc thuê giám định viên độc lập thì một trong các bên có quyền yêu cầu những bên nào sau đây trưng cầu giám định viên độc lập? Kết luận của giám định viên độc lập có giá trị bắt buộc đối với các bên.","options":[{"key":"A","text":"Tòa án có thẩm quyền"},{"key":"B","text":"Trọng tài"},{"key":"C","text":"A, B đúng"},{"key":"D","text":"A, B sai"}],"answer":"C","explanation":"Theo đáp án của đề cương, phương án **C** là nội dung đúng: **A, B đúng**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B đúng**."},{"id":470,"category":"Luật Kinh doanh bảo hiểm","question":"Theo pháp luật Việt Nam về kinh doanh bảo hiểm, tỷ lệ hoa hồng đại lý bảo hiểm tối đa vói hợp đồng bảo hiểm nông nghiệp là:","options":[{"key":"A","text":"5%"},{"key":"B","text":"10%"},{"key":"C","text":"15%"},{"key":"D","text":"20%"}],"answer":"D","explanation":"Khái niệm cần nhớ trong câu này là: **20%**. Đáp án đúng là **D**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Chốt mốc **20** và gắn với đúng điều kiện của câu."},{"id":471,"category":"Bảo hiểm xe cơ giới","question":"Theo pháp luật Việt Nam về kinh doanh bảo hiểm, trong bảo hiểm bắt buộc trách nhiệm dân sự của chủ xe cơ giới, căn cứ vào lịch sử bồi thường bảo hiểm của từng xe cơ giới hoặc lịch sử gây tai nạn của chủ xe cơ giới, doanh nghiệp bảo hiểm chủ động xem xét, điều chỉnh tăng, giảm phí bảo hiểm, tối đa bao nhiêu % trên mức phí bảo hiểm theo quy định của pháp luật?","options":[{"key":"A","text":"10%"},{"key":"B","text":"15%"},{"key":"C","text":"20%"},{"key":"D","text":"25%"}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án **B** là **15%**. Mốc cần nhớ: **15**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Chốt mốc **15** và gắn với đúng điều kiện của câu."},{"id":472,"category":"Bảo hiểm xe cơ giới","question":"Ông A mua hợp đồng bảo hiểm vật chất xe cho ô tô của mình. Trong thời hạn bảo hiểm, ông A bán xe ô tô cho ông B và có văn bản đề nghị doanh nghiệp bảo hiểm chuyển giao hợp đồng bảo hiểm này cho ông B và doanh nghiệp bảo hiểm chấp nhận. Việc chuyển giao hợp đồng bảo hiểm như trên thực hiện theo nguyên tắc cơ bản nào của bảo hiểm:","options":[{"key":"A","text":"Nguyên tắc thế quyền"},{"key":"B","text":"Nguyên tắc trung thực tuyệt đối"},{"key":"C","text":"Nguyên tắc quyền lợi có thể được bảo hiểm"},{"key":"D","text":"Nguyên tắc bồi thường"}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án **B** là **Nguyên tắc trung thực tuyệt đối**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Nguyên tắc trung thực tuyệt đối**."},{"id":473,"category":"Luật Kinh doanh bảo hiểm","question":"Theo pháp luật Việt Nam về kinh doanh bảo hiểm, vốn điều lệ tối thiểu của doanh nghiệp bảo hiểm phi nhân thọ kinh doanh bảo hiểm phi nhân thọ (trừ bảo hiểm hàng không, bảo hiểm vệ tinh) và bảo hiểm sức khỏe là:","options":[{"key":"A","text":"400 tỷ đồng Việt Nam"},{"key":"B","text":"500 tỷ đồng Việt Nam"},{"key":"C","text":"450 tỷ đồng Việt Nam"},{"key":"D","text":"600 tỷ đồng Việt Nam"}],"answer":"A","explanation":"Khái niệm cần nhớ trong câu này là: **400 tỷ đồng Việt Nam**. Đáp án đúng là **A**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Chốt mốc **400 tỷ** và gắn với đúng điều kiện của câu."},{"id":474,"category":"Bảo hiểm xe cơ giới","question":"Theo pháp luật Việt Nam về kinh doanh bảo hiểm, người thứ ba trong bảo hiểm bắt buộc trách nhiệm dân sự của chủ xe cơ giới là:","options":[{"key":"A","text":"Người bị thiệt hại về sức khỏe, tính mạng, tài sản do xe cơ giới gây ra trừ những người sau: người lái xe, người trên xe; chủ sở hữu xe trừ trường hợp chủ sở hữu đã giao cho tổ chức, cá nhân khác chiếm hữu, sử dụng chiếc xe đó"},{"key":"B","text":"Người bị thiệt hại về sức khỏe, tính mạng, tài sản do xe cơ giới gây ra trừ những người sau: người lái xe, hành khách trên chính chiếc xe đó; chủ sở hữu xe trừ trường hợp chủ sở hữu đã giao cho tổ chức, cá nhân khác chiếm hữu, sử dụng chiếc xe đó"},{"key":"C","text":"Người bị thiệt hại về sức khỏe, tính mạng, tài sản do xe cơ giới gây ra trừ những người sau: người lái xe, người trên xe, hành khách trên chính chiếc xe đó; chủ sở hữu xe trừ trường hợp chủ sở hữu đã giao cho tổ chức, cá nhân khác chiếm hữu, sử dụng chiếc xe đó"},{"key":"D","text":"Người bị thiệt hại về sức khỏe, tính mạng, tài sản do xe cơ giới gây ra trừ những người sau: người trên xe, hành khách trên chính chiếc xe đó; chủ sở hữu xe trừ trường hợp chủ sở hữu đã ủy quyền cho tổ chức, cá nhân khác chiếm hữu, sử dụng chiếc xe đó"}],"answer":"A","explanation":"Khái niệm cần nhớ trong câu này là: **Người bị thiệt hại về sức khỏe, tính mạng, tài sản do xe cơ giới gây ra trừ những người sau: người lái xe, người trên xe; chủ sở hữu xe trừ trường hợp chủ sở hữu đã giao cho tổ chức, cá nhân khác chiếm hữu, sử dụng chiếc xe đó**. Đáp án đúng là **A**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Người bị thiệt hại về sức khỏe, tính mạng, tài sản do xe cơ giới gây ra trừ những người…**."},{"id":475,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, hợp đồng bảo hiểm tài sản trên giá trị là hợp đồng trong đó:","options":[{"key":"A","text":"Số tiền bảo hiểm cao hơn giá thị trường của tài sản được bảo hiểm. Doanh nghiệp bảo hiểm và bên mua bảo hiểm không được cố ý giao kết hợp đồng bảo hiểm tài sản trên giá trị."},{"key":"B","text":"Số tiền bảo hiểm cao hơn giá thị trường của tài sản được bảo hiểm. Doanh nghiệp bảo hiểm và bên mua bảo hiểm không được giao kết hợp đồng bảo hiểm tài sản trên giá trị."},{"key":"C","text":"Số tiền bảo hiểm cao hơn giá thị trường của tài sản được bảo hiểm tại thời điểm giao kết hợp đồng. Doanh nghiệp bảo hiểm và bên mua bảo hiểm không được cố ý giao kết hợp đồng bảo hiểm tài sản trên giá trị."},{"key":"D","text":"Số tiền bảo hiểm cao hơn giá thị trường của tài sản được bảo hiểm tại thời điểm xảy ra tổn thất. Doanh nghiệp bảo hiểm và bên mua bảo hiểm không được cố ý giao kết hợp đồng bảo hiểm tài sản trên giá trị."}],"answer":"C","explanation":"Theo đáp án của đề cương, đáp án đúng là **C**: **Số tiền bảo hiểm cao hơn giá thị trường của tài sản được bảo hiểm tại thời điểm giao kết hợp đồng. Doanh nghiệp bảo hiểm và bên mua bảo hiểm không được cố ý giao kết hợp đồng bảo hiểm tài sản trên giá trị.**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Số tiền bảo hiểm cao hơn giá thị trường của tài sản được bảo hiểm tại thời điểm giao kết…**."},{"id":476,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Phương án nào sau đây không được coi là cơ sở để tính số tiền bồi thường theo đơn bảo hiểm “Gián đoạn kinh doanh” của Hiệp hội bảo hiểm Vương quốc Anh (ABI):","options":[{"key":"A","text":"Chi phí cố định"},{"key":"B","text":"Chi phí biến đổi"},{"key":"C","text":"Chi phí hoạt động gia tăng để duy trì sản xuất thuộc hạng mục lợi nhuận gộp"},{"key":"D","text":"B, C đúng"}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án **D** là **B, C đúng**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **B, C đúng**."},{"id":477,"category":"Bảo hiểm xe cơ giới","question":"Theo pháp luật Việt Nam về kinh doanh bảo hiểm, trong hồ sơ bồi thường bảo hiểm bắt buộc trách nhiệm dân sự của chủ xe cơ giới, tài liệu liên quan đến xe cơ giới, người lái xe gồm:","options":[{"key":"A","text":"Giấy chứng nhận đăng ký xe (hoặc bản sao được chứng thực từ bản chính Giấy chứng nhận đăng ký xe kèm bản gốc Giấy biên nhận của tổ chức tín dụng còn hiệu lực, thay cho bản chính Giấy chứng nhận đăng ký xe trong thời gian tổ chức tín dụng giữ bản chính Giấy chứng nhận đăng ký xe) hoặc chứng từ chuyển quyền sở hữu xe và chứng từ nguồn gốc xe (trường hợp không có Giấy chứng nhận đăng ký xe)."},{"key":"B","text":"Giấy phép lái xe; Giấy chứng nhận bảo hiểm"},{"key":"C","text":"Giấy chứng minh nhân dân hoặc thẻ căn cước công dân hoặc Hộ chiếu hoặc các giấy tờ tùy thân khác của người lái xe"},{"key":"D","text":"A, B, C đúng"}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **A, B, C đúng**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng**."},{"id":478,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Theo Quy tắc bảo hiểm “Mọi rủi ro tài sản”của Hiệp hội bảo hiểm Vương quốc Anh (ABI), chi phí khắc phục thiệt hại gây ra bởi sự cố vỡ hay tràn thoát nước từ các bể chứa, thiết bị chứa hay đường ống dẫn khi khu vực được bảo hiểm bị bỏ trống hoặc không được sử dụng có thuộc trách nhiệm bảo hiểm không (chọn phương án đúng nhất):","options":[{"key":"A","text":"Có"},{"key":"B","text":"Không"},{"key":"C","text":"Không, trừ khi những thiệt hại trên gây ra trực tiếp từ thiệt hại đối với tài sản được bảo hiểm do một nguyên nhân không bị loại trừ trong Quy tắc bảo hiểm này"}],"answer":"C","explanation":"Theo đáp án của đề cương, phương án **C** là nội dung đúng: **Không, trừ khi những thiệt hại trên gây ra trực tiếp từ thiệt hại đối với tài sản được bảo hiểm do một nguyên nhân không bị loại trừ trong Quy tắc bảo hiểm này**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Không, trừ khi những thiệt hại trên gây ra trực tiếp từ thiệt hại đối với tài sản được bảo…**."},{"id":479,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Chủ đầu tư tham gia Đơn bảo hiểm mọi rủi ro xây dựng (CAR) cho công trình A. Công trình A được xây dựng cạnh nhà hàng X. Do xây dựng ngày đêm ồn và bụi, khách đến nhà hàng X giảm nhiều, dẫn đến thu nhập nhà hàng X bị giảm nghiêm trọng. Trường hợp này có phát sinh trách nhiệm bồi thường bảo hiểm không?","options":[{"key":"A","text":"Có"},{"key":"B","text":"Không"}],"answer":"B","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **B**: **Không**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Không**."},{"id":480,"category":"Bảo hiểm xe cơ giới","question":"Theo pháp luật Việt Nam về kinh doanh bảo hiểm, trong bảo hiểm bắt buộc trách nhiệm dân sự của chủ xe cơ giới, trong vòng bao lâu doanh nghiệp bảo hiểm phải tổ chức thực hiện việc giám định tổn thất xác định nguyên nhân và mức độ tổn thất làm căn cứ giải quyết bồi thường bảo hiểm khi nhận được thông báo về tai nạn?","options":[{"key":"A","text":"01 giờ"},{"key":"B","text":"12 giờ"},{"key":"C","text":"24 giờ"},{"key":"D","text":"48 giờ"}],"answer":"C","explanation":"Theo đáp án của đề cương, đáp án **C** là **24 giờ**. Mốc cần nhớ: **24 giờ**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Chốt mốc **24 giờ** và gắn với đúng điều kiện của câu."},{"id":481,"category":"Bảo hiểm con người","question":"Theo pháp luật Việt Nam về kinh doanh bảo hiểm, đối với bảo hiểm sức khỏe, trong bảng câu hỏi kê khai sức khỏe của người được bảo hiểm, việc kê khai lịch sử khám chữa bệnh, thông tin dấu hiệu, triệu chứng liên quan đến bệnh tật không vượt quá khoảng thời gian là:","options":[{"key":"A","text":"01 năm"},{"key":"B","text":"03 năm"},{"key":"C","text":"05 năm"},{"key":"D","text":"10 năm"}],"answer":"B","explanation":"Khái niệm cần nhớ trong câu này là: **03 năm**. Đáp án đúng là **B**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Chốt mốc **03 năm** và gắn với đúng điều kiện của câu."},{"id":482,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Một hợp đồng bảo hiểm tài sản có số tiền bảo hiểm là 1,5 tỉ đồng, giá thị trường của tài sản được bảo hiểm tại thời điểm giao kết hợp đồng là 2 tỉ đồng. Hợp đồng bảo hiểm này là:","options":[{"key":"A","text":"Hợp đồng bảo hiểm tài sản dưới giá trị"},{"key":"B","text":"Hợp đồng bảo hiểm tài sản trên giá trị"},{"key":"C","text":"Hợp đồng bảo hiểm đúng giá trị"},{"key":"D","text":"B, C đúng"}],"answer":"A","explanation":"Khái niệm cần nhớ trong câu này là: **Hợp đồng bảo hiểm tài sản dưới giá trị**. Đáp án đúng là **A**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Hợp đồng bảo hiểm tài sản dưới giá trị**."},{"id":483,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Theo pháp luật Việt Nam về kinh doanh bảo hiểm, chọn phương án đúng nhất về nghĩa vụ của bên mua bảo hiểm trong bảo hiểm cháy, nổ bắt buộc:","options":[{"key":"A","text":"Áp dụng các biện pháp đề phòng, hạn chế tổn thất theo quy định của Luật Kinh doanh bảo hiểm và quy định khác của pháp luật có liên quan"},{"key":"B","text":"Kê khai đầy đủ, trung thực mọi thông tin có liên quan đến hợp đồng bảo hiểm theo yêu cầu của doanh nghiệp bảo hiểm"},{"key":"C","text":"Đóng phí bảo hiểm đầy đủ, đúng hạn theo thỏa thuận trong hợp đồng bảo hiểm"},{"key":"D","text":"A, B, C đúng"}],"answer":"D","explanation":"Theo đáp án của đề cương, phương án **D** là nội dung đúng: **A, B, C đúng**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng**."},{"id":484,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật kinh doanh bảo hiểm, doanh nghiệp bảo hiểm phi nhân thọ chỉ được phép kinh doanh các sản phẩm thuộc loại hình bảo hiểm sức khỏe có thời hạn nào sau đây?","options":[{"key":"A","text":"Từ 01 năm trở xuống"},{"key":"B","text":"Dưới 01 năm"},{"key":"C","text":"Từ 05 năm trở xuống"},{"key":"D","text":"Dưới 05 năm"}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án **A** là **Từ 01 năm trở xuống**. Mốc cần nhớ: **01 năm**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Chốt mốc **01 năm** và gắn với đúng điều kiện của câu."},{"id":485,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Chủ đầu tư và nhà thầu chỉ bảo hiểm cho máy móc, thiết bị của chủ thầu (CPM) theo quy tắc bảo hiểm của nhà tái bảo hiểm Munich Re mà không bảo hiểm cho công trình. Cần cẩu của nhà thầu gây tổn thất cho bên thứ ba trong khi hoạt động trên công trường. Tổn thất đó có thuộc trách nhiệm bảo hiểm không:","options":[{"key":"A","text":"Có"},{"key":"B","text":"Không"}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án đúng là **B**: **Không**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Không**."},{"id":486,"category":"Luật Kinh doanh bảo hiểm","question":"Chọn phương án đúng nhất: Theo Luật kinh doanh bảo hiểm, đối với hợp đồng bảo hiểm thiệt hại, bên mua bảo hiểm có quyền lợi có thể được bảo hiểm khi có:","options":[{"key":"A","text":"Quyền lợi về tài chính đối với đối tượng bảo hiểm."},{"key":"B","text":"Nghĩa vụ, trách nhiệm về tài chính đối với đối tượng bảo hiểm"},{"key":"C","text":"Thiệt hại kinh tế đối với đối tượng bảo hiểm"},{"key":"D","text":"A, B, C đúng"}],"answer":"D","explanation":"Theo đáp án của đề cương, phương án **D** là nội dung đúng: **A, B, C đúng**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng**."},{"id":487,"category":"Luật Kinh doanh bảo hiểm","question":"Theo pháp luật Việt Nam về kinh doanh bảo hiểm, tỷ lệ hoa hồng đại lý bảo hiểm tối đa đối với các hợp đồng bảo hiểm sức khỏe là bao nhiêu %?","options":[{"key":"A","text":"15%"},{"key":"B","text":"20%"},{"key":"C","text":"25%"},{"key":"D","text":"30%"}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án **B** là **20%**. Mốc cần nhớ: **20**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Chốt mốc **20** và gắn với đúng điều kiện của câu."},{"id":488,"category":"Luật Kinh doanh bảo hiểm","question":"Chọn phương án đúng nhất: Theo Luật Kinh doanh bảo hiểm, khi có sự thay đổi những yếu tố làm cơ sở để tính phí bảo hiểm dẫn đến tăng các rủi ro được bảo hiểm, căn cứ thỏa thuận trong hợp đồng bảo hiểm, doanh nghiệp bảo hiểm có quyền thực hiện một trong các nội dung nào sau đây:","options":[{"key":"A","text":"Tính lại phí bảo hiểm cho thời gian còn lại của hợp đồng bảo hiểm."},{"key":"B","text":"Giảm số tiền bảo hiểm cho thời gian còn lại của hợp đồng bảo hiểm"},{"key":"C","text":"Rút ngắn thời hạn đóng phí bảo hiểm"},{"key":"D","text":"A, B đúng"}],"answer":"D","explanation":"Theo đáp án của đề cương, phương án **D** là nội dung đúng: **A, B đúng**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B đúng**."},{"id":489,"category":"Bảo hiểm xe cơ giới","question":"Theo pháp luật Việt Nam về kinh doanh bảo hiểm, thời hạn bảo hiểm bắt buộc trách nhiệm dân sự của chủ xe cơ giới là:","options":[{"key":"A","text":"Tối thiểu là 1 năm và tối đa là 3 năm, tùy vào loại xe cơ giới, trừ các trường hợp thời hạn bảo hiểm dưới 1 năm"},{"key":"B","text":"Tối thiểu là 1 năm và tối đa là 3 năm, trừ các trường hợp thời hạn bảo hiểm dưới 1 năm theo quy định của pháp luật"},{"key":"C","text":"Tối thiểu là 1 năm và tối đa tương ứng với thời hạn kiểm định an toàn kỹ thuật và bảo vệ môi trường"},{"key":"D","text":"Tối thiểu là 1 năm và tối đa tương ứng với thời hạn kiểm định an toàn kỹ thuật và bải vệ môi trường có thời hạn trên 1 năm"}],"answer":"B","explanation":"Khái niệm cần nhớ trong câu này là: **Tối thiểu là 1 năm và tối đa là 3 năm, trừ các trường hợp thời hạn bảo hiểm dưới 1 năm theo quy định của pháp luật**. Đáp án đúng là **B**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Chốt mốc **1 năm, 3 năm, 1 năm** và gắn với đúng điều kiện của câu."},{"id":490,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, đối với hợp đồng bảo hiểm thuộc loại hình bảo hiểm phi nhân thọ, trường hợp đơn phương chấm dứt hợp đồng bảo hiểm do bên mua bảo hiểm không đóng phí bảo hiểm hoặc không đóng đủ phí bảo hiểm theo thời hạn thỏa thuận hoặc sau thời gian gia hạn đóng phí, doanh nghiệp bảo hiểm có trách nhiệm bồi thường cho người được bảo hiểm khi:","options":[{"key":"A","text":"Sự kiện bảo hiểm xảy ra trước thời điểm đơn phương chấm dứt thực hiện hợp đồng bảo hiểm"},{"key":"B","text":"Sự kiện bảo hiểm xảy ra sau thời điểm đơn phương chấm dứt thực hiện hợp đồng bảo hiểm"},{"key":"C","text":"Sự kiện bảo hiểm xảy ra tại thời điểm đơn phương chấm dứt thực hiện hợp đồng bảo hiểm"},{"key":"D","text":"Không có trách nhiệm bồi thường"}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án **A** là **Sự kiện bảo hiểm xảy ra trước thời điểm đơn phương chấm dứt thực hiện hợp đồng bảo hiểm**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Sự kiện bảo hiểm xảy ra trước thời điểm đơn phương chấm dứt thực hiện hợp đồng bảo hiểm**."},{"id":491,"category":"Bảo hiểm con người","question":"Theo pháp luật Việt Nam về kinh doanh bảo hiểm, trong bảo hiểm sức khỏe, thời gian chờ được tính từ ngày nào?","options":[{"key":"A","text":"Từ ngày bắt đầu thời hạn bảo hiểm hoặc ngày khôi phục hiệu lực gần nhất."},{"key":"B","text":"Từ khi có sự kiện bảo hiểm xảy ra"},{"key":"C","text":"Từ khi bên mua bảo hiểm đóng phí bảo hiểm"},{"key":"D","text":"Từ khi mua bảo hiểm nộp đầy đủ hồ sơ yêu cầu đòi bồi thường"}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án **A** là **Từ ngày bắt đầu thời hạn bảo hiểm hoặc ngày khôi phục hiệu lực gần nhất.**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Từ ngày bắt đầu thời hạn bảo hiểm hoặc ngày khôi phục hiệu lực gần nhất.**."},{"id":492,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Đối tượng bảo hiểm máy móc thiết bị chủ thầu (CPM) theo quy tắc của nhà tái bảo hiểm Munich Re gồm:","options":[{"key":"A","text":"Máy móc, thiết bị thuộc quyền sở hữu của người được bảo hiểm, phục vụ cho việc thi công, xây dựng, lắp đặt các công trình xây dựng"},{"key":"B","text":"Máy móc, thiết bị thuê, mượn thuộc quyền quản lý của người được bảo hiểm, phục vụ cho việc thi công, xây dựng, lắp đặt các công trình xây dựng"},{"key":"C","text":"A,B đúng"}],"answer":"C","explanation":"Theo đáp án của đề cương, đáp án đúng là **C**: **A,B đúng**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A,B đúng**."},{"id":493,"category":"Luật Kinh doanh bảo hiểm","question":"Theo pháp luật Việt Nam về kinh doanh bảo hiểm, đối với hợp đồng bảo hiểm từ 30 ngày trở lên và đóng phí bảo hiểm 1 lần, trường hợp doanh nghiệp bảo hiểm phi nhân thọ có thỏa thuận với bên mua bảo hiểm về thời hạn thanh toán phí bảo hiểm (bao gồm cả thời gian gia hạn) thì thời hạn thanh toán phí bảo hiểm không vượt quá bao nhiêu ngày kể từ ngày bắt đầu thời hạn bảo hiểm?","options":[{"key":"A","text":"15 ngày"},{"key":"B","text":"30 ngày"},{"key":"C","text":"45 ngày"},{"key":"D","text":"60 ngày"}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án **B** là **30 ngày**. Mốc cần nhớ: **30 ngày**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Chốt mốc **30 ngày** và gắn với đúng điều kiện của câu."},{"id":494,"category":"Luật Kinh doanh bảo hiểm","question":"Theo pháp luật Việt Nam về kinh doanh bảo hiểm, các nghiệp vụ bảo hiểm phi nhân thọ không bao gồm nghiệp vụ nào dưới đây?","options":[{"key":"A","text":"Bảo hiểm tài sản"},{"key":"B","text":"Bảo hiểm xe cơ giới"},{"key":"C","text":"Bảo hiểm nông nghiệp"},{"key":"D","text":"Bảo hiểm sức khỏe"}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **Bảo hiểm sức khỏe**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Bảo hiểm sức khỏe**."},{"id":495,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Trong bảo hiểm tài sản, trường hợp áp dụng mức miễn thường có khấu trừ, nếu giá trị tổn thất lớn hơn mức khấu trừ thì:","options":[{"key":"A","text":"Số tiền bồi thường bằng giá trị tổn thất."},{"key":"B","text":"Số tiền bồi thường bằng giá trị tổn thất trừ đi mức miễn thường."}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án **B** là **Số tiền bồi thường bằng giá trị tổn thất trừ đi mức miễn thường.**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Số tiền bồi thường bằng giá trị tổn thất trừ đi mức miễn thường.**."},{"id":496,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật kinh doanh bảo hiểm, hợp đồng bảo hiểm trùng là:","options":[{"key":"A","text":"Trường hợp có từ hai hợp đồng bảo hiểm trở lên để bảo hiểm cho cùng phạm vi, đối tượng, thời hạn và sự kiện bảo hiểm mà tổng số tiền bảo hiểm vượt quá giá thị trường của tài sản được bảo hiểm tại thời điểm giao kết hợp đồng bảo hiểm"},{"key":"B","text":"Trường hợp có từ hai hợp đồng bảo hiểm trở lên để bảo hiểm cho cùng phạm vi, thời hạn và sự kiện bảo hiểm mà tổng số tiền bảo hiểm vượt quá giá thị trường của tài sản được bảo hiểm tại thời điểm giao kết hợp đồng bảo hiểm"},{"key":"C","text":"Trường hợp có từ hai hợp đồng bảo hiểm trở lên để bảo hiểm cho cùng phạm vi, thời hạn bảo hiểm mà tổng số tiền bảo hiểm vượt quá giá thị trường của tài sản được bảo hiểm tại thời điểm giao kết hợp đồng bảo hiểm"},{"key":"D","text":"Trường hợp có từ hai hợp đồng bảo hiểm trở lên để bảo hiểm cho cùng thời hạn bảo hiểm mà tổng số tiền bảo hiểm không vượt quá giá thị trường của tài sản được bảo hiểm tại thời điểm giao kết hợp đồng bảo hiểm"}],"answer":"A","explanation":"Khái niệm cần nhớ trong câu này là: **Trường hợp có từ hai hợp đồng bảo hiểm trở lên để bảo hiểm cho cùng phạm vi, đối tượng, thời hạn và sự kiện bảo hiểm mà tổng số tiền bảo hiểm vượt quá giá thị trường của tài sản được bảo hiểm tại thời điểm giao kết hợp đồng bảo hiểm**. Đáp án đúng là **A**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Trường hợp có từ hai hợp đồng bảo hiểm trở lên để bảo hiểm cho cùng phạm vi, đối tượng,…**."},{"id":497,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật kinh doanh bảo hiểm, đại lý bảo hiểm có các nghĩa vụ nào sau đây:","options":[{"key":"A","text":"Chịu sự kiểm tra, giám sát của doanh nghiệp bảo hiểm"},{"key":"B","text":"Thực hiện đầy đủ nghĩa vụ tài chính theo quy định của pháp luật"},{"key":"C","text":"Chi trả hoa hồng đại lý bảo hiểm cho bên mua bảo hiểm"},{"key":"D","text":"A, B đúng"}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **A, B đúng**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B đúng**."},{"id":498,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật kinh doanh bảo hiểm, theo yêu cầu của doanh nghiệp bảo hiểm, bên mua bảo hiểm có nghĩa vụ cung cấp đầy đủ, trung thực mọi thông tin liên quan đến:","options":[{"key":"A","text":"Đối tượng bảo hiểm"},{"key":"B","text":"Hợp đồng bảo hiểm"},{"key":"C","text":"A, B đúng"}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Đối tượng bảo hiểm**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Đối tượng bảo hiểm**."},{"id":499,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Công ty A tham gia bảo hiểm “Mọi rủi ro tài sản” cho nhà xưởng M tại doanh nghiệp bảo hiểm X với số tiền bảo hiểm 75 tỷ đồng và tại doanh nghiệp bảo hiểm Y với số tiền bảo hiểm 50 tỷ đồng với cùng điều kiện, điều khoản bảo hiểm. Trong thời hạn bảo hiểm, nhà xưởng bị cháy (thuộc phạm vi bảo hiểm). Giá trị nhà xưởng tại thời điểm tổn thất là 100 tỷ đồng. Tài sản thiệt hại thực tế 5 tỷ đồng. Căn cứ số tiền bảo hiểm tham gia tại doanh nghiệp bảo hiểm X và Y, số tiền bồi thường mà doanh nghiệp Y phải trả cho công ty A là","options":[{"key":"A","text":"2 tỷ đồng"},{"key":"B","text":"2,5 tỷ đồng"},{"key":"C","text":"3 tỷ đồng"},{"key":"D","text":"5 tỷ đồng"}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án **A** là **2 tỷ đồng**. Mốc cần nhớ: **2 tỷ**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Chốt mốc **2 tỷ** và gắn với đúng điều kiện của câu."},{"id":500,"category":"Bảo hiểm con người","question":"Ông A là người được bảo hiểm của hợp đồng bảo hiểm sức khỏe với quyền lợi bảo hiểm thương tật toàn bộ vĩnh viễn do tai nạn, khi tham gia giao thông do hành vi cố ý vi phạm của ông B, ông A bị tai nạn dẫn đến thương tật toàn bộ vĩnh viễn. Trong trường hợp này, doanh nghiệp bảo hiểm sẽ giải quyết như thế nào? ( Ông B không phải là người thụ hưởng của hợp đồng bảo hiểm nói trên).","options":[{"key":"A","text":"Không chi trả"},{"key":"B","text":"Chi trả 100% số tiền bảo hiểm"},{"key":"C","text":"Chi trả 100% số tiền bảo hiểm và yêu cầu ông B bồi hoàn"}],"answer":"B","explanation":"Đây là câu hỏi tìm **phương án ngoại lệ/sai**. Theo đáp án của đề cương, phương án **B** là nội dung không phù hợp: **Chi trả 100% số tiền bảo hiểm**. Khi làm bài, cần chú ý từ khóa phủ định như **“sai”, “không”, “ngoại trừ”**.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":501,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, trường hợp hợp đồng bảo hiểm có điều khoản không rõ ràng dẫn đến có cách hiểu khác nhau thì điều khoản đó được giải thích theo hướng có lợi cho:","options":[{"key":"A","text":"Doanh nghiệp bảo hiểm"},{"key":"B","text":"Bên mua bảo hiểm"},{"key":"C","text":"Người thụ hưởng"},{"key":"D","text":"Người được bảo hiểm"}],"answer":"B","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **B**: **Bên mua bảo hiểm**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Bên mua bảo hiểm**."},{"id":502,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Chọn phương án đúng nhất, Theo pháp luật Việt Nam về kinh doanh bảo hiểm, doanh nghiệp bảo hiểm có quyền từ chối bán bảo hiểm cháy, nổ bắt buộc trong các trường hợp nào sau đây:","options":[{"key":"A","text":"Cơ sở có nguy hiểm về cháy, nổ chưa được nghiệm thu về phòng cháy và chữa cháy theo quy định của pháp luật"},{"key":"B","text":"Cơ sở có nguy hiểm về cháy, nổ không có biên bản kiểm tra an toàn về phòng cháy chữa cháy của cơ quan công an có thẩm quyền hoặc biên bản kiểm tra đã quá 1 năm tính từ thời điểm lập đến thời điểm mua bảo hiểm cháy, nổ bắt buộc"},{"key":"C","text":"Cơ sở có nguy hiểm về cháy, nổ đang bị tạm đình chỉ hoặc đình chỉ hoạt động do vi phạm quy định pháp luật phòng cháy và chữa cháy"},{"key":"D","text":"A, B, C đúng"}],"answer":"D","explanation":"Theo đáp án của đề cương, phương án **D** là nội dung đúng: **A, B, C đúng**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng**."},{"id":503,"category":"Luật Kinh doanh bảo hiểm","question":"Phát biểu sau là đúng hay sai: “Giải quyết bồi thường bảo hiểm trách nhiệm dựa trên cơ sở tổn thất phát sinh có nghĩa là: Tổn thất xảy ra trong thời hạn bảo hiểm, khiếu nại trong hoặc sau thời hạn bảo hiểm (nhưng phải hợp lệ theo quy định pháp luật)”?","options":[{"key":"A","text":"Đúng"},{"key":"B","text":"Sai"}],"answer":"A","explanation":"Khái niệm cần nhớ trong câu này là: **Đúng**. Đáp án đúng là **A**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":504,"category":"Luật Kinh doanh bảo hiểm","question":"Theo pháp luật Việt Nam về kinh doanh bảo hiểm, tỷ lệ hoa hồng đại lý bảo hiểm tối đa với hợp đồng bảo hiểm trách nhiệm là:","options":[{"key":"A","text":"5%"},{"key":"B","text":"10%"},{"key":"C","text":"15%"},{"key":"D","text":"20%"}],"answer":"A","explanation":"Khái niệm cần nhớ trong câu này là: **5%**. Đáp án đúng là **A**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Chốt mốc **5** và gắn với đúng điều kiện của câu."},{"id":505,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Đơn bảo hiểm Máy móc thiết bị chủ thầu (CPM) của nhà tái bảo hiểm Munich Re không kèm theo điều khoản sửa đổi, bổ sung có bảo hiểm cho thiết bị ngầm dưới đất không?","options":[{"key":"A","text":"Không"},{"key":"B","text":"Có"}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Không**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Không**."},{"id":506,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, chọn phương án đúng nhất về bảo hiểm sức khỏe:","options":[{"key":"A","text":"Bảo hiểm sức khỏe là loại hình bảo hiểm cho trường hợp người được bảo hiểm bị thương tật, tai nạn, ốm đau, bệnh tật hoặc chăm sóc sức khỏe"},{"key":"B","text":"Bảo hiểm sức khỏe là loại hình bảo hiểm cho tính mạng của người được bảo hiểm và chi phí y tế"},{"key":"C","text":"Bảo hiểm sức khỏe là loại hình bảo hiểm cho trường hợp người được bảo hiểm bị ốm đau, bệnh tật hoặc chăm sóc sức khỏe"},{"key":"D","text":"Không có đáp án nào đúng"}],"answer":"A","explanation":"Theo đáp án của đề cương, phương án **A** là nội dung đúng: **Bảo hiểm sức khỏe là loại hình bảo hiểm cho trường hợp người được bảo hiểm bị thương tật, tai nạn, ốm đau, bệnh tật hoặc chăm sóc sức khỏe**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Bảo hiểm sức khỏe là loại hình bảo hiểm cho trường hợp người được bảo hiểm bị thương tật,…**."},{"id":507,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Giá trị thay thế mới của một hạng mục là chi phí thay thế  hạng mục mới cùng tính năng, chủng loại và công suất, bao gồm:","options":[{"key":"A","text":"Giá trị thay thế mới của hạng mục đó"},{"key":"B","text":"Cước phí vận chuyển (nếu có)"},{"key":"C","text":"Thuế, lệ phí hải quan và các loại thuế khác (nếu có) và chi phí lắp đặt"},{"key":"D","text":"A, B, C đúng"}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **A, B, C đúng**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng**."},{"id":508,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật kinh doanh bảo hiểm, nội dung hoạt động của doanh nghiệp bảo hiểm bao gồm:","options":[{"key":"A","text":"Kinh doanh bảo hiểm, kinh doanh tái bảo hiểm, nhượng tái bảo hiểm"},{"key":"B","text":"Quản lý các quỹ và đầu tư vốn từ hoạt động kinh doanh bảo hiểm"},{"key":"C","text":"Cung cấp dịch vụ phụ trợ bảo hiểm"},{"key":"D","text":"A, B, C đúng"}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **A, B, C đúng**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng**."},{"id":509,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phát biểu nào sau đây đúng nhất:","options":[{"key":"A","text":"Tổ chức hoạt động ở rong nước của doanh nghiệp bảo hiểm, doanh nghiệp tái bảo hiểm bao gồm trụ sở chính, chi nhánh, văn phòng đại diện, địa điểm kinh doanh."},{"key":"B","text":"Tổ chức hoạt động của chi nhanh doanh nghiệp bảo hiểm phi nhân thọ nước ngoài tại Việt Nam gồm: Trụ sở chính và chi nhánh trực thuộc"},{"key":"C","text":"A, B đúng"}],"answer":"A","explanation":"Theo đáp án của đề cương, phương án **A** là nội dung đúng: **Tổ chức hoạt động ở rong nước của doanh nghiệp bảo hiểm, doanh nghiệp tái bảo hiểm bao gồm trụ sở chính, chi nhánh, văn phòng đại diện, địa điểm kinh doanh.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Tổ chức hoạt động ở rong nước của doanh nghiệp bảo hiểm, doanh nghiệp tái bảo hiểm bao gồm…**."},{"id":510,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phát biểu nào sau đây đúng nhất về đối tượng được phép kinh doanh bảo hiểm sức khỏe có thời hạn trên 1 năm:","options":[{"key":"A","text":"Doanh nghiệp bảo hiểm nhân thọ"},{"key":"B","text":"Doanh nghiệp bảo hiểm phi nhân thọ"},{"key":"C","text":"A, B đúng"},{"key":"D","text":"A, B sai"}],"answer":"A","explanation":"Theo đáp án của đề cương, phương án **A** là nội dung đúng: **Doanh nghiệp bảo hiểm nhân thọ**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Doanh nghiệp bảo hiểm nhân thọ**."},{"id":511,"category":"Luật Kinh doanh bảo hiểm","question":"Theo quy định của Luật kinh doanh bảo hiểm, chọn phương án đúng nhất:","options":[{"key":"A","text":"Doanh nghiệp bảo hiểm phi nhân thọ không được phép kinh doanh bảo hiểm nhân thọ và ngược lại"},{"key":"B","text":"Doanh nghiệp bảo hiểm phi nhân thọ và nhân thọ được phép kinh doanh nghiệp vụ bảo hiểm sức khỏe"},{"key":"C","text":"A, B đúng"}],"answer":"C","explanation":"Theo đáp án của đề cương, phương án **C** là nội dung đúng: **A, B đúng**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B đúng**."},{"id":512,"category":"Luật Kinh doanh bảo hiểm","question":"Luật kinh doanh bảo hiểm phân loại hợp đồng bảo hiểm theo:","options":[{"key":"A","text":"Hình thức bảo hiểm"},{"key":"B","text":"Đối tượng bảo hiểm"},{"key":"C","text":"Số tiền bảo hiểm"},{"key":"D","text":"Thời hạn bảo hiểm"}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án đúng là **B**: **Đối tượng bảo hiểm**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Đối tượng bảo hiểm**."},{"id":513,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, trường hợp người được bảo hiểm không thực hiện các biện pháp bảo đảm an toàn cho đối tượng bảo hiểm thì doanh nghiệp bảo hiểm có quyền:","options":[{"key":"A","text":"Tăng phí bảo hiểm ngay tại thời điểm phát hiện thấy người được bảo hiểm không thực hiện các biện pháp đảm bảo an toàn."},{"key":"B","text":"Đơn phương đình chỉ hợp đồng bảo hiểm ngay tại thời điểm phát hiện thấy người được bảo hiểm không thực hiện các biện pháp đảm bảo an toàn."},{"key":"C","text":"Ấn định một thời hạn để người được bảo hiểm được thực hiện các biện pháp đảm bảo an toàn cho đối tượng bảo hiểm"}],"answer":"C","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **C**: **Ấn định một thời hạn để người được bảo hiểm được thực hiện các biện pháp đảm bảo an toàn cho đối tượng bảo hiểm**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Ấn định một thời hạn để người được bảo hiểm được thực hiện các biện pháp đảm bảo an toàn…**."},{"id":514,"category":"Luật Kinh doanh bảo hiểm","question":"Phát biểu: “Hợp đồng bảo hiểm chấm dứt do bên mua bảo hiểm không có quyền lợi có thể được bảo hiểm tại thời điểm giao kết hợp đồng bảo hiểm” là:","options":[{"key":"A","text":"Đúng"},{"key":"B","text":"Sai"}],"answer":"B","explanation":"Đây là câu hỏi tìm **phương án ngoại lệ/sai**. Theo đáp án của đề cương, phương án **B** là nội dung không phù hợp: **Sai**. Khi làm bài, cần chú ý từ khóa phủ định như **“sai”, “không”, “ngoại trừ”**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Sai**."},{"id":515,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, trong quá trình thực hiện hợp đồng, hợp đồng bảo hiểm vô hiệu do bên mua bảo hiểm không còn “Quyền lợi có thể được bảo hiểm” là:","options":[{"key":"A","text":"Đúng"},{"key":"B","text":"Sai"}],"answer":"B","explanation":"Khái niệm cần nhớ trong câu này là: **Sai**. Đáp án đúng là **B**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Sai**."},{"id":516,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, doanh nghiệp bảo hiểm có quyền đơn phương chấm dứt thực hiện hợp đồng bảo hiểm trong trường hợp nào sau đây:","options":[{"key":"A","text":"Bên mua bảo hiểm không đồng ý chuyển giao danh mục hợp đồng bảo hiểm theo quy định của pháp luật"},{"key":"B","text":"Bên mua bảo hiểm không đóng phí bảo hiểm hoặc không đóng đủ phí bảo hiểm theo thời hạn thỏa thuận hoặc sau thời gian gia hạn đóng phí"},{"key":"C","text":"Người được bảo hiểm không thực hiện các biện pháp đảm bảo an toàn cho đối tượng bảo hiểm theo quy định của pháp luật"},{"key":"D","text":"A, B, C đúng"}],"answer":"D","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **D**: **A, B, C đúng**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng**."},{"id":517,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật kinh doanh bảo hiểm, hợp đồng bảo hiểm tài sản có thể chuyển giao được không?","options":[{"key":"A","text":"Có"},{"key":"B","text":"Không"},{"key":"C","text":"Có, với điều kiện bên mua bảo hiểm không thông báo bằng văn bản và được doanh nghiệp bảo hiểm đồng ý bằng văn bản, trừ trường hợp việc chuyển giao được thực hiện theo tập quán quốc tế hoặc theo thỏa thuận trong hợp đồng bảo hiểm"}],"answer":"C","explanation":"Theo đáp án của đề cương, đáp án đúng là **C**: **Có, với điều kiện bên mua bảo hiểm không thông báo bằng văn bản và được doanh nghiệp bảo hiểm đồng ý bằng văn bản, trừ trường hợp việc chuyển giao được thực hiện theo tập quán quốc tế hoặc theo thỏa thuận trong hợp đồng bảo hiểm**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Có, với điều kiện bên mua bảo hiểm không thông báo bằng văn bản và được doanh nghiệp bảo…**."},{"id":518,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, trong trường hợp người thứ 3 yêu cầu bên mua bảo hiểm bồi thường về những thiệt hại thuộc trách nhiệm bảo hiểm theo thỏa thuận trong hợp đồng bảo hiểm thò thời hạn nộp hồ sơ yêu cầu bồi thường theo hợp đồng bảo hiểm là:","options":[{"key":"A","text":"1 năm kể từ ngày xảy ra sự kiện bảo hiểm"},{"key":"B","text":"1 năm kể từ ngày xảy ra tranh chấp"},{"key":"C","text":"1 năm kể từ ngày người thứ 3 yêu cầu"},{"key":"D","text":"2 năm kể từ ngày người thứ 3 yêu cầu"}],"answer":"C","explanation":"Khái niệm cần nhớ trong câu này là: **1 năm kể từ ngày người thứ 3 yêu cầu**. Đáp án đúng là **C**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Chốt mốc **1 năm, 3** và gắn với đúng điều kiện của câu."},{"id":519,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiềm, bên mua bảo hiểm là:","options":[{"key":"A","text":"Tổ chức, cá nhân giao kết hợp đồng bảo hiểm với doanh nghiệp bảo hiểm và đóng phí bảo hiểm"},{"key":"B","text":"Tổ chức, cá nhân giao kết hợp đồng với đại lý bảo hiểm và đóng phí bảo hiểm"},{"key":"C","text":"Tổ chức, cá nhân giao kết hợp đồng bảo hiểm với nhà tái bảo hiểm và đóng phí bảo hiểm"},{"key":"D","text":"Tổ chức, cá nhân giao kết hợp đồng bảo hiểm với nhà tái bảo hiểm và đóng phí bảo hiểm"}],"answer":"A","explanation":"Khái niệm cần nhớ trong câu này là: **Tổ chức, cá nhân giao kết hợp đồng bảo hiểm với doanh nghiệp bảo hiểm và đóng phí bảo hiểm**. Đáp án đúng là **A**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Tổ chức, cá nhân giao kết hợp đồng bảo hiểm với doanh nghiệp bảo hiểm và đóng phí bảo hiểm**."},{"id":520,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phát biểu nào dưới đây đúng:","options":[{"key":"A","text":"Doanh nghiệp có vốn đầu tư nước ngoài, người nước ngoài tại Việt Nam có nu cầu bảo hiểm chỉ được lựa chọn tham gia bảo hiểm tại doanh nghiệp bảo hiểm hoạt động tại Việt Nam ."},{"key":"B","text":"Tổ chức, cá nhân tại Việt Nam có nhu cầu tham gia bảo hiểm chỉ được tham gia bảo hiểm tại doanh nghiệp bảo hiểm được cấp giấy phép thành lập và hoạt động tại Việt Nam"},{"key":"C","text":"Tổ chức, cá nhân tại Việt Nam có nhu cầu tham gia bảo hiểm chỉ được tham gia bảo hiểm tại doanh nghiệp bảo hiểm được cấp giấy phép thành lập và hoạt động tại Việt Nam (trừ trường hợp sử dụng dịch vụ bảo hiểm qua biên giới)"},{"key":"D","text":"A, B, C sai"}],"answer":"C","explanation":"Theo đáp án của đề cương, phương án **C** là nội dung đúng: **Tổ chức, cá nhân tại Việt Nam có nhu cầu tham gia bảo hiểm chỉ được tham gia bảo hiểm tại doanh nghiệp bảo hiểm được cấp giấy phép thành lập và hoạt động tại Việt Nam (trừ trường hợp sử dụng dịch vụ bảo hiểm qua biên giới)**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Tổ chức, cá nhân tại Việt Nam có nhu cầu tham gia bảo hiểm chỉ được tham gia bảo hiểm tại…**."},{"id":521,"category":"Luật Kinh doanh bảo hiểm","question":"Trường hợp sự kiện bảo hiểm xảy ra trong thời gian gia hạn đóng phí và bên mua bảo hiểm chưa đóng đủ phí bảo hiểm, doanh nghiệp bảo hiểm có trách nhiệm chi trả quyền lợi bảo hiểm, bên mua bảo hiểm","options":[{"key":"A","text":"Đúng"},{"key":"B","text":"Sai"}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án **A** là **Đúng**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Đúng**."},{"id":522,"category":"Kiến thức chung","question":"Chọn phương án đúng nhất về loại trừ bảo hiểm:","options":[{"key":"A","text":"Loại trừ bảo hiểm là loại trừ các rủi ro, tổn thất mà doanh nghiệp bảo hiểm không chịu trách nhiệm bồi thường, trả tiền bảo hiểm nếu xảy ra sự kiện bảo hiểm"},{"key":"B","text":"Loại trừ bảo hiểm là loại trừ các rủi ro, tổn thất và chi phí pát sinh mà doanh nghiệp bảo hiểm không chịu trách nhiệm bồi thường, trả tiền bảo hiểm nếu xảy ra sự kiện bảo hiểm"},{"key":"C","text":"Loại trừ bảo hiểm được căn cứ theo các điều kiện, điều khoản loại trừ bảo hiểm quy định trong Quy tắc bảo hiểm và các điều khoản sửa đổi, bổ sung (nếu có) kèm theo hợp đồng bảo hiểm"},{"key":"D","text":"A, C"},{"key":"E","text":"B, C"}],"answer":"E","explanation":"Theo đáp án của đề cương, phương án **E** là nội dung đúng: **B, C**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **B, C**."},{"id":523,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, đối với bảo hiểm tài sản, đáp án nào đúng khi điền vào chỗ ____ dưới đây: “_____ là số tiền mà bên mua bảo hiểm và doanh nghiệp bảo hiểm thỏa thuận trong hợp đồng bảo hiểm để bảo hiểm cho tài sản và thiệt hại trên cơ sở yêu cầu của bên mua bảo hiểm”.","options":[{"key":"A","text":"Phí bảo hiểm"},{"key":"B","text":"Số tiền bồi thường"},{"key":"C","text":"Số tiền bảo hiểm"},{"key":"D","text":"Giá trị bảo hiểm"}],"answer":"C","explanation":"Theo đáp án của đề cương, đáp án **C** là **Số tiền bảo hiểm**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Số tiền bảo hiểm**."},{"id":524,"category":"Kiến thức chung","question":"Chọn phương án đúng nhất về mức trách nhiệm bảo hiểm:","options":[{"key":"A","text":"Mức trách nhiệm bảo hiểm"},{"key":"B","text":"Mức trách nhiệm bảo hiểm là một khoản tiền gửi giới hạn trách nhiệm cho mỗi sự cố cho thời hạn đáo thời hạn bảo hiểm"},{"key":"C","text":"Mức trách nhiệm bảo hiểm là mức trách nhiệm của doanh nghiệp bảo hiểm đối với người thư ba về người và tài sản trong mỗi sự cố hoặc cho cả thời hạn bảo hiểm"},{"key":"D","text":"Mức trách nhiệm bảo hiểm là số tiền tối đa mà doanh nghiệp bảo hiểm phải trả cho người được bảo hiểm trong một sự kiện bảo hiểm hoặc trong cả thời gian"}],"answer":"C","explanation":"Theo đáp án của đề cương, phương án **C** là nội dung đúng: **Mức trách nhiệm bảo hiểm là mức trách nhiệm của doanh nghiệp bảo hiểm đối với người thư ba về người và tài sản trong mỗi sự cố hoặc cho cả thời hạn bảo hiểm**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Mức trách nhiệm bảo hiểm là mức trách nhiệm của doanh nghiệp bảo hiểm đối với người thư ba…**."},{"id":525,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, phương án đúng nhất cho trường hợp đồng bảo hiểm cho một đối tượng bảo hiểm, hợp đồng bảo hiểm phải có thông tin nào sau đây:","options":[{"key":"A","text":"Tên doanh nghiệp bảo hiểm đứng đầu"},{"key":"B","text":"Tỷ lệ đồng bảo hiểm của từng doanh nghiệp bảo hiểm"},{"key":"C","text":"Tỷ lệ phân chia trách nhiệm bồi thường trong trường hợp xảy ra sự kiện bảo hiểm"},{"key":"D","text":"A, B đúng"},{"key":"E","text":"A, B, C đúng"}],"answer":"D","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **D**: **A, B đúng**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B đúng**."},{"id":526,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật kinh doanh bảo hiểm, chọn phương án đúng về bảo hiểm trùng:","options":[{"key":"A","text":"Đối tượng bảo hiểm được bảo vệ bằng ít nhất hai hợp đồng bảo hiểm"},{"key":"B","text":"Các hợp đồng bảo hiểm phải có cùng phạm vi, thời hạn vầ sự kiện bảo hiểm"},{"key":"C","text":"Tổng số tiền bảo hiểm vượt qua giá thị trường của tài sản được bảo hiểm tại thời điểm giao kết hợp đồng bảo hiểm"},{"key":"D","text":"A, B ,C đúng"}],"answer":"D","explanation":"Theo đáp án của đề cương, phương án **D** là nội dung đúng: **A, B ,C đúng**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B ,C đúng**."},{"id":527,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, hợp đồng bảo hiểm trùng trong bảo hiểm tài sản là trường hợp có từ hai hợp đồng bảo hiểm trở lên mà tổng số tiền bảo hiểm vượt quá giá thị trường của tài sản được bảo hiểm tại thời điểm giao kết hợp đồng bảo hiểm để bảo hiểm cho:","options":[{"key":"A","text":"Cùng phạm vi, đối tượng bảo hiểm"},{"key":"B","text":"Cùng thời hạn bảo hiểm"},{"key":"C","text":"Cùng sự kiện bảo hiểm"},{"key":"D","text":"A, B, C đúng"}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án **D** là **A, B, C đúng**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng**."},{"id":528,"category":"Kiến thức chung","question":"Nguyên tắc đóng góp bồi thường có liên quan trực tiếp nhất đến nguyên tắc nào sau đây:","options":[{"key":"A","text":"Nguyên tắc thế quyền"},{"key":"B","text":"Nguyên tắc bồi thường"},{"key":"C","text":"Nguyên tắc nguyên nhân trực tiếp"},{"key":"D","text":"Nguyên tắc quyền lợi được bảo hiểm"}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án đúng là **B**: **Nguyên tắc bồi thường**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Nguyên tắc bồi thường**."},{"id":529,"category":"Bảo hiểm con người","question":"Trong bảo hiểm sức khỏe, không áp dụng thời gian chờ đối với mọi trường hợp điều trị do tai nạn?","options":[{"key":"A","text":"Đúng"},{"key":"B","text":"Sai"}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án **A** là **Đúng**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Đúng**."},{"id":530,"category":"Bảo hiểm con người","question":"Trong bảo hiểm sức khỏe, thời gian chờ không áp dụng cho trường hợp điều trị nào sau đây?","options":[{"key":"A","text":"Điều trị do tai nạn"},{"key":"B","text":"Điều trị các bệnh mãn tính"},{"key":"C","text":"Điều trị viêm đường hô hấp"},{"key":"D","text":"Điều trị ốm đau"}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án **A** là **Điều trị do tai nạn**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Điều trị do tai nạn**."},{"id":531,"category":"Bảo hiểm con người","question":"Người được bảo hiểm tham gia 02 hợp đồng bảo hiểm tai nạn con người tại hai doanh nghiệp bảo hiểm khác nhau và không may bị tai nạn dẫn đến tử vong. Quyền lợi bảo hiểm mà người thụ hưởng nhận được trong trường hợp này là:","options":[{"key":"A","text":"Số tiền bảo hiểm cao nhất trong hai hợp đồng bảo hiểm"},{"key":"B","text":"Tổng số tiền bảo hiểm đã thỏa thuận tại hai hợp đồng bảo hiểm"},{"key":"C","text":"Số tiền bảo hiểm đã thỏa thuận tại hợp đồng bảo hiểm được giao kết đầu tiên"}],"answer":"B","explanation":"Khái niệm cần nhớ trong câu này là: **Tổng số tiền bảo hiểm đã thỏa thuận tại hai hợp đồng bảo hiểm**. Đáp án đúng là **B**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Tổng số tiền bảo hiểm đã thỏa thuận tại hai hợp đồng bảo hiểm**."},{"id":532,"category":"Bảo hiểm con người","question":"Trong bảo hiểm sức khỏe, doanh nghiệp bảo hiểm có chi trả chi phí điều trị trước và sau khi nhập viện ốm đau, bệnh tật theo chỉ định của bác sĩ không?","options":[{"key":"A","text":"Có"},{"key":"B","text":"Không"}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Có**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Có**."},{"id":533,"category":"Bảo hiểm xe cơ giới","question":"Trong đơn bảo hiểm thiệt hại vật chất xe ô tô (có kèm theo điều khoản sửa đổi bổ sung “Bảo hiểm thiệt hại động cơ do hiện tượng thủy kích”), doanh nghiệp bảo hiểm sẽ bồi thường cho các chi phí nào sau đây?","options":[{"key":"A","text":"Các chi phí sửa chữa, khắc phục những thiệt hại của động cơ do xe đi vào vùng ngập nước và.hoặc nước lọt vào động cơ gây ra hiện tượng thủy kích"},{"key":"B","text":"Chi phí khắc phục tổn thất xảy ra cho động cơ xe ô tô khi lái xe cố tình khởi động lại động cơ đã ngưng hoạt động sau khi xe được bảo hiểm bị ngập nước gây ra hiện tượng thủy kích"},{"key":"C","text":"A, B đúng"}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Các chi phí sửa chữa, khắc phục những thiệt hại của động cơ do xe đi vào vùng ngập nước và.hoặc nước lọt vào động cơ gây ra hiện tượng thủy kích**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Các chi phí sửa chữa, khắc phục những thiệt hại của động cơ do xe đi vào vùng ngập nước…**."},{"id":534,"category":"Bảo hiểm xe cơ giới","question":"Theo đơn Bảo hiểm trách nhiệm dân sự của chủ xe cơ giới đối với hàng hóa vận chuyển trên xe (không kèm điều khoản sửa đổi bổ sung), doanh nghiệp bảo hiểm không bồi thường cho người được bảo hiểm đối với hàng hóa bị tổn thất trong trường hợp nào sau đây:","options":[{"key":"A","text":"Hàng hóa bị tổn thất trong quá trình xếp dỡ"},{"key":"B","text":"Hàng hóa bị hư hỏng do bao bì đóng gói"},{"key":"C","text":"Hàng hóa bị tổn thất do va chạm vào nhau trong quá trình vận chuyển"},{"key":"D","text":"A, B, C đúng"}],"answer":"D","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **D**: **A, B, C đúng**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng**."},{"id":535,"category":"Bảo hiểm xe cơ giới","question":"Cả xe A và xe B đều tham gia bảo hiểm tai nạn lái, phụ xe và người ngồi trên xe theo hai hợp đồng bảo hiểm khác nhau tại doanh nghiệp bảo hiểm X. Chủ xe A đã điều khiển xe B gây tai nạn và bị thương tật. Trường hợp này doanh nghiệp bảo hiểm X sẽ trả tiền bảo hiểm cho người được bảo hiểm như thế nào:","options":[{"key":"A","text":"Không trả tiền bảo hiểm"},{"key":"B","text":"Trả tiền theo số tiền bảo hiểm thỏa thuận tại hợp đồng bảo hiểm của xe A"},{"key":"C","text":"Trả tiền theo số tiền bảo hiểm thỏa thuận tại hợp đồng bảo hiểm của xe B"},{"key":"D","text":"Trả tiền theo hợp đồng bảo hiểm có số tiền bảo hiểm thỏa thuận lớn nhất"}],"answer":"C","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **C**: **Trả tiền theo số tiền bảo hiểm thỏa thuận tại hợp đồng bảo hiểm của xe B**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Trả tiền theo số tiền bảo hiểm thỏa thuận tại hợp đồng bảo hiểm của xe B**."},{"id":536,"category":"Bảo hiểm xe cơ giới","question":"Theo đơn bảo hiểm tai nạn lái, phụ xe và người ngồi trên xe, doanh nghiệp bảo hiểm sẽ trả tiền bảo hiểm cho người ngồi trên xe thiệt hại về thân thể, tính mạng do:","options":[{"key":"A","text":"Tai nạn xảy ra đối với người đang ngồi trên xe trong quá trình xe tham gia giao thông"},{"key":"B","text":"Tai nạn xảy ra đối với người đang lên xuống xe trong quá trình xe tham gia giao thông"},{"key":"C","text":"Tai nạn xảy ra đối với người ngồi trên xe khi xe không tham gia giao thông"},{"key":"D","text":"A, B đúng"}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **A, B đúng**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B đúng**."},{"id":537,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, đối tượng bảo hiểm của hợp đồng bảo hiểm tài sản là:","options":[{"key":"A","text":"Tài sản theo quy định của Bộ Luật Dân sự"},{"key":"B","text":"Bất kỳ lợi ích kinh tế hoặc nghĩa vụ thực hiện hợp đồng hoặc nghĩa vụ theo pháp luật mà người được bảo hiểm phải gánh chịu khi xảy ra tổn thất."},{"key":"C","text":"A, B đúng"}],"answer":"C","explanation":"Khái niệm cần nhớ trong câu này là: **A, B đúng**. Đáp án đúng là **C**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B đúng**."},{"id":538,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Đối tượng bảo hiểm tài sản là:","options":[{"key":"A","text":"Tòa nhà, đồ vật cố định và trang trí trong tòa nhà"},{"key":"B","text":"Máy móc thiết bị"},{"key":"C","text":"Nguyên vật liệu, thành phẩm, bán thành phẩm thuộc hoạt động sản xuất kinh doanh của người được bảo hiểm"},{"key":"D","text":"A, B, C đúng"}],"answer":"D","explanation":"Khái niệm cần nhớ trong câu này là: **A, B, C đúng**. Đáp án đúng là **D**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng**."},{"id":539,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, đối với bảo hiểm tài sản, trường hợp người được bảo hiểm không thực hiện các biện pháp đảm bảo an toàn cho đối tượng bảo hiểm thì doanh nghiệp bảo hiểm có quyền:","options":[{"key":"A","text":"Ấn định một thời hạn để người được bảo hiểm thực hiện các biện pháp đảm bảo an toàn cho đối tượng bảo hiểm"},{"key":"B","text":"Nếu hết thời hạn để người được bảo hiểm thực hiện các biện pháp đảm bảo an toàn mà các biện pháp đó vẫn không được thực hiên thì doanh nghiệp bảo hiểm có quyền tăng phí bảo hiểm"},{"key":"C","text":"Nếu hết thời hạn để người được bảo hiểm thực hiện các biện pháp đảm bảo an toàn mà các biện pháp đó vẫn không được thực hiện thì doanh nghiệp bảo hiểm có quyền đơn phương chấm dứt thực hiện hợp đồng bảo hiểm"},{"key":"D","text":"A, B, C"}],"answer":"C","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **C**: **Nếu hết thời hạn để người được bảo hiểm thực hiện các biện pháp đảm bảo an toàn mà các biện pháp đó vẫn không được thực hiện thì doanh nghiệp bảo hiểm có quyền đơn phương chấm dứt thực hiện hợp đồng bảo hiểm**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Nếu hết thời hạn để người được bảo hiểm thực hiện các biện pháp đảm bảo an toàn mà các biện…**."},{"id":540,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"“Trong bảo hiểm tài sản, đơn vị rủi ro (ngôi nhà) được coi là cách biệt về mặt không gian nếu giữa các ngôi nhà đảm bảo tối thiểu một khoảng cách nào đó”. Phát biểu trên là:","options":[{"key":"A","text":"Đúng"},{"key":"B","text":"Sai"}],"answer":"A","explanation":"Khái niệm cần nhớ trong câu này là: **Đúng**. Đáp án đúng là **A**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Đúng**."},{"id":541,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Kính lắp cố định có được bảo hiểm theo Quy tắc bảo hiểm “Mọi rủi ro tài sản” của Hiệp hội Bảo hiểm Vương quốc Anh (ABI) không:","options":[{"key":"A","text":"Có"},{"key":"B","text":"Không"},{"key":"C","text":"Không, trừ trường hợp được bảo hiểm theo Điều khoản bảo hiểm bổ sung riêng cho kính lắp cố định"}],"answer":"C","explanation":"Theo đáp án của đề cương, đáp án đúng là **C**: **Không, trừ trường hợp được bảo hiểm theo Điều khoản bảo hiểm bổ sung riêng cho kính lắp cố định**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Không, trừ trường hợp được bảo hiểm theo Điều khoản bảo hiểm bổ sung riêng cho kính lắp cố định**."},{"id":542,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Đối tượng có thể được bảo hiểm theo Phần I- Phần tổn thất vật chất của Đơn bảo hiểm xây dựng/lắp đặt (CAR/EAR) của nhà tái bảo hiểm Munich Re, là:","options":[{"key":"A","text":"Công trình xây dựng, lắp đặt"},{"key":"B","text":"Tài sản trên và xung quanh công trường thuộc quyền sở hữu, chăm sóc của người được bảo hiểm"},{"key":"C","text":"Trách nhiệm đối với người thứ ba về người và tài sản"},{"key":"D","text":"B, C đúng"},{"key":"E","text":"A, B, C đúng"}],"answer":"D","explanation":"Khái niệm cần nhớ trong câu này là: **B, C đúng**. Đáp án đúng là **D**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **B, C đúng**."},{"id":543,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Tại thời điểm tổn thất, nếu số tiền bảo hiểm của máy móc thiết bị chủ thầu (CPM) theo quy tắc bảo hiểm của nhà tái bảo hiểm Munich Re nhỏ hơn giá trị thay thế mới thì phương án bồi thường nào sau đây đúng (Giả sử máy móc thiết bị hư hỏng và không có giá trị thu hồi):","options":[{"key":"A","text":"Số tiền bồi thường = Chi phí khắc phục – Khấu hao tài sản"},{"key":"B","text":"Số tiền bồi thường = {Chi phí khắc phục x (số tiền bảo hiểm.Giá trị thay thế mới của tài sản được bảo hiểm) – Mức miễn thường khấu trừ"}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án **B** là **Số tiền bồi thường = {Chi phí khắc phục x (số tiền bảo hiểm.Giá trị thay thế mới của tài sản được bảo hiểm) – Mức miễn thường khấu trừ**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Số tiền bồi thường = {Chi phí khắc phục x (số tiền bảo hiểm.Giá trị thay thế mới của tài…**."},{"id":544,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Theo đơn bảo hiểm “Hỏa hoạn và các rủi ro đặc biệt” của Hiệp hội bảo hiểm Vương Quốc Anh (ABI), áp dụng từ rủi to A đến J, tài sản bị thiệt hại do nguyên nhân nào sau đây không bị loại trừ bảo hiểm","options":[{"key":"A","text":"Thiệt hại đối với máy móc thiết bị do cháy phát sinh từ sự cố máy móc thiết bị khác bị hồ quang điện"},{"key":"B","text":"Thiệt hại đối với máy móc thiết bị do đoản mạch"},{"key":"C","text":"Thiệt hại phát sinh từ hậu quả gây ra bởi nhiễm phóng xạ"},{"key":"D","text":"Thiệt hại do nước chảy ra từ hệ thống chữa cháy tự động Spinkler"}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Thiệt hại đối với máy móc thiết bị do cháy phát sinh từ sự cố máy móc thiết bị khác bị hồ quang điện**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Thiệt hại đối với máy móc thiết bị do cháy phát sinh từ sự cố máy móc thiết bị khác bị hồ…**."},{"id":545,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Theo đơn bảo hiểm “Hỏa hoạn và các rủi ro đặc biệt” của Hiệp hội bảo hiểm Vương Quốc Anh (ABI), nếu tham gia bảo hiểm rủi ro A, H thì nguyên nhân gây ra tổn thất nào sau đây thuộc phạm vi bảo hiểm","options":[{"key":"A","text":"Tổn thất do nước tràn từ các bể chứa nước"},{"key":"B","text":"Tổn thất do nước từ đường ống dẫn nước"},{"key":"C","text":"Tổn thất do nước mưa ngấm qua tường nhà làm hàng hóa trong kho bị hư hỏng"},{"key":"D","text":"Tổn thất do nước tràn từ các hồ chứa nước"}],"answer":"D","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **D**: **Tổn thất do nước tràn từ các hồ chứa nước**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Tổn thất do nước tràn từ các hồ chứa nước**."},{"id":546,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Theo đơn bảo hiểm “Hỏa hoạn và các rủi ro đặc biệt” của Hiệp hội bảo hiểm Vương Quốc Anh (ABI), nếu tham ra bảo hiểm rủi ro A, G thì tài sản nào sau đây được bảo hiểm:","options":[{"key":"A","text":"Công trình đang thi công, cải tạo nhưng tất cả các cửa ra vào, cửa sổ và các ô mở khác đã được hoàn thành để chống giông, bão"},{"key":"B","text":"Các trang thiết bị lắp đặt phía ngoài"},{"key":"C","text":"Biển quảng cáo, hàng rào"},{"key":"D","text":"Tài sản di động được để ngoài trời"}],"answer":"A","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **A**: **Công trình đang thi công, cải tạo nhưng tất cả các cửa ra vào, cửa sổ và các ô mở khác đã được hoàn thành để chống giông, bão**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Công trình đang thi công, cải tạo nhưng tất cả các cửa ra vào, cửa sổ và các ô mở khác đã…**."},{"id":547,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Những rủi ro nào thuộc phạm vi bảo hiểm của quy tắc bảo hiểm các công trình dân dụng đã hoàn thành (CECR)?","options":[{"key":"A","text":"Hỏa hoạn, sét đánh trực tiếp, nổ"},{"key":"B","text":"Bão với sức gió lớn hơn cấp 8"},{"key":"C","text":"Lũ, lụt; lún, lở đất, lở đá…"},{"key":"D","text":"A, B, C đúng"}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **A, B, C đúng**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng**."},{"id":548,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Yếu tố nào dưới đây không liên quan đến việc tính phí bảo hiểm của sản phẩm bảo hiểm trách nhiệm nghề nghiệp","options":[{"key":"A","text":"Thu nhập hàng năm của người được bảo hiểm"},{"key":"B","text":"Vị trí đặt văn phòng. nơi làm việc của người được bảo hiểm"},{"key":"C","text":"Số lượng chuyên viên tham gia công việc tư vấn. dịch vụ của người được bảo hiểm"},{"key":"D","text":"Lĩnh vực và phạm vi công việc của người được bảo hiểm"}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án đúng là **B**: **Vị trí đặt văn phòng. nơi làm việc của người được bảo hiểm**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Vị trí đặt văn phòng. nơi làm việc của người được bảo hiểm**."},{"id":549,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Theo hợp đồng bảo hiểm trách nhiệm trên cơ sở tổn thất phát sinh, doanh nghiệp bảo hiểm sẽ bồi thường cho những sự kiện bảo hiểm nào dưới đây:","options":[{"key":"A","text":"Sự kiện bảo hiểm xảy ra trước ngày bắt đầu hiệu lực của hợp đồng bảo hiểm và khiếu nại của bên thứ ba được lập trong thời hạn của hợp đồng bảo hiểm"},{"key":"B","text":"Sự kiện bảo hiểm xảy ra trong thời hạn hợp đồng bảo hiểm và khiếu nại của bên thứ ba có thể được lập sau thời hạn bảo hiểm"},{"key":"C","text":"Sự kiện bảo hiểm xảy ra trước ngày bắt đầu hiệu lực của hợp đồng bảo hiểm, được phát hiện trong thời hạn hợp đồng bảo hiểm và khiếu nại của bên thứ ba được lập trong thời hạn của hợp đồng bảo hiểm"}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án đúng là **B**: **Sự kiện bảo hiểm xảy ra trong thời hạn hợp đồng bảo hiểm và khiếu nại của bên thứ ba có thể được lập sau thời hạn bảo hiểm**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Sự kiện bảo hiểm xảy ra trong thời hạn hợp đồng bảo hiểm và khiếu nại của bên thứ ba có thể…**."},{"id":550,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Hợp đồng bảo hiểm trách nhiệm nghề nghiệp không loại trừ:","options":[{"key":"A","text":"Khiếu nại đã được biết trước hoặc tình huống phát sinh khiếu nại đã được biết trước khi đơn bảo hiểm có hiệu lực"},{"key":"B","text":"Hành vi bất cẩn của người được bảo hiểm khi đang thực hiện công việc chuyên môn cho bên thứ ba"},{"key":"C","text":"Hành vi cố ý, lỗi cố ý của người được bảo hiểm khi thực hiện công việc chuyên môn cho bên thứ ba"},{"key":"D","text":"Hành vi lừa đảo, hối lộ, không trung thực của người được bảo hiểm khi thực hiện công việc chuyên môn cho bên thứ ba"}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án đúng là **B**: **Hành vi bất cẩn của người được bảo hiểm khi đang thực hiện công việc chuyên môn cho bên thứ ba**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Hành vi bất cẩn của người được bảo hiểm khi đang thực hiện công việc chuyên môn cho bên thứ ba**."},{"id":551,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Trong bảo hiểm trách nhiệm nghề nghiệp cho kỹ sư, tư vấn xây dựng, doanh nghiệp bảo hiểm sẽ bồi thường:","options":[{"key":"A","text":"Tổn thất về tài sản và thương tật của người thứ ba ngoài phạm vi công trình do bị tai nạn bất ngờ trong khi thi công công trình"},{"key":"B","text":"Tai nạn lao động của người lao động đó do bất cẩn trong khi thi công trên công trường"},{"key":"C","text":"Thiệt hại về tài sản của công trình do lỗi thiết kế của người được bảo hiểm"},{"key":"D","text":"Tổn thất tài sản do nguyên vật liệu kém chất lượng và tay nghề kém"}],"answer":"C","explanation":"Theo đáp án của đề cương, đáp án đúng là **C**: **Thiệt hại về tài sản của công trình do lỗi thiết kế của người được bảo hiểm**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Thiệt hại về tài sản của công trình do lỗi thiết kế của người được bảo hiểm**."},{"id":552,"category":"Bảo hiểm con người","question":"Trong quá trình điều trị bệnh đau dạ dày, bệnh nhân X đang nằm nội trú trong bệnh viện A đã bị thêm chấn thương gãy chân do chiếc giường bệnh lâu ngày bị mục và sập.gãy. Giả sử bệnh viện A mua đủ các loại bảo hiểm trách nhiệm. Việc này xem xét bồi thường thương tật phát sinh (gãy chân) của bệnh nhân nói trên do lỗi của bệnh viện gây ra sẽ được thực hiện theo hợp đồng bảo hiểm nào:","options":[{"key":"A","text":"Hợp đồng bảo hiểm trách nhiệm công cộng"},{"key":"B","text":"Hợp đồng bảo hiểm trách nhiệm sản phẩm"},{"key":"C","text":"Hợp đồng bảo hiểm trách nhiệm nghề y (Medical Malpractice)"},{"key":"D","text":"Hợp đồng bảo hiểm trách nhiệm kỹ sư tư vấn thiết kế"}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Hợp đồng bảo hiểm trách nhiệm công cộng**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Hợp đồng bảo hiểm trách nhiệm công cộng**."},{"id":553,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Nhà máy sản xuất ổ cắm điện và biến áp gia đình mua bảo hiểm trách nhiệm công cộng và bảo hiểm trách nhiệm sản phẩm. Khách hàng A đến thăm phòng triển lãm sản phẩm tại nhà máy. Trong quá trình xem hàng và thao tác trên sản phẩm, khách hàng bị điện giật do sản phẩm bị rò điện. Trách nhiệm pháp lý phát sinh của nhà máy sản xuất đối với khách hàng thuộc:","options":[{"key":"A","text":"Hợp đồng bảo hiểm trách nhiệm công cộng"},{"key":"B","text":"Hợp đồng bảo hiểm trách nhiệm sản phẩm"},{"key":"C","text":"Hợp đồng bảo hiểm trách nhiệm nghề nghiệp"},{"key":"D","text":"Không thuộc hợp đồng bảo hiểm nào"}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Hợp đồng bảo hiểm trách nhiệm công cộng**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Hợp đồng bảo hiểm trách nhiệm công cộng**."},{"id":554,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Theo quy tắc bảo hiểm “Gián đoạn kinh doanh” của Hiệp hội bảo hiểm Vương quốc Anh (ABI), “Chi phí hoạt động gia tăng” trong hạng mục bảo hiểm tổn thất lợi nhuận gộp là:","options":[{"key":"A","text":"Các chi phí phát sinh thêm được bảo hiểm theo một hạn mức riêng"},{"key":"B","text":"Các chi phí cần thiết và hợp lý nhằm ngăn ngừa hay hạn chế việc giảm doanh thu mà nếu không có các chi phí này thì sự sụt giảm doanh thu có thể đã xảy ra trong thời hạn bồi thường do hậu quả của thiệt hại"},{"key":"C","text":"Các chi phí này không vượt quá số tiền được tính toán bằng cách nhân tỷ lệ lợi nhuận gộp với số sụt giảm doanh thu đã ngăn chặn được"},{"key":"D","text":"A, C đúng"},{"key":"E","text":"B, C đúng"}],"answer":"E","explanation":"Khái niệm cần nhớ trong câu này là: **B, C đúng**. Đáp án đúng là **E**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **B, C đúng**."},{"id":555,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"“Mức giảm doanh thu do hậu quả của thiệt hại gây ra” theo quy tắc bảo hiểm Gián đoạn kinh doanh của Hiệp hội bảo hiểm Vương quốc Anh (ABI) được hiểu là đúng:","options":[{"key":"A","text":"Mức giảm doanh thu do hậu quả của thiệt hại gây ra = Doanh thu tiêu chuẩn – Doanh thu thực tế thực hiện tính đến thời điểm tổn thất"},{"key":"B","text":"Mức giảm doanh thu do hậu quả của thiệt hại gây ra = Doanh thu tiêu chuẩn – Doanh thu thực tế thực hiện trong thời hạn bồi thường"},{"key":"C","text":"Mức giảm doanh thu do hậu quả của thiệt hại gây ra = Doanh thu kế hoạch năm tài chính – Doanh thu thực tế thực hiện tính đến thời điểm tổn thất"}],"answer":"B","explanation":"Khái niệm cần nhớ trong câu này là: **Mức giảm doanh thu do hậu quả của thiệt hại gây ra = Doanh thu tiêu chuẩn – Doanh thu thực tế thực hiện trong thời hạn bồi thường**. Đáp án đúng là **B**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Mức giảm doanh thu do hậu quả của thiệt hại gây ra = Doanh thu tiêu chuẩn – Doanh thu thực…**."},{"id":556,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Cách xác định lợi nhuận gộp theo Đơn bảo hiểm “Gián đoạn kinh doanh” của Hiệp hội bảo hiểm Vương quốc Anh (ABI) nào sau đây không đúng:","options":[{"key":"A","text":"Lợi nhuận gộp là lợi nhuận ròng trước thuế cộng chi phí cố định"},{"key":"B","text":"Lợi nhuận gộp là lợi nhuận kinh doanh thuần sau thuế và chi phí cố định."},{"key":"C","text":"Lợi nhuận gộp được xác định bằng doanh thu trừ đi chi phí biến đổi và các chi phí cố định mà người được bảo hiểm tự bảo hiểm"},{"key":"D","text":"Lợi nhuận gộp = (Doanh thu + Giá trị hàng tồn kho cuối kỳ + Giá trị sản phẩm dở dang cuối kỳ) – (Giá trị hàng tồn kho đầu kỳ + Giá trị sản phẩm dở dang đầu kỳ + Các khoản chi phí hoạt động không được bảo hiểm)"}],"answer":"B","explanation":"Đây là câu hỏi tìm **phương án ngoại lệ/sai**. Theo đáp án của đề cương, phương án **B** là nội dung không phù hợp: **Lợi nhuận gộp là lợi nhuận kinh doanh thuần sau thuế và chi phí cố định.**. Khi làm bài, cần chú ý từ khóa phủ định như **“sai”, “không”, “ngoại trừ”**.","tip":"💡 Mẹo nhớ: Gạch chân từ **SAI/KHÔNG/NGOẠI TRỪ** trước khi đọc phương án."},{"id":557,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, doanh nghiệp bảo hiểm không được ủy quyền cho đại lý bảo hiểm thực hiện hoạt động nào dưới đây:","options":[{"key":"A","text":"Giới thiệu, chào bán sản phẩm bảo hiểm"},{"key":"B","text":"Thu xếp giao kết hợp đồng bảo hiểm"},{"key":"C","text":"Thu phí bảo hiểm"},{"key":"D","text":"Thu xếp tái bảo hiểm"}],"answer":"E","explanation":"Theo đáp án của đề cương, đáp án đúng là **E**: **Phương án E**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý ****."},{"id":558,"category":"Luật Kinh doanh bảo hiểm","question":"Mức vốn điều lệ tối thiểu của doanh nghiệp bảo hiểm kinh doanh bảo hiểm phi nhân thọ (bao gồm vệ tinh hoặc hàng không)","options":[{"key":"A","text":"450 tỷ đồng Việt Nam"},{"key":"B","text":"300 tỷ đồng Việt Nam"},{"key":"C","text":"500 tỷ đồng Việt Nam"},{"key":"D","text":"200 tỷ đồng Việt Nam"}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án **A** là **450 tỷ đồng Việt Nam**. Mốc cần nhớ: **450 tỷ**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Chốt mốc **450 tỷ** và gắn với đúng điều kiện của câu."},{"id":559,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Theo đơn bảo hiểm mọi rủi ro xây dựng, lắp đặt (CAR/EAR) của nhà tái bảo hiểm Munich Re, tài sản trên và xung quanh khu vực công trường thuộc quyền sở hữu, quản lý, chăm sóc của người được bảo hiểm có thể được bảo hiểm theo phần nào trong đơn:","options":[{"key":"A","text":"Phần I- Phần tổn thất vật chất"},{"key":"B","text":"Phần II –Trách nhiệm đối với bên thứ ba"},{"key":"C","text":"A, B đúng"}],"answer":"C","explanation":"Theo đáp án của đề cương, đáp án đúng là **C**: **A, B đúng**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B đúng**."},{"id":560,"category":"Bảo hiểm xe cơ giới","question":"Theo đơn bảo hiểm vật chất xe cơ giới, doanh nghiệp bảo hiểm phải hoàn trả cho chủ xe cơ giới những chi phí cần thiết và hợp lý nào sau đây theo thỏa thuận tại hợp đồng bảo hiểm khi tai nạn xảy ra thuộc phạm vi bảo hiểm:","options":[{"key":"A","text":"Chi phí ngăn ngừa hạn chế tổn thất phát sinh thêm"},{"key":"B","text":"Chi phí cứu hộ và vận chuyển xe bị thiệt hại tới nơi sửa chữa gần nhất"},{"key":"C","text":"Chi phí vận chuyển người bị nạn trên xe đến bệnh viện"},{"key":"D","text":"A, B"},{"key":"E","text":"A, C"}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **A, B**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B**."},{"id":561,"category":"Luật Kinh doanh bảo hiểm","question":"Mức vốn pháp định của chi nhánh doanh nghiệp bảo hiểm phi nhân thọ nước ngoài kinh doanh bảo hiểm phi nhân thọ, bảo hiểm hàng không và bảo hiểm vệ tinh là:","options":[{"key":"A","text":"400 tỷ"},{"key":"B","text":"250 tỷ"},{"key":"C","text":"500 tỷ"},{"key":"D","text":"300 tỷ"}],"answer":"A","explanation":"Khái niệm cần nhớ trong câu này là: **400 tỷ**. Đáp án đúng là **A**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Chốt mốc **400 tỷ** và gắn với đúng điều kiện của câu."},{"id":562,"category":"Luật Kinh doanh bảo hiểm","question":"Chọn phương án đúng về chi khen thưởng và hỗ trợ đại lý của doanh nghiệp bảo hiểm phi nhân thọ:","options":[{"key":"A","text":"Được phép chi hỗ trợ đại lý nhưng không quá 50% hoa hồng bảo hiểm của các hợp đồng bảo hiểm đã khai thác trong năm tài chính"},{"key":"B","text":"Chi khen thưởng và chi hỗ trợ đại lý không quá 50% hoa hồng bảo hiểm của các hợp đồng bảo hiểm đã khai thác trong năm tài chính"},{"key":"C","text":"Được phép chi khen thưởng đại lý nhưng không quá 50% hoa hồng bảo hiểm của các hợp đồng bảo hiểm đã khai thác trong năm tài chính"},{"key":"D","text":"Không được phép chi hỗ trợ"}],"answer":"B","explanation":"Theo đáp án của đề cương, phương án **B** là nội dung đúng: **Chi khen thưởng và chi hỗ trợ đại lý không quá 50% hoa hồng bảo hiểm của các hợp đồng bảo hiểm đã khai thác trong năm tài chính**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Chốt mốc **50** và gắn với đúng điều kiện của câu."},{"id":563,"category":"Luật Kinh doanh bảo hiểm","question":"Chọn phương án đúng về chi khen thưởng và hỗ trợ đại lý bảo hiểm sức khỏe của doanh nghiệp bảo hiểm phi nhân thọ:","options":[{"key":"A","text":"Chi khen thưởng và chi hỗ trợ đại lý không quá 100% hoa hồng bảo hiểm của các hợp đồng bảo hiểm đã khai thác trong năm tài chính"},{"key":"B","text":"Chi khen thưởng và chi hỗ trợ địa lý không quá 50% hoa hồng bảo hiểm của các hợp đồng bảo hiểm đã khai thác trong năm tài chính"},{"key":"C","text":"Được phép chi khen thưởng đại lý nhưng không quá 50% hoa hồng bảo hiểm của các hợp đồng bảo hiểm đã khai thác trong năm tài chính"},{"key":"D","text":"Không được phép chi hỗ trợ"}],"answer":"A","explanation":"Theo đáp án của đề cương, phương án **A** là nội dung đúng: **Chi khen thưởng và chi hỗ trợ đại lý không quá 100% hoa hồng bảo hiểm của các hợp đồng bảo hiểm đã khai thác trong năm tài chính**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Chốt mốc **100** và gắn với đúng điều kiện của câu."},{"id":564,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật kinh doanh bảo hiểm, các tổ chức kinh doanh bảo hiểm bao gồm đối tượng nào sau đây:","options":[{"key":"A","text":"Công ty hợp danh"},{"key":"B","text":"Tổ chức tương hỗ cung cấp bảo hiểm vi mô"},{"key":"C","text":"Công ty TNHH, công ty cổ phần"},{"key":"D","text":"A, C đúng"},{"key":"E","text":"B, C đúng"}],"answer":"E","explanation":"Theo đáp án của đề cương, đáp án đúng là **E**: **B, C đúng**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **B, C đúng**."},{"id":565,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Đối tượng của hợp đồng bảo hiểm tài sản là tài sản, bao gồm:","options":[{"key":"A","text":"Vật có thực"},{"key":"B","text":"Tiền, giấy tờ trị giá được bằng tiền"},{"key":"C","text":"Các quyền tài sản"},{"key":"D","text":"A, B, C đúng"}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **A, B, C đúng**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng**."},{"id":566,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, tỷ lệ hoa hồng bảo hiểm tín dụng và rủi ro tài chính là:","options":[{"key":"A","text":"20%"},{"key":"B","text":"15%"},{"key":"C","text":"10%"},{"key":"D","text":"5%"}],"answer":"C","explanation":"Khái niệm cần nhớ trong câu này là: **10%**. Đáp án đúng là **C**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Chốt mốc **10** và gắn với đúng điều kiện của câu."},{"id":567,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật kinh doanh bảo hiểm, các tổ chức kinh doanh bảo hiểm không bao gồm đối tượng nào sau đây:","options":[{"key":"A","text":"Công ty hợp danh"},{"key":"B","text":"Công ty trách nhiệm hữu hạn"},{"key":"C","text":"Hợp tác xã bảo hiểm"},{"key":"D","text":"Công ty TNHH, công ty cổ phần"}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Công ty hợp danh**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Công ty hợp danh**."},{"id":568,"category":"Kiến thức chung","question":"Những tổn thất – hậu quả mà rủi ro sẽ mang lại được tính bằng tiền, được gọi là rủi ro:","options":[{"key":"A","text":"Rủi ro chung"},{"key":"B","text":"Rủi ro riêng"},{"key":"C","text":"Rủi ro thuần túy"},{"key":"D","text":"Rủi ro tài chính"}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **Rủi ro tài chính**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Rủi ro tài chính**."},{"id":569,"category":"Bảo hiểm xe cơ giới","question":"Mức trách nhiệm bảo hiểm đối với thiệt hại về tài sản do xe gắn máy (kể cả xe máy điện) và các loại xe tương tự theo quy định","options":[{"key":"A","text":"200 triệu"},{"key":"B","text":"150 triệu"},{"key":"C","text":"100 triệu"},{"key":"D","text":"50 triệu"}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án **D** là **50 triệu**. Mốc cần nhớ: **50 triệu**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Chốt mốc **50 triệu** và gắn với đúng điều kiện của câu."},{"id":570,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Công trường không là đối tượng phải mua bảo hiểm bắt buộc trong hoạt động đầu tư xây dựng:","options":[{"key":"A","text":"Công trình, hạng mục công trình có ảnh hưởng lớn đến an toàn, lợi ích cộng đồng"},{"key":"B","text":"Công trình đầu tư xây dựng có ảnh hưởng xấu đến môi trường"},{"key":"C","text":"Công trình kỹ thuật công nghiệp"},{"key":"D","text":"Giao thông công cộng"}],"answer":"C","explanation":"Theo đáp án của đề cương, đáp án đúng là **C**: **Công trình kỹ thuật công nghiệp**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Công trình kỹ thuật công nghiệp**."},{"id":571,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật kinh doanh bảo hiểm, tỷ lệ hoa hồng bảo hiểm cháy nổ tự nguyện là:","options":[{"key":"A","text":"20%"},{"key":"B","text":"15%"},{"key":"C","text":"10%"},{"key":"D","text":"5%."}],"answer":"C","explanation":"Khái niệm cần nhớ trong câu này là: **10%**. Đáp án đúng là **C**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Chốt mốc **10** và gắn với đúng điều kiện của câu."},{"id":572,"category":"Luật Kinh doanh bảo hiểm","question":"Văn phòng đại diện nước ngoài tại Việt Nam có ít nhất bao nhiêu Đại lý Bảo hiểm?","options":[{"key":"A","text":"100"},{"key":"B","text":"200"},{"key":"C","text":"250"},{"key":"D","text":"Không có Đại lý"}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án **D** là **Không có Đại lý**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Không có Đại lý**."},{"id":573,"category":"Kiến thức chung","question":"Rủi ro ngẫu nhiên là gì?","options":[{"key":"A","text":"Bất ngờ"},{"key":"B","text":"Không lường trước được về không gian, thời gian, cũng như mức độ nghiêm trọng"},{"key":"C","text":"Cả A và B đều đúng"}],"answer":"C","explanation":"Khái niệm cần nhớ trong câu này là: **Cả A và B đều đúng**. Đáp án đúng là **C**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Cả A và B đều đúng**."},{"id":574,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Pháp luật kinh doanh bảo hiểm, thương tật toàn bộ vĩnh viễn của trường hợp mất 2.6 tay, chân tính như thế nào:","options":[{"key":"A","text":"Với tay từ cổ tay trở lên, chân từ mắt cá chân trở lên"},{"key":"B","text":"Với tay từ khủy tay trở lên, chân từ đầu gối chân trở lên"},{"key":"C","text":"Với tay từ bàn tay trở lên, chân từ bàn chân trở lên"}],"answer":"A","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **A**: **Với tay từ cổ tay trở lên, chân từ mắt cá chân trở lên**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Với tay từ cổ tay trở lên, chân từ mắt cá chân trở lên**."},{"id":575,"category":"Kiến thức chung","question":"Ông A đầu tư chứng khoán, nếu mã cổ phiếu giảm thì gọi là rủi ro gì","options":[{"key":"A","text":"Rủi ro có đảm bảo"},{"key":"B","text":"Rủi ro thuần túy"},{"key":"C","text":"Rủi ro đầu cơ"},{"key":"D","text":"Rủi ro chung"}],"answer":"C","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **C**: **Rủi ro đầu cơ**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Rủi ro đầu cơ**."},{"id":576,"category":"Kiến thức chung","question":"Dịch vụ phụ trợ bảo hiểm bao gồm:","options":[{"key":"A","text":"Tư vấn, đánh giá rủi ro bảo hiểm"},{"key":"B","text":"Tính toán bảo hiểm, giám định tổn thất bảo hiểm"},{"key":"C","text":"Hỗ trợ giải quyết bồi thường bảo hiểm"},{"key":"D","text":"A&C đúng"},{"key":"E","text":"A, B&C"}],"answer":"E","explanation":"Theo đáp án của đề cương, đáp án đúng là **E**: **A, B&C**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B&C**."},{"id":577,"category":"Kiến thức chung","question":"Tư vấn là hoạt động:","options":[{"key":"A","text":"Tư vấn, đánh giá rủi ro bảo hiểm"},{"key":"B","text":"Tính toán bảo hiểm, giám định tổn thất bảo hiểm"},{"key":"C","text":"Hỗ trợ giải quyết bồi thường bảo hiểm"},{"key":"D","text":"A và C đúng"},{"key":"E","text":"A, B ,C đúng"}],"answer":"E","explanation":"Theo đáp án của đề cương, đáp án đúng là **E**: **A, B ,C đúng**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B ,C đúng**."},{"id":578,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Tổn thất hoặc thiệt hại do cháy đối với các thiết bị hoặc hệ thống điện được bảo hiểm theo Điều khoản Bảo hiểm Thiết bị điện 4A.4B phát sinh do hoặc gây ra bởi sự quá tải, quá áp, đoản mạch, phóng hồ quang điện, tự nung nóng hay bị rò điện vì bất kỳ nguyên nhân nào (­_______ cả sét đánh), điền vào chỗ trống_____:","options":[{"key":"A","text":"Bao gồm"},{"key":"B","text":"Không bao gồm"}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Bao gồm**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Bao gồm**."},{"id":579,"category":"Bảo hiểm xe cơ giới","question":"Bảo hiểm trách nhiệm dân sự bắt buộc xe cơ giới, doanh nghiệp bảo hiểm theo quy định phải có thời hạn giám định tổn thất xác định nguyên nhân và mức độ tổn thất làm căn cứ giải quyết bồi thường bảo hiểm:","options":[{"key":"A","text":"Trong vòng 1h"},{"key":"B","text":"Trong vòng 12h"},{"key":"C","text":"Trong vòng 24h"},{"key":"D","text":"Trong vòng 48h"}],"answer":"C","explanation":"Theo đáp án của đề cương, đáp án **C** là **Trong vòng 24h**. Với dạng câu có mốc số liệu, nên ưu tiên ghi nhớ **con số + đơn vị + điều kiện áp dụng**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Trong vòng 24h**."},{"id":580,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, trong trường hợp đại lý bảo hiểm vi phạm hợp đồng đại lý bảo hiểm, gây thiệt hại đến quyền, lợi ích hợp pháp của người được bảo hiểm thì:","options":[{"key":"A","text":"Đại lý bảo hiểm phải có trách nhiệm bồi hoàn trực tiếp cho bên mua bảo hiểm"},{"key":"B","text":"Doanh nghiệp bảo hiểm chịu trách nhiệm thực hiện các nghĩa vụ theo thỏa thuận trong hợp đồng bảo hiểm do đại lý bảo hiểm thu xếp giao kết"},{"key":"C","text":"Đại lý bảo hiểm không chịu bất cứ trách nhiệm nào vì hợp đồng bảo hiểm được giao kết giữa doanh nghiệp bảo hiểm và bên mua bảo hiểm"},{"key":"D","text":"B, C đúng"}],"answer":"B","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **B**: **Doanh nghiệp bảo hiểm chịu trách nhiệm thực hiện các nghĩa vụ theo thỏa thuận trong hợp đồng bảo hiểm do đại lý bảo hiểm thu xếp giao kết**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Doanh nghiệp bảo hiểm chịu trách nhiệm thực hiện các nghĩa vụ theo thỏa thuận trong hợp…**."},{"id":581,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật kinh doanh bảo hiểm, phương án đúng nhất về cá nhân trực tiếp thực hiện hoạt động giám định tổn thất bảo hiểm trong tổ chức cung cấp dịch vụ phụ trợ bảo hiểm phải đáp ứng các tiêu chuẩn gì:","options":[{"key":"A","text":"Từ đủ 18 tuổi trở lên, có năng lực hành vi dân sự đầy đủ."},{"key":"B","text":"Có văn bằng, chứng chỉ về giám định tổn thất phù hợp"},{"key":"C","text":"Đáp ứng các tiêu chuẩn của giám định viên theo quy định của pháp luật về thương mại."},{"key":"D","text":"A, C đúng"},{"key":"E","text":"A, B, C đúng"}],"answer":"E","explanation":"Theo đáp án của đề cương, đáp án đúng là **E**: **A, B, C đúng**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C đúng**."},{"id":582,"category":"Luật Kinh doanh bảo hiểm","question":"Khi có sự thay đổi những yếu tố làm cơ sở để tính phí bảo hiểm dẫn đến giảm các rủi ro được bảo hiểm, căn cứ thỏa thuận trong hợp đồng bảo hiểm, bên mua bảo hiểm có quyền yêu cầu doanh nghiệp bảo hiểm, chi nhánh doanh nghiệp bảo hiểm phi nhân thọ nước ngoài thực hiện một trong các nội dung sau đây:","options":[{"key":"A","text":"Giảm phí bảo hiểm cho thời gian còn lại của hợp đồng bảo hiểm; tăng số tiền bảo hiểm cho thời gian còn lại của hợp đồng bảo hiểm; kéo dài thời hạn bảo hiểm;"},{"key":"B","text":"Mở rộng phạm vi bảo hiểm cho thời gian còn lại của hợp đồng bảo hiểm."},{"key":"C","text":"Thu hẹp phạm vi bảo hiểm cho thời gian còn lại của hợp đồng bảo hiểm."},{"key":"D","text":"A & B đúng"},{"key":"E","text":"A, B & C đúng"}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **A & B đúng**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A & B đúng**."},{"id":583,"category":"Bảo hiểm con người","question":"Theo Pháp luật Việt Nam, kinh doanh bảo hiểm đối với bảo hiểm sức khỏe, tổng các khoản chi thưởng hỗ trợ và quyền lợi khác của các đại lý bảo hiểm không vượt quá:","options":[{"key":"A","text":"50% hoa hồng đại lý bảo hiểm của tất cả các hợp đồng bảo hiểm thuộc bảo hiểm sức khỏe đã  khai thác trong năm tài chính"},{"key":"B","text":"100% hoa hồng đại lý bảo hiểm của tất cả các hợp đồng bảo hiểm thuộc bảo hiểm sức khỏe đã khai thác trong năm tài chính"},{"key":"C","text":"30% Phí bảo hiểm của tất cả các hợp đồng bảo hiểm thuộc bảo hiểm sức khỏe đã khai thác trong năm tài chính"},{"key":"D","text":"50% Phí Bảo hiểm của tất cả các hợp đồng bảo hiểm thuộc bảo hiểm sức khỏe đã khai thác trong năm tài chính"}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án đúng là **B**: **100% hoa hồng đại lý bảo hiểm của tất cả các hợp đồng bảo hiểm thuộc bảo hiểm sức khỏe đã khai thác trong năm tài chính**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Chốt mốc **100** và gắn với đúng điều kiện của câu."},{"id":584,"category":"Luật Kinh doanh bảo hiểm","question":"Theo Luật Kinh doanh bảo hiểm, chọn phương án đúng nhất về “Nguyên tắc bồi thường”:","options":[{"key":"A","text":"Số tiền bồi thường mà bên mua bảo hiểm nhận được không vượt quá thiệt hại thực tế trong sự kiện bảo hiểm, trừ trường hợp có thỏa thuận khác trong hợp đồng bảo hiểm"},{"key":"B","text":"Số tiền bồi thường mà người được bảo hiểm nhận được không vượt quá thiệt hại thực tế trong sự kiện bảo hiểm, trừ trường hợp có thỏa thuận khác trong hợp đồng bảo hiểm"},{"key":"C","text":"Số tiền bồi thường mà người được bảo hiểm nhận được không vượt quá thiệt hại thực tế trong sự kiện bảo hiểm"},{"key":"D","text":"Số tiền bồi thường mà người bảo hiểm nhận được trong sự kiện bảo hiểm"}],"answer":"B","explanation":"Theo đáp án của đề cương, phương án **B** là nội dung đúng: **Số tiền bồi thường mà người được bảo hiểm nhận được không vượt quá thiệt hại thực tế trong sự kiện bảo hiểm, trừ trường hợp có thỏa thuận khác trong hợp đồng bảo hiểm**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Số tiền bồi thường mà người được bảo hiểm nhận được không vượt quá thiệt hại thực tế trong…**."},{"id":585,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Đơn bảo hiểm mọi rủi ro xây dựng.lắp đặt (CAR/EAR), “Mức khấu trừ” được hiểu là:","options":[{"key":"A","text":"Mức miễn thường có khấu trừ cho mọi sự cố"},{"key":"B","text":"Mức miễn thường có khấu trừ cho mỗi và mọi sự cố"}],"answer":"B","explanation":"Khái niệm cần nhớ trong câu này là: **Mức miễn thường có khấu trừ cho mỗi và mọi sự cố**. Đáp án đúng là **B**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Mức miễn thường có khấu trừ cho mỗi và mọi sự cố**."},{"id":586,"category":"Luật Kinh doanh bảo hiểm","question":"Chọn phương án đúng nhất về hoạt động đại lý bảo hiểm theo Luật kinh doanh bảo hiểm:","options":[{"key":"A","text":"Tư vấn sản phẩm bảo hiểm; thu xếp giao kết hợp đồng bảo hiểm; thu phí bảo hiểm; thu thập hồ sơ để phục vụ việc giải quyết bồi thường, trả tiền bảo hiểm."},{"key":"B","text":"Tư vấn sản phẩm bảo hiểm; giới thiệu sản phẩm bảo hiểm; chào bán sản phẩm bảo hiểm; thu xếp việc giao kết hợp đồng bảo hiểm; thu phí bảo hiểm; thu thập hồ sơ để phục vụ việc giải quyết bồi thường, trả tiền bảo hiểm."},{"key":"C","text":"Tư vấn sản phẩm bảo hiểm; giới thiệu sản phẩm bảo hiểm; thu xếp việc giao kết hợp đồng bảo hiểm; thu phí bảo hiểm; thu thập hồ sơ để phục vụ việc giải quyết bồi thường, trả tiền bảo hiểm."},{"key":"D","text":"Tư vấn sản phẩm bảo hiểm; giới thiệu sản phẩm bảo hiểm; chào bán sản phầm bảo hiểm; thu xếp việc giao kết hợp đồng bảo hiểm; thu thập hồ sơ để phục vụ việc giải quyết bồi thường, trả tiền bảo hiểm."}],"answer":"D","explanation":"Theo đáp án của đề cương, phương án **D** là nội dung đúng: **Tư vấn sản phẩm bảo hiểm; giới thiệu sản phẩm bảo hiểm; chào bán sản phầm bảo hiểm; thu xếp việc giao kết hợp đồng bảo hiểm; thu thập hồ sơ để phục vụ việc giải quyết bồi thường, trả tiền bảo hiểm.**. Trọng tâm là ghi nhớ đúng **chủ thể, quyền/nghĩa vụ và điều kiện** được nêu trong phương án này.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Tư vấn sản phẩm bảo hiểm; giới thiệu sản phẩm bảo hiểm; chào bán sản phầm bảo hiểm; thu xếp…**."},{"id":587,"category":"Kiến thức chung","question":"Rủi ro được coi là rủi ro có thể được bảo hiểm khi đáp ứng các điều kiện sau:","options":[{"key":"A","text":"Tổn thất phải ngẫu nhiên, bất ngờ."},{"key":"B","text":"Phải đo được, định lượng được về tài chính"},{"key":"C","text":"Phải có số đông"},{"key":"D","text":"Không trái với chuẩn mực đạo đức xã hội"},{"key":"E","text":"A, B, C, D đúng"}],"answer":"E","explanation":"Theo đáp án của đề cương, đáp án đúng là **E**: **A, B, C, D đúng**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, B, C, D đúng**."},{"id":588,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Bên thứ ba trong bảo hiểm trách nhiệm nghề nghiệp tư vấn đầu tư xây dựng là:","options":[{"key":"A","text":"Bên mua bảo hiểm"},{"key":"B","text":"Người được bảo hiểm"},{"key":"C","text":"Doanh nghiệp bảo hiểm"},{"key":"D","text":"Nhà dân ở cạnh công trình bị tổn thất do công trình thi công bị sập và đổ sang (lỗi thiết kế)"}],"answer":"D","explanation":"Khái niệm cần nhớ trong câu này là: **Nhà dân ở cạnh công trình bị tổn thất do công trình thi công bị sập và đổ sang (lỗi thiết kế)**. Đáp án đúng là **D**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Nhà dân ở cạnh công trình bị tổn thất do công trình thi công bị sập và đổ sang (lỗi thiết kế)**."},{"id":589,"category":"Bảo hiểm xe cơ giới","question":"Theo đơn bảo hiểm thiệt hại vật chất xe cơ giới (không có Điều khoản sửa đổi bổ sung), doanh nghiệp bảo hiểm bồi thường cho người được bảo hiểm đối với thiệt hại vật chất xe cơ giới do tai nạn bất ngờ, không lường trước nào sau đây:","options":[{"key":"A","text":"Mất cắp, mất cướp toàn bộ xe (có kết luận của cơ quan công an)"},{"key":"B","text":"Mất cắp bộ phận xe"},{"key":"C","text":"Đá văng trên đường làm vỡ kính xe"},{"key":"D","text":"A, C đúng"},{"key":"E","text":"A, B, C đúng"}],"answer":"D","explanation":"Theo đáp án của đề cương, đáp án đúng là **D**: **A, C đúng**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, C đúng**."},{"id":590,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Theo Quy tắc bảo hiểm Gián đoạn kinh doanh của Hiệp hội bảo hiểm Vương Quốc Anh (ABI), các hạng mục nào sau đây có thể được bảo hiểm:","options":[{"key":"A","text":"Lợi nhuận ròng trước thuế"},{"key":"B","text":"Chi phí mua nguyên vật liệu đầu vào để khôi phục hoạt động sản xuất kinh doanh"},{"key":"C","text":"Chi phí thuê văn phòng, điện nước vẫn phát sinh sau khi xảy ra thiệt hại để duy trì hoạt động sản xuất kinh doanh"},{"key":"D","text":"A, B đúng"},{"key":"E","text":"A, C đúng"}],"answer":"E","explanation":"Theo đáp án của đề cương, đáp án đúng là **E**: **A, C đúng**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **A, C đúng**."},{"id":591,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Tiền lương, tiền công để duy trì nhân viên có thể được bảo hiểm trong loại hình bảo hiểm Gián đoạn kinh doanh không:","options":[{"key":"A","text":"Có"},{"key":"B","text":"Không"}],"answer":"A","explanation":"Theo đáp án của đề cương, đáp án đúng là **A**: **Có**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Có**."},{"id":592,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Theo Đơn bảo hiểm “Mọi rủi ro tài sản” của Hiệp hội bảo hiểm Vương quốc Anh (ABI), tài sản nào sau đây được bảo hiểm:","options":[{"key":"A","text":"Đập"},{"key":"B","text":"Công trình đã bàn giao và đưa vào sử dụng"},{"key":"C","text":"Máy móc thiết bị đang lắp đặt"}],"answer":"B","explanation":"Theo đáp án của đề cương, đáp án đúng là **B**: **Công trình đã bàn giao và đưa vào sử dụng**. Khi ôn, hãy ghi nhớ **ý chính của phương án đúng** và đối chiếu với từ khóa trong câu hỏi để tránh nhầm với các phương án gần giống.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Công trình đã bàn giao và đưa vào sử dụng**."},{"id":593,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Các yếu tố cần tính đến khi xác định phần giảm giá trị do hao mòn và xuống cấp tự nhiên theo thời gian sử dụng của các công trình kiến trúc hay máy móc thiết bị là:","options":[{"key":"A","text":"Thời gian sử dụng và mức độ khai thác"},{"key":"B","text":"Chế độ chăm sóc, bảo dưỡng; trình độ, tay nghề của người vận hành và những yếu tố liên quan khác"},{"key":"C","text":"A, B đúng"}],"answer":"A","explanation":"Khái niệm cần nhớ trong câu này là: **Thời gian sử dụng và mức độ khai thác**. Đáp án đúng là **A**; nên học theo cụm từ khóa chính thay vì chỉ nhớ ký tự đáp án.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Thời gian sử dụng và mức độ khai thác**."},{"id":594,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Theo đơn bảo hiểm “Hỏa hoạn và các rủi ro đặc biệt” của Hiệp hôi bảo hiểm Vương quốc Anh (ABI), tài sản được bảo hiểm theo nhóm rủi ro A, B, trường hợp vật liệu chứa bên trong thiết bị áp lực bị nổ, tổn thất nào sau đây thuộc phạm vi bảo hiểm:","options":[{"key":"A","text":"Thiết bị áp lực bị thiệt hại"},{"key":"B","text":"Tài sản được bảo hiểm xung quanh bị thiệt hại"},{"key":"C","text":"Thiệt hại đối với tài sản của nhà máy lân cận"},{"key":"D","text":"A, B, C đúng"}],"answer":"A","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **A**: **Thiết bị áp lực bị thiệt hại**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Thiết bị áp lực bị thiệt hại**."},{"id":595,"category":"Bảo hiểm tài sản, kỹ thuật và hàng hóa","question":"Theo đơn bảo hiểm “Hỏa hoạn và các rủi ro đặc biệt” của Hiệp hội bảo hiểm Vương quốc Anh (ABI), nếu tham gia bảo hiểm rủi ro A, I, nguyên nhân gây ra tổn thất nào sau đây thuộc phạm vi bảo hiểm:","options":[{"key":"A","text":"Tổn thất do nước thoát ra từ bể chứa nước đang sử dụng"},{"key":"B","text":"Tổn thất do nước thoát ra từ hệ thống chữa cháy tự động Spinkler"},{"key":"C","text":"Tổn thất do nước thoát ra từ đường ống dẫn nước bên trong tòa nhà bỏ không."}],"answer":"A","explanation":"Trong tình huống được nêu, đáp án đúng theo đề cương là **A**: **Tổn thất do nước thoát ra từ bể chứa nước đang sử dụng**. Cách nhớ là xác định lần lượt **sự kiện/tình huống → điều kiện áp dụng → hậu quả hoặc trách nhiệm bảo hiểm**.","tip":"💡 Mẹo nhớ: Liên kết từ khóa của câu hỏi với ý **Tổn thất do nước thoát ra từ bể chứa nước đang sử dụng**."}];
